open! Core
module Activation_custody = Recurrence_activation_custody

module No_effects_observation = struct
  type t =
    { current : unit -> (unit, Agent_protocol.Error.t) result
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    ; completion : Run_preparation.Source_completion.t
    ; controller : Recurrence_controller.t
    ; observed : Recurrence_controller.observation
    ; actor : Operator_authorization.t
    ; authorize : Session_state.t -> (unit, Agent_protocol.Error.t) result
    ; revision : int64
    }

  let check_basis t = t.basis ()
  let check_current t = t.current ()
end

module Source_binding = struct
  type disposition =
    | Selected
    | Admission_pending of bool ref
    | Admitted of Agent_protocol.Run_receipt.t

  type phase =
    | Open of disposition
    | Closed of disposition

  type t =
    { source : Runtime_source_preparation.t
    ; preparation : Run_preparation.t
    ; domain : int
    ; mutable phase : phase
    ; current : unit -> (unit, Agent_protocol.Error.t) result
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    }

  let source t = t.source
  let on_domain t = Int.equal t.domain (Stdlib.Domain.self () :> int)

  let close t =
    if not (on_domain t) then invalid_arg "source binding belongs to another Eio domain";
    match t.phase with
    | Open disposition -> t.phase <- Closed disposition
    | Closed _ -> ()
  ;;

  let check_basis t =
    if not (on_domain t)
    then
      Error
        (Agent_protocol.Error.invalid_request
           "source binding belongs to another Eio domain")
    else if
      match t.phase with
      | Closed _ -> true
      | Open _ -> false
    then
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:"source binding is closed"
           ~retryable:false
           ())
    else t.basis ()
  ;;

  let check_current t =
    let open Result.Let_syntax in
    let%bind () = check_basis t in
    let%bind () = t.current () in
    check_basis t
  ;;
end

module Recurrence_retry = struct
  type phase =
    | Preparing_source
    | Selected_source of Source_binding.t
    | Closed_before_writer of Run_preparation.Source_completion.t
    | Writer_pending of Source_binding.t * bool ref
    | Attempt_unconfirmed
    | Acknowledged of Source_binding.t option * Recurrence_execution.t
    | Invalid

  type t =
    { issuing_actor : unit ref
    ; owner : Run_preparation.Owner.t
    ; controller : Recurrence_controller.t
    ; source_owner : Runtime_source_owner.Identity.t
    ; observed : Recurrence_controller.observation
    ; domain : int
    ; intent : Recurrence_execution_intent.t
    ; previous : Recurrence_execution_attempt.t
    ; next : Recurrence_execution_attempt.t
    ; request : Run_admission_request.Headless.t
    ; resolution_revision : int64
    ; read_actor : Operator_authorization.t
    ; read_authorize : Session_state.t -> (unit, Agent_protocol.Error.t) result
    ; mutable deferred : Run_preparation.Deferred.t
    ; mutable phase : phase
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    ; selected_basis : Source_binding.t -> (unit, Agent_protocol.Error.t) result
    ; policy : unit -> (unit, Agent_protocol.Error.t) result
    ; authority : unit -> (unit, Agent_protocol.Error.t) result
    }

  let intent t = t.intent
  let previous t = t.previous
  let next_attempt t = t.next

  let check_basis t =
    if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
    then
      Error (Agent_protocol.Error.invalid_request "retry belongs to another Eio domain")
    else (
      match t.phase with
      | Preparing_source | Selected_source _ | Closed_before_writer _ -> t.basis ()
      | Writer_pending _ | Attempt_unconfirmed | Acknowledged _ | Invalid ->
        Error
          (Agent_protocol.Error.create
             Conflict
             ~message:"retry is unavailable or already acknowledged"
             ~retryable:false
             ()))
  ;;
end

module Deferred_owner = struct
  type t =
    | Ordinary of Run_preparation.Deferred.t
    | Retry of Recurrence_retry.t

  let preparation = function
    | Ordinary deferred -> deferred
    | Retry retry -> retry.Recurrence_retry.deferred
  ;;
end

(* Only concrete Actor-owned association issuers construct this link. It retains
   the actual Store and immutable admitted association; public DATA cannot issue
   or replace it. Checks are pure and never invoke supplied host callbacks. *)
module Activation_issuer_policy = struct
  type t =
    | Recurrence
    | Goal of Goal_activation_policy.t
end

module Activation_association = struct
  type t =
    { issuer_policy : Activation_issuer_policy.t
    ; check_target :
        store:Recurrence_controller.t
        -> state:Session_state.t
        -> run:Agent_protocol.Run.t
        -> admission:Agent_protocol.Run_receipt.t
        -> (unit, Agent_protocol.Error.t) result
    }

  let check_target t ~store ~state ~run ~admission =
    t.check_target ~store ~state ~run ~admission
  ;;
end

module Activation_controller = struct
  module Operation = struct
    type t =
      { association : Activation_association.t
      ; install : unit -> unit
      ; close : unit -> unit
      ; refresh : unit -> (unit, Agent_protocol.Error.t) result
      ; policy : unit -> (unit, Agent_protocol.Error.t) result
      ; timing : unit -> (unit, Agent_protocol.Error.t) result
      ; authority : unit -> (unit, Agent_protocol.Error.t) result
      ; basis : unit -> (unit, Agent_protocol.Error.t) result
      }
  end

  type t = { transfer : unit -> (Operation.t, Agent_protocol.Error.t) result }
end

module Held_operation = struct
  module Proof = struct
    type t =
      { scope : Run_admission.Scope.t
      ; run : Agent_protocol.Run.t
      ; admission : Agent_protocol.Run_receipt.t
      ; source : Runtime_source_preparation.t
      ; operation : Agent_protocol.Operation.t
      ; worker : Operation_worker.t
      ; binding : Run_authorities.binding
      ; controller : Activation_controller.Operation.t
      }
  end

  type phase =
    | Staged
    | Pending_first_effect
    | Started
    | Retired

  type t =
    { proof : Proof.t
    ; mutable phase : phase
    ; mutable target_current : Recurrence_controller.observation option
    }

  let retire t =
    t.phase <- Retired;
    t.proof.controller.close ()
  ;;
end

module Held_authored_proof = struct
  type t =
    { run : Agent_protocol.Run.t
    ; admission : Agent_protocol.Run_receipt.t
    ; binding : Run_authorities.binding
    }
end

module Input_attempt = struct
  type t =
    | Available
    | Claimed
end

module Goal_callback_control = struct
  module Disposition = struct
    type t =
      | Held of Agent_protocol.Goal.Reason.t
      | Abandoned of Agent_protocol.Goal.Reason.t
    [@@deriving equal, sexp_of]
  end

  (* One immutable fact, issued only at the actual callback checkpoint ACK.
     [owner] is the exact process-local lifecycle owner, never an ID lookup. *)
  type t =
    { owner : unit ref
    ; receipt : Goal_command_receipt.t
    ; disposition : Disposition.t
    ; goal : Agent_protocol.Goal.t
    ; run : Agent_protocol.Run.t
    ; link : Run_goal_link.t
    ; callback : Agent_protocol.Id.Moderator_execution.t
    }

  let receipt t = t.receipt
  let disposition t = t.disposition

  let waiting t =
    match t.run.lifecycle with
    | Waiting wake -> Some wake
    | Admitted | Active | Terminal _ -> None
  ;;

  let conflict message = Agent_protocol.Error.create Conflict ~message ~retryable:false ()

  (* Pure final-candidate validation. [owner] is bound by the Actor only after
     selecting its real lifecycle scope; preparing this DATA issues no ACK. *)
  let prepare ~owner ~run_id ~callback ~controls candidate =
    let open Result.Let_syntax in
    match candidate.Session_state.run_state with
    | None -> Ok None
    | Some index ->
      (match Run_state.goal_link index run_id with
       | None -> Ok None
       | Some link ->
         let selected =
           List.find (List.rev controls) ~f:(fun control ->
             Agent_protocol.Id.Goal.equal
               control.Goal_native_actions.Fresh_control.receipt.goal_id
               (Run_goal_link.goal_id link))
         in
         (match selected with
          | None -> Ok None
          | Some control ->
            let%bind run =
              Result.of_option
                (Run_state.find index run_id)
                ~error:(conflict "controlled callback lost its Run")
            in
            let%bind goal =
              Option.bind candidate.goal_catalog ~f:(fun catalog ->
                Goal_catalog.find catalog control.receipt.goal_id)
              |> Result.of_option ~error:(conflict "controlled callback lost its Goal")
            in
            let%bind () =
              if
                Agent_protocol.Goal_episode.matches_run (Run_goal_link.episode link) run
                && Agent_protocol.Run_source.equal
                     (Agent_protocol.Goal.source goal)
                     run.source
                && Option.exists candidate.goal_catalog ~f:(fun catalog ->
                  List.exists
                    (Goal_catalog.receipts catalog)
                    ~f:(Goal_command_receipt.equal control.receipt))
              then Ok ()
              else Error (conflict "controlled callback final association changed")
            in
            let%map disposition =
              match control.mutation, Agent_protocol.Goal.state goal with
              | Hold reason, Open (Held (Needs_input final_reason))
                when Agent_protocol.Goal.Reason.equal reason final_reason ->
                Ok (Disposition.Held reason)
              | Abandon reason, Closed (Abandoned final_reason)
                when Agent_protocol.Goal.Reason.equal reason final_reason ->
                Ok (Disposition.Abandoned reason)
              | Hold reason, Closed (Achieved _) ->
                let%bind settlement =
                  Result.of_option
                    (Agent_protocol.Goal.request_settlement goal)
                    ~error:(conflict "final achievement lost its settlement")
                in
                let receipt = Agent_protocol.Goal_episode.Settlement.receipt settlement in
                let%bind () =
                  if
                    List.exists
                      (Run_state.receipts index)
                      ~f:(Agent_protocol.Run_receipt.equal receipt)
                  then Ok ()
                  else Error (conflict "final achievement lost its terminal ACK")
                in
                let%map () =
                  Agent_protocol.Goal_episode.validate_terminal
                    (Run_goal_link.episode link)
                    ~run
                    ~receipt
                in
                Disposition.Held reason
              | (Hold _ | Abandon _), _ ->
                Error (conflict "control differs from final Goal projection")
            in
            Some
              ({ owner
               ; receipt = control.receipt
               ; disposition
               ; goal
               ; run
               ; link
               ; callback
               }
               : t)))
  ;;

  let check control (state : Session_state.t) =
    let open Result.Let_syntax in
    let%bind () =
      if
        Option.exists state.goal_catalog ~f:(fun catalog ->
          Option.exists
            (Goal_catalog.find catalog control.receipt.goal_id)
            ~f:(Agent_protocol.Goal.equal control.goal)
          && List.exists
               (Goal_catalog.receipts catalog)
               ~f:(Goal_command_receipt.equal control.receipt))
        && Option.exists state.run_state ~f:(fun index ->
          Option.exists
            (Run_state.find index control.run.id)
            ~f:(Agent_protocol.Run.equal control.run)
          && Option.exists
               (Run_state.goal_link index control.run.id)
               ~f:(Run_goal_link.equal control.link))
        && List.exists state.moderator_executions ~f:(fun receipt ->
          Agent_protocol.Id.Moderator_execution.equal receipt.context.id control.callback
          &&
          match receipt.status with
          | Completed _ -> true
          | Running | Failed _ | Interrupted _ -> false)
      then Ok ()
      else Error (conflict "Goal callback control checkpoint changed")
    in
    let%bind _, source = Moderator_source_installation.capture state in
    if Agent_protocol.Run_source.equal source control.run.source
    then Ok ()
    else Error (conflict "Goal callback control source changed")
  ;;
end

module Goal_callback_completion = struct
  type t =
    | Controlled of Goal_callback_control.t
    | Settled of Agent_protocol.Goal_episode.Settlement.t
end

module Held_authored_result = struct
  type t =
    | Started of Agent_protocol.Run_receipt.t
    | Controlled of Goal_callback_control.t
    | Settled of Agent_protocol.Goal_episode.Settlement.t
end

module Held_run = struct
  type t =
    { admission : Agent_protocol.Run_receipt.t
    ; binding : Source_binding.t
    ; run : Agent_protocol.Run.t
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    }

  let admission t = t.admission
  let check_basis t = t.basis ()

  module Activation = struct
    type handoff =
      | User_root of Held_operation.Proof.t
      | Authored_start of Held_authored_proof.t

    type phase =
      | Reserved
      | Constructing
      | Handed_off of handoff
      | Closed

    type t =
      { domain : int
      ; preparation : Run_preparation.t
      ; source : Runtime_source_preparation.t
      ; run : Agent_protocol.Run.t
      ; admission : Agent_protocol.Run_receipt.t
      ; scope : Run_admission.Scope.t
      ; association : Activation_association.t
      ; phase : phase ref
      ; input_attempt : Input_attempt.t ref
      ; control_owner : unit ref
      ; mutable control : Goal_callback_control.t option
      ; mutable settled_callback : Agent_protocol.Goal_episode.Settlement.t option
      ; owned_basis : unit -> (unit, Agent_protocol.Error.t) result
      ; basis : unit -> (unit, Agent_protocol.Error.t) result
      ; policy : unit -> (unit, Agent_protocol.Error.t) result
      ; check_policy : unit -> (unit, Agent_protocol.Error.t) result
      ; authority : unit -> (unit, Agent_protocol.Error.t) result
      }

    let check_basis t =
      if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
      then
        Error
          (Agent_protocol.Error.invalid_request
             "held activation belongs to another Eio domain")
      else (
        match !(t.phase) with
        | Reserved | Constructing -> t.basis ()
        | Handed_off _ | Closed ->
          Error
            (Agent_protocol.Error.create
               Conflict
               ~message:"held startup owner is closed"
               ~retryable:false
               ()))
    ;;

    let close t =
      if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "held activation belongs to another Eio domain";
      match !(t.phase) with
      | Reserved | Constructing -> t.phase := Closed
      | Handed_off _ | Closed -> ()
    ;;

    let handoff_acknowledged t =
      if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "held activation belongs to another Eio domain";
      match !(t.phase) with
      | Handed_off _ -> true
      | Reserved | Constructing | Closed -> false
    ;;
  end

  module Admission = struct
    type held = t

    type t =
      | Held of held
      | Retained of Agent_protocol.Run_receipt.t
      | Rejected of Agent_protocol.Error.t
      | Uncertain of Agent_protocol.Error.t
  end
end

module Admitted_activation = struct
  module Continuation = struct
    type t =
      { target : Held_run.Activation.t
      ; controller : Activation_controller.t
      ; refresh : unit -> (unit, Agent_protocol.Error.t) result
      ; policy : unit -> (unit, Agent_protocol.Error.t) result
      ; refresh_admitted_inference : unit -> (unit, Agent_protocol.Error.t) result
      ; policy_admitted_inference : unit -> (unit, Agent_protocol.Error.t) result
      ; timing : unit -> (unit, Agent_protocol.Error.t) result
      ; authority : unit -> (unit, Agent_protocol.Error.t) result
      ; basis : unit -> (unit, Agent_protocol.Error.t) result
      }

    let target t = t.target
    let refresh t = t.refresh ()
    let check_policy t = t.policy ()
    let check_timing t = t.timing ()
    let check_authority t = t.authority ()
    let check_basis t = t.basis ()
  end

  module Checked = struct
    type t =
      { check_current : unit -> (unit, Agent_protocol.Error.t) result
      ; check_policy : unit -> (unit, Agent_protocol.Error.t) result
      ; check_authority : unit -> (unit, Agent_protocol.Error.t) result
      ; check_timing : unit -> (unit, Agent_protocol.Error.t) result
      ; check_basis : unit -> (unit, Agent_protocol.Error.t) result
      ; association : Activation_association.t
      ; continue : Held_run.Activation.t -> Continuation.t
      ; consumed : bool ref
      }

    let check_current t = t.check_current ()
    let check_policy t = t.check_policy ()
    let check_authority t = t.check_authority ()
    let check_timing t = t.check_timing ()

    let check_basis t =
      if !(t.consumed)
      then
        Error
          (Agent_protocol.Error.create
             Conflict
             ~message:"activation view was consumed by its held target"
             ~retryable:false
             ())
      else t.check_basis ()
    ;;
  end
end

module Goal_activation = struct
  type t =
    { held : Held_run.t
    ; checked : Admitted_activation.Checked.t
    }

  let held t = t.held
  let checked t = t.checked

  module Admission = struct
    type activation = t

    type t =
      | Rejected of Agent_protocol.Error.t
      | Uncertain of Agent_protocol.Error.t
      | Retained of Agent_protocol.Run_receipt.t
      | Activation_unavailable of
          { admission : Agent_protocol.Run_receipt.t
          ; error : Agent_protocol.Error.t
          }
      | Admitted of activation
  end
end

module Goal_resume_result = struct
  module Continuation = struct
    type t =
      | Started of Agent_protocol.Operation.t
      | Waiting of Agent_protocol.Run_wake.t
      | Settled of Agent_protocol.Goal_episode.Settlement.t
      | Controlled of Goal_callback_control.t
  end

  type t =
    | Resumed of
        { receipt : Goal_command_receipt.t
        ; continuation : Continuation.t
        }
    | Retained of Goal_command_receipt.t
    | Resume_failed of
        { receipt : Goal_command_receipt.t
        ; error : Agent_protocol.Error.t
        }
    | Rejected of Agent_protocol.Error.t
    | Uncertain of Agent_protocol.Error.t
end

type job_scope =
  { job : Agent_protocol.Job.t
  ; progress : Job_progress_buffer.t
  ; deadline : Agent_protocol.Timestamp.t option
  ; cancelled : unit Eio.Promise.t
  ; cancel_signal : unit Eio.Promise.u
  ; mutable active : bool
  ; mutable cancel_requested : bool
  ; mutable unfinished_on_return : bool
  ; authority_live : bool Atomic.t
  ; mutable cancel : (unit -> unit) option
  }

module Job_claim_purpose = struct
  type t =
    | Execute
    | Retire_only
end

module Job_runtime_owner = struct
  module Attribution = struct
    type t =
      | Ordinary
      | Goal
  end

  type t =
    { domain : int
    ; issuing_actor : unit ref
    ; scope : job_scope
    ; execute : Native_tool_invocation.executor
    ; attribution : Attribution.t
    }

  (* Routing retains native ancestry without manufacturing inference Unbound. *)
  let run_of_job state (job : Agent_protocol.Job.t) =
    match job.inference_origin with
    | Some _ -> Goal_work_attribution.run_of_job state job
    | None ->
      Result.map
        (Goal_work_attribution.Retained_parent.of_job state job)
        ~f:
          (Option.map ~f:(fun parent -> parent.Goal_work_attribution.Retained_parent.run))
  ;;

  let classify state job =
    let open Result.Let_syntax in
    let%bind run = run_of_job state job in
    let%map attribution =
      Option.value_map run ~default:(Ok None) ~f:(Goal_work_attribution.of_run state)
    in
    match attribution with
    | None -> Attribution.Ordinary
    | Some _ -> Goal
  ;;

  (* A saved Job is not yet its Running execution claim. Only queued work
     participates in fresh Goal selection; factual maintenance of an admitted
     attempt must not acquire a new Enabled decision. *)
  let selection state (job : Agent_protocol.Job.t) =
    let open Result.Let_syntax in
    match job.status with
    | Queued ->
      let%bind run = run_of_job state job in
      Option.value_map
        run
        ~default:(Ok Goal_execution_selection.Eligible)
        ~f:(Goal_execution_selection.of_run state)
    | Running
    | Waiting_permission _
    | Waiting_completion _
    | Succeeded
    | Failed _
    | Cancelled
    | Interrupted _ -> Ok Goal_execution_selection.Eligible
  ;;

  let attribution t =
    if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
    then invalid_arg "Job runtime owner belongs to another Eio domain";
    t.attribution
  ;;

  let deadline t =
    if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
    then invalid_arg "Job runtime owner belongs to another Eio domain";
    t.scope.deadline
  ;;
end

module Goal_execution_handoff = struct
  type t =
    | Queued_event of Agent_protocol.Moderator_execution.t
    | Subscription_turn of Agent_protocol.Operation.t
    | Claimed_job_resource of Agent_protocol.Job.t
    | Lifecycle_wait of Agent_protocol.Run_wake.t
    | Lifecycle_settlement of Agent_protocol.Goal_episode.Settlement.t
end

module Goal_runtime_handoff = struct
  type t =
    | Resume of Goal_resume_result.Continuation.t
    | Existing_execution of Goal_execution_handoff.t
end

module Goal_runtime_phase = struct
  type 'scope t =
    | Unclaimed
    | Starting_writer of bool ref
    | Starting_acknowledged
    | Running_writer of bool ref
    | Constructing
    | Installed of 'scope
    | Callback_completed of 'scope
    | Handed_off of 'scope * Goal_runtime_handoff.t
    | Retired of 'scope
    | Closed
end

(* The one existing-Run source/runtime owner. Public request families are views
   over this same preparation and custody, never parallel constructor state. *)
module Existing_goal_preparation = struct
  module Cause = struct
    type t =
      | Resume_command of Run_preparation.Goal_continuation.t
      | Pending_wake of
          { request : Run_preparation.Goal_continuation.t
          ; wake : Agent_protocol.Run_wake.t
          }
      | Claimed_job of
          { request : Run_preparation.Goal_continuation.t
          ; owner : Job_runtime_owner.t
          }

    let custody = function
      | Resume_command request | Pending_wake { request; _ } | Claimed_job { request; _ }
        -> Run_preparation.Goal_continuation.custody request
    ;;

    let resume_request = function
      | Resume_command request ->
        (match Run_preparation.Goal_continuation.cause request with
         | Resume request -> Ok request
         | Wake _ | Claimed_job _ ->
           Error
             (Agent_protocol.Error.invalid_request
                "Goal execution is not an explicit resume command"))
      | Pending_wake _ | Claimed_job _ ->
        Error
          (Agent_protocol.Error.invalid_request
             "Goal execution is not an explicit resume command")
    ;;
  end

  module Source_phase = struct
    type t =
      | Open
      | Closed
  end

  type preparation =
    { cause : Cause.t
    ; binding : Run_authorities.binding
    ; run : Agent_protocol.Run.t
    ; admission : Agent_protocol.Run_receipt.t
    ; link : Run_goal_link.t
    ; policy : Goal_activation_policy.t
    ; session : Agent_protocol.Session_ref.t
    ; domain : int
    ; mutable phase : phase
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    ; current : unit -> (unit, Agent_protocol.Error.t) result
    ; refresh : unit -> (unit, Agent_protocol.Error.t) result
    ; policy_current : unit -> (unit, Agent_protocol.Error.t) result
    ; timing : unit -> (unit, Agent_protocol.Error.t) result
    ; authority : unit -> (unit, Agent_protocol.Error.t) result
    ; effect_basis : unit -> (unit, Agent_protocol.Error.t) result
    ; registered_basis : unit -> (unit, Agent_protocol.Error.t) result
    ; registered_refresh : unit -> (unit, Agent_protocol.Error.t) result
    ; registered_policy : unit -> (unit, Agent_protocol.Error.t) result
    ; registered_authority : unit -> (unit, Agent_protocol.Error.t) result
    ; mutable runtime_phase : runtime_scope Goal_runtime_phase.t
    ; mutable observed : Recurrence_controller.observation option
    ; mutable native_command_loan : Execution_custody.Admission.t option
    ; mutable resume_outcome : Goal_resume_result.Continuation.t option
    ; resume_commit_attempted : bool ref
    ; control_owner : unit ref
    ; mutable control : Goal_callback_control.t option
    ; mutable settled_callback : Agent_protocol.Goal_episode.Settlement.t option
    }

  and phase =
    | Preparing
    | Source_bound of source_binding
    | Writer_pending of source_binding * bool ref
    | Ready of source_binding * Goal_command_receipt.t
    | Execution_ready of source_binding
    | Waiting of Goal_command_receipt.t * Agent_protocol.Run_wake.t
    | Closed of Goal_command_receipt.t option

  and source_binding =
    { preparation : preparation
    ; source : Runtime_source_preparation.t
    ; mutable source_phase : Source_phase.t
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    }

  and t =
    { binding : source_binding
    ; purpose : purpose
    }

  and purpose =
    | Resume of Goal_command_receipt.t
    | Existing_execution

  and runtime_scope =
    { issuing_actor : unit ref
    ; continuation : t
    ; worker : Operation_worker.t
    ; manager : Chat_response.Moderator_manager.t option
    ; cold : bool
    ; mutable resume : Runtime_builder.Runtime_resume.t option
    ; mutable callback : runtime_callback
    ; mutable jobs : Agent_protocol.Job.t list
    ; mutable graphs : Inference_graph_owner.t list
    }

  and runtime_callback =
    | Pending
    | Executing of Agent_protocol.Id.Moderator_execution.t
    | Completed of Agent_protocol.Id.Moderator_execution.t
    | Joined

  let custody preparation = Cause.custody preparation.cause

  let known_receipt preparation =
    match preparation.phase with
    | Ready (_, receipt) | Waiting (receipt, _) -> Some receipt
    | Closed receipt -> receipt
    | Preparing | Source_bound _ | Writer_pending _ | Execution_ready _ -> None
  ;;

  let close preparation =
    let receipt = known_receipt preparation in
    preparation.phase <- Closed receipt;
    (match preparation.runtime_phase with
     | Handed_off _ | Retired _ -> ()
     | Installed scope | Callback_completed scope ->
       preparation.runtime_phase <- Retired scope
     | Unclaimed
     | Starting_writer _
     | Starting_acknowledged
     | Running_writer _
     | Constructing
     | Closed -> preparation.runtime_phase <- Closed);
    Run_preparation.Custody.close (custody preparation)
  ;;

  let acknowledge preparation binding receipt =
    match preparation.phase with
    | Writer_pending (current, _) when phys_equal current binding ->
      preparation.phase <- Ready (binding, receipt)
    | Preparing
    | Source_bound _
    | Writer_pending _
    | Ready _
    | Execution_ready _
    | Waiting _
    | Closed _ ->
      (* An ACK is factual even after revocation. Neither a closed source nor a
         closed/displaced preparation is reopened by writer completion. *)
      preparation.phase <- Closed (Some receipt)
  ;;

  module Preparation = struct
    type t = preparation

    let receipt t =
      if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "Goal continuation belongs to another Eio domain";
      known_receipt t
    ;;
  end

  module Source_binding = struct
    type t = source_binding

    let source t = t.source

    let check_basis t =
      if Int.equal t.preparation.domain (Stdlib.Domain.self () :> int)
      then t.basis ()
      else
        Error
          (Agent_protocol.Error.invalid_request
             "Goal source binding belongs to another Eio domain")
    ;;

    let close t =
      if not (Int.equal t.preparation.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "Goal source binding belongs to another Eio domain";
      t.source_phase <- Closed
    ;;
  end

  let receipt t =
    match t.purpose with
    | Resume receipt -> receipt
    | Existing_execution ->
      invalid_arg "existing Goal execution is not an explicit Resume continuation"
  ;;

  let check_source_binding (t : t) ~(binding : Source_binding.t) =
    if not (Int.equal binding.preparation.domain (Stdlib.Domain.self () :> int))
    then
      Error
        (Agent_protocol.Error.invalid_request "Goal source belongs to another Eio domain")
    else if phys_equal t.binding binding
    then Ok ()
    else
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:"Goal source and continuation belong to different owners"
           ~retryable:false
           ())
  ;;

  module Resume_issuance = struct
    type t =
      | Retained of Goal_command_receipt.t
      | Prepare of Preparation.t
  end

  module Admission = struct
    type continuation = t

    type t =
      | Retained of Goal_command_receipt.t
      | Waiting of
          { receipt : Goal_command_receipt.t
          ; wake : Agent_protocol.Run_wake.t
          }
      | Ready of continuation
      | Rejected of Agent_protocol.Error.t
      | Uncertain of Agent_protocol.Error.t
      | Resume_failed of
          { receipt : Goal_command_receipt.t
          ; error : Agent_protocol.Error.t
          }
  end
end

(* Keep the explicit Resume API as an exact view of the same physical owner.
   Its command receipt remains specific to the actual Resume cause. *)
module Goal_continuation = Existing_goal_preparation

module Goal_execution_runtime = struct
  module Handoff = Goal_execution_handoff

  module Preparation = struct
    type t = Existing_goal_preparation.preparation

    let handoff (t : t) =
      if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "Goal execution belongs to another Eio domain";
      match t.runtime_phase with
      | Handed_off (_, Existing_execution handoff) -> Some handoff
      | Handed_off (_, Resume _)
      | Unclaimed
      | Starting_writer _
      | Starting_acknowledged
      | Running_writer _
      | Constructing
      | Installed _
      | Callback_completed _
      | Retired _
      | Closed -> None
    ;;
  end

  module Source_binding = Existing_goal_preparation.Source_binding

  type t = Existing_goal_preparation.t

  module Kind = struct
    type t =
      | Queued_wake
      | Subscription_wake
      | Claimed_job
  end

  let kind t =
    match t.Existing_goal_preparation.binding.preparation.cause with
    | Pending_wake { wake; _ } ->
      (match wake.occurrence with
       | Subscription_delivery _ -> Kind.Subscription_wake
       | Job_completion _ | Delivered_timer _ -> Queued_wake)
    | Claimed_job _ -> Kind.Claimed_job
    | Resume_command _ -> invalid_arg "Resume command is not a Goal execution owner"
  ;;

  let wake t =
    let preparation = t.Existing_goal_preparation.binding.preparation in
    if not (Int.equal preparation.domain (Stdlib.Domain.self () :> int))
    then invalid_arg "Goal execution belongs to another Eio domain";
    match preparation.cause with
    | Pending_wake { wake; _ } -> Ok wake
    | Resume_command _ | Claimed_job _ ->
      Error (Agent_protocol.Error.invalid_request "Goal execution is not a pending wake")
  ;;

  let check_source_binding = Existing_goal_preparation.check_source_binding

  module Wake_request = struct
    type t =
      | Idle
      | Timer of Agent_protocol.Schedule.t
      | Job_delivery of Run_job_delivery.t
      | Job_completion of Agent_protocol.Job.t
  end

  module Wake_selection = struct
    type t =
      | Ordinary
      | No_work
      | Suspended_goal of Goal_execution_selection.Suspension.t
      | Wake of Agent_protocol.Run_wake.t
  end

  module Wake_issuance = struct
    type t =
      | No_work
      | Suspended_goal of Goal_execution_selection.Suspension.t
      | Prepare of Preparation.t
  end

  module Wake_result = struct
    type t =
      | Queued of Agent_protocol.Moderator_execution.t
      | Started of Agent_protocol.Operation.t
      | Waiting of Agent_protocol.Run_wake.t
      | Settled of Agent_protocol.Goal_episode.Settlement.t
      | Controlled of Goal_callback_control.t
  end
end

module Delegated_load = struct
  module Custody = Delegated_runtime_load.Custody

  module Initialization = struct
    type t =
      | Scoped
      | Installed_resume
    [@@deriving equal]
  end

  module Preparation = struct
    type installation =
      { worker : Operation_worker.t
      ; inference : Inference_client.Execution.t
      ; manager : Chat_response.Moderator_manager.t option
      }

    type t =
      { load : Delegated_runtime_load.t
      ; initialization : Initialization.t
      ; domain : int
      ; source_owner : Runtime_source_owner.Identity.t
      ; basis : unit -> (unit, Agent_protocol.Error.t) result
      ; refresh : unit -> (unit, Agent_protocol.Error.t) result
      ; current : unit -> (unit, Agent_protocol.Error.t) result
      ; authority : unit -> (unit, Agent_protocol.Error.t) result
      ; mutable binding : Delegated_runtime_load.Source_binding.t option
      ; mutable consumed : bool
      ; mutable observed : Recurrence_controller.observation option
      ; mutable installation : installation option
      }

    let close t =
      Option.iter t.binding ~f:Delegated_runtime_load.Source_binding.close;
      Delegated_runtime_load.close t.load
    ;;
  end

  module Source_binding = struct
    type t =
      { preparation : Preparation.t
      ; source : Runtime_source_preparation.t
      ; binding : Delegated_runtime_load.Source_binding.t
      }

    let source t = t.source
    let close t = Delegated_runtime_load.Source_binding.close t.binding

    let check_basis t =
      if Option.exists t.preparation.binding ~f:(phys_equal t.binding)
      then t.preparation.basis ()
      else
        Error
          (Agent_protocol.Error.create
             Conflict
             ~message:"delegated load source binding was displaced"
             ~retryable:false
             ())
    ;;
  end

  type t = Source_binding.t

  let check_source_binding t ~binding =
    if phys_equal t binding
    then Source_binding.check_basis binding
    else
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:"delegated load belongs to another source binding"
           ~retryable:false
           ())
  ;;
end

module Preparation_owner = struct
  type t =
    | Initial of Run_preparation.t
    | Existing_goal of Existing_goal_preparation.Preparation.t
    | Delegated_load of Delegated_load.Preparation.t

  let initial = function
    | Initial preparation -> Some preparation
    | Existing_goal _ | Delegated_load _ -> None
  ;;

  let tracking = function
    | Initial preparation ->
      Run_preparation.Custody.tracking (Run_preparation.custody preparation)
    | Existing_goal preparation ->
      Run_preparation.Custody.tracking (Goal_continuation.custody preparation)
    | Delegated_load preparation -> Delegated_runtime_load.tracking preparation.load
  ;;

  let belongs_to t ~owner = Preparation_tracking.belongs_to (tracking t) ~owner

  let check_basis t ~owner ~state =
    Preparation_tracking.check_basis (tracking t) ~owner ~state
  ;;

  let advance t ~owner ~previous ~current =
    Preparation_tracking.advance (tracking t) ~owner ~previous ~current
  ;;

  let check_current t ~owner ~state =
    match t with
    | Initial preparation -> Run_preparation.check_current preparation ~owner ~state
    | Existing_goal preparation ->
      Run_preparation.Custody.check_current
        (Goal_continuation.custody preparation)
        ~owner
        ~state
    | Delegated_load preparation ->
      Delegated_runtime_load.check_current preparation.load ~owner ~state
  ;;

  let check t ~owner ~state =
    match t with
    | Initial preparation -> Run_preparation.check preparation ~owner ~state
    | Existing_goal preparation ->
      Run_preparation.Custody.check (Goal_continuation.custody preparation) ~owner ~state
    | Delegated_load preparation ->
      Delegated_runtime_load.check_authority preparation.load ~owner ~state
  ;;

  module Constructor_jobs = struct
    type preparation = t

    type t =
      { preparation : preparation
      ; selection : Preparation_tracking.Constructor_jobs.t
      }

    let prepare_add preparation ~owner ~state ~job =
      let open Result.Let_syntax in
      let%bind () = check preparation ~owner ~state in
      let%map selection =
        Preparation_tracking.Constructor_jobs.prepare_add
          (tracking preparation)
          ~owner
          ~state
          ~job
      in
      { preparation; selection }
    ;;

    let prepare_handoff preparation ~owner ~state =
      let open Result.Let_syntax in
      let%bind () = check preparation ~owner ~state in
      let%map jobs, selection =
        Preparation_tracking.Constructor_jobs.prepare_handoff
          (tracking preparation)
          ~owner
          ~state
      in
      jobs, { preparation; selection }
    ;;

    let check_before_commit t ~owner ~state =
      let open Result.Let_syntax in
      let%bind () = check t.preparation ~owner ~state in
      Preparation_tracking.Constructor_jobs.check_before_commit t.selection ~owner ~state
    ;;

    let acknowledge t = Preparation_tracking.Constructor_jobs.acknowledge t.selection
  end

  let same left right =
    match left, right with
    | Initial left, Initial right -> phys_equal left right
    | Existing_goal left, Existing_goal right -> phys_equal left right
    | Delegated_load left, Delegated_load right -> phys_equal left right
    | Initial _, (Existing_goal _ | Delegated_load _)
    | Existing_goal _, (Initial _ | Delegated_load _)
    | Delegated_load _, (Initial _ | Existing_goal _) -> false
  ;;

  let close = function
    | Initial preparation -> Run_preparation.close preparation
    | Existing_goal preparation -> Goal_continuation.close preparation
    | Delegated_load preparation -> Delegated_load.Preparation.close preparation
  ;;
end

module Runtime_construction = struct
  type t =
    | Initial of Admitted_activation.Continuation.t
    | Existing_goal of Existing_goal_preparation.t
    | Delegated_load of Delegated_load.t

  let of_admitted continuation = Initial continuation
  let of_goal continuation = Existing_goal continuation
  let of_existing_goal_execution execution = Existing_goal execution
  let of_delegated_load load = Delegated_load load

  module Initialization = Delegated_load.Initialization

  let initialization = function
    | Initial _ | Existing_goal _ -> Initialization.Scoped
    | Delegated_load load -> load.Delegated_load.Source_binding.preparation.initialization
  ;;

  let initial_preparation = function
    | Initial continuation ->
      Some continuation.Admitted_activation.Continuation.target.preparation
    | Existing_goal _ -> None
    | Delegated_load load ->
      Delegated_runtime_load.initial_preparation load.preparation.load
  ;;

  let preparation_owner = function
    | Initial continuation ->
      Preparation_owner.Initial
        continuation.Admitted_activation.Continuation.target.preparation
    | Existing_goal continuation ->
      Existing_goal continuation.Goal_continuation.binding.preparation
    | Delegated_load load ->
      (match Delegated_runtime_load.initial_preparation load.preparation.load with
       | Some preparation -> Initial preparation
       | None -> Delegated_load load.preparation)
  ;;

  let source = function
    | Initial continuation -> continuation.Admitted_activation.Continuation.target.source
    | Existing_goal continuation -> continuation.Goal_continuation.binding.source
    | Delegated_load load -> Delegated_load.Source_binding.source load
  ;;

  let close = function
    | Initial continuation ->
      Held_run.Activation.close continuation.Admitted_activation.Continuation.target
    | Existing_goal continuation ->
      Goal_continuation.Source_binding.close continuation.Goal_continuation.binding;
      Goal_continuation.close continuation.binding.preparation
    | Delegated_load load ->
      Delegated_load.Source_binding.close load;
      Delegated_load.Preparation.close load.preparation
  ;;

  let handoff_acknowledged = function
    | Delegated_load _ -> false
    | Initial continuation ->
      Held_run.Activation.handoff_acknowledged
        continuation.Admitted_activation.Continuation.target
    | Existing_goal continuation ->
      let preparation = continuation.Goal_continuation.binding.preparation in
      if not (Int.equal preparation.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "Goal construction belongs to another Eio domain";
      (match preparation.runtime_phase with
       | Handed_off _ -> true
       | Unclaimed
       | Starting_writer _
       | Starting_acknowledged
       | Running_writer _
       | Constructing
       | Installed _
       | Callback_completed _
       | Retired _
       | Closed -> false)
  ;;

  let refresh = function
    | Initial continuation -> Admitted_activation.Continuation.refresh continuation
    | Existing_goal continuation ->
      continuation.Goal_continuation.binding.preparation.refresh ()
    | Delegated_load load -> load.preparation.refresh ()
  ;;

  let check_policy = function
    | Initial continuation -> Admitted_activation.Continuation.check_policy continuation
    | Existing_goal continuation ->
      continuation.Goal_continuation.binding.preparation.policy_current ()
    | Delegated_load load -> load.preparation.current ()
  ;;

  let check_timing = function
    | Initial continuation -> Admitted_activation.Continuation.check_timing continuation
    | Existing_goal continuation ->
      continuation.Goal_continuation.binding.preparation.timing ()
    | Delegated_load load -> load.preparation.basis ()
  ;;

  let check_authority = function
    | Initial continuation ->
      Admitted_activation.Continuation.check_authority continuation
    | Existing_goal continuation ->
      continuation.Goal_continuation.binding.preparation.authority ()
    | Delegated_load load -> load.preparation.authority ()
  ;;

  let check_basis = function
    | Initial continuation -> Admitted_activation.Continuation.check_basis continuation
    | Existing_goal continuation ->
      continuation.Goal_continuation.binding.preparation.effect_basis ()
    | Delegated_load load ->
      let open Result.Let_syntax in
      let%bind () = Delegated_load.Source_binding.check_basis load in
      if Option.exists load.preparation.observed ~f:Recurrence_controller.is_current
      then Ok ()
      else
        Error
          (Agent_protocol.Error.create
             Conflict
             ~message:"delegated load needs its fresh Store custody"
             ~retryable:false
             ())
  ;;
end

module Recurrence_activation = struct
  type t = Activation_custody.t

  let origin = Activation_custody.origin

  module Checked = struct
    type t = Admitted_activation.Checked.t

    let check_current = Admitted_activation.Checked.check_current
    let check_policy = Admitted_activation.Checked.check_policy
    let check_authority = Admitted_activation.Checked.check_authority
    let check_timing = Admitted_activation.Checked.check_timing
    let check_basis = Admitted_activation.Checked.check_basis
    let admitted t = t
  end

  module Continuation = Admitted_activation.Continuation
end

(* This owner is issued by the real authored lifecycle ACK, never by a source
   tag or a callback receipt. The same scope is retained by its actual Event. *)
module Held_authored_start = struct
  module Phase = struct
    type t =
      | Staged
      | Starting
      | Ready
      | Executing of Agent_protocol.Id.Moderator_execution.t
      | Completed of Agent_protocol.Id.Moderator_execution.t
      | Released
      | Attempt_unconfirmed
      | Closed
  end

  type t =
    { domain : int
    ; issuing_actor : unit ref
    ; continuation : Admitted_activation.Continuation.t
    ; startup : Runtime_builder.Authored_start.t
    ; binding : Run_authorities.binding
    ; mutable jobs : Agent_protocol.Job.t list
    ; mutable graphs : Inference_graph_owner.t list
    ; mutable phase : Phase.t
    }
end

module Lifecycle_callback_owner = struct
  type t =
    | Initial_authored of Held_authored_start.t
    | Existing_goal_resume of Goal_continuation.runtime_scope

  let initial = function
    | Initial_authored scope -> Some scope
    | Existing_goal_resume _ -> None
  ;;
end

module Held_authored_resource = struct
  type t =
    { domain : int
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    }

  let check_basis t =
    if Int.equal t.domain (Stdlib.Domain.self () :> int)
    then t.basis ()
    else
      Error
        (Agent_protocol.Error.invalid_request
           "held authored resource belongs to another Eio domain")
  ;;
end

module Runtime_construction_resource = struct
  type t = Held_authored_resource.t

  let check_basis = Held_authored_resource.check_basis
end

module Held_input_scope = struct
  type phase =
    | Parsing
    | Parsed_ready of Runtime_input_preparation.Prepared_input.t
    | Consumed of Held_operation.Proof.t
    | Root_attempt_unconfirmed
    | Closed

  type t =
    { domain : int
    ; issuing_actor : unit ref
    ; continuation : Admitted_activation.Continuation.t
    ; request : Run_admission_request.t
    ; id : History_entry.Id.t
    ; mutable phase : phase
    ; mutable graphs : Inference_graph_owner.t list
    ; mutable issued_execution : Runtime_input_preparation.Execution.t option
    ; basis : unit -> (unit, Agent_protocol.Error.t) result
    }

  let parsing t =
    let open Result.Let_syntax in
    let%bind () =
      if Int.equal t.domain (Stdlib.Domain.self () :> int)
      then Ok ()
      else
        Error
          (Agent_protocol.Error.invalid_request
             "held input belongs to another Eio domain")
    in
    let%bind () =
      match t.phase with
      | Parsing -> Ok ()
      | Parsed_ready _ | Consumed _ | Root_attempt_unconfirmed | Closed ->
        Error
          (Agent_protocol.Error.create
             Conflict
             ~message:"held input excludes new effects"
             ~retryable:false
             ())
    in
    t.basis ()
  ;;

  let execution t =
    let open Result.Let_syntax in
    let%bind () = parsing t in
    Result.of_option
      t.issued_execution
      ~error:
        (Agent_protocol.Error.create
           Invalid_state
           ~message:"held input execution is not issued"
           ~retryable:false
           ())
  ;;
end

