(* Routing references only the actual existing callback owner. The actions table
   issues the integer receipts; neither a lexical scope nor caller data does. *)
module Native_goal_owner = struct
  type t =
    | Event of queued_event_borrow
    | Moderator of moderator_borrow

  let actions = function
    | Event borrow -> borrow.native_goals
    | Moderator borrow -> borrow.native_goals
  ;;
end

module Native_goal_request = struct
  type authorize =
    Operator_authorization.t -> Session_state.t -> (unit, Agent_protocol.Error.t) result

  type _ t =
    | Resume_receipt : Goal_native_resume.Selection.t -> Goal_command_receipt.t option t
    | Resume_status :
        Goal_native_admission.t * authorize * Agent_protocol.Id.Invocation.t
        -> Goal_native_resume.Status.t t
    | Select_resume : Goal_native_resume.Selection.t option t
    | Begin_resume :
        Goal_native_resume.Selection.t
        -> Goal_continuation.Resume_issuance.t t
    | Observe_dispatch :
        Goal_native_resume.Selection.t * Agent_protocol.Error.t option
        -> unit t
    | Stage_create :
        Goal_native_admission.t * authorize * Agent_protocol.Goal_native_create_request.t
        -> int option t
    | Stage_control :
        Goal_native_admission.t * authorize * Agent_protocol.Goal_native_control_request.t
        -> int option t
    | Stage_edit :
        Goal_native_admission.t * authorize * Agent_protocol.Goal_edit.t
        -> int option t
    | Stage_resume :
        Goal_native_admission.t * authorize * Goal_resume_request.t
        -> int option t
    | Read : Goal_native_admission.t * authorize -> Session_state.t t
    | Close_scope : Native_goal_owner.t -> unit t
    | Install_scope : Native_goal_owner.t * Chat_response.Goal_native_scope.t -> unit t
    | Deliverable : Native_goal_owner.t * int -> bool t
    | Accept : Native_goal_owner.t * int -> unit t
    | Rollback : Native_goal_owner.t * int -> unit t
    | Prepare : Native_goal_owner.t * int list -> unit t
end

(* Factual association witnesses retain actual process-local owners; decoded
   identifiers cannot construct them. *)
module Child_installation = struct
  type t =
    { controller : Recurrence_controller.t
    ; source_owner : Runtime_source_owner.Identity.t
    ; reference : Agent_store.Delegation_store.Reference.t
    ; check_current : unit -> (unit, Agent_protocol.Error.t) result
    }
end

(* Snapshot contents are
   immutable historical DATA. Refresh returns a negative-only final read guard;
   it cannot issue source/execution permission or replace snapshot contents. *)
module Child_usage_observation = struct
  type t =
    { controller : Recurrence_controller.t
    ; source_owner : Runtime_source_owner.Identity.t
    ; reference : Agent_store.Delegation_store.Reference.t
    ; snapshot : Child_usage_snapshot.t option
    ; refresh_read :
        unit
        -> (unit -> (unit, Agent_protocol.Error.t) result, Agent_protocol.Error.t) result
    }
end

module Child_usage_import = struct
  type t =
    | Imported of Child_contributions.disposition
    | Historical_absence
end

module Child_accounting_request = struct
  type _ t =
    | Observe_installation :
        Runtime_source_owner.t * Agent_store.Delegation_store.Reference.t
        -> Child_installation.t t
    | Register_installation :
        Native_tool_invocation.borrowed option
        * Runtime_source_owner.t
        * Child_installation.t
        * (Session_state.t -> (unit, Agent_protocol.Error.t) result)
        * int
        * int
        -> unit t
    | Observe_usage :
        Runtime_source_owner.t
        * Operator_authorization.t
        * (Session_state.t -> (unit, Agent_protocol.Error.t) result)
        * Agent_store.Delegation_store.Reference.t
        -> Child_usage_observation.t t
    | Import_usage :
        Runtime_source_owner.t
        * Operator_authorization.t
        * (Session_state.t -> (unit, Agent_protocol.Error.t) result)
        * Child_usage_observation.t
        * int
        * int
        -> Child_usage_import.t t
end

module Recurrence_read_request = struct
  type authorize = Session_state.t -> (unit, Agent_protocol.Error.t) result

  type _ t =
    | Definitions : Operator_authorization.t * authorize -> Recurrence_view.t list t
    | Query :
        Operator_authorization.t * authorize * Recurrence_query.request
        -> Recurrence_query.t t
    | Planning : Operator_authorization.t * authorize -> Recurrence_planning_read.t t
end

module Goal_request = struct
  type authorize = Session_state.t -> (unit, Agent_protocol.Error.t) result

  type _ t =
    | Initialization_completion :
        Initialization_scope.t
        -> Goal_callback_completion.t option t
    | Read : Operator_authorization.t * authorize -> Agent_protocol.Goal.t list t
    | Apply :
        Operator_authorization.t
        * authorize
        * Agent_protocol.Session_ref.t
        * Goal_command.t
        -> Goal_command_receipt.t t
end

type _ request =
  | Goal_request : 'a Goal_request.t -> 'a request
  | Child_accounting : 'a Child_accounting_request.t -> 'a request
  | Native_goal : 'a Native_goal_request.t -> 'a request
  | Open_inference_owner :
      Run_preparation.t option * Transcript.Source_id.t
      -> Inference_owner.t request
  | Admit_inference :
      Run_preparation.t option
      * Inference_owner.t
      * Transcript.Scope.relation
      * Agent_protocol.Id.Operation.t option
      * Agent_protocol.Id.Invocation.t option
      * Inference.Observation.Configuration.t
      -> Inference_ledger.Handle.t request
  | Allocate_inference :
      inference_execution
      * Inference_owner.t
      * Transcript.Scope.relation
      * Inference.Observation.Configuration.t
      -> Inference_allocation.t request
  | Admit_model_job :
      inference_execution * Agent_protocol.Job.t
      -> Agent_protocol.Job.t request
  | Refresh_inference : Admitted_inference.t -> (unit -> unit) request
  | Acknowledge_inference :
      Run_preparation.t option
      * Inference_owner.t
      * Inference_ledger.Handle.t
      * Inference_runtime.Attempt.t
      -> unit request
  | Observe_inference :
      Run_preparation.t option * Inference_ledger.Handle.t * Inference.Observation.t
      -> unit request
  | Observe_owned_inference :
      Run_preparation.t option * Inference_owner.t * Inference.Observation.t
      -> unit request
  | Complete_inference :
      Run_preparation.t option
      * Inference_owner.t
      * Inference_ledger.Handle.t
      * Inference_client.Completion.t
      -> unit request
  | Release_inference :
      Run_preparation.t option * Inference_owner.t * Inference_ledger.Handle.t
      -> unit request
  | Seal_inference_owner : Inference_owner.t -> unit request
  | Finish_inference_owner : Run_preparation.t option * Inference_owner.t -> unit request
  | Reconcile_inference_recovery : unit request
  | Claim_delegated_event :
      Agent_protocol.Id.Moderator_execution.t
      * Agent_protocol.Moderator_execution.delegation
      * Session.Moderator_state.Identity_snapshot.t
      * Chat_response.Moderation.Event.t
      -> delegated_event_claim request
  | Claim_job_moderator :
      job_scope * Agent_protocol.Invocation.t
      -> moderator_borrow request
  | Claim_job_event :
      job_scope
      * Agent_protocol.Id.Moderator_execution.t
      * Session.Moderator_state.Identity_snapshot.t
      * Chat_response.Moderation.Event.t
      -> queued_event_borrow option request
  | Manage_moderator_follow_up :
      Agent_protocol.Id.Operation.t * Agent_protocol.Invocation.observer
      -> unit request
  | Admit_moderator_turn : Agent_protocol.Id.Operation.t -> unit request
  | Admit_notification_turn : Agent_protocol.Id.Operation.t -> unit request
  | Claim_ordinary_event :
      Agent_protocol.Id.Moderator_execution.t
      * Agent_protocol.Id.Operation.t option
      * Session.Moderator_state.Identity_snapshot.t
      * Chat_response.Moderation.Event.t
      -> queued_event_borrow option request
  | Claim_queued_event :
      Agent_protocol.Id.Moderator_execution.t
      * Agent_protocol.Id.Operation.t option
      * Session.Moderator_state.Identity_snapshot.t
      -> queued_event_borrow option request
  | Claim_legacy_callback :
      Chat_response.Moderator_manager.Callback.t * legacy_callback_parent
      -> Callback_scope.t option request
  | Claim_initialization_callback :
      Initialization_scope.t
      * Chat_response.Moderator_manager.t
      * Chat_response.Moderator_manager.Callback.t
      -> Callback_scope.t option request
  | Retire_initialization_resource :
      Initialization_scope.t * Chat_response.Moderator_manager.t
      -> unit request
  | Claim_queued_retirement :
      Agent_protocol.Id.Moderator_execution.t
      * Session.Moderator_state.Identity_snapshot.t
      * string
