      Initialization_scope.t
      * Agent_protocol.Id.Job.t
      * int
      * int
      * Runtime_builder.model_job_outcome
      -> Agent_protocol.Job.t request
  | Add_job : Agent_protocol.Job.t -> Agent_protocol.Job.t request
  | Read_job : Agent_protocol.Id.Job.t -> Agent_protocol.Job.t request
  | Publish_job_progress :
      Agent_protocol.Id.Invocation.t * Ochat_function.Progress.t
      -> unit request
  | Claim_job :
      Job_claim_purpose.t * Agent_protocol.Id.Job.t * int
      -> Agent_protocol.Job.t option request
  | Complete_job :
      Agent_protocol.Id.Job.t * int * int * Runtime_builder.model_job_outcome
      -> Agent_protocol.Job.t request
  | Complete_background_job :
      Agent_protocol.Id.Job.t * int * int * Agent_protocol.Completion.t
      -> Agent_protocol.Job.t request
  | Defer_background_job :
      Agent_protocol.Id.Job.t * int * int * Agent_protocol.Job.dependency
      -> Agent_protocol.Job.t request
  | Refresh_background_job :
      Agent_protocol.Id.Job.t * int * int
      -> Agent_protocol.Job.t request
  | Recover_background_results : int * int -> unit request
  | Deliver_job :
      Agent_protocol.Id.Job.t
      * int
      * Session.Moderator_state.Identity_snapshot.t option
      * Agent_protocol.Job.t option
      * Jsonaf.t option
      * Chat_response.Moderator_manager.t option
      -> Agent_protocol.Job.t request
  | Enqueue_run_job_delivery :
      Run_job_delivery.t * Session.Moderator_state.Identity_snapshot.t * Jsonaf.t
      -> unit request
  | Cancel_job_internal : Agent_protocol.Id.Job.t -> Agent_protocol.Job.t request
  | Cancel_job :
      Agent_protocol.Id.Attachment.t * Agent_protocol.Id.Job.t * int option * int option
      -> Agent_protocol.Job.t request
  | Interrupt_job :
      Agent_protocol.Id.Job.t * int * int * string
      -> Agent_protocol.Job.t request
  | Change_schedule :
      Agent_protocol.Id.Attachment.t
      * [ `Created | `Cancelled ]
      * Agent_protocol.Schedule.t
      -> Agent_protocol.Session.t request
  | Add_schedule : Agent_protocol.Schedule.t -> Agent_protocol.Schedule.t request
  | Callback_schedule_after_ms :
      Callback_scope.t * int * Jsonaf.t
      -> Agent_protocol.Schedule.t request
  | Callback_schedule_cancel :
      Callback_scope.t * Agent_protocol.Id.Schedule.t
      -> Agent_protocol.Schedule.t request
  | Cancel_schedule :
      Agent_protocol.Id.Attachment.t * Agent_protocol.Id.Schedule.t * int option
      -> Agent_protocol.Schedule.t request
  | Cancel_schedule_internal :
      Agent_protocol.Id.Schedule.t
      -> Agent_protocol.Schedule.t request
  | Claim_schedule :
      Agent_protocol.Id.Schedule.t * int
      -> Agent_protocol.Schedule.t option request
  | Due_schedules :
      (Agent_protocol.Session.observed_state * Agent_protocol.Schedule.t list) request
  | Retry_schedule :
      Agent_protocol.Id.Schedule.t * int
      -> Agent_protocol.Schedule.t request
  | Complete_schedule :
      Agent_protocol.Id.Schedule.t
      * int
      * Session.Moderator_state.Identity_snapshot.t option
      * Agent_protocol.Schedule.t option
      * Jsonaf.t option
      * Chat_response.Moderator_manager.t option
      -> Agent_protocol.Schedule.t request
  | Prepare_ingress_submission :
      Agent_protocol.Invocation.observer
      * Agent_protocol.Id.Principal.t
      * Agent_protocol.Id.Capability.t
      * string
      * Agent_protocol.Idempotency_key.t
      * Jsonaf.t
      -> Ingress_submission.decision request
  | Commit_ingress_submission :
      Ingress_submission.t
      * Session.Moderator_state.Identity_snapshot.t
      * Session.Moderator_state.Identity_snapshot.t
      -> External_ingress.receipt request
  | Fail_schedule :
      Agent_protocol.Id.Schedule.t * int * Agent_protocol.Error.t
      -> Agent_protocol.Schedule.t request
  | Skip_schedule :
      Agent_protocol.Id.Schedule.t * int
      -> Agent_protocol.Schedule.t request
  | Claim_idle_moderator : History_entry.t list option request
  | Apply_observation_follow_up : bool request
  | Complete_idle_moderator : Runtime_builder.moderator_drain -> unit request
  | Fail_idle_moderator : Agent_protocol.Error.t -> unit request
  | Expire_permission :
      Agent_protocol.Id.Permission.t * int * Agent_protocol.Permission.choice
      -> unit request
  | Attach :
      (Agent_protocol.Session.attachment_mode
      * bool
      * Agent_protocol.Id.Principal.t option
      * string option)
      -> (Agent_protocol.Session.Attachment.t
         * Subscriber.t option
         * Agent_protocol.Snapshot.t
         * string option)
           request
  | Detach : Agent_protocol.Id.Attachment.t -> unit request
  | Renew_owner :
      Agent_protocol.Id.Attachment.t * int64
      -> (Agent_protocol.Session.Owner_lease.t * Agent_protocol.Session.t) request
  | Owner_expired : int64 -> unit request
  | Checkpoint :
      (Session_state.t -> (unit, Agent_protocol.Error.t) result)
      -> unit request
  | Quiescent_checkpoint :
      (Session_state.t -> ('a, Agent_protocol.Error.t) result)
      -> 'a option request
  | Shutdown : unit request

and compaction_outcome =
  | Compacted of History_entry.t list
  | Compaction_cancelled of string
  | Compaction_failed of Agent_protocol.Error.t

type packed =
  | Pack :
      Document_schema.Document.t option * 'a request * 'a Actor_reply.t Eio.Promise.u
      -> packed

type permission_waiter =
  { resolver : Agent_protocol.Permission.resolution Eio.Promise.u
  ; resume_observed : Agent_protocol.Session.observed_state
  }

type t =
  { sw : Eio.Switch.t
  ; sleep : float -> unit
  ; mailbox : packed Mailbox.t
  ; finished : unit Eio.Promise.t
  ; persistence : persistence
  ; services : services
  ; subscriber_mutex : Eio.Mutex.t
  ; active_calls : Active_calls.t
  ; subscribers : (Agent_protocol.Id.Attachment.t, Subscriber.t) Map.Poly.t ref
  ; permission_waiters :
      (Agent_protocol.Id.Permission.t, permission_waiter) Map.Poly.t ref
  ; lifecycle_owner : unit ref
  ; mutable lifecycle_fence : Lifecycle_fence.t option
  ; mutable organization_admission : Session_organization_admission.t option
  ; mutable configuration_policy : Configuration_policy.t option
  ; mutable recurrence_controller : Recurrence_controller.t option
  ; recurrence_runtime : Recurrence_runtime.t
  ; recurrence_creation_owner : unit ref
  ; recurrence_activation_owner : Activation_custody.Owner.t
  ; mutable recurrence_activations : Activation_custody.t list
  ; configuration_update_owner : Configuration_update.Owner.t
  ; configuration_capture : Configuration_capture.t
  ; mutable operation_worker : Operation_worker.t option
  ; mutable compaction_inference : Compaction_inference.t option
  ; mutable inference_execution : Inference_client.Execution.t option
  ; mutable moderator_manager : Chat_response.Moderator_manager.t option
  ; compaction_env : Eio_unix.Stdenv.base option
  ; owner_lease_duration_ms : int
  ; max_attachments : int
  ; subscriber_capacity : int
  ; schedule_permission_timeouts : bool
  ; mutable owner_timer_cancel : unit Eio.Promise.u option
  ; mutable active_cancel : (unit -> unit) option
  ; mutable runtime_retirement : runtime_retirement option
  ; mutable idle_moderator_borrowed : bool
  ; mutable moderator_borrow : moderator_borrow option
  ; mutable queued_event_borrow : queued_event_borrow option
  ; mutable legacy_callback_scope : Callback_scope.t option
  ; mutable legacy_queue_custody : Legacy_queue_custody.t
  ; mutable legacy_schedule_custody : Legacy_schedule_custody.t
  ; mutable operation_agent_custody : Operation_owner.t option
  ; mutable lifecycle_agent_custody : lifecycle_agent_custody
  ; mutable intent_agent_custody : agent_intent_custody list
  ; mutable pending_agent_custody : (Agent_protocol.History.entry * agent_custody) list
  ; mutable job_agent_custody : Job_custody.t
  ; mutable run_authorities : Run_authorities.t
  ; runtime_source_owner : Runtime_source_owner.Identity.t option
  ; ordinary_execution_admission : unit -> (unit, Agent_protocol.Error.t) result
  ; runtime_source_domain : int
  ; run_preparation_owner : Run_preparation.Owner.t
  ; mutable run_preparation : Preparation_owner.t option
    (* Latest negative-only attempt cell survives logical prep/source closure.
     It grants no admission or execution rights and never accumulates. *)
  ; mutable effect_deferred : Deferred_owner.t option
  ; mutable run_source_binding : Source_binding.t option
  ; mutable held_activation : Held_run.Activation.t option
  ; mutable held_input_scope : Held_input_scope.t option
  ; mutable held_authored_start : Held_authored_start.t option
  ; mutable foreground_moderator :
      (Agent_protocol.Id.Operation.t * Agent_protocol.Invocation.observer) option
  ; mutable invocation_executions : invocation_execution list
  ; inference_owner_identity : unit ref
  ; mutable inference_owners : Inference_owner.t list
  ; initialization_owner : unit ref
  ; mutable initialization_scope : Initialization_scope.t option
  ; mutable job_scopes : job_scope list
  ; staged_jobs : Job_custody.Fresh.t option Staged_jobs.t
  ; staged_subscriptions : Staged_subscriptions.t
  ; staged_ingress : Staged_ingress.t
  ; staged_schedules : Staged_schedules.t
  ; staged_notifications : Staged_notifications.t
  ; mutable notification_inputs :
      (Agent_protocol.Id.Operation.t * Agent_protocol.Id.Delivery.t list) option
  ; extension_clock : Extension_clock.t
  ; invocation_gate : Chat_response.Execution_gate.t
  ; event_sequence : int64 Atomic.t
  ; mutable state : Session_state.t
  ; mutable stopped : bool
  ; mutable command_audit : Document_schema.Document.t option
  }

let error code message = Agent_protocol.Error.create code ~message ~retryable:false ()
let initial_run_preparation t = Option.bind t.run_preparation ~f:Preparation_owner.initial

let exclude_effect_deferred t reason =
  match t.effect_deferred with
  | None -> ()
  | Some (Ordinary deferred) ->
    Run_preparation.Deferred.exclude deferred ~reason;
    t.effect_deferred <- None
  | Some (Retry retry) ->
    Run_preparation.Deferred.exclude retry.deferred ~reason;
    (* Retain this negative-only phase while the captured preparation can still
       be presented through ordinary APIs. Exclusion cannot turn it executable. *)
    (match retry.phase with
     | Acknowledged _ -> ()
     | _ -> retry.phase <- Invalid)
;;

let retry_for_preparation t preparation =
  match t.effect_deferred with
  | Some (Retry retry)
    when phys_equal (Run_preparation.Deferred.preparation retry.deferred) preparation ->
    Some retry
  | Some (Ordinary _ | Retry _) | None -> None
;;

let check_retry_execution t preparation =
  match retry_for_preparation t preparation with
  | None -> Ok ()
  | Some { phase = Acknowledged (Some _, _); _ } -> Ok ()
  | Some _ -> Error (error Conflict "retry preparation requires its controller ACK")
;;

let agent_source_current t generation source =
  Int.equal generation t.state.identity.generation
  && (not t.stopped)
  && Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running
  &&
  match Runtime_builder.moderator_snapshot_observer t.state.moderator with
  | Error _ -> false
  | Ok current -> Option.equal Agent_protocol.Invocation.equal_observer source current
;;

let observation_source t =
  match t.state.run_state with
  | None -> Ok None
  | Some index ->
    let installation = Run_state.installation index in
    (match installation.Run_source_installation.source with
     | None -> Ok None
     | Some _ ->
       Run_source_installation.captured
         installation
         ~generation:t.state.identity.generation
       |> Result.map ~f:Option.some)
;;

let observation_pending (invocation : Agent_protocol.Invocation.t) =
  match invocation.observation with
  | Some { status = Awaiting | Observing; _ } -> true
  | Some
      { status = Observed
      ; follow_up = Some (Pending_follow_up _ | Compaction_accepted_follow_up _)
      ; _
      } -> true
  | None
  | Some
      { status = Observed
      ; follow_up = None | Some (Applied_follow_up _ | Discarded_follow_up _)
      ; _
      }
  | Some { status = Observation_failed _; _ } -> false
;;

let retire_instruction_continuations t =
  (match t.lifecycle_agent_custody with
   | Unadmitted -> ()
   | Admitted { pending = Pending admission; _ } -> retire_agent_admission admission
   | Admitted { pending = Consumed; _ } -> ());
  t.lifecycle_agent_custody <- Unadmitted;
  List.iter t.intent_agent_custody ~f:(fun entry ->
    Option.iter entry.custody ~f:retire_agent_custody;
    Option.iter entry.observation ~f:Observation_continuation.retire;
    Option.iter entry.native_goal ~f:(fun native ->
      Goal_native_actions.Entry.discard native.entry));
  t.intent_agent_custody <- []
;;

let retain_instruction_continuations t =
  (match t.lifecycle_agent_custody with
   | Admitted { generation; source; _ }
     when not (agent_source_current t generation source) ->
     retire_instruction_continuations t
   | Unadmitted | Admitted _ -> ());
  let current_source = observation_source t in
  let current_observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  t.intent_agent_custody
  <- List.filter_map t.intent_agent_custody ~f:(fun entry ->
       let invocation =
         match entry.key with
         | Event_intent _ -> None
         | Invocation_intent id ->
           List.find t.state.invocations ~f:(fun invocation ->
             Agent_protocol.Id.Invocation.equal invocation.context.id id)
       in
       let follow_up =
         agent_source_current t entry.generation entry.source
         &&
         match entry.key with
         | Event_intent id ->
           List.exists t.state.moderator_executions ~f:(fun receipt ->
             Agent_protocol.Id.Moderator_execution.equal receipt.context.id id
             && Observation_follow_up.pending_event receipt)
         | Invocation_intent _ ->
           Option.exists invocation ~f:Observation_follow_up.pending
       in
       let observation =
         Option.bind entry.observation ~f:(fun observation ->
           let retained =
             (not t.stopped)
             && Int.equal entry.generation t.state.identity.generation
             &&
             match current_source, current_observer, invocation with
             | Ok source, Ok observer, Some invocation ->
               Option.equal Agent_protocol.Invocation.equal_observer entry.source observer
               && observation_pending invocation
               && Observation_continuation.matches observation ~source invocation
             | (Error _ | Ok _), (Error _ | Ok _), (None | Some _) -> false
           in
           if retained
           then Some observation
           else (
             Observation_continuation.retire observation;
             None))
       in
       let native_goal =
         Option.bind entry.native_goal ~f:(fun native ->
           let retained =
             (not t.stopped)
             && agent_source_current t entry.generation entry.source
             && Option.exists invocation ~f:(fun invocation ->
               Option.exists
                 invocation.Agent_protocol.Invocation.native_goal_resume
                 ~f:(fun intent ->
                   match Agent_protocol.Goal_native_resume_intent.phase intent with
                   | Accepted _ | Dispatch_claimed _ -> true
                   | Staged | Discarded _ | Rejected _ -> false))
           in
           if retained
           then Some native
           else (
             Goal_native_actions.Entry.discard native.entry;
             None))
       in
       if not follow_up then Option.iter entry.custody ~f:retire_agent_custody;
       if follow_up || Option.is_some observation || Option.is_some native_goal
       then
         Some
           { entry with
             custody = (if follow_up then entry.custody else None)
           ; observation
           ; native_goal
           }
       else None)
;;

(* Retention uses actual installation facts, independently of whether this
   resource is currently eligible to execute. It cannot capture a new source. *)
let retained_moderator_source (state : Session_state.t) =
  match state.run_state with
  | None -> None
  | Some index ->
    let source =
      let open Result.Let_syntax in
      let%bind observer = Moderator_checkpoint.observer state.moderator in
      let%bind source =
        Run_source_installation.captured
          (Run_state.installation index)
          ~generation:state.identity.generation
      in
      if
        Option.equal
          Agent_protocol.Invocation.equal_observer
          observer
          (Some source.observer)
      then Ok source
      else Error (error Conflict "retained moderator source differs from installation")
    in
    (match source with
     | Ok source -> Some source
     | Error _ -> None)
;;

let retained_agent_custody t =
  retain_instruction_continuations t;
  let metadata =
    match Moderator_checkpoint.queue t.state.moderator with
    | Ok metadata -> metadata
    | Error _ -> None
  in
  let source = retained_moderator_source t.state in
  t.legacy_queue_custody
  <- Legacy_queue_custody.install
       t.legacy_queue_custody
       ~incoming:
         (Legacy_queue_custody.retain_facts t.legacy_queue_custody ~source ~metadata);
  t.legacy_schedule_custody
  <- Legacy_schedule_custody.install
       t.legacy_schedule_custody
       ~incoming:
         (Legacy_schedule_custody.retain_facts
            t.legacy_schedule_custody
            ~source
            ~schedules:t.state.schedules);
  let operation_current id =
    (not t.stopped)
    && Option.exists t.state.active_operation ~f:(fun operation ->
      Agent_protocol.Id.Operation.equal operation.id id
      &&
      match operation.state with
      | Starting | Running -> true
      | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ -> false)
  in
  (match t.operation_agent_custody with
   | Some ({ Operation_owner.operation_id = id; _ } as owner)
     when not (operation_current id) ->
     Operation_owner.retire owner;
     t.operation_agent_custody <- None
   | Some _ | None -> ());
  t.job_agent_custody
  <- Job_custody.install_retained
       t.job_agent_custody
       ~incoming:
         (if t.stopped
          then Job_custody.empty
          else Job_custody.retain t.job_agent_custody ~jobs:t.state.jobs)
;;

let operation_agent_actor t id =
  match t.operation_agent_custody with
  | Some { Operation_owner.operation_id = owner; admission; _ }
    when Agent_protocol.Id.Operation.equal owner id ->
    (match Execution_custody.Admission.custody admission with
     | Some custody -> Result.map (Execution_custody.actor custody) ~f:Option.some
     | None -> Ok None)
  | Some _ | None -> Ok None
;;

let install_operation_agent_custody t operation custody =
  Option.iter t.operation_agent_custody ~f:Operation_owner.retire;
  t.operation_agent_custody
  <- Some
       { Operation_owner.operation_id = operation.Agent_protocol.Operation.id
       ; admission = create_agent_admission custody
       ; held = None
       }
;;

let job_scope_current t scope =
  match
    ( List.mem t.job_scopes scope ~equal:phys_equal
    , List.find t.state.jobs ~f:(fun job ->
        Agent_protocol.Id.Job.equal job.id scope.job.id) )
  with
  | true, Some job
    when Int.equal job.generation scope.job.generation
         && Int.equal job.generation t.state.identity.generation
         && Int.equal job.attempt scope.job.attempt
         && Agent_protocol.Job.equal_kind job.kind scope.job.kind
         && Jsonaf.exactly_equal job.payload scope.job.payload -> Ok job
  | _ -> Error (error Conflict "background callback no longer owns this job attempt")
;;

let job_scope_can_execute t scope =
  let open Result.Let_syntax in
  let%bind job = job_scope_current t scope in
  match job.status, t.state.lifecycle.desired, t.state.halted, t.state.failure with
  | (Running | Waiting_permission _), Running, false, None
    when scope.active
         && (not scope.cancel_requested)
         && Option.for_all scope.deadline ~f:(fun deadline ->
           Agent_protocol.Timestamp.compare (t.services.now ()) deadline < 0) -> Ok ()
  | _ -> Error (error Conflict "background job cannot admit another invocation")
;;

let job_execution_owned_by scope execution =
  match execution.owner with
  | Background_job owner -> phys_equal owner scope
  | Event_moderator borrow -> Option.exists borrow.job_scope ~f:(phys_equal scope)
  | Invocation_moderator borrow -> Option.exists borrow.job_scope ~f:(phys_equal scope)
  | _ -> false
;;

let signal_job_scope scope =
  match Eio.Promise.peek scope.cancelled with
  | Some () -> ()
  | None -> Eio.Promise.resolve scope.cancel_signal ()
;;

let cancel_job_scope (scope : job_scope) =
  scope.cancel_requested <- true;
  Atomic.set scope.authority_live false;
  signal_job_scope scope;
  Option.iter scope.cancel ~f:(fun cancel -> cancel ())
;;

let cancel_job_moderators t scope =
  Option.iter t.moderator_borrow ~f:(fun borrow ->
    match Option.exists borrow.job_scope ~f:(phys_equal scope) with
    | false -> ()
    | true ->
      borrow.cancel_requested <- true;
      borrow.accepts_children <- false;
      Atomic.set borrow.authority_live false;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ()));
  Option.iter t.queued_event_borrow ~f:(fun borrow ->
    match Option.exists borrow.job_scope ~f:(phys_equal scope) with
    | false -> ()
    | true ->
      borrow.cancel_requested <- true;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ()))
;;

let job_has_moderator t scope =
  Option.exists t.moderator_borrow ~f:(fun borrow ->
    Option.exists borrow.job_scope ~f:(phys_equal scope))
  || Option.exists t.queued_event_borrow ~f:(fun borrow ->
    Option.exists borrow.job_scope ~f:(phys_equal scope))
;;

let cancel_job_scopes t jobs =
  List.iter t.job_scopes ~f:(fun scope ->
    match
      List.exists jobs ~f:(fun (job : Agent_protocol.Job.t) ->
        Agent_protocol.Id.Job.equal job.id scope.job.id
        && Int.equal job.generation scope.job.generation
        && Int.equal job.attempt scope.job.attempt)
    with
    | true ->
      cancel_job_scope scope;
      cancel_job_moderators t scope
    | false -> ())
;;

let moderator_is_borrowed t =
  Option.is_some t.moderator_borrow || Option.is_some t.queued_event_borrow
;;

let call t ?(priority = Mailbox.Normal) ?command_audit request =
  let promise, resolver = Eio.Promise.create () in
  let open Result.Let_syntax in
  let%bind () =
    Mailbox.push t.mailbox ~priority (Pack (command_audit, request, resolver))
  in
  Actor_reply.await promise
;;

let publish_durable t events =
  Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
    List.iter events ~f:(Active_calls.finish t.active_calls);
    Map.iter !(t.subscribers) ~f:(fun subscriber ->
      List.iter events ~f:(Subscriber.publish_durable subscriber)))
;;

let broadcast_recoverable t event =
  Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
    Active_calls.observe t.active_calls event;
    Map.iter !(t.subscribers) ~f:(fun subscriber ->
      Subscriber.publish_recoverable subscriber event))
;;

let sync_extension_clock t =
  let timers =
    t.state.schedules @ Staged_schedules.values t.staged_schedules
    |> List.filter_map ~f:(fun timer ->
      match timer.Agent_protocol.Schedule.ownership, timer.status with
      | Some _, (Scheduled | Delivering) ->
        Some (Extension_clock.Key.Schedule timer.id, timer.next_due_at)
      | _ -> None)
  in
  let subscriptions =
    t.state.subscriptions @ Staged_subscriptions.values t.staged_subscriptions
    |> List.filter_map ~f:(fun subscription ->
      match
        subscription.Agent_protocol.Subscription.context.source, subscription.result
      with
      | Some _, None ->
        Some
          ( Extension_clock.Key.Subscription subscription.context.id
          , subscription.context.deadline )
      | _ -> None)
  in
  Extension_clock.reconcile
    t.extension_clock
    ~retained:(timers @ subscriptions)
    ~wall_now:(t.services.now ())
    ~monotonic_now:(t.services.monotonic_now ())
;;

let check_held_effect continuation =
  let open Result.Let_syntax in
  let target = Admitted_activation.Continuation.target continuation in
  let%bind () = Admitted_activation.Continuation.check_basis continuation in
  let%bind () = Admitted_activation.Continuation.check_policy continuation in
  let%bind () = Admitted_activation.Continuation.check_timing continuation in
  let%bind () = Admitted_activation.Continuation.check_authority continuation in
  let%bind () = Held_run.Activation.check_basis target in
  Admitted_activation.Continuation.check_basis continuation
;;

let check_runtime_construction_effect construction =
  let open Result.Let_syntax in
  let%bind () = Runtime_construction.check_basis construction in
  let%bind () = Runtime_construction.check_policy construction in
  let%bind () = Runtime_construction.check_timing construction in
  let%bind () = Runtime_construction.check_authority construction in
  Runtime_construction.check_basis construction
;;

let held_authored_basis t (scope : Held_authored_start.t) =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () =
    if
      Int.equal scope.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
      && Option.exists t.held_authored_start ~f:(phys_equal scope)
      && Option.exists t.held_activation ~f:(phys_equal activation)
      && Option.exists
           t.operation_worker
           ~f:(phys_equal (Runtime_builder.Authored_start.worker scope.startup))
      && Option.equal
           phys_equal
           t.moderator_manager
           (Runtime_builder.Authored_start.manager scope.startup)
      && Run_authorities.is_current
           t.run_authorities
           scope.binding
           ~run_id:activation.run.id
    then Ok ()
    else Error (error Conflict "held authored startup owner or runtime changed")
  in
  let%bind () =
    match scope.phase with
    | Starting | Ready | Executing _ | Completed _ -> Ok ()
    | Staged | Released | Attempt_unconfirmed | Closed ->
      Error (error Conflict "held authored startup is not live")
  in
  activation.owned_basis ()
;;

let held_authored_run t scope =
  let open Result.Let_syntax in
  let%bind () = held_authored_basis t scope in
  let activation =
    Admitted_activation.Continuation.target scope.Held_authored_start.continuation
  in
  Option.bind t.state.run_state ~f:(fun index -> Run_state.find index activation.run.id)
  |> Result.of_option ~error:(error Conflict "held authored Run is absent")
;;

let held_authored_event_basis t (borrow : queued_event_borrow) scope =
  let open Result.Let_syntax in
  let%bind () = held_authored_basis t scope in
  if
    Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
    && Option.exists
         (Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
         ~f:(phys_equal scope)
    && t.idle_moderator_borrowed
    && borrow.callback_active
    && Atomic.get borrow.authority_live
    && (not (borrow.committed || borrow.cancel_requested))
    && (match scope.Held_authored_start.phase with
        | Executing id ->
          Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        | Staged
        | Starting
        | Ready
        | Completed _
        | Released
        | Attempt_unconfirmed
        | Closed -> false)
    && List.exists t.state.moderator_executions ~f:(fun retained ->
      Agent_protocol.Moderator_execution.equal_context
        retained.context
        borrow.receipt.context
      &&
      match retained.status with
      | Running -> true
      | Completed _ | Failed _ | Interrupted _ -> false)
  then Ok ()
  else Error (error Conflict "held authored Event is no longer current")
;;

(* The payload is retained by the one actual preparation phase. This predicate
   authenticates a physical runtime/callback; it grants no fresh effect right. *)
let goal_runtime_scope_basis t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let preparation = scope.continuation.binding.preparation in
  let%bind () =
    if
      Int.equal preparation.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
      && Run_preparation.Custody.belongs_to
           (Goal_continuation.custody preparation)
           ~owner:t.run_preparation_owner
      && Option.exists t.operation_worker ~f:(phys_equal scope.worker)
      && Option.equal phys_equal t.moderator_manager scope.manager
      &&
      match preparation.runtime_phase with
      | Installed current | Callback_completed current -> phys_equal current scope
      | Handed_off (current, _) | Retired current -> phys_equal current scope
      | _ -> false
    then Ok ()
    else Error (error Conflict "Goal resume runtime owner changed")
  in
  Runtime_source_preparation.validate_target scope.continuation.binding.source t.state
;;

let select_goal_runtime t continuation =
  let open Result.Let_syntax in
  let preparation = continuation.Goal_continuation.binding.preparation in
  let%bind scope =
    match preparation.runtime_phase with
    | (Installed scope | Callback_completed scope | Handed_off (scope, _) | Retired scope)
      when phys_equal scope.continuation continuation -> Ok scope
    | _ -> Error (error Conflict "Goal continuation has no exact installed runtime")
  in
  let%map () = goal_runtime_scope_basis t scope in
  scope
;;

let goal_runtime_run t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  Option.bind t.state.run_state ~f:(fun index ->
    Run_state.find index scope.continuation.binding.preparation.run.id)
  |> Result.of_option ~error:(error Conflict "Goal resume Run is absent")
;;

let goal_runtime_event_basis t (borrow : queued_event_borrow) scope =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  if
    Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
    && Option.exists borrow.lifecycle_owner ~f:(function
      | Existing_goal_resume current -> phys_equal current scope
      | Initial_authored _ -> false)
    && t.idle_moderator_borrowed
    && borrow.callback_active
    && Atomic.get borrow.authority_live
    && (not (borrow.committed || borrow.cancel_requested))
    && (match scope.Goal_continuation.callback with
        | Executing id ->
          Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        | Pending | Completed _ | Joined -> false)
    && List.exists t.state.moderator_executions ~f:(fun retained ->
      Agent_protocol.Moderator_execution.equal_context
        retained.context
        borrow.receipt.context
      &&
      match retained.status with
      | Running -> true
      | _ -> false)
  then Ok ()
  else Error (error Conflict "Goal resume Event is no longer current")
;;

let goal_wake_transferred_borrow t (preparation : Goal_continuation.Preparation.t) =
  match preparation.runtime_phase with
  | Handed_off (scope, Existing_execution (Queued_event executing)) ->
    phys_equal scope.continuation.binding.preparation preparation
    && Option.exists t.queued_event_borrow ~f:(fun borrow ->
      Agent_protocol.Moderator_execution.equal_context
        borrow.receipt.context
        executing.context
      && Result.is_ok (goal_runtime_event_basis t borrow scope))
  | Unclaimed
  | Starting_writer _
  | Starting_acknowledged
  | Running_writer _
  | Constructing
  | Installed _
  | Callback_completed _
  | Retired _
  | Closed
  | Handed_off (_, Resume _)
  | Handed_off
      ( _
      , Existing_execution
          ( Subscription_turn _
          | Claimed_job_resource _
          | Lifecycle_wait _
          | Lifecycle_settlement _ ) ) -> false
;;

let lifecycle_event_basis t borrow = function
  | Lifecycle_callback_owner.Initial_authored scope ->
    held_authored_event_basis t borrow scope
  | Existing_goal_resume scope -> goal_runtime_event_basis t borrow scope
;;

let lifecycle_event_effect t borrow owner =
  let open Result.Let_syntax in
  let%bind () = lifecycle_event_basis t borrow owner in
  let%bind () =
    match owner with
    | Lifecycle_callback_owner.Initial_authored scope ->
      check_held_effect scope.continuation
    | Existing_goal_resume scope ->
      check_runtime_construction_effect (Existing_goal scope.continuation)
  in
  lifecycle_event_basis t borrow owner
;;

let lifecycle_event_run t borrow owner =
  let open Result.Let_syntax in
  let%bind () = lifecycle_event_basis t borrow owner in
  match owner with
  | Lifecycle_callback_owner.Initial_authored scope -> held_authored_run t scope
  | Existing_goal_resume scope -> goal_runtime_run t scope
;;

let goal_runtime_of_borrow (borrow : queued_event_borrow) =
  Option.bind borrow.lifecycle_owner ~f:(function
    | Lifecycle_callback_owner.Existing_goal_resume scope -> Some scope
    | Initial_authored _ -> None)
;;

let goal_runtime_scope t =
  Option.bind t.run_preparation ~f:(function
    | Existing_goal preparation ->
      (match preparation.runtime_phase with
       | Installed scope | Callback_completed scope -> Some scope
       | _ -> None)
    | Initial _ | Delegated_load _ -> None)
;;

let goal_runtime_job t (job : Agent_protocol.Job.t) =
  Option.bind (goal_runtime_scope t) ~f:(fun scope ->
    Option.some_if
      (List.exists scope.jobs ~f:(fun owned ->
         Agent_protocol.Id.Job.equal owned.id job.id
         && Int.equal owned.generation job.generation))
      scope)
;;

let held_authored_factual_preparation t (scope : Held_authored_start.t) =
  let preparation =
    (Admitted_activation.Continuation.target scope.continuation).preparation
  in
  if
    phys_equal scope.issuing_actor t.inference_owner_identity
    && Option.exists t.held_authored_start ~f:(phys_equal scope)
    && Option.exists (initial_run_preparation t) ~f:(phys_equal preparation)
    && Result.is_ok
         (Run_preparation.check_basis
            preparation
            ~owner:t.run_preparation_owner
            ~state:t.state)
  then Some preparation
  else None
;;

let held_authored_of_borrow _t (borrow : queued_event_borrow) =
  match Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial with
  | None -> None
  | Some scope -> Some scope
;;

let held_authored_job t (job : Agent_protocol.Job.t) =
  Option.bind t.held_authored_start ~f:(fun scope ->
    Option.some_if
      ((match scope.Held_authored_start.phase with
        | Starting | Ready | Executing _ | Completed _ -> true
        | Staged | Released | Attempt_unconfirmed | Closed -> false)
       && List.exists scope.Held_authored_start.jobs ~f:(fun admitted ->
         Agent_protocol.Id.Job.equal admitted.id job.id
         && Int.equal admitted.generation job.generation
         && Agent_protocol.Job.equal_kind admitted.kind job.kind
         && Jsonaf.exactly_equal admitted.payload job.payload
         && Option.equal
              Agent_protocol.Job.Inference_origin.equal
              admitted.inference_origin
              job.inference_origin
         && Option.equal Agent_protocol.Job.equal_launch admitted.launch job.launch))
      scope)
;;

(* Scheduled descendants stay queued until this actual startup releases its
   hold. They cannot race target Store custody during the final handoff refresh.
   Synchronous Not_required calls still execute inside the owning callback. *)
let held_authored_job_deferred t (job : Agent_protocol.Job.t) =
  match job.status, job.delivery with
  | Queued, (Pending | Delivered _) ->
    Option.exists (held_authored_job t job) ~f:(fun scope ->
      Result.is_ok (held_authored_basis t scope))
  | Queued, (Not_required | Discarded _)
  | ( ( Running
      | Waiting_permission _
      | Waiting_completion _
      | Succeeded
      | Failed _
      | Cancelled
      | Interrupted _ )
    , _ ) -> false
;;

let held_authored_job_preparation t job =
  Option.bind (held_authored_job t job) ~f:(held_authored_factual_preparation t)
;;

let held_authored_of_execution t = function
  | Inference_event borrow -> held_authored_of_borrow t borrow
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow -> held_authored_of_borrow t borrow
     | Background_job scope -> held_authored_job t scope.job
     | Foreground _ | Invocation_moderator _ -> None)
  | Inference_job scope -> held_authored_job t scope.job
  | Inference_moderator borrow ->
    Option.bind borrow.job_scope ~f:(fun scope -> held_authored_job t scope.job)
  | Inference_operation _
  | Inference_held_input _
  | Inference_initialization _
  | Inference_initialization_job _ -> None
;;

let held_authored_handoff_acknowledged (scope : Held_authored_start.t) =
  if not (Int.equal scope.domain (Stdlib.Domain.self () :> int))
  then false
  else (
    match
      scope.phase, !((Admitted_activation.Continuation.target scope.continuation).phase)
    with
    | Released, Handed_off (Authored_start proof) ->
      phys_equal proof.binding scope.binding
    | _ -> false)
;;

let refresh_held_authored t scope =
  let open Result.Let_syntax in
  if held_authored_handoff_acknowledged scope
  then Ok ()
  else (
    let%bind () = held_authored_basis t scope in
    let%bind () =
      Admitted_activation.Continuation.refresh scope.Held_authored_start.continuation
    in
    let%bind () = check_held_effect scope.continuation in
    held_authored_basis t scope)
;;

let initialization_construction_of_execution t = function
  | Inference_initialization scope | Inference_initialization_job (scope, _) ->
    if Option.exists t.initialization_scope ~f:(phys_equal scope)
    then Initialization_scope.construction scope
    else None
  | Inference_event borrow ->
    Option.bind t.legacy_callback_scope ~f:(fun callback ->
      if phys_equal callback.borrow borrow
      then Option.bind callback.constructor_scope ~f:Initialization_scope.construction
      else None)
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow ->
       Option.bind t.legacy_callback_scope ~f:(fun callback ->
         if phys_equal callback.borrow borrow
         then Option.bind callback.constructor_scope ~f:Initialization_scope.construction
         else None)
     | Foreground _ | Background_job _ | Invocation_moderator _ -> None)
  | Inference_operation _
  | Inference_held_input _
  | Inference_job _
  | Inference_moderator _ -> None
;;

let goal_runtime_of_execution t = function
  | Inference_event borrow -> goal_runtime_of_borrow borrow
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow -> goal_runtime_of_borrow borrow
     | Background_job job -> goal_runtime_job t job.job
     | Foreground _ | Invocation_moderator _ -> None)
  | Inference_job job -> goal_runtime_job t job.job
  | Inference_moderator borrow ->
    Option.bind borrow.job_scope ~f:(fun job -> goal_runtime_job t job.job)
  | Inference_operation _
  | Inference_held_input _
  | Inference_initialization _
  | Inference_initialization_job _ -> None
;;

let refresh_held_execution t execution =
  let open Result.Let_syntax in
  let%bind () =
    Option.value_map
      (held_authored_of_execution t execution)
      ~default:(Ok ())
      ~f:(refresh_held_authored t)
  in
  let%bind () =
    Option.value_map
      (goal_runtime_of_execution t execution)
      ~default:(Ok ())
      ~f:(fun scope -> Runtime_construction.refresh (Existing_goal scope.continuation))
  in
  match initialization_construction_of_execution t execution with
  | Some ((Runtime_construction.Existing_goal _ | Delegated_load _) as construction) ->
    Runtime_construction.refresh construction
  | Some (Initial _) | None -> Ok ()
;;

(* The supplied key selects an existing physical execution only. The actual
   mailbox operation still validates that owner and its current effect rights;
   an unmatched/ordinary key gains no startup authority from this refresh. *)
let refresh_held_background_owner t = function
  | Agent_protocol.Job.Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id ->
       refresh_held_execution t (Inference_event borrow)
     | None | Some _ -> Ok ())
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal id execution.dispatched.context.id)
     with
     | Some execution -> refresh_held_execution t (Inference_invocation execution)
     | None ->
       (match t.moderator_borrow with
        | Some borrow
          when Agent_protocol.Id.Invocation.equal id borrow.invocation.context.id ->
          refresh_held_execution t (Inference_moderator borrow)
        | None | Some _ -> Ok ()))
;;

let inference_port t execution ~graph ~relation ~configuration =
  let open Result.Let_syntax in
  let%bind () = refresh_held_execution t execution in
  call t (Allocate_inference (execution, graph, relation, configuration))
;;

let model_job_port t execution =
  Model_job_admission.Host.create ~admit:(fun job ->
    let%bind.Result () = refresh_held_execution t execution in
    Eio.Cancel.protect (fun () -> call t (Admit_model_job (execution, job))))
;;

(* Selected only at fresh-effect writers. Negative results carrying the SAME
   preparation do not enter this authorization stage. *)
let held_startup_effect t preparation =
  let authored =
    Option.bind t.held_authored_start ~f:(fun scope ->
      let activation = Admitted_activation.Continuation.target scope.continuation in
      if Option.exists preparation ~f:(phys_equal activation.preparation)
      then
        Some
          (fun () ->
            let open Result.Let_syntax in
            let%bind () = held_authored_basis t scope in
            let%bind () = check_held_effect scope.continuation in
            held_authored_basis t scope)
      else None)
  in
  match authored with
  | Some _ -> authored
  | None ->
    Option.bind t.initialization_scope ~f:(fun scope ->
      Option.bind
        (Initialization_scope.initial_continuation scope)
        ~f:(fun continuation ->
          let activation = Admitted_activation.Continuation.target continuation in
          if Option.exists preparation ~f:(phys_equal activation.preparation)
          then
            Some
              (fun () ->
                let open Result.Let_syntax in
                let%bind () = check_held_effect continuation in
                if
                  Option.exists t.initialization_scope ~f:(phys_equal scope)
                  && Option.exists t.held_activation ~f:(phys_equal activation)
                then
                  Run_preparation.check_basis
                    activation.preparation
                    ~owner:t.run_preparation_owner
                    ~state:t.state
                else Error (error Conflict "held Init effect owner changed"))
          else None))
;;

let close_run_preparation t =
  Option.iter t.held_authored_start ~f:(fun scope ->
    match scope.Held_authored_start.phase with
    | Released -> ()
    | Staged | Starting | Ready | Executing _ | Completed _ | Attempt_unconfirmed | Closed
      -> scope.phase <- Closed);
  Option.iter t.held_input_scope ~f:(fun scope -> scope.Held_input_scope.phase <- Closed);
  Option.iter t.held_activation ~f:Held_run.Activation.close;
  (* Closed startup disposition survives a failed factual retirement ACK. It
     cannot authorize effects; the exact retained Run is still pending retirement. *)
  t.held_activation
  <- Option.filter t.held_activation ~f:(fun activation ->
       Option.exists t.state.run_state ~f:(fun index ->
         Option.exists (Run_state.find index activation.run.id) ~f:(fun run ->
           match run.Agent_protocol.Run.lifecycle with
           | Admitted | Active | Waiting _ -> true
           | Terminal _ -> false)));
  Option.iter t.run_source_binding ~f:Source_binding.close;
  t.run_source_binding <- None;
  Option.iter t.run_preparation ~f:Preparation_owner.close;
  t.run_preparation <- None
;;

let close_bound_run_preparation t =
  if
    Option.is_some t.run_source_binding
    || Option.is_some t.held_activation
    || Option.exists t.run_preparation ~f:(function
      | Existing_goal _ -> true
      | Initial _ | Delegated_load _ -> false)
  then close_run_preparation t
;;

let pending_initial_startup_run t =
  Option.bind t.held_activation ~f:(fun activation ->
    let retained () =
      let open Result.Let_syntax in
      let%bind () =
        Runtime_source_preparation.validate_target activation.source t.state
      in
      let%bind index =
        Result.of_option
          t.state.run_state
          ~error:(error Conflict "held startup Run index is absent")
      in
      let%bind run =
        Result.of_option
          (Run_state.find index activation.run.id)
          ~error:(error Conflict "held startup Run is absent")
      in
      let%bind admission =
        Run_state.receipt
          index
          ~principal_id:activation.admission.principal_id
          ~key:activation.admission.key
          ~request_sha256:activation.admission.request_sha256
      in
      let%bind () =
        if
          Option.exists
            admission
            ~f:(Agent_protocol.Run_receipt.equal activation.admission)
        then Ok ()
        else Error (error Conflict "held startup Admission changed")
      in
      let%bind () =
        match activation.association.issuer_policy with
        | Recurrence ->
          let%bind origin =
            Result.of_option
              (Run_state.recurrence_origin index run.id)
              ~error:(error Conflict "held startup origin is absent")
          in
          Recurrence_run_origin.validate_run origin ~run ~admission:activation.admission
        | Goal policy ->
          Goal_activation_policy.check_association
            policy
            ~state:t.state
            ~run
            ~admission:activation.admission
      in
      match run.lifecycle with
      | Admitted | Active | Waiting _ -> Ok run
      | Terminal _ -> Error (error Conflict "held startup already terminated")
    in
    match !(activation.Held_run.Activation.phase) with
    | Closed ->
      (* Negative custody only: a failed retirement write must not turn a later
         child ACK into successful completion of input that never started. *)
      Result.ok (retained ())
    | Handed_off _ -> None
    | Reserved | Constructing ->
      let exact_scope =
        match t.initialization_scope with
        | None -> true
        | Some scope ->
          Option.exists
            (Initialization_scope.initial_continuation scope)
            ~f:(fun continuation ->
              phys_equal activation (Admitted_activation.Continuation.target continuation))
      in
      if exact_scope && Result.is_ok (activation.owned_basis ())
      then Result.ok (retained ())
      else None)
;;

let pending_held_startup_run t =
  match pending_initial_startup_run t with
  | Some _ as run -> run
  | None ->
    Option.bind t.run_preparation ~f:(function
      | Initial _ | Delegated_load _ -> None
      | Existing_goal preparation ->
        let owns_hold =
          match preparation.runtime_phase with
          | Installed scope | Callback_completed scope ->
            Result.is_ok (goal_runtime_scope_basis t scope)
          | Constructing ->
            Option.exists t.initialization_scope ~f:(fun scope ->
              match Initialization_scope.construction scope with
              | Some (Existing_goal continuation) ->
                phys_equal continuation.binding.preparation preparation
              | Some (Initial _ | Delegated_load _) | None -> false)
          | Unclaimed
          | Starting_writer _
          | Starting_acknowledged
          | Running_writer _
          | Handed_off _
          | Retired _
          | Closed -> false
        in
        if owns_hold && Result.is_ok (preparation.registered_basis ())
        then
          Option.bind t.state.run_state ~f:(fun index ->
            Option.filter (Run_state.find index preparation.run.id) ~f:(fun run ->
              match run.Agent_protocol.Run.lifecycle with
              | Admitted | Active | Waiting _ -> true
              | Terminal _ -> false))
        else None)
;;

let initialization_held_run t (scope : Initialization_scope.t) =
  if not (Option.exists t.initialization_scope ~f:(phys_equal scope))
  then None
  else (
    match Initialization_scope.construction scope with
    | Some (Existing_goal continuation) ->
      let preparation = continuation.Goal_continuation.binding.preparation in
      if Result.is_ok (preparation.basis ())
      then
        Option.bind t.state.run_state ~f:(fun index ->
          Run_state.find index preparation.run.id)
      else None
    | Some (Initial continuation) ->
      let activation = continuation.Admitted_activation.Continuation.target in
      if Option.exists t.held_activation ~f:(phys_equal activation)
      then (
        match !(activation.phase) with
        | Reserved | Constructing -> pending_held_startup_run t
        | Handed_off _ | Closed -> None)
      else None
    | Some (Delegated_load _) | None -> None)
;;

let held_initialization_of_execution t = function
  | Inference_initialization scope | Inference_initialization_job (scope, _) ->
    Option.map (initialization_held_run t scope) ~f:(fun run -> scope, run)
  | Inference_event borrow ->
    Option.bind t.legacy_callback_scope ~f:(fun callback ->
      if phys_equal callback.borrow borrow
      then
        Option.bind callback.constructor_scope ~f:(fun scope ->
          Option.map (initialization_held_run t scope) ~f:(fun run -> scope, run))
      else None)
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow ->
       Option.bind t.legacy_callback_scope ~f:(fun callback ->
         if phys_equal callback.borrow borrow
         then
           Option.bind callback.constructor_scope ~f:(fun scope ->
             Option.map (initialization_held_run t scope) ~f:(fun run -> scope, run))
         else None)
     | Foreground _ | Background_job _ | Invocation_moderator _ -> None)
  | Inference_held_input _
  | Inference_operation _
  | Inference_moderator _
  | Inference_job _ -> None
;;

let check_registered_run_preparation t preparation =
  match t.run_preparation with
  | Some (Initial active) when phys_equal active preparation ->
    Run_preparation.check preparation ~owner:t.run_preparation_owner ~state:t.state
  | Some _ | None ->
    Error (error Conflict "run preparation is not this actor's live admission")
;;

let check_run_preparation t preparation =
  let open Result.Let_syntax in
  let%bind () = check_retry_execution t preparation in
  check_registered_run_preparation t preparation
;;

let install_live_run_agent_custody t =
  match t.operation_agent_custody, t.state.active_operation, t.state.run_state with
  | None, Some operation, Some index
    when match operation.state with
         | Starting | Running -> true
         | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ -> false ->
    let owners =
      List.filter (Run_state.runs index) ~f:(fun run ->
        List.exists run.owned_work ~f:(fun work ->
          Int.equal work.Agent_protocol.Run_work.generation operation.generation
          &&
          match work.key with
          | Operation id -> Agent_protocol.Id.Operation.equal operation.id id
          | Retained _ -> false))
    in
    (match owners with
     | [ run ] ->
       Option.iter (Run_authorities.find t.run_authorities run.id) ~f:(fun binding ->
         Option.iter
           (Run_admission.Scope.original_actor (Run_authorities.scope binding))
           ~f:(fun actor ->
             t.operation_agent_custody
             <- Some
                  { Operation_owner.operation_id = operation.id
                  ; admission = create_agent_admission (Some (create_agent_custody actor))
                  ; held = None
                  }))
     | [] | _ :: _ :: _ -> ())
  | Some _, _, _ | None, None, _ | None, Some _, (Some _ | None) -> ()
;;

let close_recurrence_activations t =
  List.iter t.recurrence_activations ~f:Activation_custody.close;
  t.recurrence_activations <- []
;;

let retain_recurrence_activations t state =
  t.recurrence_activations
  <- Activation_custody.retain_candidates t.recurrence_activations state
;;

let retain_goal_activation_owners t ~retained =
  Option.iter t.held_activation ~f:(fun activation ->
    if not (retained activation.Held_run.Activation.association)
    then Held_run.Activation.close activation);
  Option.iter t.operation_agent_custody ~f:(fun owner ->
    Option.iter owner.Operation_owner.held ~f:(fun held ->
      match held.Held_operation.phase with
      | Staged | Pending_first_effect ->
        if not (retained held.proof.controller.association)
        then Held_operation.retire held
      | Started | Retired -> ()))
;;

let retire_goal_activation t goal_id =
  retain_goal_activation_owners t ~retained:(fun association ->
    match association.Activation_association.issuer_policy with
    | Recurrence -> true
    | Goal policy ->
      not (Agent_protocol.Id.Goal.equal (Goal_activation_policy.goal_id policy) goal_id));
  Option.iter t.run_preparation ~f:(function
    | Existing_goal preparation ->
      if
        Agent_protocol.Id.Goal.equal
          (Goal_activation_policy.goal_id preparation.policy)
          goal_id
      then Goal_continuation.close preparation
    | Initial _ | Delegated_load _ -> ())
;;

let retain_goal_activations ?admission_hold t (current : Session_state.t) =
  let goal_state state id =
    Option.bind state.Session_state.goal_catalog ~f:(fun catalog ->
      Option.map (Goal_catalog.find catalog id) ~f:Agent_protocol.Goal.state)
  in
  retain_goal_activation_owners t ~retained:(fun association ->
    match association.Activation_association.issuer_policy with
    | Recurrence -> true
    | Goal policy ->
      let id = Goal_activation_policy.goal_id policy in
      Result.is_ok (Goal_activation_policy.check_policy policy ~state:current)
      || ((Option.exists admission_hold ~f:(Agent_protocol.Id.Goal.equal id)
           || Option.equal
                Agent_protocol.Goal.State.equal
                (goal_state t.state id)
                (goal_state current id))
          && Result.is_ok
               (Goal_activation_policy.check_admitted_policy policy ~state:t.state)
          && Result.is_ok
               (Goal_activation_policy.check_admitted_policy policy ~state:current)));
  Option.iter t.run_preparation ~f:(function
    | Initial _ | Delegated_load _ -> ()
    | Existing_goal preparation ->
      let id = Goal_activation_policy.goal_id preparation.policy in
      let compatible =
        Result.is_ok
          (Goal_activation_policy.check_admitted_policy preparation.policy ~state:current)
        && Option.exists current.run_state ~f:(fun index ->
          Option.exists (Run_state.find index preparation.run.id) ~f:(fun run ->
            (match run.Agent_protocol.Run.lifecycle with
             | Admitted | Active | Waiting _ -> true
             | Terminal _ -> false)
            && Result.is_ok
                 (Goal_activation_policy.check_association
                    preparation.policy
                    ~state:current
                    ~run
                    ~admission:preparation.admission)
            && Result.is_ok
                 (let open Result.Let_syntax in
                  let%bind captured_index, source =
                    Moderator_source_installation.capture current
                  in
                  if
                    Run_state.equal captured_index index
                    && Agent_protocol.Run_source.equal source preparation.run.source
                  then Ok ()
                  else Error (error Conflict "Goal resume source candidate changed"))))
      in
      let retained =
        compatible
        &&
        match preparation.phase with
        | Preparing | Source_bound _ | Writer_pending _ -> true
        | Ready _ | Execution_ready _ ->
          Result.is_ok
            (Goal_activation_policy.check_policy preparation.policy ~state:current)
          || Option.exists admission_hold ~f:(Agent_protocol.Id.Goal.equal id)
          || Option.equal
               Agent_protocol.Goal.State.equal
               (goal_state t.state id)
               (goal_state current id)
        | Waiting _ | Closed _ -> false
      in
      if not retained then Goal_continuation.close preparation)
;;

let invalidate_goal_inference_allocations t goal_id =
  List.iter t.inference_owners ~f:(fun owner ->
    Graph_owner.iter_registrations owner ~f:(fun registration ->
      if
        Option.exists
          (Inference_owner.Registration.goal_id registration)
          ~f:(Agent_protocol.Id.Goal.equal goal_id)
      then Inference_owner.Registration.invalidate_policy registration))
;;

let invalidate_goal_inference_policy ?admission_hold t (current : Session_state.t) =
  let goal state id =
    Option.bind state.Session_state.goal_catalog ~f:(fun catalog ->
      Goal_catalog.find catalog id)
  in
  List.iter t.inference_owners ~f:(fun owner ->
    Graph_owner.iter_registrations owner ~f:(fun registration ->
      Option.iter (Inference_owner.Registration.goal_id registration) ~f:(fun id ->
        let changed =
          match goal t.state id, goal current id with
          | Some before, Some after ->
            (not (Goal_admission_policy.same_allocation_policy before after))
            || ((not (Option.exists admission_hold ~f:(Agent_protocol.Id.Goal.equal id)))
                && not
                     (Agent_protocol.Goal.State.equal
                        (Agent_protocol.Goal.state before)
                        (Agent_protocol.Goal.state after)))
          | None, _ | _, None -> true
        in
        if changed then Inference_owner.Registration.invalidate_policy registration)))
;;

(* Stop retires only the actual constructor callback already held by this actor.
   This is factual terminal DATA, not an initialization acknowledgement or an
   assertion that an external native effect was rolled back. *)
module Constructor_stop_acknowledgement = struct
  type actor = t

  module Child = struct
    type t =
      { execution : invocation_execution
      ; previous : Agent_protocol.Invocation.t
      ; cancelled : Agent_protocol.Invocation.t option
      }
  end

  type t =
    { constructor : Initialization_scope.t
    ; callback : Callback_scope.t
    ; borrow : queued_event_borrow
    ; previous : Agent_protocol.Moderator_execution.t
    ; interrupted : Agent_protocol.Moderator_execution.t
    ; children : Child.t list
    ; previous_executions : invocation_execution list
    ; revision : int64
    }

  let owned_children (actor : actor) borrow =
    List.filter actor.invocation_executions ~f:(fun execution ->
      match execution.owner with
      | Event_moderator owner -> phys_equal owner borrow
      | Foreground _ | Invocation_moderator _ | Background_job _ -> false)
  ;;

  let check t ~(actor : actor) =
    let open Result.Let_syntax in
    let%bind _, source = Moderator_source_installation.capture actor.state in
    let%bind () =
      if
        phys_equal actor.initialization_owner t.constructor.owner
        && Option.exists actor.initialization_scope ~f:(phys_equal t.constructor)
        && Option.exists actor.legacy_callback_scope ~f:(phys_equal t.callback)
        && Option.exists t.callback.constructor_scope ~f:(phys_equal t.constructor)
        && phys_equal t.callback.borrow t.borrow
        && Option.exists actor.queued_event_borrow ~f:(phys_equal t.borrow)
        && actor.idle_moderator_borrowed
        && phys_equal actor.invocation_executions t.previous_executions
        && (not t.borrow.committed)
        && Option.is_none t.borrow.stop_retirement
        && (match t.constructor.callback with
            | Claimed id ->
              Agent_protocol.Id.Moderator_execution.equal id t.previous.context.id
            | Unclaimed | Settled _ -> false)
        && Agent_protocol.Id.Session.equal
             actor.state.identity.session_id
             t.previous.context.session_id
        && Int.equal actor.state.identity.generation t.previous.context.generation
        && Agent_protocol.Moderator_execution.equal_context
             t.previous.context
             t.borrow.receipt.context
        && Agent_protocol.Invocation.equal_observer
             t.previous.context.source
             t.callback.source.observer
        && Agent_protocol.Run_source.equal source t.callback.source
        && List.exists
             actor.state.moderator_executions
             ~f:(Agent_protocol.Moderator_execution.equal t.previous)
        && List.equal
             phys_equal
             (owned_children actor t.borrow)
             (List.map t.children ~f:(fun child -> child.Child.execution))
        && Int64.equal actor.state.counters.revision t.revision
      then Ok ()
      else Error (error Conflict "constructor Stop no longer owns its exact receipt")
    in
    if
      List.for_all t.children ~f:(fun child ->
        Agent_protocol.Invocation.equal_context
          child.Child.previous.context
          child.execution.dispatched.context
        && Option.equal
             Agent_protocol.Id.Moderator_execution.equal
             child.previous.parent_event
             child.execution.dispatched.parent_event
        && List.exists
             actor.state.invocations
             ~f:(Agent_protocol.Invocation.equal child.previous))
    then Ok ()
    else Error (error Conflict "constructor Stop native outcome changed before commit")
  ;;

  let prepare (actor : actor) =
    let open Result.Let_syntax in
    match
      actor.initialization_scope, actor.legacy_callback_scope, actor.queued_event_borrow
    with
    | Some constructor, Some callback, Some borrow
      when Option.exists callback.constructor_scope ~f:(phys_equal constructor)
           && phys_equal callback.borrow borrow
           && (not borrow.committed)
           && Option.is_none borrow.stop_retirement ->
      let%bind previous =
        List.find actor.state.moderator_executions ~f:(fun receipt ->
          Agent_protocol.Id.Moderator_execution.equal
            receipt.context.id
            borrow.receipt.context.id)
        |> Result.of_option
             ~error:(error Conflict "constructor Stop receipt is unavailable")
      in
      (match previous.status with
       | Completed _ | Failed _ | Interrupted _ -> Ok None
       | Running ->
         let%bind interrupted =
           Agent_protocol.Moderator_execution.interrupt
             previous
             ~reason:"constructor retired by Stop before checkpoint acknowledgement"
         in
         let%bind children =
           owned_children actor borrow
           |> List.map ~f:(fun execution ->
             let%bind previous =
               List.find actor.state.invocations ~f:(fun invocation ->
                 Agent_protocol.Id.Invocation.equal
                   invocation.context.id
                   execution.dispatched.context.id)
               |> Result.of_option
                    ~error:(error Conflict "constructor Stop native row is unavailable")
             in
             let%map cancelled =
               match previous.status with
               | Resolved _ | Published _ -> Ok None
               | Admitted | Dispatching ->
                 Agent_protocol.Invocation.cancel
                   previous
                   ~reason:
                     "constructor retired by Stop before native result acknowledgement"
                 |> Result.map ~f:Option.some
             in
             { Child.execution; previous; cancelled })
           |> Result.all
         in
         let acknowledgement =
           { constructor
           ; callback
           ; borrow
           ; previous
           ; interrupted
           ; children
           ; previous_executions = actor.invocation_executions
           ; revision = actor.state.counters.revision
           }
         in
         let%map () = check acknowledgement ~actor in
         Some acknowledgement)
    | (Some _ | None), (Some _ | None), (Some _ | None) -> Ok None
  ;;

  let deltas t =
    List.filter_map t.children ~f:(fun child ->
      Option.map child.Child.cancelled ~f:(fun invocation ->
        Session_delta.Invocation_changed invocation))
    @ [ Session_delta.Moderator_execution_changed t.interrupted ]
  ;;

  let install t ~(actor : actor) =
    (* Already validated before the sole writer. Assignment/retirement only;
       never mark a stopped callback as a successful Manager checkpoint. *)
    t.borrow.stop_retirement <- Some t.interrupted;
    t.borrow.callback_active <- false;
    Atomic.set t.borrow.authority_live false;
    List.iter t.children ~f:(fun child ->
      child.Child.execution.accepts_children <- false;
      Atomic.set child.execution.authority_live false);
    (* Keep these exact closed execution cells until the existing callback unwind
       aborts their Invocation-owned provisional work and releases the borrow.
       Graceful Stop does not synchronously cancel the external call. The unwind
       never persists another outcome after [stop_retirement]. *)
    t.constructor.callback <- Settled t.interrupted.context.id;
    retire_agent_admission t.constructor.agent_admission;
    (match t.callback.custody with
     | Unavailable -> ()
     | Admitted admission -> retire_agent_admission admission);
    actor.initialization_scope <- None
  ;;
end

module Held_authored_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; previous_authorities : Run_authorities.t
    ; candidate : Session_transition.t
    ; scope : Held_authored_start.t
    ; authorities : Run_authorities.t
    ; pending : lifecycle_agent_custody option
    ; mutable installed : bool
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () =
      Authored_run_acknowledgement.require_unadmitted actor.lifecycle_agent_custody
    in
    if
      (not t.installed)
      && phys_equal t.previous actor.state
      && phys_equal t.previous_authorities actor.run_authorities
      && phys_equal t.candidate candidate
      && Option.is_none actor.held_authored_start
      && (match t.scope.phase with
          | Staged -> true
          | _ -> false)
      && Option.exists
           actor.operation_worker
           ~f:(phys_equal (Runtime_builder.Authored_start.worker t.scope.startup))
      && Option.equal
           phys_equal
           actor.moderator_manager
           (Runtime_builder.Authored_start.manager t.scope.startup)
    then Ok ()
    else Error (error Conflict "held authored first acknowledgement changed")
  ;;

  let install t ~(actor : actor) =
    t.installed <- true;
    actor.run_authorities <- t.authorities;
    Option.iter t.pending ~f:(fun pending -> actor.lifecycle_agent_custody <- pending);
    actor.held_authored_start <- Some t.scope;
    t.scope.phase <- Starting;
    (Admitted_activation.Continuation.target t.scope.continuation).phase := Constructing
  ;;

  let discard t =
    if not t.installed
    then
      Option.iter t.pending ~f:(function
        | Admitted { pending = Pending admission; _ } -> retire_agent_admission admission
        | Unadmitted | Admitted { pending = Consumed; _ } -> ())
  ;;
end

(* An owned Job result may change this callback's Run while its Event remains
   executing. Extend only that physical callback at the same acknowledged fact;
   a retained Run revision alone cannot renew or reconstruct a callback. *)
module Held_authored_callback_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; scope : Held_authored_start.t
    ; borrow : queued_event_borrow
    ; actions : Run_action_service.t
    ; previous_run : Agent_protocol.Run.t
    ; advance : Run_scope.Host.advance
    }

  let check t ~(actor : actor) ~candidate =
    let callback = Run_action_service.scope t.actions in
    if
      phys_equal t.previous actor.state
      && phys_equal t.candidate candidate
      && phys_equal t.scope.issuing_actor actor.inference_owner_identity
      && Option.exists actor.held_authored_start ~f:(phys_equal t.scope)
      && Option.exists actor.queued_event_borrow ~f:(phys_equal t.borrow)
      && Option.exists
           (Option.bind t.borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
           ~f:(phys_equal t.scope)
      && Option.exists t.borrow.run_actions ~f:(phys_equal t.actions)
      && t.borrow.callback_active
      && (not t.borrow.committed)
      && (match t.scope.phase with
          | Executing id ->
            Agent_protocol.Id.Moderator_execution.equal id t.borrow.receipt.context.id
          | Staged
          | Starting
          | Ready
          | Completed _
          | Released
          | Attempt_unconfirmed
          | Closed -> false)
      && Run_scope.is_open callback
      && Int64.equal (Run_scope.revision callback) t.previous_run.revision
    then Ok ()
    else Error (error Conflict "held callback fact acknowledgement changed")
  ;;

  let prepare (actor : actor) (scope : Held_authored_start.t) ~candidate =
    let open Result.Let_syntax in
    match scope.phase, actor.queued_event_borrow with
    | Executing id, Some borrow
      when Option.exists
             (Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
             ~f:(phys_equal scope)
           && Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
           && borrow.callback_active
           && not borrow.committed ->
      (match borrow.run_actions with
       | None -> Ok None
       | Some actions ->
         let run_id = Run_scope.run_id (Run_action_service.scope actions) in
         let find state =
           Option.bind state.Session_state.run_state ~f:(fun index ->
             Run_state.find index run_id)
           |> Result.of_option
                ~error:(error Conflict "held callback fact has no retained Run")
         in
         let%bind previous_run = find actor.state in
         let%bind next = find candidate.Session_transition.state in
         if Agent_protocol.Run.equal previous_run next
         then Ok None
         else (
           let%bind advance =
             Run_scope.Host.prepare_advance
               (Run_action_service.scope actions)
               ~previous:previous_run
               ~next
               ~execution_id:borrow.receipt.context.id
           in
           let acknowledgement =
             { previous = actor.state
             ; candidate
             ; scope
             ; borrow
             ; actions
             ; previous_run
             ; advance
             }
           in
           let%map () = check acknowledgement ~actor ~candidate in
           Some acknowledgement))
    | ( ( Staged
        | Starting
        | Ready
        | Executing _
        | Completed _
        | Released
        | Attempt_unconfirmed
        | Closed )
      , (None | Some _) ) -> Ok None
  ;;

  let install t = Run_scope.Host.acknowledge_advance t.advance
end

(* A producer ACK can settle work while its actual callback remains Running.
   This bookkeeping extends only that same physical callback, never a retained
   ID, source replacement, terminal retirement or a newly admitted effect. *)
module Producer_callback_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; borrow : queued_event_borrow
    ; actions : Run_action_service.t
    ; previous_run : Agent_protocol.Run.t
    ; advance : Run_scope.Host.advance
    }

  let check t ~(actor : actor) ~candidate =
    if
      phys_equal t.previous actor.state
      && phys_equal t.candidate candidate
      && Option.exists actor.queued_event_borrow ~f:(phys_equal t.borrow)
      && Option.exists t.borrow.run_actions ~f:(phys_equal t.actions)
      && t.borrow.callback_active
      && (not t.borrow.committed)
      && Run_scope.is_open (Run_action_service.scope t.actions)
      && Int64.equal
           (Run_scope.revision (Run_action_service.scope t.actions))
           t.previous_run.revision
    then Ok ()
    else Error (error Conflict "producer callback fact acknowledgement changed")
  ;;

  let prepare (actor : actor) ~candidate =
    let open Result.Let_syntax in
    match actor.queued_event_borrow with
    | Some borrow when borrow.callback_active && not borrow.committed ->
      (match borrow.run_actions with
       | None -> Ok None
       | Some actions ->
         let scope = Run_action_service.scope actions in
         let find state =
           Option.bind state.Session_state.run_state ~f:(fun index ->
             Run_state.find index (Run_scope.run_id scope))
         in
         (match find actor.state, find candidate.Session_transition.state with
          | Some previous_run, Some next
            when not (Agent_protocol.Run.equal previous_run next) ->
            (match next.lifecycle with
             | Terminal _ -> Ok None
             | Admitted | Active | Waiting _ ->
               let%bind _, proofs =
                 Run_producer_settlement.capture
                   actor.state
                   ~delta:candidate.delta
                   ~run:previous_run
                   ~owned_work:next.owned_work
               in
               if List.is_empty proofs
               then Ok None
               else (
                 let%bind advance =
                   Run_scope.Host.prepare_advance
                     scope
                     ~previous:previous_run
                     ~next
                     ~execution_id:borrow.receipt.context.id
                 in
                 let acknowledgement =
                   { previous = actor.state
                   ; candidate
                   ; borrow
                   ; actions
                   ; previous_run
                   ; advance
                   }
                 in
                 let%map () = check acknowledgement ~actor ~candidate in
                 Some acknowledgement))
          | (Some _ | None), (Some _ | None) -> Ok None))
    | None | Some _ -> Ok None
  ;;

  let install t = Run_scope.Host.acknowledge_advance t.advance
end

(* A single acknowledged candidate advances the exact runtime callback owner.
   This is staged DATA; only installation after the real writer changes custody. *)
module Goal_runtime_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; scope : Goal_continuation.runtime_scope
    ; jobs : Agent_protocol.Job.t list
    ; callback_advance : Run_scope.Host.advance option
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () = goal_runtime_scope_basis actor t.scope in
    if phys_equal t.previous actor.state && phys_equal t.candidate candidate
    then Ok ()
    else Error (error Conflict "Goal runtime acknowledgement candidate changed")
  ;;

  let prepare (actor : actor) scope ~candidate =
    let open Result.Let_syntax in
    let%bind () = goal_runtime_scope_basis actor scope in
    let%bind callback_advance =
      match actor.queued_event_borrow with
      | Some borrow
        when Option.exists (goal_runtime_of_borrow borrow) ~f:(phys_equal scope)
             && borrow.callback_active
             && not borrow.committed ->
        (match borrow.run_actions with
         | None -> Ok None
         | Some actions ->
           let find state =
             Option.bind state.Session_state.run_state ~f:(fun index ->
               Run_state.find
                 index
                 scope.Goal_continuation.continuation.binding.preparation.run.id)
           in
           (match find actor.state, find candidate.Session_transition.state with
            | Some previous, Some next when not (Agent_protocol.Run.equal previous next)
              ->
              (match next.lifecycle with
               | Terminal _ -> Ok None
               | Admitted | Active | Waiting _ ->
                 Run_scope.Host.prepare_advance
                   (Run_action_service.scope actions)
                   ~previous
                   ~next
                   ~execution_id:borrow.receipt.context.id
                 |> Result.map ~f:Option.some)
            | _ -> Ok None))
      | None | Some _ -> Ok None
    in
    let rec jobs = function
      | Session_delta.Batch deltas -> List.concat_map deltas ~f:jobs
      | Job_changed job -> [ job ]
      | _ -> []
    in
    Ok
      { previous = actor.state
      ; candidate
      ; scope
      ; jobs = jobs candidate.delta
      ; callback_advance
      }
  ;;

  let install t =
    t.scope.jobs <- t.jobs @ t.scope.jobs;
    Option.iter t.callback_advance ~f:(fun advance ->
      match Run_scope.Host.acknowledge_advance advance with
      | Ok () -> ()
      | Error error ->
        raise_s
          [%message
            "acknowledged Goal callback advance lost its exact basis"
              (error : Agent_protocol.Error.t)]);
    match t.scope.callback with
    | Executing id ->
      Option.iter
        (List.find t.candidate.state.moderator_executions ~f:(fun receipt ->
           Agent_protocol.Id.Moderator_execution.equal receipt.context.id id))
        ~f:(fun receipt ->
          match receipt.status with
          | Completed _ -> t.scope.callback <- Completed id
          | Running | Failed _ | Interrupted _ -> ())
    | Pending | Completed _ | Joined -> ()
  ;;
end

module Held_operation_acknowledgement = struct
  type actor = t

  type t =
    { input_scope : Held_input_scope.t
    ; input : Runtime_input_preparation.Prepared_input.t
    ; activation : Held_run.Activation.t
    ; held : Held_operation.t
    ; owner : Operation_owner.t
    ; previous : Session_state.t
    ; candidate : Session_transition.t
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () =
      if
        phys_equal t.previous actor.state
        && phys_equal t.candidate candidate
        && Option.exists actor.held_input_scope ~f:(phys_equal t.input_scope)
        && Option.exists actor.held_activation ~f:(phys_equal t.activation)
        && Option.is_none actor.operation_agent_custody
      then Ok ()
      else Error (error Conflict "held root acknowledgement owner changed")
    in
    match t.input_scope.phase, t.held.phase with
    | Parsed_ready input, Staged
      when Runtime_input_preparation.Prepared_input.equal input t.input
           && phys_equal t.held.proof.controller.association t.activation.association
           && Option.exists actor.operation_worker ~f:(phys_equal t.held.proof.worker)
           && Run_authorities.is_current
                actor.run_authorities
                t.held.proof.binding
                ~run_id:t.held.proof.run.id -> Ok ()
    | (Parsing | Parsed_ready _ | Consumed _ | Root_attempt_unconfirmed | Closed), _ ->
      Error (error Conflict "held root input or physical worker changed")
  ;;

  let install t ~(actor : actor) =
    t.held.proof.controller.install ();
    t.held.phase <- Pending_first_effect;
    t.input_scope.phase <- Consumed t.held.proof;
    t.activation.phase := Handed_off (User_root t.held.proof);
    actor.operation_agent_custody <- Some t.owner;
    actor.held_input_scope <- None
  ;;
end

module Goal_runtime_operation_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; scope : Goal_continuation.runtime_scope
    ; held : Held_operation.t
    ; owner : Operation_owner.t
    ; handoff : Goal_runtime_handoff.t
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () = goal_runtime_scope_basis actor t.scope in
    if
      phys_equal t.previous actor.state
      && phys_equal t.candidate candidate
      && Option.is_none actor.operation_agent_custody
      && Option.is_none actor.state.active_operation
      && (match t.held.phase with
          | Staged -> true
          | _ -> false)
      && (match t.scope.callback with
          | Joined -> true
          | _ -> false)
      && Run_authorities.is_current
           actor.run_authorities
           t.held.proof.binding
           ~run_id:t.held.proof.run.id
    then Ok ()
    else Error (error Conflict "Goal continuation Operation acknowledgement changed")
  ;;

  let install t ~(actor : actor) =
    t.held.proof.controller.install ();
    t.held.phase <- Pending_first_effect;
    actor.operation_agent_custody <- Some t.owner;
    t.scope.continuation.binding.preparation.runtime_phase
    <- Handed_off (t.scope, t.handoff);
    match t.handoff with
    | Goal_runtime_handoff.Resume handoff ->
      t.scope.continuation.binding.preparation.resume_outcome <- Some handoff
    | Existing_execution _ -> ()
  ;;
end

let install_committed_transition_owned
      ?held_authored_acknowledgement
      ?goal_runtime_acknowledgement
      ?held_operation_acknowledgement
      ?goal_operation_acknowledgement
      ?queued_claim_acknowledgement
      ?authored_run_acknowledgement
      ?legacy_queue_custody
      ?legacy_schedule_custody
      ?retire_legacy_custody
      ~preparation_owner
      ?job_custody
      ?initialization_acknowledgement
      ?constructor_stop_acknowledgement
      ?admission_hold
      ?(explicit_goal_holds = [])
      t
      (transition : Session_transition.t)
  =
  let stopping_jobs =
    match t.state.lifecycle.desired, transition.state.lifecycle.desired with
    | Running, Stopped -> true
    | Running, Running | Stopped, Running | Stopped, Stopped -> false
  in
  (match t.run_preparation, preparation_owner with
   | Some active, Some supplied when Preparation_owner.same active supplied ->
     (match
        Preparation_owner.advance
          active
          ~owner:t.run_preparation_owner
          ~previous:t.state
          ~current:transition.state
      with
      | Ok () -> ()
      | Error _ -> close_run_preparation t)
   | Some _, (Some _ | None) -> close_run_preparation t
   | None, (Some _ | None) -> ());
  Option.iter goal_runtime_acknowledgement ~f:Goal_runtime_acknowledgement.install;
  t.command_audit <- None;
  List.iter explicit_goal_holds ~f:(invalidate_goal_inference_allocations t);
  invalidate_goal_inference_policy ?admission_hold t transition.state;
  t.state <- transition.state;
  Option.iter
    held_authored_acknowledgement
    ~f:(Held_authored_acknowledgement.install ~actor:t);
  Option.iter
    held_operation_acknowledgement
    ~f:(Held_operation_acknowledgement.install ~actor:t);
  Option.iter
    goal_operation_acknowledgement
    ~f:(Goal_runtime_operation_acknowledgement.install ~actor:t);
  Option.iter
    constructor_stop_acknowledgement
    ~f:(Constructor_stop_acknowledgement.install ~actor:t);
  Option.iter authored_run_acknowledgement ~f:(fun acknowledgement ->
    let authorities, lifecycle = Authored_run_acknowledgement.install acknowledgement in
    t.run_authorities <- authorities;
    Option.iter lifecycle ~f:(fun lifecycle -> t.lifecycle_agent_custody <- lifecycle));
  Option.iter
    initialization_acknowledgement
    ~f:Initialization_scope.Acknowledgement.install;
  Option.iter job_custody ~f:(fun update ->
    t.job_agent_custody <- Job_custody.Update.install update);
  Option.iter legacy_queue_custody ~f:(fun incoming ->
    t.legacy_queue_custody
    <- Legacy_queue_custody.install t.legacy_queue_custody ~incoming);
  Option.iter legacy_schedule_custody ~f:(fun incoming ->
    t.legacy_schedule_custody
    <- Legacy_schedule_custody.install t.legacy_schedule_custody ~incoming);
  if stopping_jobs
  then (
    Job_custody.retire t.job_agent_custody;
    t.job_agent_custody <- Job_custody.empty);
  (* Explicit Stop also retires loans when already Stopped. An ordinary
     constructor ACK while initially Stopped is not a Stop disposition. *)
  let stopping_legacy_custody =
    match retire_legacy_custody with
    | Some () -> true
    | None -> stopping_jobs
  in
  if stopping_legacy_custody
  then (
    Legacy_queue_custody.retire t.legacy_queue_custody;
    t.legacy_queue_custody <- Legacy_queue_custody.empty;
    Legacy_schedule_custody.retire t.legacy_schedule_custody;
    t.legacy_schedule_custody <- Legacy_schedule_custody.empty);
  Recurrence_runtime.retain_committed t.recurrence_runtime t.state;
  t.run_authorities
  <- Run_authorities.retain_current
       t.run_authorities
       ~index:t.state.run_state
       ~generation:t.state.identity.generation;
  retained_agent_custody t;
  install_live_run_agent_custody t;
  Option.iter queued_claim_acknowledgement ~f:(fun acknowledgement ->
    t.queued_event_borrow <- Some (Queued_claim_acknowledgement.install acknowledgement);
    t.idle_moderator_borrowed <- true);
  Atomic.set t.event_sequence t.state.counters.event_sequence
;;

(* Initial callers retain their typed adapter; the shared ACK installation owns
   exactly one closed preparation family, never two optional mutable owners. *)
let install_committed_transition
      ?held_authored_acknowledgement
      ?goal_runtime_acknowledgement
      ?held_operation_acknowledgement
      ?goal_operation_acknowledgement
      ?queued_claim_acknowledgement
      ?authored_run_acknowledgement
      ?legacy_queue_custody
      ?legacy_schedule_custody
      ?retire_legacy_custody
      ?run_preparation
      ?job_custody
      ?initialization_acknowledgement
      ?constructor_stop_acknowledgement
      ?admission_hold
      ?(explicit_goal_holds = [])
      t
      transition
  =
  install_committed_transition_owned
    ?held_authored_acknowledgement
    ?goal_runtime_acknowledgement
    ?held_operation_acknowledgement
    ?goal_operation_acknowledgement
    ?queued_claim_acknowledgement
    ?authored_run_acknowledgement
    ?legacy_queue_custody
    ?legacy_schedule_custody
    ?retire_legacy_custody
    ?job_custody
    ?initialization_acknowledgement
    ?constructor_stop_acknowledgement
    ?admission_hold
    ~explicit_goal_holds
    ~preparation_owner:
      (match goal_runtime_acknowledgement, initialization_acknowledgement with
       | Some acknowledgement, _ ->
         Some
           (Existing_goal
              acknowledgement.Goal_runtime_acknowledgement.scope.continuation.binding
                .preparation)
       | None, Some (acknowledgement : Initialization_scope.Acknowledgement.t) ->
         (* This private ACK pins the authentic Init scope and its previous
            projection before the writer. Its same closed owner advances at
            ACK; it cannot substitute whichever constructor is now current. *)
         Initialization_scope.preparation_owner acknowledgement.scope
       | None, None ->
         Option.map run_preparation ~f:(fun preparation ->
           Preparation_owner.Initial preparation))
    t
    transition
;;

let publish_committed_transition t (transition : Session_transition.t) =
  sync_extension_clock t;
  publish_durable t transition.events;
  t.services.state_committed t.state transition.events
;;

(* Inspect only the requested typed changes while an eligible negative cell
   remains. Empty claim polls never reach this seam. Source/controller bookkeeping
   and factual terminal/release deltas do not become effects merely by committing. *)
let rec deferred_execution_delta (previous : Session_state.t) (delta : Session_delta.t) =
  match delta with
  | Batch deltas -> List.exists deltas ~f:(deferred_execution_delta previous)
  | Active_operation_changed (Some operation) ->
    not
      (Option.exists previous.active_operation ~f:(fun current ->
         Agent_protocol.Id.Operation.equal current.id operation.id))
  | Job_changed job ->
    (match job.status with
     | Running ->
       not
         (List.exists previous.jobs ~f:(fun current ->
            Agent_protocol.Id.Job.equal current.id job.id
            && Int.equal current.attempt job.attempt
            &&
            match current.status with
            | Running -> true
            | _ -> false))
     | Queued
     | Waiting_permission _
     | Waiting_completion _
     | Succeeded
     | Failed _
     | Cancelled
     | Interrupted _ -> false)
  | Schedule_changed schedule ->
    (match schedule.status with
     | Delivering ->
       not
         (List.exists previous.schedules ~f:(fun current ->
            Agent_protocol.Id.Schedule.equal current.id schedule.id
            &&
            match current.status with
            | Delivering -> true
            | _ -> false))
     | Scheduled | Delivered | Cancelled | Failed _ -> false)
  | Invocation_changed invocation ->
    let prior =
      List.find previous.invocations ~f:(fun current ->
        Agent_protocol.Id.Invocation.equal current.context.id invocation.context.id)
    in
    let dispatching (value : Agent_protocol.Invocation.t) =
      match value.status with
      | Dispatching -> true
      | Admitted | Resolved _ | Published _ -> false
    in
    let observing (value : Agent_protocol.Invocation.t) =
      Option.exists value.observation ~f:(fun observation ->
        match observation.status with
        | Observing -> true
        | Awaiting | Observed | Observation_failed _ -> false)
    in
    (dispatching invocation && not (Option.exists prior ~f:dispatching))
    || (observing invocation && not (Option.exists prior ~f:observing))
  | Moderator_execution_changed receipt ->
    (match receipt.status with
     | Running ->
       not
         (List.exists previous.moderator_executions ~f:(fun current ->
            Agent_protocol.Id.Moderator_execution.equal
              current.context.id
              receipt.context.id
            &&
            match current.status with
            | Running -> true
            | _ -> false))
     | Completed _ | Failed _ | Interrupted _ -> false)
  | Created _
  | Lifecycle_changed _
  | Metadata_changed _
  | Organization_changed _
  | Initial_start_consumed
  | Stop_epoch_changed _
  | Parent_stop_epoch_changed _
  | Workspace_changed _
  | Canonical_entries_appended _
  | Canonical_history_replaced _
  | Authoring_references_forgotten _
  | Authoring_publication_changed _
  | Initial_prompt_count_changed _
  | Deferred_entries_enqueued _
  | Deferred_entries_adopted
  | Pending_inputs_changed _
  | Active_operation_changed None
  | Automatic_turn_budget_enabled _
  | Automatic_turn_pauses_changed _
  | Attachment_added _
  | Attachment_removed _
  | Permission_changed _
  | Grant_changed _
  | Inference_target_captured _
  | Configuration_revision_changed _
  | Inference_target_changed _
  | Model_job_target_captured _
  | Model_job_recipe_target_captured _
  | Model_job_target_restored _
  | Inference_ledger_changed _
  | Delegated_inference_ledger_changed _
  | Child_contributions_changed _
  | Managed_submission_admitted _
  | Managed_submission_changed _
  | Managed_stop_admitted _
  | Invocation_reconciled _
  | Moderator_execution_reconciled _
  | Subscription_changed _
  | Subscription_expired _
  | Subscription_cancelled _
  | Delivery_changed _
  | Ingress_changed _
  | Delivery_committed _
  | Delivery_wake_changed _
  | Goal_catalog_changed _
  | Goal_accounts_changed _
  | Instruction_selection_changed _
  | Recurrence_catalog_changed _
  | Run_state_changed _
  | Moderator_changed _
  | Shell_changed _
  | History_block_reserved _
  | Compaction_generation_changed _
  | Compaction_archived _
  | History_deleted _
  | History_edited _
  | Owner_lease_generation_changed _
  | Failure_changed _
  | Halt_changed _
  | Reset_generation _ -> false
;;

let rec deferred_admission_delta (previous : Session_state.t) (delta : Session_delta.t) =
  match delta with
  | Batch deltas -> List.exists deltas ~f:(deferred_admission_delta previous)
  | Run_state_changed index ->
    let before = Option.value previous.run_state ~default:Run_state.empty in
    List.exists (Run_state.receipts index) ~f:(fun receipt ->
      Agent_protocol.Run_receipt.Kind.equal receipt.kind Admission
      &&
      match
        Run_state.receipt
          before
          ~principal_id:receipt.principal_id
          ~key:receipt.key
          ~request_sha256:receipt.request_sha256
      with
      | Ok (Some _) -> false
      | Ok None | Error _ -> true)
  | _ -> false
;;

(* Every actual durable write passes this seam. Only real Turn starts sample
   fresh policy time; ledger/outcome/cleanup writes add no clock callback. *)
let persist_transition
      ?run_preparation
      ?admission_hold
      ?commit_attempted
      ?check_before_commit
      ?(explicit_goal_holds = [])
      t
      (candidate : Session_transition.t)
  =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let%bind source_binding =
    match t.run_source_binding with
    | None -> Ok None
    | Some binding
      when Option.exists
             run_preparation
             ~f:(phys_equal binding.Source_binding.preparation) ->
      let%map () = Source_binding.check_current binding in
      Some binding
    | Some _ ->
      close_run_preparation t;
      Ok None
  in
  let%bind payloads =
    List.filter_map candidate.events ~f:(fun event ->
      match event.Agent_protocol.Event.Durable.kind with
      | Operation_started ->
        Some (Agent_protocol.Event.Durable.Payload.of_json ~kind:event.kind event.payload)
      | _ -> None)
    |> Result.all
  in
  let starts_turn =
    List.exists payloads ~f:(function
      | Agent_protocol.Event.Durable.Payload.Operation_started { kind = Turn _; _ } ->
        true
      | _ -> false)
  in
  let policy_now = if starts_turn then Some (t.services.now ()) else None in
  let%bind admission =
    if starts_turn
    then (
      match check_before_commit with
      | None -> Error (error Invalid_state "host turn has no captured final owner check")
      | Some _ ->
        Goal_host_turn_admission.prepare
          ~previous:t.state
          ~candidate:candidate.state
          ~payloads
          ~now:(Option.value_exn policy_now))
    else Ok Goal_host_turn_admission.Allow
  in
  let%bind () =
    Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check -> check ())
  in
  let%bind () =
    if Int64.equal revision t.state.counters.revision
    then Ok ()
    else Error (error Conflict "candidate basis changed during final commit policy")
  in
  let%bind () =
    Option.value_map source_binding ~default:(Ok ()) ~f:Source_binding.check_basis
  in
  (* Source policy precedes the composed final guard. Only pure basis checks
     follow it, and the attempt becomes uncertain only at a real writer call. *)
  let requested = candidate in
  let commit ?admission_hold ~command_audit candidate =
    (* Retire live Goal prefixes before a yielding control writer. A failed save
       cannot make a previously revoked checked view executable again. *)
    retain_goal_activations ?admission_hold t candidate.Session_transition.state;
    (* Selected fresh controls retire only here, after all original/source/ACK
       checks. Same-valued Hold must not close its own callback before those
       checks, and a failed writer must never revive this prefix. *)
    List.iter explicit_goal_holds ~f:(retire_goal_activation t);
    if Option.is_some t.effect_deferred
    then
      if
        (* Keep the requested candidate across Goal's metadata-only replacement.
         The mark belongs to the actual writer attempt, never a no-write hold. *)
        deferred_admission_delta t.state requested.delta
      then exclude_effect_deferred t Admission_attempted
      else if deferred_execution_delta t.state requested.delta
      then exclude_effect_deferred t Ordinary_execution;
    Option.iter commit_attempted ~f:(fun attempted -> attempted := true);
    t.persistence.commit ~command_audit ~previous:t.state candidate
  in
  match admission with
  | Allow ->
    retain_recurrence_activations t candidate.state;
    commit ?admission_hold ~command_audit:t.command_audit candidate
  | Held { goal_id; delta } ->
    let%bind () =
      match delta with
      | None -> Ok ()
      | Some delta ->
        (* Only the actual preexisting Goal may be held. Candidate operation,
           inputs, episode and charges are discarded. Reuse sampled policy time. *)
        let%bind held =
          Session_transition.apply
            ~now:(Option.value_exn policy_now)
            t.state
            ~delta
            ~payloads:[]
        in
        retain_recurrence_activations t held.state;
        let%map () = commit ~admission_hold:goal_id ~command_audit:None held in
        install_committed_transition ~admission_hold:goal_id t held;
        publish_committed_transition t held
    in
    Error (error Permission_denied "goal policy holds fresh host-turn admission")
;;

let prepare_completion_plan t (transition : Session_transition.t) completion_sample =
  match completion_sample with
  | None -> Ok None
  | Some sample ->
    Recurrence_runtime.prepare_completions
      t.recurrence_runtime
      ~sample
      ~previous:t.state
      ~current:transition.state
    |> Result.map ~f:Option.some
;;

let install
      ?turn_stage
      ?held_authored_callback_acknowledgement
      ?goal_runtime_acknowledgement
      ?queued_claim_acknowledgement
      ?authored_run_acknowledgement
      ?initialization_acknowledgement
      ?constructor_stop_acknowledgement
      ?check_before_commit
      ?admission_hold
      ?retire_legacy_custody
      ?run_preparation
      ?commit_attempted
      ?job_custody
      ?completion_sample
      ?(explicit_goal_holds = [])
      t
      transition
  =
  let open Result.Let_syntax in
  let%bind () =
    Option.value_map job_custody ~default:(Ok ()) ~f:(fun update ->
      Job_custody.Update.check_before_commit update ~current:t.job_agent_custody)
  in
  let%bind producer_callback_acknowledgement =
    match held_authored_callback_acknowledgement, goal_runtime_acknowledgement with
    | None, None -> Producer_callback_acknowledgement.prepare t ~candidate:transition
    | (Some _ | None), (Some _ | None) -> Ok None
  in
  let%bind completion_plan = prepare_completion_plan t transition completion_sample in
  let check_before_commit =
    match held_authored_callback_acknowledgement with
    | None -> check_before_commit
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
              check ())
          in
          Held_authored_callback_acknowledgement.check
            acknowledgement
            ~actor:t
            ~candidate:transition)
  in
  let final_check = check_before_commit in
  let check_before_commit =
    match goal_runtime_acknowledgement with
    | None -> final_check
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map final_check ~default:(Ok ()) ~f:(fun check -> check ())
          in
          Goal_runtime_acknowledgement.check
            acknowledgement
            ~actor:t
            ~candidate:transition)
  in
  let previous_check = check_before_commit in
  let check_before_commit =
    match producer_callback_acknowledgement with
    | None -> previous_check
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map previous_check ~default:(Ok ()) ~f:(fun f -> f ())
          in
          Producer_callback_acknowledgement.check
            acknowledgement
            ~actor:t
            ~candidate:transition)
  in
  let%bind () =
    persist_transition
      ?run_preparation
      ?admission_hold
      ?commit_attempted
      ?check_before_commit
      ~explicit_goal_holds
      t
      transition
  in
  (* Fresh explicit controls revoke admitted policy cells at their actual
     writer ACK, including a Hold equal to an automatic hold. Publication can
     yield or fail, so it cannot own this denial. Failed saves never reach here;
     automatic admission holds do not supply these control IDs. *)
  install_committed_transition
    ~explicit_goal_holds
    ?goal_runtime_acknowledgement
    ?queued_claim_acknowledgement
    ?authored_run_acknowledgement
    ?initialization_acknowledgement
    ?constructor_stop_acknowledgement
    ?admission_hold
    ?retire_legacy_custody
    ?run_preparation
    ?job_custody
    t
    transition;
  let%bind () =
    Option.value_map turn_stage ~default:(Ok ()) ~f:(fun staged ->
      Turn_admission_staging.acknowledge
        staged
        ~owner:t.run_preparation_owner
        ~state:t.state
      |> Result.map ~f:ignore)
  in
  let%bind () =
    Option.value_map
      producer_callback_acknowledgement
      ~default:(Ok ())
      ~f:Producer_callback_acknowledgement.install
  in
  let%bind () =
    Option.value_map
      held_authored_callback_acknowledgement
      ~default:(Ok ())
      ~f:Held_authored_callback_acknowledgement.install
  in
  Option.iter
    completion_plan
    ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
  publish_committed_transition t transition;
  Ok ()
;;

let current_snapshot t =
  Eio.Mutex.use_ro t.subscriber_mutex (fun () ->
    let active_tool_calls, active_agent_calls = Active_calls.snapshot t.active_calls in
    { (Session_state.snapshot ~now:(t.services.now ()) t.state) with
      active_tool_calls
    ; active_agent_calls
    })
;;

(* Every actor candidate, including audited commits and speculative staged work,
   selects source retirement before validation. Persistence and installation
   consume this exact prepared candidate without rewriting it. *)
let completion_clock_pair t =
  let wall = t.services.now () in
  let monotonic = t.services.monotonic_now () in
  wall, Recurrence_runtime.Completion.sample ~wall ~monotonic
;;

(* Only an actual selected producer transition requests this clock. Existing
   callback/Job samples retain their exact wall; no later clock replaces it. *)
let producer_completion_sample ?completion_sample t ~delta =
  match completion_sample with
  | Some _ -> completion_sample
  | None ->
    if Run_producer_settlement.requires_completion_sample t.state ~delta
    then Some (snd (completion_clock_pair t))
    else None
;;

let prepare_transition ?run_preparation ?completion_sample t ~delta ~payloads =
  let open Result.Let_syntax in
  let%bind () =
    match run_preparation with
    | None -> Ok ()
    | Some preparation -> check_run_preparation t preparation
  in
  let now =
    match completion_sample with
    | Some sample -> Recurrence_runtime.Completion.wall sample
    | None -> t.services.now ()
  in
  let%bind delta = Run_source_change.prepare t.state ~delta ~now in
  let%bind delta = Goal_catalog_source.prepare_change t.state ~delta in
  let%bind delta =
    Run_producer_settlement.prepare
      ?startup_run:(pending_held_startup_run t)
      t.state
      ~delta
      ~now
  in
  let%bind delta = Goal_run_settlement.prepare t.state ~delta in
  let%bind delta = Recurrence_source.prepare_change t.state ~delta in
  let%bind prepared = Session_transition.apply ~now t.state ~delta ~payloads in
  let%map () =
    match prepared.state.run_state with
    | None -> Ok ()
    | Some index ->
      let%bind additional_bytes =
        Run_job_capacity.bookkeeping_reserve index ~jobs:prepared.state.jobs
      in
      Run_state.validate_encoded_capacity_with_reserve
        index
        ~additional_bytes
        (Run_state.to_jsonaf index)
  in
  prepared
;;

let goal_runtime_transition
      ?admission_hold
      ?job_custody
      ?completion_sample
      ?check_before_commit
      t
      scope
      ~delta
      ~payloads
  =
  let open Result.Let_syntax in
  let completion_sample = producer_completion_sample ?completion_sample t ~delta in
  let%bind candidate = prepare_transition ?completion_sample t ~delta ~payloads in
  let%bind acknowledgement = Goal_runtime_acknowledgement.prepare t scope ~candidate in
  let%map () =
    install
      ?admission_hold
      ~goal_runtime_acknowledgement:acknowledgement
      ?job_custody
      ?completion_sample
      ?check_before_commit
      t
      candidate
  in
  Session_state.summary t.state
;;

let prepare_constructor_job_handoff ?run_preparation t ~delta ~payloads ~ids ~manager =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let%bind prepared = prepare_transition ?run_preparation t ~delta ~payloads in
  let%bind index, binding = Constructor_job_handoff.prepare prepared.state ~manager in
  let source_changed =
    not (Option.equal Run_state.equal_observation prepared.state.run_state index)
  in
  let%bind prepared =
    if not source_changed
    then Ok prepared
    else (
      match index with
      | None -> Error (error Invalid_state "constructor removed its planned source index")
      | Some index ->
        let delta =
          match Session_replacement_delta.classify delta with
          | Some replacement ->
            let candidate = Session_replacement_delta.state replacement in
            Session_replacement_delta.with_state
              replacement
              { candidate with run_state = Some index }
          | None -> Session_delta.Batch [ delta; Run_state_changed index ]
        in
        prepare_transition ?run_preparation t ~delta ~payloads)
  in
  let jobs =
    List.filter_map ids ~f:(fun id ->
      List.find prepared.state.jobs ~f:(fun job -> Agent_protocol.Id.Job.equal id job.id))
  in
  let%map job_custody =
    Job_custody.prepare_constructor_handoff t.job_agent_custody ~jobs ~binding
  in
  prepared, job_custody, source_changed, revision
;;

let check_constructor_job_handoff
      t
      ~(prepared : Session_transition.t)
      ~job_custody
      ~manager
      ~revision
  =
  let open Result.Let_syntax in
  let%bind () =
    if Int64.equal revision t.state.counters.revision
    then Ok ()
    else Error (error Conflict "constructor checkpoint basis changed before commit")
  in
  let%bind _ = Constructor_job_handoff.prepare prepared.state ~manager in
  Option.value_map job_custody ~default:(Ok ()) ~f:(fun update ->
    Job_custody.Update.check_before_commit update ~current:t.job_agent_custody)
;;

let transition
      ?goal_runtime_scope
      ?check_before_commit
      ?constructor_stop_acknowledgement
      ?admission_hold
      ?retire_legacy_custody
      ?run_preparation
      ?commit_attempted
      ?job_custody
      ?completion_sample
      t
      ~delta
      ~payloads
  =
  Exn.protect
    ~finally:(fun () -> Option.iter job_custody ~f:Job_custody.Update.discard)
    ~f:(fun () ->
      let open Result.Let_syntax in
      let completion_sample = producer_completion_sample ?completion_sample t ~delta in
      let%bind transition =
        prepare_transition ?completion_sample ?run_preparation t ~delta ~payloads
      in
      let%bind goal_runtime_acknowledgement =
        match goal_runtime_scope with
        | None -> Ok None
        | Some scope ->
          Goal_runtime_acknowledgement.prepare t scope ~candidate:transition
          |> Result.map ~f:Option.some
      in
      let check_before_commit =
        match goal_runtime_scope with
        | None -> check_before_commit
        | Some scope ->
          Some
            (fun () ->
              let%bind () =
                Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
                  check ())
              in
              check_runtime_construction_effect (Existing_goal scope.continuation))
      in
      let%map () =
        install
          ?goal_runtime_acknowledgement
          ?check_before_commit
          ?constructor_stop_acknowledgement
          ?admission_hold
          ?retire_legacy_custody
          ?run_preparation
          ?commit_attempted
          ?job_custody
          ?completion_sample
          t
          transition
      in
      Agent_protocol.Session.(Session_state.summary t.state))
;;

let require_recurrence_controller t =
  Result.of_option
    t.recurrence_controller
    ~error:(error Invalid_state "recurrence controller lifecycle owner is not installed")
;;

let reconcile_recurrences_internal t =
  match t.state.recurrence_catalog with
  | None -> Ok ()
  | Some _ ->
    let open Result.Let_syntax in
    let%bind controller = require_recurrence_controller t in
    let%bind prepared = Recurrence_reconciliation.prepare t.state ~controller in
    let%bind () = Recurrence_reconciliation.check_current prepared in
    (match prepared.delta with
     | None -> Ok ()
     | Some delta ->
       let%bind candidate = prepare_transition t ~delta ~payloads:[] in
       let%bind () = Recurrence_reconciliation.check_current prepared in
       install t candidate)
;;

let inference_error _ = error Invalid_state "inference tracking admission failed"

let input_scope_basis t (scope : Held_input_scope.t) =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () =
    if
      phys_equal scope.issuing_actor t.inference_owner_identity
      && Option.exists t.held_input_scope ~f:(phys_equal scope)
      && Option.exists t.held_activation ~f:(phys_equal activation)
      && Option.exists (initial_run_preparation t) ~f:(phys_equal activation.preparation)
    then Ok ()
    else Error (error Conflict "held input owner was displaced")
  in
  Run_preparation.check_basis
    activation.preparation
    ~owner:t.run_preparation_owner
    ~state:t.state
;;

let input_graph_basis t (scope : Held_input_scope.t) owner =
  if
    phys_equal scope.Held_input_scope.issuing_actor t.inference_owner_identity
    && List.mem scope.graphs owner ~equal:phys_equal
    && List.mem t.inference_owners owner ~equal:phys_equal
    && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor owner)
  then Ok ()
  else Error (error Conflict "inference graph does not belong to this held input")
;;

module Owned_inference_mutation = struct
  type acknowledgement =
    | Preserve
    | Acknowledge of Inference_owner.Registration.t * Inference_runtime.Attempt.t
    | Finish

  module Scope = struct
    type t =
      | Input of Held_input_scope.t
      | Authored of Held_authored_start.t
      | Initialization of Runtime_constructor_graph.t
  end

  type t =
    { scope : Scope.t
    ; owner : Inference_owner.t
    ; acknowledgement : acknowledgement
    }
end

let initialization_graph_basis t (graph : Runtime_constructor_graph.t) =
  if
    phys_equal graph.scope.owner t.initialization_owner
    && List.mem graph.scope.graphs graph.owner ~equal:phys_equal
    && List.mem t.inference_owners graph.owner ~equal:phys_equal
    && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor graph.owner)
    && Option.exists
         (Initialization_scope.construction graph.scope)
         ~f:(fun construction ->
           Preparation_owner.same
             (Runtime_construction.preparation_owner construction)
             (Runtime_construction.preparation_owner graph.construction))
  then Ok ()
  else Error (error Conflict "constructor graph belongs to another or substituted scope")
;;

let owned_graph_basis t (mutation : Owned_inference_mutation.t) =
  match mutation.scope with
  | Input scope -> input_graph_basis t scope mutation.owner
  | Initialization graph ->
    if phys_equal graph.owner mutation.owner
    then initialization_graph_basis t graph
    else Error (error Conflict "constructor graph owner was substituted")
  | Authored scope ->
    if
      phys_equal scope.issuing_actor t.inference_owner_identity
      && List.mem scope.graphs mutation.owner ~equal:phys_equal
      && List.mem t.inference_owners mutation.owner ~equal:phys_equal
      && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor mutation.owner)
    then Ok ()
    else Error (error Conflict "graph does not belong to this held authored startup")
;;

let owned_graph_preparation (mutation : Owned_inference_mutation.t) =
  match mutation.scope with
  | Input scope -> Some (Preparation_owner.Initial scope.continuation.target.preparation)
  | Authored scope ->
    Some (Preparation_owner.Initial scope.continuation.target.preparation)
  | Initialization graph -> Initialization_scope.preparation_owner graph.scope
;;

let select_authored_graph t owner acknowledgement =
  Option.bind t.held_authored_start ~f:(fun scope ->
    if
      (match scope.Held_authored_start.phase with
       | Released -> false
       | _ -> true)
      && List.mem scope.Held_authored_start.graphs owner ~equal:phys_equal
    then Some Owned_inference_mutation.{ scope = Authored scope; owner; acknowledgement }
    else None)
;;

let authored_graph_for_handle t handle =
  List.find_map t.inference_owners ~f:(fun owner ->
    match
      Graph_owner.registration owner ~ordinal:(Inference_ledger.Handle.ordinal handle)
    with
    | Some registration
      when Inference_ledger.Handle.equal
             handle
             (Inference_owner.Registration.handle registration) ->
      select_authored_graph t owner Owned_inference_mutation.Preserve
    | Some _ | None -> None)
;;

let install_input_graph_acknowledgement t (mutation : Owned_inference_mutation.t) =
  match mutation.acknowledgement with
  | Preserve -> ()
  | Acknowledge (registration, attempt) ->
    Inference_owner.Registration.acknowledge registration attempt
  | Finish ->
    Graph_owner.finish mutation.owner;
    t.inference_owners
    <- List.filter t.inference_owners ~f:(fun owner ->
         not (phys_equal owner mutation.owner));
    (match mutation.scope with
     | Input scope ->
       scope.graphs
       <- List.filter scope.graphs ~f:(fun owner -> not (phys_equal owner mutation.owner))
     | Authored scope ->
       scope.graphs
       <- List.filter scope.graphs ~f:(fun owner -> not (phys_equal owner mutation.owner))
     | Initialization graph ->
       graph.scope.graphs
       <- List.filter graph.scope.graphs ~f:(fun owner ->
            not (phys_equal owner mutation.owner)))
;;

module Held_inference_allocation_acknowledgement = struct
  type actor = t

  module Scope = struct
    type t =
      | Authored of Held_authored_start.t
      | Goal_runtime of Goal_continuation.runtime_scope
      | Initialization of Initialization_scope.t
  end

  type t =
    { scope : Scope.t
    ; owner : Inference_owner.t
    ; ledger : Inference_ledger.t
    ; handle : Inference_ledger.Handle.t
    ; configuration : Inference.Observation.Configuration.t
    ; goal_id : Agent_protocol.Id.Goal.t option
    }

  let check t ~(actor : actor) ~ledger =
    let open Result.Let_syntax in
    let%bind () =
      match t.scope with
      | Authored scope -> held_authored_basis actor scope
      | Goal_runtime scope ->
        let%bind () = goal_runtime_scope_basis actor scope in
        scope.continuation.binding.preparation.registered_basis ()
      | Initialization scope ->
        let%bind () =
          if List.mem scope.graphs t.owner ~equal:phys_equal
          then Ok ()
          else Error (error Conflict "allocation is outside its actual Init graph")
        in
        if
          phys_equal scope.owner actor.initialization_owner
          && Option.exists actor.initialization_scope ~f:(phys_equal scope)
        then
          Option.value_map
            (Initialization_scope.preparation_owner scope)
            ~default:(Ok ())
            ~f:(fun selected ->
              if Option.exists actor.run_preparation ~f:(Preparation_owner.same selected)
              then
                Preparation_owner.check_basis
                  selected
                  ~owner:actor.run_preparation_owner
                  ~state:actor.state
              else Error (error Conflict "allocation Init preparation was displaced"))
        else Error (error Conflict "allocation Init was displaced")
    in
    if
      phys_equal t.ledger ledger
      && List.mem actor.inference_owners t.owner ~equal:phys_equal
      && phys_equal actor.inference_owner_identity (Graph_owner.issuing_actor t.owner)
      &&
      match Graph_owner.phase t.owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "held allocation ACK differs from its actual graph")
  ;;

  let install t =
    Graph_owner.register
      t.owner
      ~handle:t.handle
      ~configuration:t.configuration
      ~goal_id:t.goal_id;
    match t.scope with
    | Goal_runtime scope ->
      if not (List.mem scope.graphs t.owner ~equal:phys_equal)
      then scope.graphs <- t.owner :: scope.graphs
    | Authored scope ->
      if not (List.mem scope.graphs t.owner ~equal:phys_equal)
      then scope.graphs <- t.owner :: scope.graphs
    | Initialization scope ->
      if not (List.mem scope.graphs t.owner ~equal:phys_equal)
      then scope.graphs <- t.owner :: scope.graphs
  ;;
end

let commit_inference_ledger
      ?allocation_acknowledgement
      ?owned_graph
      ?run_preparation
      ?admission
      ?check_before_commit
      t
      ledger
  =
  let open Result.Let_syntax in
  let%bind () =
    match owned_graph with
    | Some mutation -> owned_graph_basis t mutation
    | None ->
      (match run_preparation with
       | None -> Ok ()
       | Some preparation -> check_run_preparation t preparation)
  in
  if
    Int64.equal
      (Inference_ledger.revision ledger)
      (Inference_ledger.revision t.state.inference_ledger)
  then (
    Option.iter owned_graph ~f:(install_input_graph_acknowledgement t);
    Ok ())
  else (
    let%bind accounting =
      Canonical_usage_update.prepare
        t.state.inference_ledger
        ~accounts:t.state.goal_accounts
        ~catalog:t.state.goal_catalog
        ~after:ledger
        ~delegated_usage:t.state.delegated_usage
        ~admission
    in
    let accounting_delta =
      if Canonical_usage_update.accounts_changed accounting
      then
        [ Session_delta.Goal_accounts_changed
            (Option.value_exn (Canonical_usage_update.accounts accounting))
        ]
      else []
    in
    let delta =
      Session_delta.Batch
        (Session_delta.inference_ledger_update
           ledger
           ~delegated_usage:(Canonical_usage_update.delegated_usage accounting)
         :: accounting_delta)
    in
    let payloads =
      [ Agent_protocol.Event.Durable.Payload.Session_updated
          (Session_state.summary { t.state with inference_ledger = ledger })
      ]
    in
    match allocation_acknowledgement, owned_graph with
    | Some acknowledgement, None ->
      let%bind () =
        Held_inference_allocation_acknowledgement.check acknowledgement ~actor:t ~ledger
      in
      let%bind candidate = prepare_transition ?run_preparation t ~delta ~payloads in
      let initialization_acknowledgement =
        match acknowledgement.scope with
        | Authored _ | Goal_runtime _ -> None
        | Initialization scope ->
          Some (Initialization_scope.Acknowledgement.prepare scope candidate.state)
      in
      let%bind goal_runtime_acknowledgement =
        match acknowledgement.scope with
        | Goal_runtime scope ->
          Goal_runtime_acknowledgement.prepare t scope ~candidate
          |> Result.map ~f:Option.some
        | Authored _ | Initialization _ -> Ok None
      in
      let final_check () =
        let%bind () =
          Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check -> check ())
        in
        let%bind () =
          Held_inference_allocation_acknowledgement.check acknowledgement ~actor:t ~ledger
        in
        let%bind () =
          Option.value_map
            initialization_acknowledgement
            ~default:(Ok ())
            ~f:Initialization_scope.Acknowledgement.check_basis
        in
        Option.value_map goal_runtime_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
          Goal_runtime_acknowledgement.check ack ~actor:t ~candidate)
      in
      Eio.Cancel.protect (fun () ->
        let%bind () =
          persist_transition ?run_preparation ~check_before_commit:final_check t candidate
        in
        install_committed_transition
          ?goal_runtime_acknowledgement
          ?run_preparation
          ?initialization_acknowledgement
          t
          candidate;
        Held_inference_allocation_acknowledgement.install acknowledgement;
        publish_committed_transition t candidate;
        Ok ())
    | Some _, Some _ ->
      Error (error Conflict "inference mutation has conflicting ACK ownership")
    | None, None ->
      transition ?check_before_commit ?run_preparation t ~delta ~payloads
      |> Result.map ~f:ignore
    | None, Some mutation ->
      let goal_scope =
        Option.filter (goal_runtime_scope t) ~f:(fun scope ->
          List.mem scope.graphs mutation.owner ~equal:phys_equal)
      in
      let selected_preparation =
        match goal_scope with
        | Some scope ->
          Some (Preparation_owner.Existing_goal scope.continuation.binding.preparation)
        | None -> owned_graph_preparation mutation
      in
      (* This selected factual path never reauthorizes a produced result. The
         exact graph and preparation are retained, and only their basis advances
         after ACK. Preparing without a preparation avoids fresh-effect policy. *)
      let revision = t.state.counters.revision in
      let%bind candidate = prepare_transition t ~delta ~payloads in
      let%bind goal_runtime_acknowledgement =
        Option.value_map goal_scope ~default:(Ok None) ~f:(fun scope ->
          Goal_runtime_acknowledgement.prepare t scope ~candidate
          |> Result.map ~f:Option.some)
      in
      let preparation_owner =
        Option.filter selected_preparation ~f:(fun preparation ->
          Option.exists t.run_preparation ~f:(Preparation_owner.same preparation)
          && Result.is_ok
               (Preparation_owner.check_basis
                  preparation
                  ~owner:t.run_preparation_owner
                  ~state:t.state))
      in
      let run_preparation = Option.bind preparation_owner ~f:Preparation_owner.initial in
      let%bind () =
        persist_transition
          ?run_preparation
          ~check_before_commit:(fun () ->
            let%bind () = owned_graph_basis t mutation in
            let%bind () =
              match preparation_owner with
              | None -> Ok ()
              | Some preparation ->
                if Option.exists t.run_preparation ~f:(Preparation_owner.same preparation)
                then
                  Preparation_owner.check_basis
                    preparation
                    ~owner:t.run_preparation_owner
                    ~state:t.state
                else
                  Error
                    (error Conflict "constructor factual preparation changed before ACK")
            in
            if Int64.equal revision t.state.counters.revision
            then Ok ()
            else Error (error Conflict "held input ledger basis changed before ACK"))
          t
          candidate
      in
      install_committed_transition_owned
        ?goal_runtime_acknowledgement
        ~preparation_owner
        t
        candidate;
      install_input_graph_acknowledgement t mutation;
      publish_committed_transition t candidate;
      Ok ())
;;

let validate_inference_owner t (owner : Inference_owner.t) =
  if not (phys_equal t.inference_owner_identity (Graph_owner.issuing_actor owner))
  then Error (error Conflict "inference owner belongs to another actor")
  else if not (List.mem t.inference_owners owner ~equal:phys_equal)
  then Error (error Conflict "inference graph owner is no longer active")
  else Ok ()
;;

let require_selected_execution t = t.ordinary_execution_admission ()

let require_selected_or_held_execution t preparation =
  match held_startup_effect t preparation with
  | Some check -> check ()
  | None -> require_selected_execution t
;;

let open_inference_owner t source =
  if
    List.exists t.inference_owners ~f:(fun owner ->
      Transcript.Source_id.equal (Graph_owner.source owner) source)
  then Error (error Conflict "inference graph source is already owned")
  else
    let open Result.Let_syntax in
    let%bind qualified_source =
      Inference_ledger.qualify_source t.state.inference_ledger source
      |> Result.map_error ~f:inference_error
    in
    let owner =
      Graph_owner.create
        ~issuing_actor:t.inference_owner_identity
        ~source
        ~generation:t.state.identity.generation
        ~qualified_source
    in
    exclude_effect_deferred t Ordinary_execution;
    t.inference_owners <- owner :: t.inference_owners;
    Ok owner
;;

let inference_registration t owner handle =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t owner in
  match
    Graph_owner.registration owner ~ordinal:(Inference_ledger.Handle.ordinal handle)
  with
  | Some registration
    when Inference_ledger.Handle.equal
           (Inference_owner.Registration.handle registration)
           handle -> Ok registration
  | Some _ | None -> Error (error Conflict "inference handle is not owned by this graph")
;;

let admit_inference
      ?run_preparation
      t
      owner
      relation
      operation_id
      invocation_id
      configuration
  =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t owner in
  let%bind () =
    if
      Int.equal (Graph_owner.generation owner) t.state.identity.generation
      &&
      match Graph_owner.phase owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "inference graph excludes new attempts")
  in
  let%bind protected_ordinals =
    Canonical_usage_update.protected_ordinals
      t.state.inference_ledger
      ~accounts:t.state.goal_accounts
      ~delegated_usage:t.state.delegated_usage
  in
  let%bind ledger, handle, _tracking =
    Inference_ledger.admit
      ~protected_ordinals
      t.state.inference_ledger
      ~source:(Graph_owner.source owner)
      ~relation
      ~operation_id
      ~invocation_id
      ~configuration
    |> Result.map_error ~f:inference_error
  in
  let%bind () = commit_inference_ledger ?run_preparation t ledger in
  Graph_owner.register owner ~handle ~configuration ~goal_id:None;
  Ok handle
;;

let validate_inference_attempt registration attempt =
  if
    Transcript.Scope.equal
      (Inference_ledger.Handle.scope (Inference_owner.Registration.handle registration))
      (Inference_runtime.Attempt.scope attempt)
    && Inference.Observation.Observation_id.equal
         (Inference_ledger.Handle.accounting_id
            (Inference_owner.Registration.handle registration))
         (Inference_runtime.Attempt.accounting_id attempt)
    && Inference.Observation.Configuration.equal
         (Inference_owner.Registration.configuration registration)
         (Inference_runtime.Attempt.configuration attempt)
  then Ok ()
  else Error (error Conflict "inference attempt differs from its admitted identity")
;;

let acknowledge_inference ?owned_graph ?run_preparation t owner handle attempt =
  let open Result.Let_syntax in
  let%bind registration = inference_registration t owner handle in
  let%bind () = validate_inference_attempt registration attempt in
  let%bind ledger =
    Inference_ledger.set_state t.state.inference_ledger handle Running
    |> Result.map_error ~f:inference_error
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> select_authored_graph t owner (Acknowledge (registration, attempt))
  in
  (match owned_graph with
   | None -> Inference_owner.Registration.acknowledge registration attempt
   | Some _ -> ());
  commit_inference_ledger ?owned_graph ?run_preparation t ledger
;;

let observe_inference ?owned_graph ?run_preparation t handle incoming =
  let open Result.Let_syntax in
  let%bind ledger, _disposition =
    Inference_ledger.observe t.state.inference_ledger handle incoming
    |> Result.map_error ~f:inference_error
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> authored_graph_for_handle t handle
  in
  commit_inference_ledger ?owned_graph ?run_preparation t ledger
;;

let observe_owned_inference ?owned_graph ?run_preparation t owner incoming =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t owner in
  let scope = Inference.Observation.scope incoming in
  let owner_matches =
    match Graph_owner.phase owner, Graph_owner.qualified_source owner with
    | (Open | Sealed), Some source ->
      Transcript.Source_id.equal source (Transcript.Scope.key scope).source
    | Finished, _ | _, None -> false
  in
  let%bind () =
    if owner_matches
    then Ok ()
    else Error (error Conflict "observation does not belong to a live inference graph")
  in
  match
    List.find (Inference_ledger.rows t.state.inference_ledger) ~f:(fun row ->
      let handle = Inference_ledger.Row.handle row in
      Int.equal (Graph_owner.generation owner) (Inference_ledger.Handle.generation handle)
      && Transcript.Scope.equal scope (Inference_ledger.Handle.scope handle))
  with
  | None -> Error (error Conflict "observation has no retained admitted scope")
  | Some row ->
    observe_inference
      ?owned_graph
      ?run_preparation
      t
      (Inference_ledger.Row.handle row)
      incoming
;;

let complete_inference ?owned_graph ?run_preparation t owner handle completion =
  let open Result.Let_syntax in
  let%bind registration = inference_registration t owner handle in
  let%bind () =
    validate_inference_attempt
      registration
      (Inference_client.Completion.attempt completion)
  in
  let state =
    match Inference_client.Completion.outcome completion with
    | Returned terminal -> Inference.Observation.Attempt_record.Terminal terminal
    | Interrupted { reason; delivery } -> Interrupted { reason; delivery }
  in
  let%bind ledger =
    Inference_ledger.set_state t.state.inference_ledger handle state
    |> Result.map_error ~f:inference_error
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> select_authored_graph t owner Preserve
  in
  commit_inference_ledger ?owned_graph ?run_preparation t ledger
;;

let interrupt_inference_row ledger handle ~delivery =
  let interrupt fallback =
    Inference_ledger.set_state
      ledger
      handle
      (Interrupted
         { reason = Host_interrupted; delivery = Option.value delivery ~default:fallback })
    |> Result.map_error ~f:inference_error
  in
  match
    Inference_ledger.find ledger ~ordinal:(Inference_ledger.Handle.ordinal handle)
  with
  | None -> Ok ledger
  | Some row ->
    (match
       Inference.Observation.Attempt_record.state (Inference_ledger.Row.record row)
     with
     | Terminal _ | Interrupted _ -> Ok ledger
     | Prepared -> interrupt Inference.Event.Terminal.Definitely_not_submitted
     | Running -> interrupt Inference.Event.Terminal.Possibly_submitted)
;;

let release_inference ?owned_graph ?run_preparation t owner handle =
  let open Result.Let_syntax in
  let%bind registration = inference_registration t owner handle in
  Exn.protect
    ~f:(fun () ->
      let%bind ledger =
        interrupt_inference_row
          t.state.inference_ledger
          handle
          ~delivery:
            (Option.map
               (Inference_owner.Registration.attempt registration)
               ~f:Inference_runtime.Attempt.delivery)
      in
      let owned_graph =
        match owned_graph with
        | Some _ -> owned_graph
        | None -> select_authored_graph t owner Preserve
      in
      commit_inference_ledger ?owned_graph ?run_preparation t ledger)
    ~finally:(fun () ->
      Graph_owner.release owner ~ordinal:(Inference_ledger.Handle.ordinal handle))
;;

let seal_inference_owner t owner =
  let open Result.Let_syntax in
  let%map () = validate_inference_owner t owner in
  Graph_owner.seal owner
;;

let finish_inference_owner ?owned_graph ?run_preparation t owner =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t owner in
  let%bind () =
    match Graph_owner.phase owner with
    | Open -> Error (error Conflict "inference graph must exclude calls before joining")
    | Sealed -> Ok ()
    | Finished -> Error (error Conflict "inference graph already finished")
  in
  let rows = Inference_ledger.rows t.state.inference_ledger in
  let%bind ledger =
    List.fold_result rows ~init:t.state.inference_ledger ~f:(fun ledger row ->
      let handle = Inference_ledger.Row.handle row in
      match Graph_owner.qualified_source owner with
      | Some source
        when Transcript.Source_id.equal
               source
               (Transcript.Scope.key (Inference_ledger.Handle.scope handle)).source ->
        interrupt_inference_row
          ledger
          handle
          ~delivery:
            (Graph_owner.registration
               owner
               ~ordinal:(Inference_ledger.Handle.ordinal handle)
             |> Option.bind ~f:(fun registration ->
               Inference_owner.Registration.attempt registration)
             |> Option.map ~f:Inference_runtime.Attempt.delivery)
      | Some _ | None -> Ok ledger)
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> select_authored_graph t owner Finish
  in
  let%map () = commit_inference_ledger ?owned_graph ?run_preparation t ledger in
  match owned_graph with
  | Some _ -> ()
  | None ->
    Graph_owner.finish owner;
    t.inference_owners
    <- List.filter t.inference_owners ~f:(fun current -> not (phys_equal current owner))
;;

let input_graph_request
  : type a. t -> a Input_graph_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let open Result.Let_syntax in
  match request with
  | Open (scope, source) ->
    let%bind () = input_scope_basis t scope in
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = check_held_effect scope.continuation in
    let%bind () = input_scope_basis t scope in
    let%map owner = open_inference_owner t source in
    scope.graphs <- owner :: scope.graphs;
    owner
  | Acknowledge (scope, owner, handle, attempt) ->
    let%bind () = input_graph_basis t scope owner in
    let%bind registration = inference_registration t owner handle in
    let%bind () = validate_inference_attempt registration attempt in
    let%bind ledger =
      Inference_ledger.set_state t.state.inference_ledger handle Running
      |> Result.map_error ~f:inference_error
    in
    commit_inference_ledger
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope
          ; owner
          ; acknowledgement = Acknowledge (registration, attempt)
          }
      t
      ledger
  | Observe (scope, owner, handle, incoming) ->
    let%bind _ = inference_registration t owner handle in
    let%bind () = input_graph_basis t scope owner in
    observe_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      handle
      incoming
  | Observe_owned (scope, owner, incoming) ->
    let%bind () = input_graph_basis t scope owner in
    observe_owned_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
      incoming
  | Complete (scope, owner, handle, completion) ->
    let%bind () = input_graph_basis t scope owner in
    complete_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
      handle
      completion
  | Release (scope, owner, handle) ->
    let%bind () = input_graph_basis t scope owner in
    release_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
      handle
  | Seal (scope, owner) ->
    let%bind () = input_graph_basis t scope owner in
    seal_inference_owner t owner
  | Finish (scope, owner) ->
    let%bind () = input_graph_basis t scope owner in
    finish_inference_owner
      ~owned_graph:
        Owned_inference_mutation.{ scope = Input scope; owner; acknowledgement = Finish }
      t
      owner
;;

let reconcile_inference_recovery t =
  let open Result.Let_syntax in
  let%bind () =
    if List.is_empty t.inference_owners
    then Ok ()
    else Error (error Conflict "live inference graphs must join before recovery")
  in
  let%bind ledger =
    List.fold_result
      (Inference_ledger.rows t.state.inference_ledger)
      ~init:t.state.inference_ledger
      ~f:(fun ledger row ->
        interrupt_inference_row ledger (Inference_ledger.Row.handle row) ~delivery:None)
  in
  commit_inference_ledger t ledger
;;

let abort_staged_work t ~owner =
  Staged_jobs.abort_owner t.staged_jobs ~owner;
  Staged_subscriptions.release_owner t.staged_subscriptions ~owner;
  Staged_ingress.release_owner t.staged_ingress ~owner;
  Staged_schedules.release_owner t.staged_schedules ~owner;
  Staged_notifications.release_owner t.staged_notifications ~owner;
  sync_extension_clock t
;;

let abort_all_staged_work t =
  Staged_jobs.abort_all t.staged_jobs;
  Staged_subscriptions.abort_all t.staged_subscriptions;
  Staged_ingress.abort_all t.staged_ingress;
  Staged_schedules.abort_all t.staged_schedules;
  Staged_notifications.abort_all t.staged_notifications;
  sync_extension_clock t
;;

let with_staged_transaction t owner f =
  match f () with
  | Ok _ as result ->
    Staged_jobs.commit t.staged_jobs ~owner;
    Staged_subscriptions.release_owner t.staged_subscriptions ~owner;
    Staged_ingress.release_owner t.staged_ingress ~owner;
    Staged_schedules.release_owner t.staged_schedules ~owner;
    Staged_notifications.release_owner t.staged_notifications ~owner;
    sync_extension_clock t;
    result
  | Error _ as result ->
    abort_staged_work t ~owner;
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    abort_staged_work t ~owner;
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let lookup_subscription t id =
  List.find t.state.subscriptions ~f:(fun subscription ->
    Agent_protocol.Id.Subscription.equal subscription.context.id id)
;;

let lookup_notification t id =
  List.find t.state.deliveries ~f:(fun value ->
    Agent_protocol.Id.Delivery.equal value.context.id id)
;;

let lookup_ingress t id =
  List.find t.state.ingress_registrations ~f:(fun value ->
    Agent_protocol.Id.Capability.equal value.External_ingress.context.id id)
;;

let ingress_subscription_lookup t subscriptions id epoch =
  let matches value =
    Agent_protocol.Id.Subscription.equal value.Agent_protocol.Subscription.context.id id
  in
  match
    List.find (subscriptions @ t.state.subscriptions) ~f:(fun value ->
      matches value && value.epoch = epoch)
  with
  | Some _ as result -> result
  | None -> List.find (List.rev subscriptions @ t.state.subscriptions) ~f:matches
;;

let selected_ingress t owner subscriptions =
  Staged_ingress.selected
    t.staged_ingress
    ~owner
    ~lookup:(lookup_ingress t)
    ~subscription:(ingress_subscription_lookup t subscriptions)
;;

let staged_work_changes t owner =
  let open Result.Let_syntax in
  let%bind subscriptions =
    Staged_subscriptions.selected
      t.staged_subscriptions
      ~owner
      ~lookup:(lookup_subscription t)
  in
  let%bind registrations = selected_ingress t owner subscriptions in
  let%bind () =
    List.fold_result registrations ~init:() ~f:(fun () value ->
      match lookup_ingress t value.External_ingress.context.id with
      | Some _ -> Ok ()
      | None ->
        let%bind due =
          Extension_clock.is_due
            t.extension_clock
            (Subscription value.context.subscription_id)
            ~now:(t.services.monotonic_now ())
        in
        (match
           (not due)
           && Agent_protocol.Timestamp.compare
                (t.services.now ())
                value.context.expires_at
              < 0
         with
         | true -> Ok ()
         | false ->
           Error
             (error Conflict "ingress subscription expired before registration commit")))
  in
  let%bind () =
    match
      List.exists registrations ~f:(fun value ->
        Option.is_none (lookup_ingress t value.External_ingress.context.id))
    with
    | false -> Ok ()
    | true ->
      Staged_ingress.check_capacity
        ~limits:t.services.ingress_limits
        ~generation:t.state.identity.generation
        ~now:(t.services.now ())
        ~subscriptions:(t.state.subscriptions @ subscriptions)
        ~values:(t.state.ingress_registrations @ registrations)
  in
  let%bind schedules =
    Staged_schedules.selected t.staged_schedules ~owner ~lookup:(fun id ->
      List.find t.state.schedules ~f:(fun value ->
        Agent_protocol.Id.Schedule.equal value.id id))
  in
  let%map notifications =
    Staged_notifications.selected
      t.staged_notifications
      ~owner
      ~lookup:(lookup_notification t)
  in
  let jobs = Staged_jobs.selected t.staged_jobs ~owner in
  ( List.map jobs ~f:(fun job -> Session_delta.Job_changed job)
    @ Staged_ingress.ordered_changes ~subscriptions ~registrations
    @ List.map schedules ~f:(fun schedule -> Session_delta.Schedule_changed schedule)
    @ List.map notifications ~f:(fun delivery -> Session_delta.Delivery_changed delivery)
  , List.map jobs ~f:(fun job ->
      Agent_protocol.Event.Durable.Payload.Job_state_changed job)
    @ List.map schedules ~f:(fun schedule ->
      Agent_protocol.Event.Durable.Payload.Schedule_state_changed schedule) )
;;

