let check_recurrence_creation_admission t prepared =
  let open Result.Let_syntax in
  let%bind () =
    if Option.is_none (Eio.Promise.peek t.finished)
    then Ok ()
    else Error (error Server_shutting_down "recurrence actor has terminated")
  in
  let%bind () = require_runtime_admission t in
  let%bind moderator_halted =
    Runtime_builder.moderator_snapshot_is_halted t.state.moderator
  in
  let%bind () =
    match t.state.lifecycle.desired, t.state.runtime_initialization, t.state.failure with
    | Running, Ready, None when not (t.stopped || t.state.halted || moderator_halted) ->
      Ok ()
    | (Running | Stopped), (Ready | Pending _), (Some _ | None) ->
      Error (error Conflict "recurrence creation controller runtime is unavailable")
  in
  let%bind () = Recurrence_creation_admission.check_current prepared t.state in
  let%bind snapshot =
    Recurrence_runtime.snapshot
      t.recurrence_runtime
      ~wall:(t.services.now ())
      ~monotonic:(t.services.monotonic_now ())
  in
  let entry = Recurrence_creation_admission.entry prepared in
  let%bind late =
    Recurrence_runtime.selection_lateness
      t.recurrence_runtime
      ~entry
      ~nominal:(Recurrence_creation_admission.nominal prepared)
      ~snapshot
  in
  let%bind () =
    match late with
    | Some late
      when Int64.(
             late
             <= Recurrence_policy.grace_ns
                  (Recurrence_definition.policy (Recurrence_entry.current entry))) ->
      Ok ()
    | None | Some _ ->
      Error (error Conflict "recurrence creation nominal is outside current grace")
  in
  let%bind () = require_runtime_admission t in
  Recurrence_creation_admission.check_current prepared t.state
;;

let check_recurrence_new_work_runtime t ~entry ~nominal =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind moderator_halted =
    Runtime_builder.moderator_snapshot_is_halted t.state.moderator
  in
  let%bind () =
    match t.state.lifecycle.desired, t.state.runtime_initialization, t.state.failure with
    | Running, Ready, None when not (t.state.halted || moderator_halted) -> Ok ()
    | (Running | Stopped), (Ready | Pending _), (Some _ | None) ->
      Error (error Conflict "recurrence execution controller runtime is unavailable")
  in
  let%bind snapshot =
    Recurrence_runtime.snapshot
      t.recurrence_runtime
      ~wall:(t.services.now ())
      ~monotonic:(t.services.monotonic_now ())
  in
  let%bind late =
    Recurrence_runtime.selection_lateness t.recurrence_runtime ~entry ~nominal ~snapshot
  in
  let%bind () =
    match late with
    | Some late
      when Int64.(
             late
             <= Recurrence_policy.grace_ns
                  (Recurrence_definition.policy (Recurrence_entry.current entry))) ->
      Ok ()
    | None | Some _ ->
      Error (error Conflict "recurrence execution nominal is outside current grace")
  in
  let%bind () = require_runtime_admission t in
  Ok ()
;;

let check_recurrence_execution_runtime t prepared =
  let open Result.Let_syntax in
  let%bind () =
    if
      (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
    then Ok ()
    else Error (error Conflict "recurrence execution controller owner is unavailable")
  in
  match Recurrence_execution_admission.decision prepared with
  | Retained _ -> Ok ()
  | New _ ->
    check_recurrence_new_work_runtime
      t
      ~entry:(Recurrence_execution_admission.entry prepared)
      ~nominal:(Recurrence_execution_admission.nominal prepared)
;;

let check_recurrence_execution_admission t prepared =
  let open Result.Let_syntax in
  let%bind () =
    if
      (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
    then Ok ()
    else Error (error Conflict "recurrence execution controller owner is unavailable")
  in
  let%bind () = Recurrence_execution_admission.check_current prepared t.state in
  match Recurrence_execution_admission.decision prepared with
  | Retained _ -> Ok ()
  | New _ ->
    let%bind () = check_recurrence_execution_runtime t prepared in
    Recurrence_execution_admission.check_current prepared t.state
;;

let record_recurrence_execution_internal ?binding t ~actor ~authorize ~intent ~attempt =
  let open Result.Let_syntax in
  let%bind () =
    Option.value_map binding ~default:(Ok ()) ~f:(fun binding ->
      check_selected_recurrence_source t binding ~intent ~attempt)
  in
  let run_preparation =
    Option.map binding ~f:(fun binding -> binding.Source_binding.preparation)
  in
  let%bind controller = require_recurrence_controller t in
  let prepare () =
    Recurrence_execution_admission.prepare
      t.state
      ~controller
      ~actor
      ~authorize
      ~intent
      ~attempt
  in
  let check_owned prepared binding =
    (* The central source-policy check has finished. Controller policies and
       fresh grace precede both originals and the final joint pure bases. *)
    let%bind () = Recurrence_execution_admission.check_current prepared t.state in
    let%bind () = check_recurrence_execution_runtime t prepared in
    let%bind () = check_source_original t binding in
    let%bind () =
      Recurrence_command_admission.check_write actor ~authorize:(fun _ -> Ok ()) t.state
    in
    let%bind () = Recurrence_execution_admission.check_basis prepared t.state in
    check_selected_source t binding
  in
  let check_current prepared =
    match binding with
    | None -> check_recurrence_execution_admission t prepared
    | Some binding ->
      let%bind () = Source_binding.check_current binding in
      check_owned prepared binding
  in
  let%bind prepared = prepare () in
  let%bind () = check_current prepared in
  match Recurrence_execution_admission.decision prepared with
  | Retained row -> Ok row
  | New { catalog; execution } ->
    let%bind candidate =
      prepare_transition
        ?run_preparation
        t
        ~delta:(Session_delta.Recurrence_catalog_changed catalog)
        ~payloads:[]
    in
    let%bind () = check_current prepared in
    let check_before_commit =
      Option.map binding ~f:(fun binding -> fun () -> check_owned prepared binding)
    in
    let%bind () = persist_transition ?run_preparation ?check_before_commit t candidate in
    install_committed_transition ?run_preparation t candidate;
    publish_committed_transition t candidate;
    (* Our own canonical projection rotates the genuine Current. Refresh rather
       than testing the precommit observation or claiming rollback after ACK. *)
    let%bind refreshed = prepare () in
    let%bind () = check_current refreshed in
    (match Recurrence_execution_admission.decision refreshed with
     | Retained row when Recurrence_execution.equal row execution -> Ok row
     | Retained _ | New _ ->
       Error (error Conflict "committed recurrence execution changed before return"))
;;

let retry_selected_basis ?writer retry next =
  let open Result.Let_syntax in
  let%bind () = retry.Recurrence_retry.basis () in
  let%bind () =
    match retry.phase with
    | Selected_source binding when phys_equal binding next -> Ok ()
    | Writer_pending (binding, actual)
      when phys_equal binding next && Option.exists writer ~f:(phys_equal actual) -> Ok ()
    | _ -> Error (error Conflict "retry does not own this selected source or writer")
  in
  if
    phys_equal
      next.Source_binding.preparation
      (Run_preparation.Deferred.preparation retry.deferred)
    && Recurrence_controller.is_current retry.observed
  then retry.selected_basis next
  else Error (error Conflict "retry target source or Store observation changed")
;;

let rotate_recurrence_retry_internal t ~retry ~next ~actor ~authorize =
  let open Result.Let_syntax in
  let%bind controller = require_recurrence_controller t in
  let%bind () =
    if
      Int.equal retry.Recurrence_retry.domain (Stdlib.Domain.self () :> int)
      && Recurrence_controller.same_store controller retry.controller
    then Ok ()
    else Error (error Conflict "retry belongs to another Store or Eio domain")
  in
  let self = phys_equal retry.issuing_actor t.inference_owner_identity in
  let%bind () =
    if
      Agent_protocol.Session_ref.equal
        (Recurrence_controller.session controller)
        (Recurrence_controller.session retry.controller)
      && not self
    then Error (error Conflict "same-session retry belongs to another physical actor")
    else Ok ()
  in
  let%bind () =
    match retry.phase with
    | Acknowledged _ -> Ok ()
    | _ -> Recurrence_retry.check_basis retry
  in
  let%bind resolution =
    match retry.phase with
    | Acknowledged (_, execution) ->
      let%bind predecessor =
        Result.of_option
          (List.find (Recurrence_execution.attempts execution) ~f:(fun old ->
             Recurrence_execution_attempt.equal
               (Recurrence_execution.Attempt.request old)
               retry.previous))
          ~error:(error Conflict "acknowledged retry lost its predecessor")
      in
      Result.of_option
        (Recurrence_execution.Attempt.retry_resolution predecessor)
        ~error:(error Conflict "acknowledged retry lost its resolution")
    | _ ->
      Recurrence_retry_resolution.create
        ~intent:retry.intent
        ~attempt:retry.previous
        ~target_revision:retry.resolution_revision
        ~resolved_at:(t.services.now ())
  in
  let prepare () =
    Recurrence_retry_admission.prepare
      t.state
      ~controller
      ~actor
      ~authorize
      ~intent:retry.intent
      ~previous:retry.previous
      ~resolution
      ~next:retry.next
  in
  let controller_current () =
    if
      (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
    then Ok ()
    else Error (error Conflict "retry controller writer is unavailable")
  in
  let%bind () = controller_current () in
  let%bind prepared = prepare () in
  let%bind () = Recurrence_retry_admission.check_policy prepared t.state in
  let%bind () = Recurrence_retry_admission.check_basis prepared t.state in
  match Recurrence_retry_admission.decision prepared with
  | Retained execution ->
    (* This path is historical DATA only. It cannot install a missing live ACK. *)
    Ok execution
  | New { catalog; execution } ->
    let%bind () = retry_selected_basis retry next in
    let run_preparation =
      Option.some_if self (Run_preparation.Deferred.preparation retry.deferred)
    in
    let attempted = ref false in
    let check_owned () =
      let%bind () = controller_current () in
      let%bind () = retry_selected_basis ~writer:attempted retry next in
      (* Source admission policy is run centrally before this final closure. The
         target read/new-preparation policy and controller policy precede clock;
         only originals and callback-free exact bases follow the clock. *)
      let%bind () = retry.policy () in
      let%bind () = Recurrence_retry_admission.check_policy prepared t.state in
      let%bind () =
        check_recurrence_new_work_runtime
          t
          ~entry:(Recurrence_retry_admission.entry prepared)
          ~nominal:(Recurrence_retry_admission.nominal prepared)
      in
      let%bind () = retry.authority () in
      let%bind () =
        Recurrence_command_admission.check_write actor ~authorize:(fun _ -> Ok ()) t.state
      in
      let%bind () = Recurrence_retry_admission.check_basis prepared t.state in
      retry_selected_basis ~writer:attempted retry next
    in
    let%bind () = Source_binding.check_current next in
    let%bind () = check_owned () in
    (* The pending preparation cannot authorize execution. This candidate is
       pure controller bookkeeping; only persist/install below use the exact
       preparation to advance the self-target's acknowledged source owner. *)
    let%bind candidate =
      prepare_transition
        t
        ~delta:(Session_delta.Recurrence_catalog_changed catalog)
        ~payloads:[]
    in
    let selected = retry.phase in
    retry.phase <- Writer_pending (next, attempted);
    let acknowledged = ref false in
    let%bind () =
      Exn.protect
        ~finally:(fun () ->
          if not !acknowledged
          then (
            match retry.phase with
            | Writer_pending (binding, current)
              when phys_equal binding next && phys_equal current attempted ->
              retry.phase <- (if !attempted then Attempt_unconfirmed else selected)
            | _ -> ()))
        ~f:(fun () ->
          let%bind () =
            persist_transition
              ?run_preparation
              ~commit_attempted:attempted
              ~check_before_commit:check_owned
              t
              candidate
          in
          (* The sole writer has acknowledged THIS candidate. Preserve the fact
             even if the physical target was invalidated while the writer yielded;
             an absent live binding is not restored from the saved row. *)
          install_committed_transition ?run_preparation t candidate;
          let live =
            match retry.phase with
            | Writer_pending (binding, current)
              when phys_equal binding next
                   && phys_equal current attempted
                   && Result.is_ok (retry.basis ())
                   && Result.is_ok (Source_binding.check_basis next) -> Some next
            | _ -> None
          in
          retry.phase <- Acknowledged (live, execution);
          acknowledged := true;
          publish_committed_transition t candidate;
          Ok ())
    in
    let%bind refreshed = prepare () in
    let%bind () = Recurrence_retry_admission.check_policy refreshed t.state in
    let%bind () = Recurrence_retry_admission.check_basis refreshed t.state in
    (match Recurrence_retry_admission.decision refreshed with
     | Retained row when Recurrence_execution.equal execution row -> Ok row
     | _ -> Error (error Conflict "acknowledged retry row changed before return"))
;;

let effect_deferred_request
  : type a. t -> a Effect_deferred_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  match request with
  | Begin (actor, authorize, request) ->
    begin_effect_deferred_internal t ~actor ~authorize ~request
  | Begin_retry (observation, actor, authorize, intent, previous, request) ->
    begin_recurrence_retry_internal
      t
      ~observation
      ~actor
      ~authorize
      ~intent
      ~previous
      ~request
  | Resume_retry (retry, actor, authorize) ->
    resume_recurrence_retry_internal t ~retry ~actor ~authorize
  | Complete_retry (retry, completion) ->
    complete_recurrence_retry_internal t ~retry ~completion
  | Rotate_retry (retry, next, actor, authorize) ->
    rotate_recurrence_retry_internal t ~retry ~next ~actor ~authorize
  | Check_execution preparation -> check_run_preparation t preparation
  | Exclude ->
    exclude_effect_deferred t Ordinary_execution;
    Ok ()
  | Close deferred -> close_effect_deferred_internal t deferred
  | Observe (actor, authorize, completion) ->
    observe_no_run_effects_internal t ~actor ~authorize ~completion
;;

let check_lifecycle_fence t fence =
  if
    phys_equal t.lifecycle_owner fence.Lifecycle_fence.owner
    && Option.exists t.lifecycle_fence ~f:(fun current -> phys_equal current fence)
  then Ok ()
  else Error (error Conflict "session lifecycle fence is no longer current")
;;

let begin_lifecycle t attachment_id expected_generation expected_revision =
  let open Result.Let_syntax in
  let%bind () =
    match attachment_id with
    | None -> Ok ()
    | Some id -> Result.map (write_attachment t id) ~f:(fun _ -> ())
  in
  if Option.is_some t.lifecycle_fence
  then Error (error Conflict "session lifecycle change is already reserved")
  else if
    (not (Int.equal t.state.identity.generation expected_generation))
    || not (Int64.equal t.state.counters.revision expected_revision)
  then Error (error Conflict "session lifecycle canonical anchor changed")
  else (
    let fence = Lifecycle_fence.{ owner = t.lifecycle_owner; phase = Reserved } in
    close_recurrence_activations t;
    close_bound_run_preparation t;
    t.lifecycle_fence <- Some fence;
    Ok fence)
;;

let refresh_recurrence_creation t permit =
  let open Result.Let_syntax in
  let%bind () =
    if phys_equal permit.Recurrence_creation.owner t.recurrence_creation_owner
    then Ok ()
    else Error (error Conflict "recurrence creation permit belongs to another actor")
  in
  let%bind () = require_runtime_admission t in
  let%bind controller = require_recurrence_controller t in
  let%bind prepared =
    Recurrence_creation_admission.prepare
      t.state
      ~controller
      ~actor:permit.actor
      ~authorize:permit.authorize
      ~occurrence:(Recurrence_child_reservation.occurrence permit.reservation)
      ~expected_control_revision:
        (Recurrence_child_reservation.control_revision permit.reservation)
  in
  let%bind () = check_recurrence_creation_admission t prepared in
  let%bind () =
    match Recurrence_creation_admission.reservation prepared with
    | Some row when Recurrence_child_reservation.equal row permit.reservation -> Ok ()
    | None | Some _ ->
      Error (error Conflict "recurrence creation permit lost exact durable reservation")
  in
  let definition =
    Recurrence_entry.current (Recurrence_creation_admission.entry prepared)
  in
  let check_current () =
    let%bind () = check_recurrence_creation_admission t prepared in
    (* The trusted policy callback is nonyielding. Repeat the original proof
       and actual owner-state checks after it before the caller's effect. *)
    let%bind () = permit.authorize t.state definition in
    check_recurrence_creation_admission t prepared
  in
  let checked : Recurrence_creation.Checked.t =
    { definition
    ; principal = Operator_authorization.principal permit.actor
    ; check_current
    }
  in
  Ok checked
;;

let observe_recurrence_run_internal t ~actor ~authorize ~intent ~attempt =
  let open Result.Let_syntax in
  let owner_current () =
    if
      (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
    then Ok ()
    else Error (error Conflict "recurrence target observation owner is unavailable")
  in
  let check_read () =
    let%bind () = owner_current () in
    Recurrence_command_admission.check_read actor ~authorize t.state
  in
  let%bind () = check_read () in
  let%bind () = Recurrence_execution_attempt.validate attempt ~intent in
  let%bind controller = require_recurrence_controller t in
  let%bind () =
    if
      Agent_protocol.Session_ref.equal
        (Recurrence_controller.session controller)
        (Recurrence_execution_intent.target intent)
    then Ok ()
    else Error (error Conflict "recurrence observation targets another session")
  in
  let lookup () =
    match t.state.run_state with
    | None -> Ok None
    | Some index ->
      let%bind receipt =
        Run_state.receipt
          index
          ~principal_id:(Recurrence_execution_attempt.principal_id attempt)
          ~key:(Recurrence_execution_attempt.key attempt)
          ~request_sha256:(Recurrence_execution_attempt.request_sha256 attempt)
      in
      (match receipt with
       | None -> Ok None
       | Some admission ->
         let%bind origin =
           Result.of_option
             (Run_state.recurrence_origin index admission.run_id)
             ~error:(error Conflict "retained Run lacks its exact recurrence origin")
         in
         let%bind run =
           Result.of_option
             (Run_state.find index admission.run_id)
             ~error:(error Conflict "recurrence origin lost its retained Run")
         in
         let%bind () = Recurrence_run_origin.validate origin ~intent ~attempt in
         let%bind () = Recurrence_run_origin.validate_run origin ~run ~admission in
         let%map terminal =
           match run.lifecycle with
           | Admitted | Active | Waiting _ -> Ok None
           | Terminal _ ->
             let receipts =
               List.filter (Run_state.receipts index) ~f:(fun receipt ->
                 Agent_protocol.Run_receipt.Kind.equal receipt.kind Terminal
                 && Agent_protocol.Id.Run.equal receipt.run_id run.id
                 && Int64.equal receipt.run_revision run.revision)
             in
             (match receipts with
              | [ receipt ] ->
                Recurrence_run_reference.create ~origin ~run ~receipt
                |> Result.map ~f:Option.some
              | [] | _ :: _ :: _ ->
                Error
                  (error
                     Conflict
                     "recurrence terminal Run lacks one exact terminal receipt"))
         in
         Some (origin, run, admission, terminal))
  in
  let%bind evidence = lookup () in
  let%bind current = Recurrence_controller.observe controller t.state in
  let check_owner () =
    let%bind () = owner_current () in
    if Recurrence_controller.is_current current
    then Ok ()
    else Error (error Conflict "recurrence target lifecycle observation changed")
  in
  let check_authority () =
    if
      Operator_authorization.is_current actor
      && Agent_protocol.Principal.has_scope
           (Operator_authorization.principal actor)
           View_session_transcript
    then Ok ()
    else
      Error
        (error
           Permission_denied
           "recurrence original authority expired, was revoked or lacks scope")
  in
  let check_basis () =
    let%bind () = check_owner () in
    let%bind actual = lookup () in
    let same =
      match evidence, actual with
      | None, None -> true
      | ( Some (origin, run, admission, terminal)
        , Some (next_origin, next_run, next_admission, next_terminal) ) ->
        Recurrence_run_origin.equal origin next_origin
        && Agent_protocol.Run.equal run next_run
        && Agent_protocol.Run_receipt.equal admission next_admission
        && Option.equal Recurrence_run_reference.equal terminal next_terminal
      | None, Some _ | Some _, None -> false
    in
    if same
    then check_owner ()
    else Error (error Conflict "recurrence target retained evidence changed")
  in
  let check () =
    let%bind () = check_basis () in
    let%bind () = check_read () in
    let%bind () = check_authority () in
    check_basis ()
  in
  let%bind () = check () in
  match evidence with
  | None -> Ok None
  | Some (observed_origin, observed_run, _, observed_terminal) ->
    let validate_reference reference =
      let%bind () = check () in
      let%bind () =
        match observed_terminal with
        | None -> Error (error Conflict "recurrence observation has no terminal payload")
        | Some terminal ->
          Recurrence_run_reference.validate
            reference
            ~origin:observed_origin
            ~run:observed_run
            ~receipt:(Recurrence_run_reference.receipt terminal)
      in
      check ()
    in
    let%map completion =
      match observed_terminal with
      | None -> Ok None
      | Some terminal ->
        Recurrence_runtime.completion
          t.recurrence_runtime
          ~origin:observed_origin
          ~terminal
    in
    let observation : Recurrence_run_observation.t =
      { origin = observed_origin
      ; terminal = observed_terminal
      ; controller
      ; check_current = check
      ; check_policy = check_read
      ; check_authority
      ; check_basis
      ; validate_reference
      ; completion
      ; check_admitted =
          (fun () ->
            let%bind () = check_basis () in
            match observed_run.lifecycle with
            | Admitted -> Ok ()
            | Active | Waiting _ | Terminal _ ->
              Error (error Conflict "activation target Run is no longer Admitted"))
      }
    in
    Some observation
;;

let check_recurrence_import_owner t =
  if
    (not t.stopped)
    && Option.is_none (Eio.Promise.peek t.finished)
    && Option.is_none t.lifecycle_fence
  then Ok ()
  else Error (error Conflict "recurrence settlement controller owner is unavailable")
;;

let check_held_recurrence_source
      t
      (held : Held_run.t)
      (observation : Recurrence_run_observation.t)
  =
  let open Result.Let_syntax in
  let%bind () = check_bound_source t held.binding in
  let%bind () = Held_run.check_basis held in
  let%bind controller = require_recurrence_controller t in
  let session = Recurrence_controller.session controller in
  let origin = observation.origin in
  let controller_session =
    Recurrence_run_origin.occurrence origin
    |> Recurrence_identity.Occurrence.definition
    |> Recurrence_identity.Definition.controller
  in
  let%bind () =
    if
      Recurrence_controller.same_store controller observation.controller
      && Agent_protocol.Session_ref.equal session held.run.session
      && Agent_protocol.Session_ref.equal session (Recurrence_run_origin.session origin)
      && Agent_protocol.Session_ref.equal session controller_session
      && Agent_protocol.Run_receipt.equal
           held.admission
           (Recurrence_run_origin.admission origin)
      && Option.is_none observation.terminal
    then Ok ()
    else
      Error (error Conflict "held association requires this exact self-target Admission")
  in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "held association index is unavailable")
  in
  let%bind () =
    if
      Option.exists
        (Run_state.recurrence_origin index held.run.id)
        ~f:(Recurrence_run_origin.equal origin)
    then Ok ()
    else
      Error (error Conflict "held association differs from the actual immutable origin")
  in
  observation.check_admitted ()
;;

let recurrence_import_evidence t (observation : Recurrence_run_observation.t) =
  let open Result.Let_syntax in
  let origin = observation.origin in
  let occurrence = Recurrence_run_origin.occurrence origin in
  let recurrence_id =
    occurrence
    |> Recurrence_identity.Occurrence.definition
    |> Recurrence_identity.Definition.recurrence_id
  in
  let%bind retained =
    match
      Option.bind t.state.recurrence_catalog ~f:(fun catalog ->
        Recurrence_catalog.find catalog recurrence_id)
    with
    | None -> Ok None
    | Some entry ->
      let%map frontier = Recurrence_entry.frontier entry in
      Recurrence_frontier.find_execution frontier occurrence
  in
  match retained with
  | None -> Ok (origin, observation.terminal)
  | Some execution ->
    let attempt = Recurrence_execution.current_attempt execution in
    let%bind () =
      Recurrence_run_origin.validate
        origin
        ~intent:(Recurrence_execution.intent execution)
        ~attempt:(Recurrence_execution.Attempt.request attempt)
    in
    let%bind () =
      match Recurrence_execution.Attempt.origin attempt with
      | None -> Ok ()
      | Some saved when Recurrence_run_origin.equal saved origin -> Ok ()
      | Some _ ->
        Error (error Conflict "observed recurrence origin differs from retained data")
    in
    (match Recurrence_execution.Attempt.terminal attempt with
     | None -> Ok (origin, observation.terminal)
     | Some saved ->
       (* Authenticate annotations against the actual retained target payload,
          then keep this complete original carrier for strict pure equality. *)
       let%map () = observation.validate_reference saved in
       origin, Some saved)
;;

let prepare_recurrence_import_candidate
      ?run_preparation
      t
      (observation : Recurrence_run_observation.t)
      admission
  =
  let open Result.Let_syntax in
  let prepare admission =
    prepare_transition
      ?run_preparation
      t
      ~delta:
        (Session_delta.Recurrence_catalog_changed
           (Recurrence_settlement_admission.catalog admission))
      ~payloads:[]
  in
  let%bind candidate = prepare admission in
  match Recurrence_settlement_admission.settlement admission with
  | Imported { next = Successor basis; _ } ->
    let recurrence_id =
      Recurrence_delay_basis.occurrence basis
      |> Recurrence_identity.Occurrence.definition
      |> Recurrence_identity.Definition.recurrence_id
    in
    let%bind entry =
      Result.of_option
        (Option.bind candidate.state.recurrence_catalog ~f:(fun catalog ->
           Recurrence_catalog.find catalog recurrence_id))
        ~error:(error Conflict "settlement successor entry is absent from candidate")
    in
    let wall = t.services.now () in
    let monotonic = t.services.monotonic_now () in
    let%bind phase =
      Recurrence_runtime.prepare_completion_phase
        t.recurrence_runtime
        ~completion:observation.completion
        ~basis
        ~entry
        ~state:candidate.state
        ~wall
        ~monotonic
    in
    (match phase with
     | Prepared phase ->
       let timing : Recurrence_import.Timing.t =
         match Recurrence_runtime.Completion_phase.source phase with
         | Live_completion -> Live_phase
         | Recovery_adoption -> Recovery_adoption
       in
       Ok
         Recurrence_import_candidate.
           { admission; transition = candidate; phase = Some phase; timing }
     | Timing_unavailable diagnostic ->
       (* Rebuild from the original catalog, never commit the automatic
          alternative first or classify contradictory facts as clock trouble. *)
       let%bind admission = Recurrence_settlement_admission.hold admission in
       let%map candidate = prepare admission in
       Recurrence_import_candidate.
         { admission; transition = candidate; phase = None; timing = Held diagnostic })
  | Imported { next = Evidence_only | Review_hold _; _ } ->
    Ok
      Recurrence_import_candidate.
        { admission; transition = candidate; phase = None; timing = No_successor }
  | Retained_exact _ | Detail_not_retained _ ->
    Error (error Conflict "unchanged recurrence import cannot prepare a transaction")
;;

let import_recurrence_execution_internal
      ?held
      t
      ~actor
      ~authorize
      ~automatic_policy
      ~(observation : Recurrence_run_observation.t)
  =
  let open Result.Let_syntax in
  let%bind () =
    Option.value_map held ~default:(Ok ()) ~f:(fun held ->
      check_held_recurrence_source t held observation)
  in
  let run_preparation =
    Option.map held ~f:(fun held -> held.Held_run.binding.preparation)
  in
  let%bind () = check_recurrence_import_owner t in
  let%bind () =
    Recurrence_command_admission.check_write actor ~authorize:(fun _ -> Ok ()) t.state
  in
  let%bind controller = require_recurrence_controller t in
  let%bind () =
    if Recurrence_controller.same_store controller observation.controller
    then Ok ()
    else Error (error Conflict "recurrence import requires the actual same Store")
  in
  let%bind () = observation.check_current () in
  let%bind origin, terminal = recurrence_import_evidence t observation in
  let%bind admission =
    Recurrence_settlement_admission.prepare
      t.state
      ~controller
      ~actor
      ~authorize
      ~automatic_policy
      ~origin
      ~terminal
  in
  let check_current admission =
    let%bind () = check_recurrence_import_owner t in
    let%bind () = observation.check_current () in
    let%bind () = Recurrence_settlement_admission.check_current admission t.state in
    (* Preserve both originals after all policies. The existing admission basis
       still invokes its original guard; recheck the target's pure owner/evidence
       basis after that callback, without another policy or evidence query. *)
    let%bind () = observation.check_authority () in
    let%bind () = Recurrence_settlement_admission.check_basis admission t.state in
    let%bind () =
      match held with
      | None -> Ok ()
      | Some held ->
        let%bind () = check_source_original t held.binding in
        let%bind () =
          Recurrence_command_admission.check_write
            actor
            ~authorize:(fun _ -> Ok ())
            t.state
        in
        let%bind () = check_held_recurrence_source t held observation in
        Recurrence_settlement_admission.check_state_basis admission t.state
    in
    let%bind () = observation.check_basis () in
    check_recurrence_import_owner t
  in
  let check_all admission =
    let%bind () =
      Option.value_map held ~default:(Ok ()) ~f:(fun held ->
        Source_binding.check_current held.Held_run.binding)
    in
    check_current admission
  in
  let%bind () = check_all admission in
  match Recurrence_settlement_admission.settlement admission with
  | (Retained_exact _ | Detail_not_retained _) as settlement ->
    Ok Recurrence_import.{ settlement; timing = No_successor }
  | Imported _ ->
    let%bind candidate =
      prepare_recurrence_import_candidate ?run_preparation t observation admission
    in
    let%bind () = check_all candidate.admission in
    let settlement = Recurrence_settlement_admission.settlement candidate.admission in
    let check_before_commit =
      Option.map held ~f:(fun _ -> fun () -> check_current candidate.admission)
    in
    let%bind () =
      persist_transition ?run_preparation ?check_before_commit t candidate.transition
    in
    install_committed_transition ?run_preparation t candidate.transition;
    Option.iter
      candidate.phase
      ~f:(Recurrence_runtime.install_completion_phase t.recurrence_runtime);
    publish_committed_transition t candidate.transition;
    (* Own ACK rotates Current, including a self-target's target observation.
       Refresh controller visibility only; acknowledged facts need no requery. *)
    let%bind current = Recurrence_controller.observe controller t.state in
    let%bind () =
      Recurrence_command_admission.check_write
        actor
        ~authorize:(fun state ->
          authorize state (Recurrence_settlement_admission.definition candidate.admission))
        t.state
    in
    let%bind () =
      match held with
      | None -> Ok ()
      | Some held ->
        (* Own ACK stales the target observation. Authenticate the actual live
           source and controller only, then check the advanced Held basis. *)
        let%bind () = check_source_original t held.binding in
        let%bind () =
          Recurrence_command_admission.check_write
            actor
            ~authorize:(fun _ -> Ok ())
            t.state
        in
        Held_run.check_basis held
    in
    let%bind () = check_recurrence_import_owner t in
    if Recurrence_controller.is_current current
    then Ok Recurrence_import.{ settlement; timing = candidate.timing }
    else Error (error Conflict "settlement controller visibility changed after ACK")
;;

let check_recurrence_activation_internal
      t
      custody
      (observation : Recurrence_run_observation.t)
  =
  let open Result.Let_syntax in
  let consumed = ref false in
  let%bind controller = require_recurrence_controller t in
  let owner () =
    let%bind () = check_recurrence_import_owner t in
    require_runtime_admission t
  in
  let%bind () = owner () in
  (* Reject foreign, closed or stale custody before its policy sees this state. *)
  let%bind () =
    Activation_custody.check_basis custody ~owner:t.recurrence_activation_owner t.state
  in
  let%bind () =
    if
      Recurrence_controller.same_store controller observation.controller
      && Recurrence_run_origin.equal
           (Activation_custody.origin custody)
           observation.origin
    then Ok ()
    else
      Error (error Conflict "activation requires the exact same-Store target observation")
  in
  let%bind () = observation.check_admitted () in
  let%bind () = Activation_custody.check_policy custody t.state in
  let%bind () = observation.check_current () in
  let%bind current = Recurrence_controller.observe controller t.state in
  let association : Activation_association.t =
    { issuer_policy = Recurrence
    ; check_target =
        (fun ~store ~state ~run ~admission ->
          let%bind () =
            if
              Recurrence_controller.same_store store observation.controller
              && Agent_protocol.Run_receipt.equal
                   admission
                   (Recurrence_run_origin.admission observation.origin)
            then Ok ()
            else
              Error
                (error Conflict "activation view belongs to another held Run or Store")
          in
          let%bind index =
            Result.of_option
              state.Session_state.run_state
              ~error:(error Conflict "held activation lost its Run index")
          in
          let%bind origin =
            Result.of_option
              (Run_state.recurrence_origin index run.Agent_protocol.Run.id)
              ~error:(error Conflict "held activation lost its reciprocal origin")
          in
          let%bind () =
            if Recurrence_run_origin.equal origin observation.origin
            then Ok ()
            else
              Error
                (error Conflict "activation view belongs to another held Run or Store")
          in
          Recurrence_run_origin.validate_run origin ~run ~admission)
    }
  in
  let check_basis () =
    let%bind () =
      if !consumed then Error (error Conflict "activation view was consumed") else Ok ()
    in
    let%bind () = owner () in
    let%bind () =
      Activation_custody.check_basis custody ~owner:t.recurrence_activation_owner t.state
    in
    let%bind () = observation.check_admitted () in
    let definition = Activation_custody.definition custody in
    let%bind () =
      if
        Recurrence_controller.is_current current
        && Recurrence_controller.automatic current
        && Agent_protocol.Session_lifecycle.Revision.equal
             (Recurrence_controller.revision current)
             (Recurrence_definition.birth_lifecycle_revision definition)
      then Ok ()
      else Error (error Conflict "activation controller lifecycle observation changed")
    in
    owner ()
  in
  let check_policy () =
    let%bind () = check_basis () in
    let%bind () = Activation_custody.check_policy custody t.state in
    let%bind () = observation.check_policy () in
    check_basis ()
  in
  let check_authority () =
    let%bind () = check_basis () in
    let%bind () = Activation_custody.check_authority custody in
    let%bind () = observation.check_authority () in
    check_basis ()
  in
  let sample_timing () =
    let%bind entry = Activation_custody.entry custody t.state in
    (* These supplied readers are host callbacks. Sample them before the final
       pure bases, never from a purported callback-free first-effect fence. *)
    let wall = t.services.now () in
    let monotonic = t.services.monotonic_now () in
    let%bind snapshot =
      Recurrence_runtime.snapshot t.recurrence_runtime ~wall ~monotonic
    in
    let%bind late =
      Recurrence_runtime.selection_lateness
        t.recurrence_runtime
        ~entry
        ~nominal:(Activation_custody.nominal custody)
        ~snapshot
    in
    let%bind () =
      match late with
      | Some late
        when Int64.(
               late
               <= Recurrence_policy.grace_ns
                    (Recurrence_definition.policy (Activation_custody.definition custody)))
        -> Ok ()
      | None | Some _ ->
        Error (error Conflict "activation nominal is outside current grace")
    in
    Ok ()
  in
  let check_timing () =
    let%bind () = check_basis () in
    let%bind () = sample_timing () in
    check_basis ()
  in
  let check_current () =
    (* A returned view may outlive its cell. Never invoke its stored policy then. *)
    let%bind () = check_basis () in
    let%bind () = check_policy () in
    let%bind () = check_authority () in
    let%bind () = check_timing () in
    check_basis ()
  in
  let%map () = check_current () in
  let continue (target : Held_run.Activation.t) =
    let refreshed = ref None in
    let owned () =
      let%bind () =
        if Int.equal target.domain (Stdlib.Domain.self () :> int)
        then Ok ()
        else
          Error (error Invalid_request "held continuation belongs to another Eio domain")
      in
      let%bind () = owner () in
      let%bind () =
        Activation_custody.check_basis
          custody
          ~owner:t.recurrence_activation_owner
          t.state
      in
      target.owned_basis ()
    in
    let basis () =
      let%bind () = owned () in
      let%bind () = Held_run.Activation.check_basis target in
      match !refreshed with
      | Some current
        when Recurrence_controller.is_current current
             && Recurrence_controller.automatic current
             && Agent_protocol.Session_lifecycle.Revision.equal
                  (Recurrence_controller.revision current)
                  (Recurrence_definition.birth_lifecycle_revision
                     (Activation_custody.definition custody)) -> Ok ()
      | Some _ | None ->
        Error
          (error Conflict "owned activation needs a fresh controller Store observation")
    in
    let policy () =
      let%bind () = basis () in
      let%bind () = Activation_custody.check_policy custody t.state in
      let%bind () = observation.check_policy () in
      let%bind () = target.check_policy () in
      basis ()
    in
    let refresh () =
      (* Unlike the old Checked view this preflight does not require a stale
         Current to be fresh before acquiring its genuine replacement. *)
      let%bind () = owned () in
      let%bind () = Activation_custody.check_policy custody t.state in
      let%bind () = observation.check_policy () in
      let%bind () = target.policy () in
      let%bind current = Recurrence_controller.observe controller t.state in
      refreshed := Some current;
      policy ()
    in
    let timing () =
      let%bind () = basis () in
      let%bind () = sample_timing () in
      basis ()
    in
    let authority () =
      let%bind () = basis () in
      let%bind () = Activation_custody.check_authority custody in
      let%bind () = observation.check_authority () in
      let%bind () = target.authority () in
      basis ()
    in
    let transfer () =
      let%bind () = basis () in
      let%map transfer =
        Activation_custody.Transfer.prepare
          custody
          ~owner:t.recurrence_activation_owner
          t.state
      in
      let operation = Activation_custody.Transfer.operation transfer in
      let current = ref None in
      let owned () =
        let%bind () = owner () in
        Activation_custody.Operation.check_basis
          operation
          ~owner:t.recurrence_activation_owner
          t.state
      in
      let basis () =
        let%bind () = owned () in
        match !current with
        | Some current
          when Recurrence_controller.is_current current
               && Recurrence_controller.automatic current
               && Agent_protocol.Session_lifecycle.Revision.equal
                    (Recurrence_controller.revision current)
                    (Recurrence_definition.birth_lifecycle_revision
                       (Activation_custody.definition custody)) -> Ok ()
        | Some _ | None ->
          Error (error Conflict "operation needs fresh controller Store custody")
      in
      let policy () =
        let%bind () = basis () in
        let%bind () = Activation_custody.Operation.check_policy operation t.state in
        let%bind () = observation.check_policy () in
        basis ()
      in
      let refresh () =
        let%bind () = owned () in
        let%bind () = Activation_custody.Operation.check_policy operation t.state in
        let%bind () = observation.check_policy () in
        let%bind observed = Recurrence_controller.observe controller t.state in
        current := Some observed;
        policy ()
      in
      let timing () =
        let%bind () = basis () in
        let%bind () = sample_timing () in
        basis ()
      in
      let authority () =
        let%bind () = basis () in
        let%bind () = Activation_custody.Operation.check_authority operation in
        let%bind () = observation.check_authority () in
        basis ()
      in
      ({ association
       ; install = (fun () -> Activation_custody.Transfer.install transfer)
       ; close = (fun () -> Activation_custody.Operation.close operation)
       ; refresh
       ; policy
       ; timing
       ; authority
       ; basis
       }
       : Activation_controller.Operation.t)
    in
    let controller : Activation_controller.t = { transfer } in
    ({ target
     ; controller
     ; refresh
     ; policy
     ; refresh_admitted_inference = refresh
     ; policy_admitted_inference = policy
     ; timing
     ; authority
     ; basis
     }
     : Admitted_activation.Continuation.t)
  in
  ({ check_current
   ; check_policy
   ; check_authority
   ; check_timing
   ; check_basis
   ; association
   ; continue
   ; consumed
   }
   : Recurrence_activation.Checked.t)
;;

let goal_run_receipt_internal t ~actor ~authorize ~request ~session =
  let open Result.Let_syntax in
  let check_authority () =
    let%bind () = Run_command_authorization.check actor ~authorize t.state in
    Result.map (Goal_command_admission.read t.state ~actor ~authorize) ~f:ignore
  in
  let%bind () = check_authority () in
  let%bind controller = require_recurrence_controller t in
  let%bind () =
    if Agent_protocol.Session_ref.equal session (Recurrence_controller.session controller)
    then Ok ()
    else Error (error Invalid_request "Goal receipt targets another actor")
  in
  let headless = Goal_activation_request.request request in
  let%bind digest =
    Run_admission_request.request_sha256 (Run_admission_request.of_headless headless)
  in
  let%bind current = Recurrence_controller.observe controller t.state in
  let%bind () = check_authority () in
  let index = Option.value t.state.run_state ~default:Run_state.empty in
  let%bind receipt =
    Run_state.receipt
      index
      ~principal_id:(Operator_authorization.principal actor).id
      ~key:headless.key
      ~request_sha256:digest
  in
  let%bind () =
    match receipt with
    | None -> Ok ()
    | Some receipt ->
      let%bind link =
        Result.of_option
          (Run_state.goal_link index receipt.run_id)
          ~error:(error Conflict "retained Run has no original Goal association")
      in
      if
        Agent_protocol.Run_receipt.Kind.equal receipt.kind Admission
        && String.equal
             (Run_goal_link.intent_sha256 link)
             (Goal_episode_admission.digest (Goal_activation_request.intent request))
        && Agent_protocol.Run_receipt.equal
             receipt
             (Agent_protocol.Goal_episode.admission (Run_goal_link.episode link))
      then Ok ()
      else Error (error Conflict "retained Goal association intent changed")
  in
  let%bind () = check_authority () in
  if Recurrence_controller.is_current current
  then Ok receipt
  else Error (error Conflict "Goal receipt Store observation changed")
;;

let goal_resume_receipt_internal t ~actor ~authorize ~session ~request =
  let open Result.Let_syntax in
  let check_authority () =
    let%bind () = Run_command_authorization.check actor ~authorize t.state in
    Result.map (Goal_command_admission.read t.state ~actor ~authorize) ~f:ignore
  in
  let%bind () = check_authority () in
  let%bind controller = require_recurrence_controller t in
  let%bind () =
    if Agent_protocol.Session_ref.equal session (Recurrence_controller.session controller)
    then Ok ()
    else Error (error Invalid_request "Goal resume receipt targets another actor")
  in
  let%bind current = Recurrence_controller.observe controller t.state in
  let%bind () = check_authority () in
  let%bind receipt =
    Goal_resume_admission.find_receipt
      t.state
      ~request
      ~principal_id:(Operator_authorization.principal actor).id
  in
  let%bind () = check_authority () in
  if Recurrence_controller.is_current current
  then Ok receipt
  else Error (error Conflict "Goal resume receipt Store observation changed")
;;

let check_job_runtime_owner_internal t (owner : Job_runtime_owner.t) =
  let open Result.Let_syntax in
  let%bind () =
    if
      Int.equal owner.domain (Stdlib.Domain.self () :> int)
      && phys_equal owner.issuing_actor t.inference_owner_identity
    then Ok ()
    else Error (error Conflict "Job runtime owner belongs to another Actor")
  in
  job_scope_can_execute t owner.scope
;;

let pending_goal_wake_run t (wake : Agent_protocol.Run_wake.t) =
  let open Result.Let_syntax in
  let%bind () = Agent_protocol.Run_wake.validate wake in
  match t.state.run_state with
  | None -> Ok None
  | Some index ->
    (match Run_state.find index wake.run_id with
     | None -> Ok None
     | Some run ->
       (match run.lifecycle with
        | Waiting retained when Agent_protocol.Run_wake.equal retained wake ->
          if
            List.exists (Run_state.intents index) ~f:(fun intent ->
              match intent.Run_intent.disposition, intent.action with
              | Pending, Wait pending -> Agent_protocol.Run_wake.equal pending wake
              | _ -> false)
          then Ok (Some run)
          else Error (error Conflict "Goal wake lost its actual Pending Wait")
        | Admitted | Active | Waiting _ | Terminal _ -> Ok None))
;;

let goal_wake_queue_head t run wake =
  let open Result.Let_syntax in
  let%bind snapshot = Moderator_checkpoint.decode t.state.moderator in
  match snapshot with
  | None -> Ok false
  | Some snapshot ->
    (match snapshot.queued_internal_events with
     | [] -> Ok false
     | _ :: _ ->
       (* This is the existing pure candidate validation, not a persisted claim.
          Its fresh ID and returned receipt are never exposed as authority. *)
       let%bind executing, event =
         Queued_moderator_event.claim
           ~state:t.state
           ~id:(Agent_protocol.Id.Moderator_execution.create ())
           ~snapshot
           ~now:(t.services.now ())
       in
       let%bind reason =
         Queued_moderator_event.delivery_retirement_reason
           ~state:t.state
           ~observer:executing.context.source
           ~event
           ~subscription_expired:(subscription_is_due t)
       in
       (match reason with
        | Some _ -> Ok false
        | None -> Run_wake_owner.claim_matches t.state ~run ~wake ~executing))
;;

let goal_wake_producer_ready t run (wake : Agent_protocol.Run_wake.t) =
  let open Result.Let_syntax in
  let%bind () =
    match wake.occurrence with
    | Job_completion _ ->
      (match
         Option.bind t.state.run_state ~f:(fun index ->
           Option.bind
             (Run_job_delivery.Key.of_wake wake)
             ~f:(Run_state.find_job_delivery index))
       with
       | Some delivery ->
         if
           Agent_protocol.Id.Run.equal
             (Run_job_delivery.run_id delivery)
             run.Agent_protocol.Run.id
           && Agent_protocol.Run_source.equal
                (Run_job_delivery.source delivery)
                wake.source
         then Ok ()
         else Error (error Conflict "retained Goal Job delivery owner changed")
       | None -> Run_wake_owner.validate t.state ~run ~wake)
    | Delivered_timer _ | Subscription_delivery _ ->
      Run_wake_owner.validate t.state ~run ~wake
  in
  match wake.occurrence with
  | Delivered_timer { schedule_id; _ } ->
    let%bind schedule = find_schedule t schedule_id in
    (match schedule.status with
     | Scheduled | Delivering ->
       Ok (Agent_protocol.Timestamp.compare schedule.next_due_at (t.services.now ()) <= 0)
     | Delivered -> goal_wake_queue_head t run wake
     | Cancelled | Failed _ -> Ok false)
  | Job_completion { job_id; attempt } ->
    let retained =
      Option.bind t.state.run_state ~f:(fun index ->
        Option.bind
          (Run_job_delivery.Key.of_wake wake)
          ~f:(Run_state.find_job_delivery index))
    in
    (match retained with
     | Some delivery ->
       (match Run_job_delivery.disposition delivery with
        | Pending -> Ok true
        | Enqueued _ -> goal_wake_queue_head t run wake
        | Claimed _ | Retired _ -> Ok false)
     | None ->
       let%bind job = find_job t job_id in
       if not (Int.equal attempt job.attempt)
       then
         Error (error Conflict "Goal wake Job attempt changed without retained delivery")
       else (
         match job.status, job.delivery with
         | (Succeeded | Failed _ | Cancelled | Interrupted _), Pending -> Ok true
         | (Succeeded | Failed _ | Cancelled | Interrupted _), Delivered _ ->
           goal_wake_queue_head t run wake
         | _ -> Ok false))
  | Subscription_delivery { delivery_id; _ } ->
    let%bind delivery =
      List.find t.state.deliveries ~f:(fun delivery ->
        Agent_protocol.Id.Delivery.equal delivery.context.id delivery_id)
      |> Result.of_option ~error:(error Conflict "Goal wake delivery is absent")
    in
    Ok
      (match delivery.status, delivery.wake_disposition with
       | Committed _, Some Pending_wake -> true
       | _ -> false)
;;

let classify_goal_wake t wake
  : (Goal_execution_runtime.Wake_selection.t, Agent_protocol.Error.t) result
  =
  let open Result.Let_syntax in
  let%bind run = pending_goal_wake_run t wake in
  match run with
  | None -> Ok Goal_execution_runtime.Wake_selection.No_work
  | Some run ->
    let%bind attribution = Goal_work_attribution.of_run t.state run in
    (match attribution with
     | None -> Ok Goal_execution_runtime.Wake_selection.Ordinary
     | Some _ ->
       let%bind ready = goal_wake_producer_ready t run wake in
       if not ready
       then Ok Goal_execution_runtime.Wake_selection.No_work
       else (
         let%map selection = Goal_execution_selection.of_run t.state run in
         match selection with
         | Eligible -> Goal_execution_runtime.Wake_selection.Wake wake
         | Suspended_goal suspension -> Suspended_goal suspension))
;;

let validate_goal_wake_request t (request : Goal_execution_runtime.Wake_request.t) =
  let open Result.Let_syntax in
  let changed () = Error (error Conflict "Goal wake producer changed before routing") in
  match request with
  | Idle -> Ok ()
  | Timer expected ->
    let%bind current = find_schedule t expected.id in
    if
      Jsonaf.exactly_equal
        (Agent_protocol.Schedule.to_json current)
        (Agent_protocol.Schedule.to_json expected)
    then Ok ()
    else changed ()
  | Job_completion expected ->
    let%bind current = find_job t expected.id in
    if
      Jsonaf.exactly_equal
        (Agent_protocol.Job.to_json current)
        (Agent_protocol.Job.to_json expected)
    then Ok ()
    else changed ()
  | Job_delivery expected ->
    let%bind current =
      Option.bind t.state.run_state ~f:(fun index ->
        Run_state.find_job_delivery index (Run_job_delivery.key expected))
      |> Result.of_option ~error:(error Conflict "Goal retained Job delivery is absent")
    in
    if Run_job_delivery.equal current expected then Ok () else changed ()
;;

let select_goal_runtime_wake_internal t (request : Goal_execution_runtime.Wake_request.t) =
  let open Result.Let_syntax in
  let%bind () = validate_goal_wake_request t request in
  let wakes =
    Option.value_map t.state.run_state ~default:[] ~f:(fun index ->
      List.filter_map (Run_state.runs index) ~f:(fun run ->
        match run.Agent_protocol.Run.lifecycle with
        | Waiting wake -> Some wake
        | _ -> None))
  in
  let matching matches =
    match List.filter wakes ~f:matches with
    | [] -> Ok Goal_execution_runtime.Wake_selection.Ordinary
    | [ wake ] -> classify_goal_wake t wake
    | _ -> Error (error Conflict "producer references conflicting retained Wait owners")
  in
  match request with
  | Timer expected ->
    let%bind current = find_schedule t expected.id in
    matching (fun wake ->
      match wake.occurrence with
      | Delivered_timer { schedule_id; _ } ->
        Agent_protocol.Id.Schedule.equal schedule_id current.id
      | Job_completion _ | Subscription_delivery _ -> false)
  | Job_completion expected ->
    let%bind current = find_job t expected.id in
    matching (fun wake ->
      match wake.occurrence with
      | Job_completion { job_id; attempt } ->
        Agent_protocol.Id.Job.equal job_id current.id && Int.equal attempt current.attempt
      | Delivered_timer _ | Subscription_delivery _ -> false)
  | Job_delivery current ->
    matching (fun wake ->
      Option.exists
        (Run_job_delivery.Key.of_wake wake)
        ~f:(Run_job_delivery.Key.equal (Run_job_delivery.key current)))
  | Idle ->
    let%bind snapshot = Moderator_checkpoint.decode t.state.moderator in
    let queued =
      Option.exists snapshot ~f:(fun snapshot ->
        not (List.is_empty snapshot.queued_internal_events))
    in
    if queued
    then (
      let%bind heads =
        List.filter_map wakes ~f:(fun wake ->
          match wake.Agent_protocol.Run_wake.occurrence with
          | Subscription_delivery _ -> None
          | Job_completion _ | Delivered_timer _ -> Some wake)
        |> List.map ~f:(fun wake ->
          let%bind run = pending_goal_wake_run t wake in
          let%map matches =
            Option.value_map run ~default:(Ok false) ~f:(fun run ->
              goal_wake_queue_head t run wake)
          in
          Option.some_if matches wake)
        |> Result.all
        |> Result.map ~f:List.filter_opt
      in
      match heads with
      | [] -> Ok Goal_execution_runtime.Wake_selection.Ordinary
      | [ wake ] -> classify_goal_wake t wake
      | _ -> Error (error Conflict "queue head has conflicting retained Goal wakes"))
    else (
      (* Same oldest-first durable wake order as Notification_delivery. A Wait
         locator which has no eligible delivery never suppresses other work. *)
      let deliveries =
        List.filter t.state.deliveries ~f:(fun delivery ->
          Int.equal
            delivery.Agent_protocol.Delivery.context.generation
            t.state.identity.generation
          && (Option.is_some delivery.context.ownership
              || Option.is_some delivery.completion_projection)
          &&
          match delivery.status, delivery.wake_disposition with
          | Committed _, Some Pending_wake -> true
          | (Pending | Failed _), _
          | Committed _, (None | Some (Accepted_wake _ | Discarded_wake _)) -> false)
        |> List.sort ~compare:(fun (left : Agent_protocol.Delivery.t) right ->
          match
            Agent_protocol.Timestamp.compare
              left.context.created_at
              right.context.created_at
          with
          | 0 -> Agent_protocol.Id.Delivery.compare left.context.id right.context.id
          | order -> order)
      in
      let rec select ~suspended = function
        | [] ->
          Ok
            (Option.value
               suspended
               ~default:Goal_execution_runtime.Wake_selection.Ordinary)
        | (delivery : Agent_protocol.Delivery.t) :: remaining ->
          let%bind selection =
            matching (fun wake ->
              match wake.occurrence with
              | Subscription_delivery { delivery_id; _ } ->
                Agent_protocol.Id.Delivery.equal delivery.context.id delivery_id
              | Job_completion _ | Delivered_timer _ -> false)
          in
          (match selection with
           | Ordinary | Wake _ -> Ok selection
           | No_work -> select ~suspended remaining
           | Suspended_goal _ ->
             select
               ~suspended:(Some (Option.value suspended ~default:selection))
               remaining)
      in
      select ~suspended:None deliveries)
;;

(* Negative-only original-custody maintenance. Routing DATA never permits a
   source borrow or claim, including when Hold clears while callbacks yield. *)
let reconcile_goal_wake_authority_internal t request =
  let open Result.Let_syntax in
  (* Reuse exact canonical DTO comparison before choosing any retained owner. *)
  let%bind () = validate_goal_wake_request t request in
  let matching (wake : Agent_protocol.Run_wake.t) =
    match request, wake.occurrence with
    | Goal_execution_runtime.Wake_request.Idle, _ -> true
    | Timer schedule, Delivered_timer { schedule_id; _ } ->
      Agent_protocol.Id.Schedule.equal schedule.id schedule_id
    | Job_completion job, Job_completion { job_id; attempt } ->
      Agent_protocol.Id.Job.equal job.id job_id && Int.equal job.attempt attempt
    | Job_delivery delivery, Job_completion _ ->
      Option.exists
        (Run_job_delivery.Key.of_wake wake)
        ~f:(Run_job_delivery.Key.equal (Run_job_delivery.key delivery))
    | Timer _, (Job_completion _ | Subscription_delivery _)
    | Job_completion _, (Delivered_timer _ | Subscription_delivery _)
    | Job_delivery _, (Delivered_timer _ | Subscription_delivery _) -> false
  in
  let owners =
    Option.value_map t.state.run_state ~default:[] ~f:(fun index ->
      List.filter (Run_state.runs index) ~f:(fun run ->
        match run.Agent_protocol.Run.lifecycle with
        | Waiting wake -> matching wake
        | Admitted | Active | Terminal _ -> false))
  in
  List.fold_result owners ~init:() ~f:(fun () expected_run ->
    let%bind current =
      Option.bind t.state.run_state ~f:(fun index -> Run_state.find index expected_run.id)
      |> Result.of_option
           ~error:(error Conflict "Goal wake disappeared during maintenance")
    in
    let%bind () =
      if
        Jsonaf.exactly_equal
          (Agent_protocol.Run.to_json current)
          (Agent_protocol.Run.to_json expected_run)
      then Ok ()
      else Error (error Conflict "Goal wake occurrence changed during maintenance")
    in
    (* Historical immutable association chooses factual maintenance. It does
       not require current Goal Enabled/episode/source policy or issue rights. *)
    let link =
      Option.bind t.state.run_state ~f:(fun index -> Run_state.goal_link index current.id)
    in
    match link with
    | None -> Ok ()
    | Some _ ->
      let expected = t.state in
      let binding = Run_authorities.find t.run_authorities expected_run.id in
      let check_original () =
        let%bind index =
          Result.of_option
            t.state.run_state
            ~error:(error Conflict "Goal wake source index disappeared")
        in
        let installation = Run_state.installation index in
        if
          Int.equal current.source.generation t.state.identity.generation
          && Int64.equal current.source.installation_epoch installation.epoch
          && Option.exists
               installation.source
               ~f:(Agent_protocol.Invocation.equal_observer current.source.observer)
        then check_run_binding t expected_run.id
        else Error (error Permission_denied "Goal wake lost its original source")
      in
      (match check_original () with
       | Ok () -> Ok ()
       | Error _ ->
         let%bind () =
           if
             phys_equal expected t.state
             && Option.equal
                  phys_equal
                  binding
                  (Run_authorities.find t.run_authorities expected_run.id)
           then Ok ()
           else Error (error Conflict "Goal wake owner changed during retirement check")
         in
         let%bind index =
           Result.of_option
             t.state.run_state
             ~error:(error Conflict "Goal wake Run index disappeared during retirement")
         in
         let%bind index =
           Run_retirement.interrupt_run
             index
             ~run_id:expected_run.id
             ~session_revision:(Int64.succ t.state.counters.revision)
             ~now:(t.services.now ())
         in
         transition
           t
           ~check_before_commit:(fun () ->
             if
               phys_equal expected t.state
               && Option.equal
                    phys_equal
                    binding
                    (Run_authorities.find t.run_authorities expected_run.id)
             then Ok ()
             else Error (error Conflict "Goal wake changed before retirement ACK"))
           ~delta:(Session_delta.Run_state_changed index)
           ~payloads:[]
         |> Result.map ~f:ignore))
;;

(* Ordinary child loading has its own source custody. This does not manufacture
   a Run binding or Init; the Factory later consumes the actual route derived
   here, and the Init receiver repeats its existing independent eligibility. *)
let delegated_load_preparation_basis t (preparation : Delegated_load.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () =
    if
      Int.equal preparation.domain (Stdlib.Domain.self () :> int)
      && (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.exists
           t.runtime_source_owner
           ~f:(Runtime_source_owner.Identity.equal preparation.source_owner)
    then Ok ()
    else Error (error Conflict "delegated load lost its actual Factory/Actor owner")
  in
  let%bind () = require_runtime_admission t in
  let%bind () = require_selected_execution t in
  let%bind () =
    match
      Delegated_runtime_load.initial_preparation preparation.load, t.run_preparation
    with
    | Some expected, Some (Preparation_owner.Initial actual)
      when phys_equal expected actual ->
      (* Includes the actual retry-phase gate; a pending retry never reaches a
         native constructor by presenting only a captured initial preparation. *)
      let%bind () = check_retry_execution t actual in
      Run_preparation.check_basis actual ~owner:t.run_preparation_owner ~state:t.state
    | None, Some (Delegated_load actual) when phys_equal actual preparation -> Ok ()
    | (Some _ | None), (Some _ | None) ->
      Error (error Conflict "delegated load is not this Actor's active preparation")
  in
  let%bind () =
    Delegated_runtime_load.check_basis
      preparation.load
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  Option.value_map preparation.binding ~default:(Ok ()) ~f:(fun binding ->
    Delegated_runtime_load.Source_binding.check_basis
      binding
      ~owner:t.run_preparation_owner
      ~state:t.state)
;;

let delegated_load_current t (preparation : Delegated_load.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = delegated_load_preparation_basis t preparation in
  let%bind () =
    Delegated_runtime_load.check_authority
      preparation.load
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  delegated_load_preparation_basis t preparation
;;

let refresh_delegated_load t (preparation : Delegated_load.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = delegated_load_current t preparation in
  let%bind controller = require_recurrence_controller t in
  let%bind observed = Recurrence_controller.observe controller t.state in
  preparation.observed <- Some observed;
  let%bind () = delegated_load_current t preparation in
  if Recurrence_controller.is_current observed
  then Ok ()
  else Error (error Conflict "delegated load Store observation changed")
;;

let begin_delegated_load_preparation_internal t ~source_owner ~custody =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind () = require_selected_execution t in
  let%bind () =
    if Option.exists t.runtime_source_owner ~f:(Runtime_source_owner.matches source_owner)
    then Ok ()
    else Error (error Conflict "delegated load issuer differs from its actual Factory")
  in
  let%bind () =
    match custody, t.run_preparation with
    | Delegated_load.Custody.Host (Some _ | None), None -> Ok ()
    | Prepared_run expected, Some (Preparation_owner.Initial actual)
      when phys_equal actual expected -> check_run_preparation t actual
    | (Host _ | Prepared_run _), (Some _ | None) ->
      Error (error Conflict "another source preparation owns this Actor")
  in
  let%bind () =
    if
      Option.is_none t.operation_worker
      && Option.is_none t.initialization_scope
      && (not (moderator_is_borrowed t))
      && not t.idle_moderator_borrowed
    then Ok ()
    else Error (error Conflict "delegated cold load requires its actual empty runtime")
  in
  let%bind load =
    Delegated_runtime_load.capture ~owner:t.run_preparation_owner ~state:t.state ~custody
  in
  let unresolved_run =
    Option.exists t.state.run_state ~f:(fun index ->
      List.exists (Run_state.runs index) ~f:(fun run ->
        match run.Agent_protocol.Run.lifecycle with
        | Admitted | Active | Waiting _ -> true
        | Terminal _ -> false))
  in
  let initialization =
    match t.state.runtime_initialization, custody with
    | Pending _, _ -> Delegated_load.Initialization.Scoped
    | Ready, Host None -> Installed_resume
    | Ready, (Host (Some _) | Prepared_run _) ->
      if unresolved_run then Installed_resume else Scoped
  in
  let rec preparation : Delegated_load.Preparation.t =
    { load
    ; initialization
    ; domain = (Stdlib.Domain.self () :> int)
    ; source_owner = Runtime_source_owner.identity source_owner
    ; basis = (fun () -> delegated_load_preparation_basis t preparation)
    ; refresh = (fun () -> refresh_delegated_load t preparation)
    ; current = (fun () -> delegated_load_current t preparation)
    ; authority = (fun () -> delegated_load_current t preparation)
    ; binding = None
    ; consumed = false
    ; observed = None
    ; installation = None
    }
  in
  (match custody with
   | Host _ -> t.run_preparation <- Some (Preparation_owner.Delegated_load preparation)
   | Prepared_run _ -> ());
  Ok preparation
;;

let bind_delegated_load_source_internal t ~preparation ~source =
  let open Result.Let_syntax in
  let%bind () = delegated_load_current t preparation in
  let%bind () =
    if
      Option.is_none preparation.Delegated_load.Preparation.binding
      && not preparation.consumed
    then Ok ()
    else Error (error Conflict "delegated source selection was already bound")
  in
  let%map binding =
    Delegated_runtime_load.Source_binding.bind
      preparation.load
      ~owner:t.run_preparation_owner
      ~state:t.state
      ~source
  in
  preparation.binding <- Some binding;
  ({ preparation; source; binding } : Delegated_load.Source_binding.t)
;;

let prepare_delegated_load_internal t (binding : Delegated_load.Source_binding.t) =
  let open Result.Let_syntax in
  let%bind () = Delegated_load.Source_binding.check_basis binding in
  let%bind () = delegated_load_current t binding.preparation in
  let%bind () =
    Delegated_runtime_load.Source_binding.consume
      binding.binding
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  binding.preparation.consumed <- true;
  Ok binding
;;

let end_delegated_load_preparation_internal t (preparation : Delegated_load.Preparation.t)
  =
  if
    Int.equal preparation.domain (Stdlib.Domain.self () :> int)
    && Preparation_tracking.belongs_to
         (Delegated_runtime_load.tracking preparation.load)
         ~owner:t.run_preparation_owner
  then (
    Delegated_load.Preparation.close preparation;
    (match t.run_preparation with
     | Some (Preparation_owner.Delegated_load current) when phys_equal current preparation
       -> t.run_preparation <- None
     | Some (Initial _ | Existing_goal _ | Delegated_load _) | None -> ());
    Ok ())
  else Error (error Conflict "delegated load cleanup belongs to another Actor")
;;

let delegated_load_request
  : type a. t -> a Delegated_load_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t -> function
  | Begin (source_owner, custody) ->
    begin_delegated_load_preparation_internal t ~source_owner ~custody
  | Bind (preparation, source) ->
    bind_delegated_load_source_internal t ~preparation ~source
  | Prepare binding -> prepare_delegated_load_internal t binding
  | End preparation -> end_delegated_load_preparation_internal t preparation
;;

let goal_existing_execution_quiescent t cause =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind () = require_runtime_admission t in
  if
    (not t.stopped)
    && Option.is_none (Eio.Promise.peek t.finished)
    && Option.is_none t.state.failure
    && Option.is_none t.state.active_operation
    && (match t.state.lifecycle.observed with
        | Idle | Stopped -> true
        | _ -> false)
    && (not t.idle_moderator_borrowed)
    && (not (moderator_is_borrowed t))
    && Option.is_none t.queued_event_borrow
    && Option.is_none t.legacy_callback_scope
    && Option.is_none t.initialization_scope
    && Option.is_none t.held_activation
    && Option.is_none t.held_input_scope
    && Option.is_none t.held_authored_start
    && List.is_empty t.invocation_executions
    && List.for_all t.job_scopes ~f:(fun scope ->
      match cause with
      | Some (Existing_goal_preparation.Cause.Claimed_job { owner; _ }) ->
        phys_equal owner.scope scope
      | Some (Resume_command _ | Pending_wake _) | None -> false)
  then Ok ()
  else Error (error Conflict "Goal resume requires its actual idle construction lane")
;;

let goal_resume_quiescent t = goal_existing_execution_quiescent t None

type goal_preparation_use =
  | Fresh_effect
  | Registered_allocation

let goal_preparation_basis_for use t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () =
    if
      Int.equal preparation.domain (Stdlib.Domain.self () :> int)
      && (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.exists t.run_preparation ~f:(function
        | Existing_goal current -> phys_equal current preparation
        | Initial _ | Delegated_load _ -> false)
    then require_runtime_admission t
    else Error (error Conflict "Goal continuation lost its actual Actor owner")
  in
  let%bind () =
    Run_preparation.Custody.check_basis
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let%bind () =
    if
      Run_authorities.is_current
        t.run_authorities
        preparation.binding
        ~run_id:preparation.run.id
    then Ok ()
    else Error (error Permission_denied "Goal continuation lost its original Run binding")
  in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "Goal continuation Run index is absent")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index preparation.run.id)
      ~error:(error Conflict "Goal continuation Run is absent")
  in
  let%bind link =
    Result.of_option
      (Run_state.goal_link index run.id)
      ~error:(error Conflict "Goal continuation immutable association is absent")
  in
  let%bind admission =
    Run_state.receipt
      index
      ~principal_id:preparation.admission.principal_id
      ~key:preparation.admission.key
      ~request_sha256:preparation.admission.request_sha256
  in
  let%bind goal =
    Option.bind t.state.goal_catalog ~f:(fun catalog ->
      Goal_catalog.find catalog (Run_goal_link.goal_id preparation.link))
    |> Result.of_option ~error:(error Conflict "Goal continuation Goal is absent")
  in
  let%bind () =
    if
      Run_goal_link.equal link preparation.link
      && Agent_protocol.Goal_episode.matches_run (Run_goal_link.episode link) run
      && Option.exists
           admission
           ~f:(Agent_protocol.Run_receipt.equal preparation.admission)
      && Agent_protocol.Run_source.equal run.source preparation.run.source
      && Agent_protocol.Run_source.equal (Agent_protocol.Goal.source goal) run.source
      && Option.exists
           (Agent_protocol.Goal.episode goal)
           ~f:(Agent_protocol.Goal_episode.equal (Run_goal_link.episode link))
      && Agent_protocol.Session_ref.equal run.session preparation.session
    then Ok ()
    else Error (error Conflict "Goal continuation immutable Run/source/episode changed")
  in
  let%bind captured_index, source = Moderator_source_installation.capture t.state in
  let%bind () =
    if
      Run_state.equal captured_index index
      && Agent_protocol.Run_source.equal source preparation.run.source
    then Ok ()
    else Error (error Conflict "Goal continuation source installation changed")
  in
  let%bind () =
    match run.lifecycle with
    | Admitted | Active | Waiting _ -> Ok ()
    | Terminal _ -> Error (error Conflict "Goal continuation Run is terminal")
  in
  let%bind () =
    Goal_activation_policy.check_admitted_policy preparation.policy ~state:t.state
  in
  let%bind () =
    match preparation.cause with
    | Resume_command _ -> Ok ()
    | Pending_wake { wake; _ } ->
      let transferred = goal_wake_transferred_borrow t preparation in
      if transferred
      then Ok ()
      else (
        let%bind pending = pending_goal_wake_run t wake in
        if
          Option.exists pending ~f:(fun current ->
            Agent_protocol.Id.Run.equal current.id run.id)
        then Ok ()
        else Error (error Conflict "Goal execution no longer owns its Pending Wait"))
    | Claimed_job { owner; _ } ->
      let%bind current = job_scope_current t owner.scope in
      let%bind parent = job_runtime_run t current in
      if
        Option.exists parent ~f:(fun parent ->
          Agent_protocol.Id.Run.equal parent.id run.id)
      then Ok ()
      else Error (error Conflict "Goal Job original Run changed")
  in
  match preparation.cause with
  | Resume_command _ ->
    (match preparation.phase, Agent_protocol.Goal.state goal with
     | (Preparing | Source_bound _ | Writer_pending _), Open (Held _) -> Ok ()
     | Ready _, Open Enabled -> Ok ()
     | Ready _, Open (Held _)
       when match use with
            | Registered_allocation -> true
            | Fresh_effect -> false -> Ok ()
     | ( (Preparing | Source_bound _ | Writer_pending _ | Ready _ | Execution_ready _)
       , (Open _ | Closed _) )
     | (Waiting _ | Closed _), _ ->
       Error (error Permission_denied "Goal continuation is not live in its actual phase"))
  | Pending_wake _ ->
    (match preparation.phase, Agent_protocol.Goal.state goal with
     | (Preparing | Source_bound _ | Execution_ready _), Open Enabled -> Ok ()
     | Execution_ready _, Open (Held _)
       when match use with
            | Registered_allocation -> true
            | Fresh_effect -> false -> Ok ()
     | _ -> Error (error Permission_denied "Goal wake construction is not live"))
  | Claimed_job { owner; _ } ->
    let%bind _ = job_scope_current t owner.scope in
    let%bind () =
      if
        owner.scope.active
        && (not owner.scope.cancel_requested)
        && Atomic.get owner.scope.authority_live
      then Ok ()
      else Error (error Conflict "Goal Job scope is no longer active")
    in
    (match preparation.phase, Agent_protocol.Goal.state goal with
     | (Preparing | Source_bound _ | Execution_ready _), Open (Enabled | Held _) -> Ok ()
     | _ -> Error (error Permission_denied "claimed Goal Job construction is not live"))
;;

let goal_preparation_basis t preparation =
  goal_preparation_basis_for Fresh_effect t preparation
;;

(* Canonical admitted-allocation selection and the exact claimed Init Job's
   cancellation monitor use these private stages. The former rechecks the same
   registration/handle/attribution; the latter exposes only liveness DATA and
   cannot admit another effect. Fresh public construction still uses Enabled. *)
let goal_registered_basis t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = goal_preparation_basis_for Registered_allocation t preparation in
  match preparation.phase with
  | Ready (binding, _) | Execution_ready binding ->
    (match binding.source_phase with
     | Open -> Runtime_source_preparation.validate_target binding.source t.state
     | Closed -> Error (error Conflict "admitted Goal constructor source closed"))
  | Preparing | Source_bound _ | Writer_pending _ | Waiting _ | Closed _ ->
    Error (error Conflict "admitted Goal constructor lost its actual command ACK")
;;

let goal_registered_policy t preparation =
  let open Result.Let_syntax in
  let%bind () = goal_registered_basis t preparation in
  let%bind () =
    Run_admission.Scope.authorize (Run_authorities.scope preparation.binding) t.state
  in
  let%bind () =
    Run_preparation.Custody.check
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let%bind () =
    Goal_activation_policy.check_admitted_policy preparation.policy ~state:t.state
  in
  goal_registered_basis t preparation
;;

let goal_registered_authority t preparation =
  let open Result.Let_syntax in
  let%bind () = goal_registered_basis t preparation in
  let%bind () =
    Run_admission.Scope.check_current (Run_authorities.scope preparation.binding)
  in
  let%bind () =
    Run_preparation.Custody.check_current
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  goal_registered_basis t preparation
;;

let refresh_goal_registered t preparation =
  let open Result.Let_syntax in
  let%bind () = goal_registered_policy t preparation in
  let%bind controller = require_recurrence_controller t in
  let%bind current = Recurrence_controller.observe controller t.state in
  preparation.observed <- Some current;
  let%bind () = goal_registered_authority t preparation in
  goal_registered_basis t preparation
;;

let goal_preparation_current t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = preparation.basis () in
  let%bind () = require_selected_execution t in
  let%bind () =
    Run_preparation.Custody.check
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let scope = Run_authorities.scope preparation.binding in
  let%bind () = Run_admission.Scope.authorize scope t.state in
  let%bind () = Run_admission.Scope.check_current scope in
  let%bind () =
    Run_preparation.Custody.check_current
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  preparation.basis ()
;;

let goal_construction_basis t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = preparation.basis () in
  let%bind () =
    match preparation.phase with
    | Ready (binding, _) | Execution_ready binding ->
      Goal_continuation.Source_binding.check_basis binding
    | Preparing | Source_bound _ | Writer_pending _ | Waiting _ | Closed _ ->
      Error (error Conflict "Goal construction requires its actual command ACK")
  in
  match preparation.observed with
  | Some observed when Recurrence_controller.is_current observed -> Ok ()
  | Some _ | None -> Error (error Conflict "Goal construction needs fresh Store custody")
;;

let goal_construction_policy t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = goal_construction_basis t preparation in
  let%bind () = preparation.current () in
  let%bind () = Goal_activation_policy.check_policy preparation.policy ~state:t.state in
  goal_construction_basis t preparation
;;

let refresh_goal_construction t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = preparation.current () in
  let%bind () = Goal_activation_policy.check_policy preparation.policy ~state:t.state in
  let%bind controller = require_recurrence_controller t in
  let%bind observed = Recurrence_controller.observe controller t.state in
  preparation.observed <- Some observed;
  goal_construction_policy t preparation
;;

let goal_construction_timing t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = goal_construction_basis t preparation in
  let%bind () =
    Goal_activation_policy.check_deadline
      preparation.policy
      ~state:t.state
      ~now:(t.services.now ())
  in
  let%bind () =
    match preparation.cause with
    | Resume_command _ -> Ok ()
    | Pending_wake { wake; _ } ->
      if goal_wake_transferred_borrow t preparation
      then Ok ()
      else (
        let%bind ready = goal_wake_producer_ready t preparation.run wake in
        if ready then Ok () else Error (error Conflict "Goal wake is no longer ready"))
    | Claimed_job { owner; _ } -> check_job_runtime_owner_internal t owner
  in
  goal_construction_basis t preparation
;;

let goal_construction_authority t (preparation : Goal_continuation.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = goal_construction_basis t preparation in
  let%bind () =
    Run_admission.Scope.check_current (Run_authorities.scope preparation.binding)
  in
  let%bind () =
    Run_preparation.Custody.check_current
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  goal_construction_basis t preparation
;;

let make_existing_goal_preparation
      t
      ~cause
      ~binding
      ~run
      ~admission
      ~link
      ~policy
      ~session
  =
  let rec preparation : Goal_continuation.Preparation.t =
    { cause
    ; binding
    ; run
    ; admission
    ; link
    ; policy
    ; session
    ; domain = (Stdlib.Domain.self () :> int)
    ; phase = Preparing
    ; basis = (fun () -> goal_preparation_basis t preparation)
    ; current = (fun () -> goal_preparation_current t preparation)
    ; refresh = (fun () -> refresh_goal_construction t preparation)
    ; policy_current = (fun () -> goal_construction_policy t preparation)
    ; timing = (fun () -> goal_construction_timing t preparation)
    ; authority = (fun () -> goal_construction_authority t preparation)
    ; effect_basis = (fun () -> goal_construction_basis t preparation)
    ; registered_basis = (fun () -> goal_registered_basis t preparation)
    ; registered_refresh = (fun () -> refresh_goal_registered t preparation)
    ; registered_policy = (fun () -> goal_registered_policy t preparation)
    ; registered_authority = (fun () -> goal_registered_authority t preparation)
    ; runtime_phase = Unclaimed
    ; observed = None
    ; native_command_loan = None
    ; resume_outcome = None
    ; resume_commit_attempted = ref false
    ; control_owner = ref ()
    ; control = None
    ; settled_callback = None
    }
  in
  preparation
;;

let begin_goal_resume_preparation_internal t ~actor ~authorize ~session ~request =
  let open Result.Let_syntax in
  let%bind retained =
    goal_resume_receipt_internal t ~actor ~authorize ~session ~request
  in
  match retained with
  | Some receipt -> Ok (Goal_continuation.Resume_issuance.Retained receipt)
  | None ->
    let%bind () = goal_resume_quiescent t in
    let%bind () =
      if Option.is_none t.run_preparation
      then Ok ()
      else Error (error Conflict "another source/command preparation is active")
    in
    let principal_id = (Operator_authorization.principal actor).id in
    let%bind plan =
      Goal_resume_admission.prepare
        t.state
        ~request
        ~principal_id
        ~session
        ~now:(t.services.now ())
    in
    (match plan with
     | Retained receipt -> Ok (Goal_continuation.Resume_issuance.Retained receipt)
     | Commit plan ->
       let run = Goal_resume_admission.run plan in
       let%bind binding =
         Result.of_option
           (Run_authorities.find t.run_authorities run.id)
           ~error:(error Permission_denied "Goal resume has no surviving Run authority")
       in
       let scope = Run_authorities.scope binding in
       let%bind _ =
         Result.of_option
           (Run_admission.Scope.original_actor scope)
           ~error:
             (error
                Permission_denied
                "Goal resume requires the original Run authentication")
       in
       let%bind () = Run_admission.Scope.authorize scope t.state in
       let%bind () = Run_admission.Scope.check_current scope in
       exclude_effect_deferred t Displaced;
       let%bind custody =
         Run_preparation.Goal_continuation.create_authenticated
           ~owner:t.run_preparation_owner
           ~state:t.state
           ~actor
           ~cause:(Resume request)
           ~authorize
       in
       (* Trusted original policies may run host code. No actual owner is
          published until all new/old semantic and physical bases pass again. *)
       let%bind () = goal_resume_quiescent t in
       let%bind () = Goal_resume_admission.check_basis plan ~state:t.state in
       let%bind () = Run_admission.Scope.check_current scope in
       let%bind () =
         Run_preparation.Custody.check_current
           (Run_preparation.Goal_continuation.custody custody)
           ~owner:t.run_preparation_owner
           ~state:t.state
       in
       let%bind () =
         if
           Option.is_none t.run_preparation
           && Run_authorities.is_current t.run_authorities binding ~run_id:run.id
         then Ok ()
         else
           Error (error Conflict "Goal resume source lane or original Run was displaced")
       in
       let%bind policy =
         Goal_activation_policy.create
           ~goal:(Goal_resume_admission.goal plan)
           ~link:(Goal_resume_admission.link plan)
       in
       let preparation =
         make_existing_goal_preparation
           t
           ~cause:(Resume_command custody)
           ~binding
           ~run
           ~admission:(Goal_resume_admission.admission plan)
           ~link:(Goal_resume_admission.link plan)
           ~policy
           ~session
       in
       t.run_preparation <- Some (Existing_goal preparation);
       Ok (Goal_continuation.Resume_issuance.Prepare preparation))
;;

let native_goal_selection_slot t (selection : Goal_native_resume.Selection.t) =
  let open Result.Let_syntax in
  let%bind () =
    if phys_equal selection.issuing_actor t.inference_owner_identity
    then Ok ()
    else Error (error Permission_denied "native Goal selection belongs to another Actor")
  in
  let%bind slot =
    List.find t.intent_agent_custody ~f:(fun slot ->
      equal_agent_intent_key slot.key (Invocation_intent selection.invocation_id)
      && Option.exists slot.native_goal ~f:(phys_equal selection.native))
    |> Result.of_option
         ~error:
           (error Permission_denied "native Goal intent no longer owns its live loan")
  in
  let%bind invocation =
    List.find t.state.invocations ~f:(fun invocation ->
      Agent_protocol.Id.Invocation.equal invocation.context.id selection.invocation_id)
    |> Result.of_option
         ~error:(error Conflict "native Goal invocation is no longer retained")
  in
  let%bind actual =
    Result.of_option
      invocation.native_goal_resume
      ~error:(error Conflict "native Goal invocation has no accepted command")
  in
  let%bind () =
    if Agent_protocol.Goal_native_resume_intent.equal actual selection.intent
    then Ok ()
    else Error (error Conflict "native Goal selection has advanced")
  in
  let%bind () = Goal_native_actions.Entry.check selection.native.entry t.state in
  Ok (slot, invocation)
;;

let native_goal_resume_receipt_internal t selection =
  let open Result.Let_syntax in
  let%bind _ = native_goal_selection_slot t selection in
  let%bind actor = Goal_native_actions.Entry.actor selection.native.entry in
  goal_resume_receipt_internal
    t
    ~actor
    ~authorize:(Goal_native_actions.Entry.authorize selection.native.entry actor)
    ~session:selection.session
    ~request:(Goal_native_resume.Selection.request selection)
;;

let validate_native_goal_receipt t intent (receipt : Goal_command_receipt.t) =
  let open Result.Let_syntax in
  let request = Agent_protocol.Goal_native_resume_intent.request intent in
  let%bind digest = Goal_resume_request.digest request in
  let%bind () =
    if
      Agent_protocol.Id.Principal.equal
        receipt.principal_id
        (Agent_protocol.Goal_native_resume_intent.principal_id intent)
      && Agent_protocol.Idempotency_key.equal
           receipt.key
           (Goal_resume_request.key request)
      && String.equal receipt.request_sha256 digest
      && Agent_protocol.Id.Goal.equal
           receipt.goal_id
           (Goal_resume_request.goal_id request)
      && Option.equal
           Agent_protocol.Run_source.equal
           receipt.source
           (Some (Goal_resume_request.source request))
      && Int64.(Goal_resume_request.expected_goal_revision request < max_value)
      && Int64.(Goal_resume_request.expected_catalog_revision request < max_value)
      && Int64.equal
           receipt.goal_revision
           Int64.(Goal_resume_request.expected_goal_revision request + 1L)
      && Int64.equal
           receipt.catalog_revision
           Int64.(Goal_resume_request.expected_catalog_revision request + 1L)
    then Ok ()
    else
      Error (error Conflict "native Goal receipt immutable command association changed")
  in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "native Goal receipt has no retained Run index")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index (Goal_resume_request.run_id request))
      ~error:(error Conflict "native Goal receipt's actual Run is not retained")
  in
  let%bind link =
    Result.of_option
      (Run_state.goal_link index run.id)
      ~error:(error Conflict "native Goal receipt's immutable episode link is absent")
  in
  let episode = Run_goal_link.episode link in
  let admission = Agent_protocol.Goal_episode.admission episode in
  if
    Agent_protocol.Id.Goal.equal (Run_goal_link.goal_id link) receipt.goal_id
    && Agent_protocol.Goal_episode.matches_run episode run
    && Agent_protocol.Run_source.equal run.source (Goal_resume_request.source request)
    && List.exists
         (Run_state.receipts index)
         ~f:(Agent_protocol.Run_receipt.equal admission)
  then Goal_run_evidence.validate ~catalog:t.state.goal_catalog ~runs:t.state.run_state
  else
    Error
      (error
         Conflict
         "native Goal receipt lost its actual historical admission association")
;;

let native_goal_resume_status_internal t admission authorize invocation_id =
  let open Result.Let_syntax in
  let%bind () = Goal_native_admission.check_now admission t.state ~effect_kind:Get in
  let actor = Goal_native_admission.actor admission in
  let%bind _ = Goal_command_admission.read t.state ~actor ~authorize:(authorize actor) in
  let%bind invocation =
    List.find t.state.invocations ~f:(fun invocation ->
      Agent_protocol.Id.Invocation.equal invocation.context.id invocation_id)
    |> Result.of_option
         ~error:(error Invalid_request "native Goal invocation is not retained")
  in
  let%bind intent =
    Result.of_option
      invocation.native_goal_resume
      ~error:(error Invalid_request "Invocation has no native Goal Resume command")
  in
  let request = Agent_protocol.Goal_native_resume_intent.request intent in
  let%bind receipt =
    Goal_resume_admission.find_receipt
      t.state
      ~request
      ~principal_id:(Agent_protocol.Goal_native_resume_intent.principal_id intent)
  in
  let native =
    List.find_map t.intent_agent_custody ~f:(fun slot ->
      if equal_agent_intent_key slot.key (Invocation_intent invocation_id)
      then slot.native_goal
      else None)
  in
  let live =
    Option.exists native ~f:(fun native ->
      Result.is_ok (Goal_native_actions.Entry.actor native.entry)
      || Option.exists native.preparation ~f:(fun preparation ->
        Option.exists preparation.native_command_loan ~f:(fun loan ->
          match Execution_custody.Admission.status loan with
          | Current -> true
          | Closed | Authority_expired -> false)))
  in
  let%bind status =
    match receipt with
    | Some receipt ->
      let%map () = validate_native_goal_receipt t intent receipt in
      let detail =
        Option.bind native ~f:(fun native ->
          Option.bind native.preparation ~f:(fun preparation ->
            match Goal_continuation.Preparation.receipt preparation with
            | Some actual when Goal_command_receipt.equal actual receipt ->
              preparation.resume_outcome
            | _ -> None))
        |> Option.value_map
             ~default:Goal_native_resume.Detail.Unavailable
             ~f:(fun handoff -> Goal_native_resume.Detail.Actor_outcome handoff)
      in
      let failure = Option.bind native ~f:(fun native -> native.failure) in
      Goal_native_resume.Status.Acknowledged { intent; receipt; detail; failure }
    | None ->
      Ok
        (match Agent_protocol.Goal_native_resume_intent.phase intent with
         | Staged -> Goal_native_resume.Status.Staged intent
         | Accepted _ when live -> Accepted intent
         | Accepted _ -> Interrupted_before_dispatch intent
         | Dispatch_claimed _ when live -> Dispatching intent
         | Dispatch_claimed _ -> Unknown intent
         | Discarded _ -> Discarded intent
         | Rejected _ -> Rejected intent)
  in
  let%bind _ = Goal_command_admission.read t.state ~actor ~authorize:(authorize actor) in
  let%map () = Goal_native_admission.check_now admission t.state ~effect_kind:Get in
  status
;;

let select_native_goal_resume_internal t =
  let open Result.Let_syntax in
  (* Selection is scheduling DATA tied to a physical live slot, not a claim. The
     existing Owner source reservation must be acquired before Begin consumes it. *)
  match
    t.state.active_operation, t.run_preparation, t.moderator_borrow, t.queued_event_borrow
  with
  | Some _, _, _, _ | _, Some _, _, _ | _, _, Some _, _ | _, _, _, Some _ -> Ok None
  | None, None, None, None ->
    let%bind controller = require_recurrence_controller t in
    let rec choose = function
      | [] -> Ok None
      | slot :: rest ->
        (match slot.key, slot.native_goal with
         | Invocation_intent id, Some native when not native.dispatch_finished ->
           let intent =
             List.find_map t.state.invocations ~f:(fun invocation ->
               if Agent_protocol.Id.Invocation.equal invocation.context.id id
               then invocation.native_goal_resume
               else None)
           in
           (match intent with
            | Some intent ->
              (match Agent_protocol.Goal_native_resume_intent.phase intent with
               | Accepted _ ->
                 let selection : Goal_native_resume.Selection.t =
                   { issuing_actor = t.inference_owner_identity
                   ; invocation_id = id
                   ; intent
                   ; session = Recurrence_controller.session controller
                   ; native
                   }
                 in
                 (match native_goal_selection_slot t selection with
                  | Ok _ -> Ok (Some selection)
                  | Error _ ->
                    Goal_native_actions.Entry.discard native.entry;
                    choose rest)
               | Staged | Dispatch_claimed _ | Discarded _ | Rejected _ -> choose rest)
            | None -> choose rest)
         | _ -> choose rest)
    in
    choose t.intent_agent_custody
;;

let begin_native_goal_resume_preparation_internal t selection =
  let open Result.Let_syntax in
  let%bind _, invocation = native_goal_selection_slot t selection in
  let%bind () = goal_resume_quiescent t in
  let%bind () =
    if Option.is_none t.run_preparation
    then Ok ()
    else Error (error Conflict "another source preparation is active")
  in
  let%bind actor = Goal_native_actions.Entry.actor selection.native.entry in
  let authorize = Goal_native_actions.Entry.authorize selection.native.entry actor in
  let request = Goal_native_resume.Selection.request selection in
  (* Do not silently rebase immutable CAS. The claim is a separate durable fact;
     a stale command can then be reported as rejected without replaying it. *)
  let%bind claimed =
    Agent_protocol.Goal_native_resume_intent.claim
      selection.intent
      ~now:(t.services.now ())
  in
  let%bind invocation =
    Agent_protocol.Invocation.record_native_goal_resume invocation claimed
  in
  let%bind candidate =
    prepare_transition t ~delta:(Invocation_changed invocation) ~payloads:[]
  in
  let attempted = ref false in
  let handed_off = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !handed_off then Goal_native_actions.Entry.discard selection.native.entry)
    ~f:(fun () ->
      let%bind () =
        persist_transition
          ~commit_attempted:attempted
          ~check_before_commit:(fun () ->
            let%map _ = native_goal_selection_slot t selection in
            ())
          t
          candidate
      in
      install_committed_transition t candidate;
      publish_committed_transition t candidate;
      let%bind loan = Goal_native_actions.Entry.take_admission selection.native.entry in
      let transferred = ref false in
      Exn.protect
        ~finally:(fun () ->
          if not !transferred then Execution_custody.Admission.retire loan)
        ~f:(fun () ->
          let%map issuance =
            begin_goal_resume_preparation_internal
              t
              ~actor
              ~authorize
              ~session:selection.session
              ~request
          in
          (match issuance with
           | Retained _ -> ()
           | Prepare preparation ->
             preparation.native_command_loan <- Some loan;
             selection.native.preparation <- Some preparation;
             transferred := true;
             handed_off := true);
          issuance))
;;

let observe_native_goal_dispatch_internal t selection failure =
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal
        selection.Goal_native_resume.Selection.issuing_actor
        t.inference_owner_identity
      && List.exists t.intent_agent_custody ~f:(fun slot ->
        Option.exists slot.native_goal ~f:(phys_equal selection.native))
    then Ok ()
    else Error (error Conflict "native Goal dispatch detail has no live intent owner")
  in
  let invocation =
    List.find t.state.invocations ~f:(fun invocation ->
      Agent_protocol.Id.Invocation.equal invocation.context.id selection.invocation_id)
  in
  let phase =
    Option.bind invocation ~f:(fun invocation -> invocation.native_goal_resume)
    |> Option.map ~f:Agent_protocol.Goal_native_resume_intent.phase
  in
  let pending_busy =
    match phase, failure with
    | Some (Accepted _), Some { Agent_protocol.Error.code = Conflict; _ } ->
      Result.is_ok (Goal_native_actions.Entry.actor selection.native.entry)
    | _ -> false
  in
  if pending_busy
  then Ok ()
  else (
    (* No generic post-Started writer: the actual Goal command receipt and
       current Run remain the durable outcome. Only pre-admission rejection of
       a known claim gets an immutable bounded negative intent leaf. *)
    selection.native.dispatch_finished <- true;
    selection.native.failure <- failure;
    let rejection =
      match invocation, failure with
      | Some invocation, Some error ->
        (match invocation.native_goal_resume with
         | Some intent ->
           (match Agent_protocol.Goal_native_resume_intent.phase intent with
            | Dispatch_claimed _ ->
              let preparation_unattempted =
                Option.value_map
                  selection.native.preparation
                  ~default:true
                  ~f:(fun preparation ->
                    Option.is_none (Goal_continuation.Preparation.receipt preparation)
                    && not !(preparation.resume_commit_attempted))
              in
              (* Host failure is not pre-admission rejection. Keep actual ACK or
                 uncertain-writer facts even after source cleanup closed custody;
                 no generic outcome write may invalidate a handed-off prefix. *)
              if preparation_unattempted
              then (
                match
                  Goal_resume_admission.find_receipt
                    t.state
                    ~request:(Agent_protocol.Goal_native_resume_intent.request intent)
                    ~principal_id:
                      (Agent_protocol.Goal_native_resume_intent.principal_id intent)
                with
                | Ok None -> Some (invocation, intent, error)
                | Ok (Some _) | Error _ -> None)
              else None
            | Staged | Accepted _ | Discarded _ | Rejected _ -> None)
         | None -> None)
      | _ -> None
    in
    Exn.protect
      ~finally:(fun () -> Goal_native_actions.Entry.discard selection.native.entry)
      ~f:(fun () ->
        match rejection with
        | None -> Ok ()
        | Some (invocation, intent, failure) ->
          let%bind rejected =
            Agent_protocol.Goal_native_resume_intent.reject intent failure
          in
          let%bind invocation =
            Agent_protocol.Invocation.record_native_goal_resume invocation rejected
          in
          Result.map
            (transition t ~delta:(Invocation_changed invocation) ~payloads:[])
            ~f:ignore))
;;

module Goal_execution_issuance = struct
  type t =
    | Wake of Agent_protocol.Run_wake.t
    | Job of Job_runtime_owner.t
end

let begin_goal_execution_preparation_internal t ~run ~execution =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind () = require_runtime_admission t in
  let%bind () =
    if Option.is_none t.run_preparation
    then Ok ()
    else Error (error Conflict "another source preparation is active")
  in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "Goal execution Run index is absent")
  in
  let%bind link =
    Result.of_option
      (Run_state.goal_link index run.Agent_protocol.Run.id)
      ~error:(error Conflict "Goal execution immutable link is absent")
  in
  let%bind goal =
    Option.bind t.state.goal_catalog ~f:(fun catalog ->
      Goal_catalog.find catalog (Run_goal_link.goal_id link))
    |> Result.of_option ~error:(error Conflict "Goal execution Goal is absent")
  in
  let%bind binding =
    Result.of_option
      (Run_authorities.find t.run_authorities run.id)
      ~error:(error Permission_denied "Goal execution has no surviving Run authority")
  in
  let scope = Run_authorities.scope binding in
  let%bind original =
    Result.of_option
      (Run_admission.Scope.original_actor scope)
      ~error:(error Permission_denied "Goal execution lost original Run authentication")
  in
  let%bind policy = Goal_activation_policy.create ~goal ~link in
  let admission = Agent_protocol.Goal_episode.admission (Run_goal_link.episode link) in
  let%bind () =
    Goal_activation_policy.check_association policy ~state:t.state ~run ~admission
  in
  let expected = t.state in
  let request_cause =
    match execution with
    | Goal_execution_issuance.Job owner ->
      Run_preparation.Goal_continuation.Cause.Claimed_job
        { run_id = run.id; job = owner.Job_runtime_owner.scope.job }
    | Wake wake -> Run_preparation.Goal_continuation.Cause.Wake { run_id = run.id; wake }
  in
  let%bind () = Run_admission.Scope.authorize scope t.state in
  let%bind () = Run_admission.Scope.check_current scope in
  exclude_effect_deferred t Displaced;
  let%bind request =
    Run_preparation.Goal_continuation.create_authenticated
      ~owner:t.run_preparation_owner
      ~state:t.state
      ~actor:original
      ~cause:request_cause
      ~authorize:(Run_admission.Scope.authorize scope)
  in
  let cause =
    match execution with
    | Goal_execution_issuance.Job owner ->
      Existing_goal_preparation.Cause.Claimed_job { request; owner }
    | Wake wake -> Existing_goal_preparation.Cause.Pending_wake { request; wake }
  in
  let%bind () = goal_existing_execution_quiescent t (Some cause) in
  let%bind () =
    if
      phys_equal expected t.state
      && Option.is_none t.run_preparation
      && Run_authorities.is_current t.run_authorities binding ~run_id:run.id
    then Ok ()
    else Error (error Conflict "Goal execution changed during original authorization")
  in
  let%bind () =
    Run_preparation.Custody.check_current
      (Run_preparation.Goal_continuation.custody request)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let preparation =
    make_existing_goal_preparation
      t
      ~cause
      ~binding
      ~run
      ~admission
      ~link
      ~policy
      ~session:run.session
  in
  t.run_preparation <- Some (Existing_goal preparation);
  Ok preparation
;;

let begin_goal_wake_preparation_internal t wake =
  let open Result.Let_syntax in
  let%bind selection = classify_goal_wake t wake in
  match selection with
  | No_work -> Ok Goal_execution_runtime.Wake_issuance.No_work
  | Suspended_goal suspension -> Ok (Suspended_goal suspension)
  | Ordinary -> Error (error Invalid_request "ordinary wake has no Goal execution owner")
  | Wake wake ->
    let%bind run = pending_goal_wake_run t wake in
    let%bind run =
      Result.of_option
        run
        ~error:(error Conflict "Goal Wait changed before source issuance")
    in
    let%map preparation =
      begin_goal_execution_preparation_internal t ~run ~execution:(Wake wake)
    in
    Goal_execution_runtime.Wake_issuance.Prepare preparation
;;

let begin_goal_job_runtime_preparation_internal t (owner : Job_runtime_owner.t) =
  let open Result.Let_syntax in
  let%bind () = check_job_runtime_owner_internal t owner in
  let%bind () =
    match owner.attribution with
    | Goal -> Ok ()
    | Ordinary ->
      Error (error Invalid_request "ordinary Job has no Goal construction owner")
  in
  let%bind job = job_scope_current t owner.scope in
  let%bind run = job_runtime_run t job in
  let%bind run =
    Result.of_option run ~error:(error Conflict "Goal Job lost its original Run")
  in
  let%bind attribution = Goal_work_attribution.of_run t.state run in
  let%bind () =
    if Option.is_some attribution
    then Ok ()
    else Error (error Conflict "Goal Job lost its immutable attribution")
  in
  begin_goal_execution_preparation_internal t ~run ~execution:(Job owner)
;;

let goal_source_basis t (binding : Goal_continuation.Source_binding.t) =
  let open Result.Let_syntax in
  let preparation = binding.preparation in
  let%bind () =
    match binding.source_phase with
    | Open -> Ok ()
    | Closed -> Error (error Conflict "Goal source binding is closed")
  in
  let%bind () = preparation.basis () in
  let%bind () =
    match preparation.phase with
    | Source_bound current
    | Writer_pending (current, _)
    | Ready (current, _)
    | Execution_ready current
      when phys_equal current binding -> Ok ()
    | Preparing
    | Source_bound _
    | Writer_pending _
    | Ready _
    | Execution_ready _
    | Waiting _
    | Closed _ -> Error (error Conflict "Goal source selection was consumed or replaced")
  in
  let%bind () = Runtime_source_preparation.validate_target binding.source t.state in
  match Runtime_source_preparation.moderator binding.source with
  | Legacy observer | Extension observer ->
    if Agent_protocol.Invocation.equal_observer observer preparation.run.source.observer
    then preparation.basis ()
    else Error (error Conflict "Goal selected source differs from the original Run")
  | No_moderator ->
    Error (error Invalid_request "Goal resume requires its actual moderator source")
;;

let bind_goal_continuation_source_internal t ~preparation ~source =
  let open Result.Let_syntax in
  let%bind () = goal_preparation_basis t preparation in
  let%bind () = preparation.Goal_continuation.current () in
  let%bind () = goal_existing_execution_quiescent t (Some preparation.cause) in
  let%bind () = Runtime_source_preparation.validate_target source t.state in
  let%bind () =
    match Runtime_source_preparation.moderator source with
    | Legacy observer | Extension observer ->
      if Agent_protocol.Invocation.equal_observer observer preparation.run.source.observer
      then Ok ()
      else Error (error Conflict "Goal selected source differs from the original Run")
    | No_moderator ->
      Error (error Invalid_request "Goal resume requires its actual moderator source")
  in
  match preparation.phase with
  | Preparing ->
    let rec binding : Goal_continuation.Source_binding.t =
      { preparation
      ; source
      ; source_phase = Open
      ; basis = (fun () -> goal_source_basis t binding)
      }
    in
    (* Only nonfailing publication follows the last actual owner/original fence. *)
    let%bind () = preparation.current () in
    (match preparation.phase with
     | Preparing ->
       preparation.phase <- Source_bound binding;
       Ok binding
     | Source_bound _
     | Writer_pending _
     | Ready _
     | Execution_ready _
     | Waiting _
     | Closed _ ->
       Error (error Conflict "Goal source selection changed during original policy"))
  | Source_bound binding when phys_equal binding.source source ->
    Result.map (Goal_continuation.Source_binding.check_basis binding) ~f:(fun () ->
      binding)
  | Source_bound _ | Writer_pending _ | Ready _ | Execution_ready _ | Waiting _ | Closed _
    -> Error (error Conflict "Goal source is already selected or consumed")
;;

let prepare_goal_execution_runtime_internal
      t
      (binding : Goal_execution_runtime.Source_binding.t)
  =
  let open Result.Let_syntax in
  let preparation = binding.preparation in
  let%bind () = Goal_execution_runtime.Source_binding.check_basis binding in
  let%bind () = preparation.current () in
  let%bind () =
    match preparation.cause with
    | Pending_wake _ | Claimed_job _ -> Ok ()
    | Resume_command _ ->
      Error (error Invalid_request "Resume command needs its actual command ACK")
  in
  match preparation.phase with
  | Source_bound current when phys_equal current binding ->
    let%bind () = Goal_execution_runtime.Source_binding.check_basis binding in
    preparation.phase <- Execution_ready binding;
    Ok ({ binding; purpose = Existing_execution } : Goal_execution_runtime.t)
  | Preparing
  | Source_bound _
  | Writer_pending _
  | Ready _
  | Execution_ready _
  | Waiting _
  | Closed _ -> Error (error Conflict "Goal execution source selection was consumed")
;;

module Goal_resume_candidate = struct
  type t =
    | Retained of Goal_command_receipt.t
    | Commit of
        { plan : Goal_resume_admission.t
        ; candidate : Session_transition.t
        ; check_before_commit : unit -> (unit, Agent_protocol.Error.t) result
        }
end

let commit_goal_resume_internal t ~(binding : Goal_continuation.Source_binding.t) =
  let open Result.Let_syntax in
  let preparation = binding.preparation in
  let attempted = preparation.resume_commit_attempted in
  let returned = ref false in
  let request = Existing_goal_preparation.Cause.resume_request preparation.cause in
  Exn.protect
    ~finally:(fun () -> if not !returned then Goal_continuation.close preparation)
    ~f:(fun () ->
      let plan () =
        let%bind request = request in
        let%bind () = Goal_continuation.Source_binding.check_basis binding in
        let%bind () =
          match preparation.phase with
          | Source_bound current when phys_equal current binding -> Ok ()
          | Preparing
          | Source_bound _
          | Writer_pending _
          | Ready _
          | Execution_ready _
          | Waiting _
          | Closed _ ->
            Error (error Conflict "Goal resume command selection is no longer fresh")
        in
        let%bind () = preparation.current () in
        let%bind () = goal_resume_quiescent t in
        let principal_id =
          Run_preparation.Custody.principal_id (Goal_continuation.custody preparation)
        in
        let%bind plan =
          Goal_resume_admission.prepare
            t.state
            ~request
            ~principal_id
            ~session:preparation.session
            ~now:(t.services.now ())
        in
        match plan with
        | Retained receipt -> Ok (Goal_resume_candidate.Retained receipt)
        | Commit plan ->
          (* This is metadata bookkeeping for the existing owner, not ordinary
             initial Run admission. Its common writer retains the exact new
             custody through ACK; no initial request or fake Held is supplied. *)
          let%bind candidate =
            prepare_transition
              t
              ~delta:(Goal_catalog_changed (Goal_resume_admission.catalog plan))
              ~payloads:[]
          in
          let check_before_commit () =
            let%bind () = preparation.current () in
            (* Recheck only global new-activation policy with a fresh clock;
               no count dimension is re-admitted or charged. *)
            let%bind fresh =
              Goal_resume_admission.prepare
                t.state
                ~request
                ~principal_id
                ~session:preparation.session
                ~now:(t.services.now ())
            in
            let%bind () =
              match fresh with
              | Commit _ -> Ok ()
              | Retained _ ->
                Error (error Conflict "Goal resume key appeared before its writer")
            in
            let%bind () =
              Run_admission.Scope.check_current
                (Run_authorities.scope preparation.binding)
            in
            let%bind () =
              Run_preparation.Custody.check_current
                (Goal_continuation.custody preparation)
                ~owner:t.run_preparation_owner
                ~state:t.state
            in
            let%bind () = Goal_resume_admission.check_basis plan ~state:t.state in
            Goal_continuation.Source_binding.check_basis binding
          in
          let%map () = check_before_commit () in
          Goal_resume_candidate.Commit { plan; candidate; check_before_commit }
      in
      match plan () with
      | Error failure -> Ok (Goal_continuation.Admission.Rejected failure)
      | Ok (Retained receipt) -> Ok (Goal_continuation.Admission.Retained receipt)
      | Ok (Commit { plan; candidate; check_before_commit }) ->
        preparation.phase <- Writer_pending (binding, attempted);
        (match
           persist_transition ~commit_attempted:attempted ~check_before_commit t candidate
         with
         | Error failure ->
           Ok
             (if !attempted
              then Goal_continuation.Admission.Uncertain failure
              else Goal_continuation.Admission.Rejected failure)
         | Ok () ->
           let receipt = Goal_resume_admission.receipt plan in
           (* Known ACK is retained before installation/publication can fail. A
              later close preserves this factual receipt and cannot permit retry. *)
           Goal_continuation.acknowledge preparation binding receipt;
           install_committed_transition_owned
             ~preparation_owner:(Some (Existing_goal preparation))
             t
             candidate;
           publish_committed_transition t candidate;
           let ready () =
             let%bind () = Goal_continuation.Source_binding.check_basis binding in
             let%bind controller = require_recurrence_controller t in
             let%bind current = Recurrence_controller.observe controller t.state in
             let%bind () = preparation.current () in
             let%bind () = Goal_continuation.Source_binding.check_basis binding in
             if Recurrence_controller.is_current current
             then Ok ()
             else Error (error Conflict "Goal resume canonical Store observation changed")
           in
           (match ready () with
            | Error error ->
              Ok (Goal_continuation.Admission.Resume_failed { receipt; error })
            | Ok () ->
              returned := true;
              (match (Goal_resume_admission.run plan).lifecycle with
               | Waiting wake ->
                 preparation.phase <- Waiting (receipt, wake);
                 preparation.resume_outcome
                 <- Some (Goal_resume_result.Continuation.Waiting wake);
                 Ok (Goal_continuation.Admission.Waiting { receipt; wake })
               | Admitted | Active ->
                 Ok
                   (Goal_continuation.Admission.Ready
                      { binding; purpose = Resume receipt })
               | Terminal _ ->
                 (* The pure plan rejects this; keep known ACK truth if an
                   unexpected future lifecycle extension reaches this branch. *)
                 returned := false;
                 Ok
                   (Goal_continuation.Admission.Resume_failed
                      { receipt
                      ; error = error Conflict "Goal resume Run became terminal"
                      })))))
;;

let admit_goal_resume_internal t (binding : Goal_continuation.Source_binding.t) =
  let open Result.Let_syntax in
  (* A foreign receiver or repeated/invalid call must not close another actual
     owner's live preparation while reporting its own rejection. *)
  let%bind () = goal_preparation_basis t binding.preparation in
  match binding.preparation.phase with
  | Source_bound current when phys_equal current binding ->
    commit_goal_resume_internal t ~binding
  | Ready (current, receipt) when phys_equal current binding ->
    let%map () = binding.preparation.current () in
    Goal_continuation.Admission.Retained receipt
  | Preparing
  | Source_bound _
  | Writer_pending _
  | Ready _
  | Execution_ready _
  | Waiting _
  | Closed _ ->
    Ok
      (Goal_continuation.Admission.Rejected
         (error Conflict "Goal resume command selection is no longer fresh"))
;;

let end_goal_continuation_preparation_internal
      t
      (preparation : Goal_continuation.Preparation.t)
  =
  if
    Int.equal preparation.domain (Stdlib.Domain.self () :> int)
    && Run_preparation.Custody.belongs_to
         (Goal_continuation.custody preparation)
         ~owner:t.run_preparation_owner
  then (
    Goal_continuation.close preparation;
    Option.iter preparation.native_command_loan ~f:Execution_custody.Admission.retire;
    preparation.native_command_loan <- None;
    (match t.run_preparation with
     | Some (Existing_goal current) when phys_equal current preparation ->
       t.run_preparation <- None
     | Some (Initial _ | Existing_goal _ | Delegated_load _) | None -> ());
    Ok ())
  else Error (error Conflict "Goal continuation belongs to another Actor owner")
;;

module Goal_controller_phase = struct
  type t =
    | Startup
    | Operation of unit ref
    | Closed
end

(* The Goal issuer is the same actual target actor. Its private continuation
   retains original authorization independently of preparation cleanup. *)
let checked_goal_activation t binding held policy authorization =
  let open Result.Let_syntax in
  let%bind controller = require_recurrence_controller t in
  let%bind original =
    Result.of_option
      (Run_preparation.original_actor binding.Source_binding.preparation)
      ~error:(error Permission_denied "Goal activation lost original authorization")
  in
  let phase = ref Goal_controller_phase.Startup in
  let consumed = ref false in
  let owner () = require_runtime_admission t in
  let run () =
    Option.bind t.state.run_state ~f:(fun index ->
      Run_state.find index held.Held_run.run.id)
    |> Result.of_option ~error:(error Conflict "Goal activation Run is absent")
  in
  let association : Activation_association.t =
    { issuer_policy = Goal policy
    ; check_target =
        (fun ~store ~state ~run ~admission ->
          if Recurrence_controller.same_store store controller
          then Goal_activation_policy.check_association policy ~state ~run ~admission
          else Error (error Conflict "Goal activation belongs to another Store"))
    }
  in
  let check_association () =
    let%bind () = owner () in
    let%bind run = run () in
    Activation_association.check_target
      association
      ~store:controller
      ~state:t.state
      ~run
      ~admission:held.admission
  in
  let original_current () =
    Run_command_authorization.check original ~authorize:(fun _ -> Ok ()) t.state
  in
  let policy_current () =
    let%bind () = Run_preparation.Authorization.check authorization t.state in
    Goal_activation_policy.check_policy policy ~state:t.state
  in
  let admitted_policy_current () =
    let%bind () = Run_preparation.Authorization.check authorization t.state in
    Goal_activation_policy.check_admitted_policy policy ~state:t.state
  in
  let deadline () =
    let now = t.services.now () in
    Goal_activation_policy.check_deadline policy ~state:t.state ~now
  in
  let%bind current = Recurrence_controller.observe controller t.state in
  let checked_basis () =
    let%bind () =
      if
        (not !consumed)
        &&
        match !phase with
        | Startup -> true
        | Operation _ | Closed -> false
      then Ok ()
      else Error (error Conflict "Goal activation view was consumed or retired")
    in
    let%bind () = Held_run.check_basis held in
    let%bind () = check_association () in
    if Recurrence_controller.is_current current
    then Ok ()
    else Error (error Conflict "Goal activation Store observation changed")
  in
  let check_policy () =
    let%bind () = checked_basis () in
    let%bind () = policy_current () in
    checked_basis ()
  in
  let check_timing () =
    let%bind () = checked_basis () in
    let%bind () = deadline () in
    checked_basis ()
  in
  let check_authority () =
    let%bind () = checked_basis () in
    let%bind () = original_current () in
    checked_basis ()
  in
  let check_current () =
    let%bind () = check_policy () in
    let%bind () = check_timing () in
    let%bind () = check_authority () in
    checked_basis ()
  in
  let continue (target : Held_run.Activation.t) =
    let refreshed = ref None in
    let startup () =
      if
        Int.equal target.domain (Stdlib.Domain.self () :> int)
        &&
        match !phase with
        | Startup -> true
        | Operation _ | Closed -> false
      then target.owned_basis ()
      else Error (error Conflict "Goal startup owner is retired or foreign")
    in
    let basis () =
      let%bind () = startup () in
      let%bind () = check_association () in
      let%bind () = Held_run.Activation.check_basis target in
      match !refreshed with
      | Some current when Recurrence_controller.is_current current -> Ok ()
      | Some _ | None -> Error (error Conflict "Goal startup needs fresh Store custody")
    in
    let policy_check () =
      let%bind () = basis () in
      let%bind () = policy_current () in
      let%bind () = target.check_policy () in
      basis ()
    in
    let refresh () =
      let%bind () = startup () in
      let%bind () = policy_current () in
      let%bind () = target.policy () in
      let%bind current = Recurrence_controller.observe controller t.state in
      refreshed := Some current;
      policy_check ()
    in
    let policy_admitted_inference () =
      let%bind () = basis () in
      let%bind () = admitted_policy_current () in
      let%bind () = target.check_policy () in
      basis ()
    in
    let refresh_admitted_inference () =
      let%bind () = startup () in
      let%bind () = admitted_policy_current () in
      let%bind () = target.policy () in
      let%bind current = Recurrence_controller.observe controller t.state in
      refreshed := Some current;
      policy_admitted_inference ()
    in
    let timing () =
      let%bind () = basis () in
      let%bind () = deadline () in
      basis ()
    in
    let authority () =
      let%bind () = basis () in
      let%bind () = target.authority () in
      let%bind () = original_current () in
      basis ()
    in
    let transfer () =
      let%map () = basis () in
      let token = ref () in
      let fresh = ref None in
      let operation_basis () =
        let%bind () =
          match !phase with
          | Operation actual when phys_equal actual token -> check_association ()
          | Startup | Operation _ | Closed ->
            Error (error Conflict "Goal Operation custody is not acknowledged")
        in
        match !fresh with
        | Some current when Recurrence_controller.is_current current -> Ok ()
        | Some _ | None ->
          Error (error Conflict "Goal Operation needs fresh Store custody")
      in
      let operation_policy () =
        let%bind () = operation_basis () in
        let%bind () = policy_current () in
        operation_basis ()
      in
      let refresh () =
        let%bind () =
          match !phase with
          | Operation actual when phys_equal actual token -> check_association ()
          | Startup | Operation _ | Closed ->
            Error (error Conflict "Goal Operation was retired")
        in
        let%bind () = policy_current () in
        let%bind current = Recurrence_controller.observe controller t.state in
        fresh := Some current;
        operation_policy ()
      in
      let timing () =
        let%bind () = operation_basis () in
        let%bind () = deadline () in
        operation_basis ()
      in
      let authority () =
        let%bind () = operation_basis () in
        let%bind () = original_current () in
        operation_basis ()
      in
      ({ association
       ; install =
           (fun () ->
             match !phase with
             | Startup -> phase := Operation token
             | Operation _ | Closed -> ())
       ; close = (fun () -> phase := Closed)
       ; refresh
       ; policy = operation_policy
       ; timing
       ; authority
       ; basis = operation_basis
       }
       : Activation_controller.Operation.t)
    in
    ({ target
     ; controller = { transfer }
     ; refresh
     ; policy = policy_check
     ; refresh_admitted_inference
     ; policy_admitted_inference
     ; timing
     ; authority
     ; basis
     }
     : Admitted_activation.Continuation.t)
  in
  let%map () = check_current () in
  ({ check_current
   ; check_policy
   ; check_authority
   ; check_timing
   ; check_basis = checked_basis
   ; association
   ; continue
   ; consumed
   }
   : Admitted_activation.Checked.t)
;;

let admit_held_goal_run_internal t ~binding ~intent ~session =
  let open Result.Let_syntax in
  let previous = t.state in
  let preparation = binding.Source_binding.preparation in
  let check_basis () =
    let%bind () = check_bound_source t binding in
    if Int64.equal previous.counters.revision t.state.counters.revision
    then Ok ()
    else Error (error Conflict "Goal admission candidate basis changed")
  in
  let%bind () = check_basis () in
  let%bind controller = require_recurrence_controller t in
  let%bind () =
    if Agent_protocol.Session_ref.equal session (Recurrence_controller.session controller)
    then Ok ()
    else Error (error Invalid_request "Goal admission targets another actor")
  in
  let%bind () = Source_binding.check_current binding in
  let request = Run_preparation.request preparation in
  let%bind () =
    if
      Agent_protocol.Run.Mode.equal request.mode Workflow
      && Run_admission_request.Caller.equal request.caller Headless_command
    then Ok ()
    else Error (error Invalid_request "Goal episode requires headless Workflow")
  in
  let index = Option.value previous.run_state ~default:Run_state.empty in
  let%bind retained =
    Run_state.receipt
      index
      ~principal_id:(Run_preparation.principal_id preparation)
      ~key:request.key
      ~request_sha256:(Run_preparation.request_sha256 preparation)
  in
  match retained with
  | Some admission ->
    let%bind link =
      Result.of_option
        (Run_state.goal_link index admission.run_id)
        ~error:(error Conflict "retained Run has no Goal association")
    in
    if
      String.equal
        (Run_goal_link.intent_sha256 link)
        (Goal_episode_admission.digest intent)
      && Agent_protocol.Run_receipt.equal
           admission
           (Agent_protocol.Goal_episode.admission (Run_goal_link.episode link))
    then Ok (Goal_activation.Admission.Retained admission)
    else Error (error Conflict "retained Goal association intent changed")
  | None ->
    let%bind () = check_retry_execution t preparation in
    let%bind () = check_selected_source t binding in
    let%bind authorization =
      Run_preparation.capture_authorization
        preparation
        ~owner:t.run_preparation_owner
        ~state:t.state
    in
    let attempted = ref false in
    let returned = ref false in
    Exn.protect
      ~finally:(fun () -> if not !returned then Source_binding.close binding)
      ~f:(fun () ->
        let prepare () =
          let now = t.services.now () in
          let%bind () = check_basis () in
          let%bind facts =
            Run_admission.prepare_held_from_preparation
              previous
              ~preparation
              ~owner:t.run_preparation_owner
              ~source:binding.source
              ~session
              ~run_id:(Agent_protocol.Id.Run.create ())
              ~now
          in
          let%bind planned =
            Goal_episode_admission.prepare_held previous ~admission:facts ~intent
          in
          let%bind policy =
            Goal_activation_policy.create
              ~goal:(Goal_episode_admission.goal planned)
              ~link:(Goal_episode_admission.link planned)
          in
          let%bind candidate =
            prepare_transition
              ~run_preparation:preparation
              t
              ~delta:
                (Session_delta.Batch
                   [ Run_state_changed (Goal_episode_admission.run_state planned)
                   ; Goal_catalog_changed (Goal_episode_admission.catalog planned)
                   ])
              ~payloads:[]
          in
          let check_before_commit () =
            let%bind decision =
              Goal_activation_policy.check_new_episode_eligibility
                policy
                ~state:candidate.state
                ~now:(t.services.now ())
            in
            let%bind () =
              match decision with
              | Allow -> Ok ()
              | Hold _ ->
                Error (error Permission_denied "Goal policy holds new episode admission")
            in
            let%bind () = check_source_original t binding in
            check_basis ()
          in
          let%bind () = check_before_commit () in
          let held =
            held_run
              t
              binding
              (Run_admission.Held_plan.run facts)
              (Run_admission.Held_plan.receipt facts)
          in
          Ok (candidate, held, policy, check_before_commit)
        in
        match prepare () with
        | Error failure -> Ok (Goal_activation.Admission.Rejected failure)
        | Ok (candidate, held, policy, check_before_commit) ->
          binding.phase <- Open (Admission_pending attempted);
          (match
             persist_transition
               ~run_preparation:preparation
               ~commit_attempted:attempted
               ~check_before_commit
               t
               candidate
           with
           | Error failure ->
             Ok
               (if !attempted
                then Goal_activation.Admission.Uncertain failure
                else Goal_activation.Admission.Rejected failure)
           | Ok () ->
             install_committed_transition ~run_preparation:preparation t candidate;
             binding.phase
             <- (match binding.phase with
                 | Open _ -> Open (Admitted held.admission)
                 | Closed _ -> Closed (Admitted held.admission));
             (* The durable association is inert. Publish its canonical Store
                projection before observing the SAME receipt for live issuance.
                Reentrant publication may retire it; issuance then reports its
                exact failure instead of fabricating a Current or permission. *)
             publish_committed_transition t candidate;
             let activation =
               checked_goal_activation t binding held policy authorization
             in
             returned := true;
             (match activation with
              | Ok checked -> Ok (Goal_activation.Admission.Admitted { held; checked })
              | Error error ->
                Ok
                  (Goal_activation.Admission.Activation_unavailable
                     { admission = held.admission; error }))))
;;

let begin_held_activation_internal t binding (held : Held_run.t) checked =
  let open Result.Let_syntax in
  let%bind () =
    if phys_equal binding held.binding
    then Ok ()
    else Error (error Conflict "held activation belongs to another prepared source")
  in
  let%bind () = Held_run.check_basis held in
  let%bind () = Admitted_activation.Checked.check_basis checked in
  let%bind controller = require_recurrence_controller t in
  let association = checked.Admitted_activation.Checked.association in
  let%bind () =
    Activation_association.check_target
      association
      ~store:controller
      ~state:t.state
      ~run:held.run
      ~admission:held.admission
  in
  let preparation = held.binding.Source_binding.preparation in
  let%bind authorization =
    Run_preparation.capture_authorization
      preparation
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let phase = ref Held_run.Activation.Reserved in
  let owned = ref None in
  let startup_pending () =
    (match !phase with
     | Reserved | Constructing -> true
     | Handed_off _ | Closed -> false)
    && Option.exists t.held_activation ~f:(fun active ->
      Option.exists !owned ~f:(phys_equal active))
  in
  let observer = held.run.Agent_protocol.Run.source.observer in
  let%bind scope =
    Run_admission.Scope.create_authenticated
      ~actor:(Run_preparation.Authorization.actor authorization)
      ~observer
      ~startup_pending
      ~authorize:(fun state ->
        match !phase with
        | Held_run.Activation.Reserved | Constructing | Handed_off _ ->
          Run_preparation.Authorization.check authorization state
        | Closed -> Error (error Conflict "held startup authority was retired"))
  in
  let fresh = ref None in
  let rec activation : Held_run.Activation.t =
    { domain = held.binding.domain
    ; preparation
    ; source = held.binding.source
    ; run = held.run
    ; admission = held.admission
    ; scope
    ; association
    ; phase
    ; input_attempt = ref Input_attempt.Available
    ; control_owner = ref ()
    ; control = None
    ; settled_callback = None
    ; owned_basis =
        (fun () ->
          let%bind () = require_runtime_admission t in
          let%bind () =
            if
              Option.exists t.held_activation ~f:(phys_equal activation)
              && Option.exists (initial_run_preparation t) ~f:(phys_equal preparation)
              &&
              match !phase with
              | Reserved | Constructing -> true
              | Handed_off _ | Closed -> false
            then Ok ()
            else Error (error Conflict "held activation owner was retired")
          in
          let%bind () =
            Run_preparation.check_basis
              preparation
              ~owner:t.run_preparation_owner
              ~state:t.state
          in
          let%bind () =
            Runtime_source_preparation.validate_target activation.source t.state
          in
          let%bind index =
            Result.of_option
              t.state.run_state
              ~error:(error Conflict "held startup Run index is absent")
          in
          let%bind run =
            Result.of_option
              (Run_state.find index held.run.id)
              ~error:(error Conflict "held startup Run is absent")
          in
          let%bind admission =
            Run_state.receipt
              index
              ~principal_id:held.admission.principal_id
              ~key:held.admission.key
              ~request_sha256:held.admission.request_sha256
          in
          let%bind () =
            if
              Option.exists admission ~f:(Agent_protocol.Run_receipt.equal held.admission)
            then
              Activation_association.check_target
                association
                ~store:controller
                ~state:t.state
                ~run
                ~admission:held.admission
            else Error (error Conflict "held startup Admission changed")
          in
          match run.lifecycle with
          | Admitted | Active -> Ok ()
          | Waiting _
            when Option.exists t.held_authored_start ~f:(fun scope ->
                   phys_equal
                     (Admitted_activation.Continuation.target scope.continuation)
                     activation
                   &&
                   match scope.phase with
                   | Executing _ | Completed _ -> true
                   | _ -> false) -> Ok ()
          | Waiting _ | Terminal _ ->
            Error (error Conflict "held startup is no longer exclusively starting"))
    ; basis =
        (fun () ->
          let%bind () = activation.owned_basis () in
          match !fresh with
          | Some current when Recurrence_controller.is_current current -> Ok ()
          | Some _ | None ->
            Error (error Conflict "held startup requires fresh target Store custody"))
    ; check_policy =
        (fun () ->
          let%bind () = activation.owned_basis () in
          let%bind () = Run_admission.Scope.authorize scope t.state in
          activation.owned_basis ())
    ; policy =
        (fun () ->
          let%bind () = activation.owned_basis () in
          let%bind () = Run_admission.Scope.authorize scope t.state in
          let%bind current = Recurrence_controller.observe controller t.state in
          fresh := Some current;
          activation.basis ())
    ; authority =
        (fun () ->
          let%bind () = activation.owned_basis () in
          let%bind () =
            Run_preparation.check_current
              preparation
              ~owner:t.run_preparation_owner
              ~state:t.state
          in
          activation.owned_basis ())
    }
  in
  owned := Some activation;
  (* No ownership mutation until all callbacks and both original guards finish.
     The new phase has not yet installed any normal Run authority. *)
  let%bind () = Source_binding.check_current held.binding in
  let%bind () = Admitted_activation.Checked.check_policy checked in
  let%bind () = Admitted_activation.Checked.check_timing checked in
  let%bind () = check_source_original t held.binding in
  let%bind () = Admitted_activation.Checked.check_authority checked in
  let%bind () = Held_run.check_basis held in
  let%bind () = Admitted_activation.Checked.check_basis checked in
  let continuation = checked.continue activation in
  Source_binding.close held.binding;
  t.run_source_binding <- None;
  t.held_activation <- Some activation;
  checked.consumed := true;
  Ok continuation
;;

let select_held_run_authority t (activation : Held_run.Activation.t) run =
  let caller = (Run_preparation.request activation.preparation).caller in
  match Run_authorities.find t.run_authorities run.Agent_protocol.Run.id with
  | None ->
    Run_authorities.add_for_caller t.run_authorities ~run ~scope:activation.scope ~caller
  | Some binding
    when phys_equal (Run_authorities.scope binding) activation.scope
         && Run_admission_request.Caller.equal (Run_authorities.caller binding) caller ->
    Ok t.run_authorities
  | Some _ -> Error (error Conflict "held startup lost its exact Run authority")
;;

let validate_held_authored_runtime t continuation startup snapshot =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target continuation in
  let%bind () = activation.Held_run.Activation.owned_basis () in
  let%bind () =
    if
      Option.exists
        t.operation_worker
        ~f:(phys_equal (Runtime_builder.Authored_start.worker startup))
      && Option.equal
           phys_equal
           t.moderator_manager
           (Runtime_builder.Authored_start.manager startup)
      && Option.is_none t.state.active_operation
      && (not (t.idle_moderator_borrowed || moderator_is_borrowed t))
      &&
      match t.state.runtime_initialization with
      | Ready -> true
      | Pending _ -> false
    then Ok ()
    else
      Error (error Conflict "authored startup requires its exact installed ready runtime")
  in
  let%bind () =
    match
      ( Runtime_source_preparation.moderator activation.source
      , Runtime_builder.Authored_start.disposition startup )
    with
    | Legacy _, Legacy_acknowledged | Extension _, Extension_pending -> Ok ()
    | ( (Legacy _ | Extension _ | No_moderator)
      , (Legacy_acknowledged | Extension_pending | No_callback) ) ->
      Error
        (error Conflict "authored startup disposition differs from its pinned moderator")
  in
  let%bind incoming =
    match snapshot, Runtime_builder.Authored_start.manager startup with
    | Some snapshot, Some _ -> Ok (Some (Moderator_checkpoint.encode snapshot))
    | None, None -> Ok None
    | Some _, None | None, Some _ ->
      Error (error Conflict "authored Manager snapshot is missing")
  in
  let%bind retained =
    Moderator_checkpoint.reuse_unchanged_snapshot ~previous:t.state.moderator ~incoming
  in
  if Option.equal Jsonaf.exactly_equal retained t.state.moderator
  then Ok ()
  else Error (error Conflict "authored Manager and retained checkpoint disagree")
;;

let begin_held_authored_internal t continuation startup snapshot =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target continuation in
  let request = Run_preparation.request activation.preparation in
  let%bind () =
    match request.input, !(activation.input_attempt), t.held_authored_start with
    | Authored_start, Available, None -> Ok ()
    | (Authored_start | User_submission _), (Available | Claimed), (Some _ | None) ->
      Error (error Conflict "held authored startup attempt is unavailable")
  in
  let%bind () =
    Authored_run_acknowledgement.require_unadmitted t.lifecycle_agent_custody
  in
  let%bind () =
    match t.state.lifecycle.desired, t.state.lifecycle.observed with
    | Stopped, Stopped -> Ok ()
    | _ -> Error (error Conflict "held authored startup requires a stopped target")
  in
  let%bind () = validate_held_authored_runtime t continuation startup snapshot in
  let%bind () = Runtime_builder.Authored_start.check_pending startup in
  let%bind () = check_held_effect continuation in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "held authored Run index is absent")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index activation.run.id)
      ~error:(error Conflict "held authored Run is absent")
  in
  let%bind authorities = select_held_run_authority t activation run in
  let%bind binding =
    Result.of_option
      (Run_authorities.find authorities run.id)
      ~error:(error Conflict "held authored authority selection is absent")
  in
  let%bind original =
    Result.of_option
      (Run_admission.Scope.original_actor activation.scope)
      ~error:
        (error Permission_denied "held authored startup requires its genuine original")
  in
  let scope : Held_authored_start.t =
    { domain = activation.domain
    ; issuing_actor = t.inference_owner_identity
    ; continuation
    ; startup
    ; binding
    ; jobs = []
    ; graphs = []
    ; phase = Staged
    }
  in
  let pending =
    match Runtime_builder.Authored_start.disposition startup with
    | Extension_pending ->
      Some
        (Admitted
           { generation = run.source.generation
           ; source = Some run.source.observer
           ; pending =
               Pending (create_agent_admission (Some (create_agent_custody original)))
           })
    | Legacy_acknowledged | No_callback -> None
  in
  let delta =
    Session_delta.Lifecycle_changed { desired = Running; observed = Starting }
  in
  let%bind candidate =
    prepare_transition
      ~run_preparation:activation.preparation
      t
      ~delta:
        (Batch
           (if t.state.pending_initial_start
            then [ Initial_start_consumed; delta ]
            else [ delta ]))
      ~payloads:
        [ Session_state_changed { desired_state = Running; observed_state = Starting } ]
  in
  let acknowledgement : Held_authored_acknowledgement.t =
    { previous = t.state
    ; previous_authorities = t.run_authorities
    ; candidate
    ; scope
    ; authorities
    ; pending
    ; installed = false
    }
  in
  let attempted = ref false in
  Exn.protect
    ~finally:(fun () ->
      if !attempted
      then (
        activation.input_attempt := Claimed;
        if not acknowledgement.installed then scope.phase <- Attempt_unconfirmed);
      Held_authored_acknowledgement.discard acknowledgement)
    ~f:(fun () ->
      Eio.Cancel.protect (fun () ->
        let check_before_commit () =
          let%bind () = Runtime_builder.Authored_start.check_pending startup in
          let%bind () = check_held_effect continuation in
          Held_authored_acknowledgement.check acknowledgement ~actor:t ~candidate
        in
        let%bind () =
          persist_transition
            ~run_preparation:activation.preparation
            ~commit_attempted:attempted
            ~check_before_commit
            t
            candidate
        in
        install_committed_transition
          ~run_preparation:activation.preparation
          ~held_authored_acknowledgement:acknowledgement
          t
          candidate;
        activation.input_attempt := Claimed;
        publish_committed_transition t candidate;
        Ok scope))
;;

let ready_held_authored_internal t (scope : Held_authored_start.t) =
  let open Result.Let_syntax in
  let%bind () = held_authored_basis t scope in
  let%bind () =
    match scope.phase, t.state.lifecycle.desired, t.state.lifecycle.observed with
    | Starting, Running, Starting -> Ok ()
    | _ -> Error (error Conflict "held authored lifecycle is not starting")
  in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind candidate =
    prepare_transition
      ~run_preparation:activation.preparation
      t
      ~delta:(Lifecycle_changed { desired = Running; observed = Idle })
      ~payloads:
        [ Session_state_changed { desired_state = Running; observed_state = Idle } ]
  in
  let revision = t.state.counters.revision in
  let check_before_commit () =
    let%bind () = held_authored_basis t scope in
    let%bind () = check_held_effect scope.continuation in
    if Int64.equal revision t.state.counters.revision
    then held_authored_basis t scope
    else Error (error Conflict "held authored ready ACK basis changed")
  in
  Eio.Cancel.protect (fun () ->
    let%bind () =
      persist_transition
        ~run_preparation:activation.preparation
        ~check_before_commit
        t
        candidate
    in
    install_committed_transition ~run_preparation:activation.preparation t candidate;
    scope.phase <- Ready;
    publish_committed_transition t candidate;
    Ok ())
;;

let finish_held_authored_execution_internal t (scope : Held_authored_start.t) =
  let open Result.Let_syntax in
  let%bind run = held_authored_run t scope in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () =
    if
      Option.is_some t.queued_event_borrow
      || moderator_is_borrowed t
      || Option.is_some t.state.active_operation
    then Error (error Conflict "held authored callback has not joined")
    else (
      match Runtime_builder.Authored_start.disposition scope.startup, scope.phase with
      | Legacy_acknowledged, Ready -> Ok ()
      | Extension_pending, Completed id ->
        if
          List.exists t.state.moderator_executions ~f:(fun receipt ->
            Agent_protocol.Id.Moderator_execution.equal receipt.context.id id
            && Agent_protocol.Moderator_execution.equal_phase
                 receipt.context.phase
                 Session_start
            && Int.equal receipt.context.generation run.source.generation
            && Agent_protocol.Invocation.equal_observer
                 receipt.context.source
                 run.source.observer
            &&
            match receipt.status with
            | Completed _ -> true
            | Running | Failed _ | Interrupted _ -> false)
        then Ok ()
        else
          Error (error Conflict "held authored lifecycle has no successful owned result")
      | (Legacy_acknowledged | Extension_pending | No_callback), _ ->
        Error (error Conflict "held authored startup has not completed"))
  in
  let%bind () = check_held_effect scope.continuation in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "held authored Run index is absent")
  in
  let now, sample = completion_clock_pair t in
  let%bind index =
    Run_work_settlement.prepare
      index
      ~state:t.state
      ~previous:run
      ~owned_work:run.owned_work
      ~terminal_work:run.terminal_work
      ~operation_id:None
      ~now
  in
  let%bind candidate =
    prepare_transition
      ~run_preparation:activation.preparation
      t
      ~delta:(Run_state_changed index)
      ~payloads:[]
  in
  let%bind completions = prepare_completion_plan t candidate (Some sample) in
  let revision = t.state.counters.revision in
  let check_before_commit () =
    let%bind () = held_authored_basis t scope in
    let%bind () = check_held_effect scope.continuation in
    if Int64.equal revision t.state.counters.revision
    then held_authored_basis t scope
    else Error (error Conflict "held authored final ACK basis changed")
  in
  Eio.Cancel.protect (fun () ->
    let%bind () =
      persist_transition
        ~run_preparation:activation.preparation
        ~check_before_commit
        t
        candidate
    in
    install_committed_transition ~run_preparation:activation.preparation t candidate;
    Option.iter
      completions
      ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
    let acknowledged_run = Option.value_exn (Run_state.find index run.id) in
    activation.phase
    := Handed_off
         (Authored_start
            { run = acknowledged_run
            ; admission = activation.admission
            ; binding = scope.binding
            });
    scope.phase <- Released;
    t.held_authored_start <- None;
    publish_committed_transition t candidate;
    Ok activation.admission)
;;

let finish_held_authored_internal t (scope : Held_authored_start.t) =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  match activation.control with
  | None ->
    let%map receipt = finish_held_authored_execution_internal t scope in
    Held_authored_result.Started receipt
  | Some control ->
    let%bind () =
      if
        Int.equal scope.domain (Stdlib.Domain.self () :> int)
        && phys_equal scope.issuing_actor t.inference_owner_identity
        && Option.exists t.held_authored_start ~f:(phys_equal scope)
        && Option.exists t.held_activation ~f:(phys_equal activation)
        && Option.exists
             t.operation_worker
             ~f:(phys_equal (Runtime_builder.Authored_start.worker scope.startup))
        && Option.equal
             phys_equal
             t.moderator_manager
             (Runtime_builder.Authored_start.manager scope.startup)
        && Option.is_none t.state.active_operation
        &&
        match scope.phase with
        | Completed id -> Agent_protocol.Id.Moderator_execution.equal id control.callback
        | Staged
        | Starting
        | Ready
        | Executing _
        | Released
        | Attempt_unconfirmed
        | Closed -> false
      then Ok ()
      else Error (error Conflict "controlled authored startup has not joined")
    in
    let construction = Runtime_construction.Initial scope.continuation in
    let%bind settled = complete_controlled_callback t construction control in
    let%map result =
      match settled with
      | None -> Ok (Held_authored_result.Controlled control)
      | Some (index, run) ->
        let%map settlement =
          goal_callback_settlement index ~episode:(Run_goal_link.episode control.link) run
        in
        Held_authored_result.Settled settlement
    in
    (* Real callback completion or settlement, never a synthetic startup handoff. *)
    scope.phase <- Released;
    t.held_authored_start <- None;
    result
;;

let prepare_held_history_reservation t continuation count =
  let open Result.Let_syntax in
  let target = Admitted_activation.Continuation.target continuation in
  let%bind () = target.Held_run.Activation.owned_basis () in
  let%bind () =
    if Option.exists t.held_activation ~f:(phys_equal target)
    then Ok ()
    else Error (error Conflict "held reservation belongs to another actor")
  in
  let%bind () = check_held_effect continuation in
  let%bind index =
    Result.of_option t.state.run_state ~error:(error Conflict "held index absent")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index target.run.id)
      ~error:(error Conflict "held Run absent")
  in
  let%bind authorities = select_held_run_authority t target run in
  let%bind () =
    if
      count > 0
      && Int64.(t.state.conversation.next_history_sequence <= max_value - of_int count)
    then Ok ()
    else Error (error Invalid_request "invalid held history reservation")
  in
  let first_sequence = t.state.conversation.next_history_sequence in
  let reserved_through = Int64.(first_sequence + of_int count) in
  let%bind candidate =
    prepare_transition
      ~run_preparation:target.preparation
      t
      ~delta:(Session_delta.History_block_reserved reserved_through)
      ~payloads:[]
  in
  Ok
    ( target
    , authorities
    , candidate
    , History_id_source.{ first_sequence; reserved_through } )
;;

let held_authored_resource_internal t continuation owner =
  let open Result.Let_syntax in
  let%bind scope =
    Result.of_option
      t.held_authored_start
      ~error:(error Conflict "held authored resource has no startup owner")
  in
  let%bind () =
    if phys_equal scope.continuation continuation
    then held_authored_basis t scope
    else Error (error Conflict "resource belongs to another held startup")
  in
  let%bind selected, execution =
    match owner with
    | Agent_protocol.Job.Moderator_event id ->
      let%bind borrow =
        Result.of_option
          t.queued_event_borrow
          ~error:(error Conflict "resource has no actual Event owner")
      in
      let%map () =
        if Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        then held_authored_event_basis t borrow scope
        else Error (error Conflict "resource Event owner changed")
      in
      `Event borrow, None
    | Invocation id ->
      let%bind execution =
        List.find t.invocation_executions ~f:(fun execution ->
          Agent_protocol.Id.Invocation.equal id execution.dispatched.context.id)
        |> Result.of_option
             ~error:(error Conflict "resource has no actual Invocation owner")
      in
      let%map selected =
        match execution.owner with
        | Event_moderator borrow ->
          let%map () = held_authored_event_basis t borrow scope in
          `Event borrow
        | Background_job job_scope ->
          let%bind () =
            if Option.exists (held_authored_job t job_scope.job) ~f:(phys_equal scope)
            then Ok ()
            else Error (error Conflict "resource Job is not this admitted startup child")
          in
          let%map () = job_scope_can_execute t job_scope in
          `Job job_scope
        | Foreground _ | Invocation_moderator _ ->
          Error (error Conflict "resource Invocation belongs to another physical owner")
      in
      selected, Some execution
  in
  let basis () =
    let%bind () = held_authored_basis t scope in
    let%bind () =
      match selected with
      | `Event borrow -> held_authored_event_basis t borrow scope
      | `Job job_scope ->
        let%bind job = job_scope_current t job_scope in
        if
          Option.exists (held_authored_job t job) ~f:(phys_equal scope)
          && job_scope.active
          && (not job_scope.cancel_requested)
          && Atomic.get job_scope.authority_live
          && Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running
          && (not t.state.halted)
          && Option.is_none t.state.failure
          &&
          match job.status with
          | Running | Waiting_permission _ -> true
          | _ -> false
        then Ok ()
        else Error (error Conflict "resource Job execution scope ended")
    in
    match execution with
    | None -> Ok ()
    | Some execution ->
      if
        List.mem t.invocation_executions execution ~equal:phys_equal
        && execution.accepts_children
        && Atomic.get execution.authority_live
        && List.exists
             t.state.invocations
             ~f:(Agent_protocol.Invocation.equal execution.dispatched)
      then Ok ()
      else Error (error Conflict "resource Invocation scope ended")
  in
  let%bind () =
    match selected with
    | `Event _ -> Ok ()
    | `Job job_scope ->
      let%bind admission = job_agent_admission t job_scope in
      Option.value_map
        admission
        ~default:(Error (error Permission_denied "resource Job has no original custody"))
        ~f:check_agent_admission
  in
  let%bind () = check_held_effect continuation in
  let%map () = basis () in
  { Held_authored_resource.domain = (Stdlib.Domain.self () :> int); basis }
;;

let reserve_held_history_block_internal t continuation count =
  let open Result.Let_syntax in
  let%bind target, authorities, candidate, reservation =
    prepare_held_history_reservation t continuation count
  in
  let%bind () =
    persist_transition
      ~run_preparation:target.Held_run.Activation.preparation
      ~check_before_commit:(fun () ->
        let%map () = check_held_effect continuation in
        target.phase := Constructing)
      t
      candidate
  in
  install_committed_transition ~run_preparation:target.preparation t candidate;
  t.run_authorities <- authorities;
  publish_committed_transition t candidate;
  Ok reservation
;;

let begin_held_input_internal t continuation =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target continuation in
  let request = Run_preparation.request activation.preparation in
  let%bind () =
    match request.input with
    | Authored_start ->
      Error (error Invalid_request "authored start has no user input to parse")
    | User_submission _ -> Ok ()
  in
  let%bind () =
    match !(activation.input_attempt) with
    | Input_attempt.Available -> Ok ()
    | Claimed -> Error (error Conflict "held input attempt has already been consumed")
  in
  let%bind () =
    match t.held_input_scope with
    | None -> Ok ()
    | Some _ -> Error (error Conflict "held input already has an owner")
  in
  let%bind () =
    if Int64.(t.state.conversation.next_history_sequence <= of_int Int.max_value)
    then Ok ()
    else Error (error Invalid_state "held input history sequence is exhausted")
  in
  let%bind _, authorities, candidate, reservation =
    prepare_held_history_reservation t continuation 1
  in
  let%bind id =
    History_entry.Id.create
      ~namespace:(Agent_protocol.Id.Session.to_string t.state.identity.session_id)
      ~sequence:(Int64.to_int_exn reservation.first_sequence)
    |> Result.map_error ~f:(error Invalid_state)
  in
  let selected = ref None in
  let scope =
    { Held_input_scope.domain = (Stdlib.Domain.self () :> int)
    ; issuing_actor = t.inference_owner_identity
    ; continuation
    ; request
    ; id
    ; phase = Parsing
    ; graphs = []
    ; issued_execution = None
    ; basis =
        (fun () ->
          match !selected with
          | None -> Error (error Invalid_state "held input has not been installed")
          | Some scope -> input_scope_basis t scope)
    }
  in
  selected := Some scope;
  let attempted = ref false in
  let result =
    Exn.protect
      ~finally:(fun () ->
        (* A failed or exceptional writer may already have committed. This
           actual attempt remains consumed even when no reply reaches its caller. *)
        if !attempted then activation.input_attempt := Claimed)
      ~f:(fun () ->
        persist_transition
          ~run_preparation:activation.preparation
          ~commit_attempted:attempted
          ~check_before_commit:(fun () ->
            let%bind () = check_held_effect continuation in
            if
              Option.is_none t.held_input_scope
              &&
              match !(activation.input_attempt) with
              | Available -> true
              | Claimed -> false
            then Ok ()
            else Error (error Conflict "held input was selected during admission"))
          t
          candidate)
  in
  let%bind () = result in
  install_committed_transition ~run_preparation:activation.preparation t candidate;
  activation.phase := Constructing;
  t.run_authorities <- authorities;
  t.held_input_scope <- Some scope;
  publish_committed_transition t candidate;
  Ok scope
;;

let ready_held_input_internal t (scope : Held_input_scope.t) input =
  let open Result.Let_syntax in
  let%bind () = input_scope_basis t scope in
  let%bind () = Held_input_scope.parsing scope in
  let%bind () = check_held_effect scope.continuation in
  let%bind () = input_scope_basis t scope in
  let%bind () =
    Runtime_input_preparation.Prepared_input.validate
      input
      ~request:scope.request
      ~id:scope.id
  in
  if List.is_empty scope.graphs
  then (
    scope.phase <- Parsed_ready input;
    Ok ())
  else Error (error Conflict "held input graph must join before parsing completes")
;;

let close_held_input_internal t (scope : Held_input_scope.t) =
  if not (phys_equal scope.issuing_actor t.inference_owner_identity)
  then Error (error Conflict "held input belongs to another actor")
  else (
    match scope.phase with
    | Consumed _ when Option.is_none t.held_input_scope -> Ok ()
    | Parsing | Parsed_ready _ | Consumed _ | Root_attempt_unconfirmed | Closed ->
      if not (Option.exists t.held_input_scope ~f:(phys_equal scope))
      then Error (error Conflict "held input was displaced before scope exit")
      else (
        (match scope.phase with
         | Parsing | Parsed_ready _ -> scope.phase <- Closed
         | Consumed _ | Root_attempt_unconfirmed | Closed -> ());
        if List.is_empty scope.graphs
        then (
          t.held_input_scope <- None;
          Ok ())
        else Error (error Conflict "held input graph did not join before scope exit")))
;;

let submit_held_run_input_internal t (scope : Held_input_scope.t) input =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () = input_scope_basis t scope in
  let%bind () =
    match scope.phase with
    | Parsed_ready recorded
      when Runtime_input_preparation.Prepared_input.equal recorded input -> Ok ()
    | Parsing | Parsed_ready _ | Consumed _ | Root_attempt_unconfirmed | Closed ->
      Error (error Conflict "held root requires its unconsumed recorded parsed input")
  in
  let%bind () =
    match
      t.state.lifecycle.desired, t.state.lifecycle.observed, t.state.active_operation
    with
    | Running, Idle, None
      when (not t.idle_moderator_borrowed)
           && Option.is_none t.state.failure
           && (not t.state.halted)
           && List.is_empty scope.graphs -> Ok ()
    | _ -> Error (error Conflict "held root requires an idle running target")
  in
  let%bind () = check_held_effect scope.continuation in
  let%bind worker =
    Result.of_option
      t.operation_worker
      ~error:(error Invalid_state "held root has no actual foreground worker")
  in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "held root Run index disappeared")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index activation.run.id)
      ~error:(error Conflict "held root Run disappeared")
  in
  let%bind binding =
    Result.of_option
      (Run_authorities.find t.run_authorities run.id)
      ~error:(error Permission_denied "held root lost its actual Run authority")
  in
  let%bind () =
    if phys_equal (Run_authorities.scope binding) activation.scope
    then Ok ()
    else Error (error Conflict "held root Run binding was replaced")
  in
  let%bind store = require_recurrence_controller t in
  let%bind () =
    Activation_association.check_target
      activation.association
      ~store
      ~state:t.state
      ~run
      ~admission:activation.admission
  in
  let%bind original =
    Result.of_option
      (Run_admission.Scope.original_actor activation.scope)
      ~error:(error Permission_denied "held root requires its genuine original")
  in
  let entry = Runtime_input_preparation.Prepared_input.entry input in
  let%bind () =
    Runtime_input_preparation.Prepared_input.validate
      input
      ~request:scope.request
      ~id:scope.id
  in
  let%bind enqueue =
    prepare_pending_inputs t ~owner:Host_internal Safe_boundary [ entry ]
  in
  let%bind pending =
    Pending_turn.prepare
      t.state
      ~enqueue
      ~entry
      ~runtime_admission_open:(runtime_admission_open t)
  in
  let operation = create_turn_operation t User_submit in
  let%bind handoff =
    Run_input_handoff.prepare
      t.state
      ~run
      ~request:scope.request
      ~input
      ~operation
      ~pending
      ~now:operation.started_at
  in
  let lifecycle = lifecycle_for_operation t operation.id in
  let before = t.state in
  let%bind candidate =
    prepare_transition
      ~run_preparation:activation.preparation
      t
      ~delta:
        (Session_delta.Batch
           ((Run_input_handoff.delta handoff :: Pending_turn.turn_deltas pending)
            @ [ Active_operation_changed (Some operation); Lifecycle_changed lifecycle ]))
      ~payloads:
        (Pending_turn.deferred_payloads pending
         @ [ History_appended (Pending_turn.entries pending)
           ; Operation_started operation
           ; Session_state_changed
               { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
           ])
  in
  let%bind controller = scope.continuation.controller.transfer () in
  let%bind () =
    if phys_equal controller.association activation.association
    then Ok ()
    else Error (error Conflict "held root transferred another admitted association")
  in
  let proof : Held_operation.Proof.t =
    { scope = activation.scope
    ; run
    ; admission = activation.admission
    ; source = activation.source
    ; operation
    ; worker
    ; binding
    ; controller
    }
  in
  let held : Held_operation.t = { proof; phase = Staged; target_current = None } in
  let owner : Operation_owner.t =
    { operation_id = operation.id
    ; admission = create_agent_admission (Some (create_agent_custody original))
    ; held = Some held
    }
  in
  let acknowledgement : Held_operation_acknowledgement.t =
    { input_scope = scope; input; activation; held; owner; previous = t.state; candidate }
  in
  let attempted = ref false in
  let%bind staged =
    Turn_admission_staging.capture
      ~owner:t.run_preparation_owner
      ~before
      ~candidate
      ~operation
      ~remaining_audit:t.command_audit
      ~commit_attempted:attempted
      ~plan:(operation, entry)
  in
  let persisted =
    Exn.protect
      ~finally:(fun () ->
        if !attempted
        then (
          match scope.phase with
          | Parsed_ready _ -> scope.phase <- Root_attempt_unconfirmed
          | Parsing | Consumed _ | Root_attempt_unconfirmed | Closed -> ());
        match held.phase with
        | Staged -> retire_agent_admission owner.admission
        | Pending_first_effect | Started | Retired -> ())
      ~f:(fun () ->
        let%bind () =
          persist_transition
            ~run_preparation:activation.preparation
            ~commit_attempted:attempted
            ~check_before_commit:(fun () ->
              let%bind () = check_held_effect scope.continuation in
              let%bind () =
                Held_operation_acknowledgement.check acknowledgement ~actor:t ~candidate
              in
              let%bind () = input_scope_basis t scope in
              let%bind () =
                Admitted_activation.Continuation.check_basis scope.continuation
              in
              Turn_admission_staging.check_before_writer
                staged
                ~owner:t.run_preparation_owner
                ~state:t.state)
            t
            candidate
        in
        install_committed_transition
          ~held_operation_acknowledgement:acknowledgement
          ~run_preparation:activation.preparation
          t
          candidate;
        Turn_admission_staging.acknowledge
          staged
          ~owner:t.run_preparation_owner
          ~state:t.state)
  in
  let%bind acknowledgement = persisted in
  let%bind operation, entry =
    Turn_admission_staging.finish
      acknowledgement
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  (* A failed publisher preserves the acknowledged proof but starts no worker;
     existing owner termination/recovery handles that truthful Starting row. *)
  publish_committed_transition t candidate;
  launch_worker t operation;
  Ok
    { session = Session_state.summary t.state
    ; history_id = entry.id
    ; disposition = Started
    ; operation_id = Some operation.id
    }
;;

let end_held_activation_internal t (activation : Held_run.Activation.t) =
  let open Result.Let_syntax in
  let%bind () =
    if Run_preparation.belongs_to activation.preparation ~owner:t.run_preparation_owner
    then Ok ()
    else Error (error Conflict "held cleanup belongs to another actor")
  in
  let clear_authored () =
    match t.held_authored_start with
    | Some scope
      when phys_equal
             (Admitted_activation.Continuation.target scope.continuation)
             activation ->
      scope.phase <- Closed;
      t.held_authored_start <- None
    | Some _ | None -> ()
  in
  match t.held_activation with
  | None -> Ok ()
  | Some other when not (phys_equal activation other) ->
    Error (error Conflict "another held startup owner replaced this cleanup")
  | Some _
    when match !(activation.phase) with
         | Handed_off _ -> true
         | Reserved | Constructing | Closed -> false ->
    (* The immutable root ACK proof, not the pending gate's mutable lifetime,
       makes startup cleanup independent from the actual Operation owner. *)
    t.held_activation <- None;
    Ok ()
  | Some _ when Option.is_some activation.control ->
    Held_run.Activation.close activation;
    clear_authored ();
    t.held_activation <- None;
    Ok ()
  | Some _ ->
    Held_run.Activation.close activation;
    let previous = t.state in
    let%bind () =
      match previous.run_state with
      | None -> Error (error Conflict "held cleanup lost its Run index")
      | Some index ->
        let%bind run =
          Result.of_option
            (Run_state.find index activation.run.id)
            ~error:(error Conflict "held cleanup Run is absent")
        in
        let%bind () =
          match run.Agent_protocol.Run.lifecycle with
          | Terminal _ -> Ok ()
          | Admitted | Active | Waiting _ ->
            if Int64.(previous.counters.revision < max_value)
            then Ok ()
            else Error (error Conflict "held cleanup revision is exhausted")
        in
        let now, sample = completion_clock_pair t in
        let session_revision =
          match run.lifecycle with
          | Terminal _ -> previous.counters.revision
          | Admitted | Active | Waiting _ -> Int64.succ previous.counters.revision
        in
        let%bind next =
          Run_retirement.interrupt_run
            index
            ~run_id:activation.run.id
            ~session_revision
            ~now
        in
        if Run_state.equal index next
        then (
          clear_authored ();
          Ok ())
        else (
          let run_preparation =
            match
              Run_preparation.check_basis
                activation.preparation
                ~owner:t.run_preparation_owner
                ~state:t.state
            with
            | Ok () -> Some activation.preparation
            | Error _ -> None
          in
          (* Factual loss of startup custody, not fresh execution authorization.
             Keep the same actual preparation only for its own ACK advancement. *)
          let%bind candidate =
            prepare_transition
              t
              ~delta:(Session_delta.Run_state_changed next)
              ~payloads:[]
          in
          let%bind completion = prepare_completion_plan t candidate (Some sample) in
          let%bind () =
            persist_transition
              ?run_preparation
              ~check_before_commit:(fun () ->
                if
                  Option.exists t.held_activation ~f:(phys_equal activation)
                  && Int64.equal previous.counters.revision t.state.counters.revision
                then Ok ()
                else Error (error Conflict "held cleanup basis changed"))
              t
              candidate
          in
          install_committed_transition ?run_preparation t candidate;
          Option.iter
            completion
            ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
          clear_authored ();
          publish_committed_transition t candidate;
          Ok ())
    in
    t.held_activation <- None;
    Ok ()
;;

let runtime_construction_owner_basis t construction =
  let supplied = Runtime_construction.preparation_owner construction in
  if
    Preparation_owner.belongs_to supplied ~owner:t.run_preparation_owner
    && Option.exists t.run_preparation ~f:(Preparation_owner.same supplied)
  then Ok ()
  else Error (error Conflict "runtime construction belongs to another Actor")
;;

let check_runtime_construction_admission_internal t construction =
  let open Result.Let_syntax in
  let%bind () = runtime_construction_owner_basis t construction in
  let%bind () = require_runtime_admission t in
  let%bind () = check_runtime_construction_effect construction in
  runtime_construction_owner_basis t construction
;;

let runtime_initialization_scope_basis t construction =
  let open Result.Let_syntax in
  let%bind () = runtime_construction_owner_basis t construction in
  let%bind scope =
    Result.of_option
      t.initialization_scope
      ~error:(error Conflict "runtime construction has no actual Init scope")
  in
  let%bind () =
    if
      Option.exists (Initialization_scope.construction scope) ~f:(fun selected ->
        Preparation_owner.same
          (Runtime_construction.preparation_owner selected)
          (Runtime_construction.preparation_owner construction))
    then validate_initialization_scope_basis t scope
    else Error (error Conflict "runtime construction does not own this Init scope")
  in
  Ok scope
;;

let runtime_initialization_scope t construction =
  let open Result.Let_syntax in
  let%bind scope = runtime_initialization_scope_basis t construction in
  let%map () = validate_initialization_scope t scope in
  scope
;;

let begin_runtime_initialization_internal t construction purpose expected =
  let open Result.Let_syntax in
  let%bind () = check_runtime_construction_admission_internal t construction in
  match construction with
  | Runtime_construction.Delegated_load load ->
    let%bind () =
      match load.preparation.initialization with
      | Scoped -> Ok ()
      | Installed_resume ->
        Error (error Permission_denied "installed resume cannot issue an ordinary Init")
    in
    begin_initialization_owned
      ~construction
      ?run_preparation:(Delegated_runtime_load.initial_preparation load.preparation.load)
      ?original_actor:(Delegated_runtime_load.original_actor load.preparation.load)
      ~purpose
      t
      expected
  | Initial _ | Existing_goal _ ->
    let original_actor =
      match construction with
      | Initial continuation ->
        Run_admission.Scope.original_actor continuation.target.scope
      | Existing_goal continuation ->
        Run_admission.Scope.original_actor
          (Run_authorities.scope
             continuation.Goal_continuation.binding.preparation.binding)
      | Delegated_load _ -> None
    in
    let%bind original_actor =
      Result.of_option
        original_actor
        ~error:
          (error
             Permission_denied
             "runtime construction lost its original Run authorization")
    in
    begin_initialization_owned ~construction ~original_actor ~purpose t expected
;;

let begin_held_initialization_internal t continuation purpose expected =
  begin_runtime_initialization_internal
    t
    (Runtime_construction.of_admitted continuation)
    purpose
    expected
;;

let begin_goal_runtime_construction_internal t construction step =
  let open Result.Let_syntax in
  let%bind () = check_runtime_construction_admission_internal t construction in
  let%bind continuation =
    match construction with
    | Runtime_construction.Existing_goal continuation -> Ok continuation
    | Initial _ | Delegated_load _ ->
      Error
        (error Invalid_request "Goal construction requires its existing episode owner")
  in
  let preparation = continuation.Goal_continuation.binding.preparation in
  let%bind () =
    if
      Option.is_none t.operation_worker
      && Option.is_none t.moderator_manager
      && Option.is_none t.state.active_operation
      && Option.is_none t.initialization_scope
      && (not t.idle_moderator_borrowed)
      && not (moderator_is_borrowed t)
    then Ok ()
    else
      Error
        (error Conflict "cold Goal construction requires its actual empty runtime slot")
  in
  let%bind observed =
    match step, preparation.runtime_phase, t.state.lifecycle.observed with
    | Runtime_construction_request.Step.Starting, Unclaimed, (Stopped | Idle) ->
      Ok Agent_protocol.Session.Starting
    | Running, Starting_acknowledged, Starting -> Ok Agent_protocol.Session.Idle
    | (Starting | Running), _, _ ->
      Error (error Conflict "Goal construction lifecycle attempt was consumed")
  in
  let lifecycle = Session_state.Lifecycle.{ desired = Running; observed } in
  let%bind candidate =
    prepare_transition
      t
      ~delta:(Session_delta.Lifecycle_changed lifecycle)
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_state_changed
            { desired_state = Running; observed_state = observed }
        ]
  in
  let attempted = ref false in
  let previous_phase = preparation.runtime_phase in
  let consumed = ref false in
  let check_before_commit () =
    let%bind () = check_runtime_construction_admission_internal t construction in
    if
      Option.is_none t.operation_worker
      && Option.is_none t.moderator_manager
      && Option.is_none t.state.active_operation
      && Option.is_none t.initialization_scope
    then Ok ()
    else Error (error Conflict "Goal runtime slot changed before lifecycle ACK")
  in
  preparation.runtime_phase
  <- (match step with
      | Starting -> Starting_writer attempted
      | Running -> Running_writer attempted);
  Exn.protect
    ~finally:(fun () ->
      if not !consumed
      then
        if !attempted
        then Goal_continuation.close preparation
        else (
          match preparation.runtime_phase with
          | (Starting_writer current | Running_writer current)
            when phys_equal current attempted ->
            preparation.runtime_phase <- previous_phase
          | Unclaimed
          | Starting_writer _
          | Starting_acknowledged
          | Running_writer _
          | Constructing
          | Installed _
          | Callback_completed _
          | Handed_off _
          | Retired _
          | Closed -> ()))
    ~f:(fun () ->
      Eio.Cancel.protect (fun () ->
        let%bind () =
          persist_transition ~commit_attempted:attempted ~check_before_commit t candidate
        in
        install_committed_transition_owned
          ~preparation_owner:(Some (Existing_goal preparation))
          t
          candidate;
        (* Local revocation during the yielding save remains monotone. The ACK
         advances factual custody but cannot reopen a closed runtime context. *)
        (match preparation.runtime_phase with
         | (Starting_writer current | Running_writer current)
           when phys_equal current attempted ->
           preparation.runtime_phase
           <- (match step with
               | Starting -> Starting_acknowledged
               | Running -> Constructing)
         | Unclaimed
         | Starting_writer _
         | Starting_acknowledged
         | Running_writer _
         | Constructing
         | Installed _
         | Callback_completed _
         | Handed_off _
         | Retired _
         | Closed -> ());
        consumed := true;
        publish_committed_transition t candidate;
        Ok ()))
;;

let reserve_owned_runtime_history t construction count =
  let open Result.Let_syntax in
  let%bind () = check_runtime_construction_admission_internal t construction in
  let%bind () =
    if
      count > 0
      && Int64.(t.state.conversation.next_history_sequence <= max_value - of_int count)
    then Ok ()
    else Error (error Invalid_request "invalid runtime history reservation")
  in
  let first_sequence = t.state.conversation.next_history_sequence in
  let reserved_through = Int64.(first_sequence + of_int count) in
  let%bind candidate =
    prepare_transition
      t
      ~delta:(Session_delta.History_block_reserved reserved_through)
      ~payloads:[]
  in
  let%map () =
    Eio.Cancel.protect (fun () ->
      let%bind () =
        persist_transition
          ~check_before_commit:(fun () ->
            check_runtime_construction_admission_internal t construction)
          t
          candidate
      in
      install_committed_transition_owned
        ~preparation_owner:(Some (Runtime_construction.preparation_owner construction))
        t
        candidate;
      publish_committed_transition t candidate;
      Ok ())
  in
  History_id_source.{ first_sequence; reserved_through }
;;

let reserve_runtime_history_block_internal t construction count =
  match construction with
  | Runtime_construction.Initial continuation ->
    reserve_held_history_block_internal t continuation count
  | Delegated_load _ -> reserve_owned_runtime_history t construction count
  | Existing_goal continuation ->
    let open Result.Let_syntax in
    let%bind () =
      match continuation.binding.preparation.runtime_phase with
      | Constructing -> Ok ()
      | Unclaimed
      | Starting_writer _
      | Starting_acknowledged
      | Running_writer _
      | Installed _
      | Callback_completed _
      | Handed_off _
      | Retired _
      | Closed ->
        Error
          (error Conflict "Goal history reservation requires its cold construction ACK")
    in
    reserve_owned_runtime_history t construction count
;;

let runtime_constructor_mutation_request
  : type a.
    t -> a Runtime_constructor_mutation_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let open Result.Let_syntax in
  let graph_mutation (graph : Runtime_constructor_graph.t) acknowledgement =
    Owned_inference_mutation.
      { scope = Initialization graph; owner = graph.owner; acknowledgement }
  in
  match request with
  | Open_graph (construction, source) ->
    let%bind scope = runtime_initialization_scope t construction in
    let%bind owner = open_inference_owner t source in
    scope.graphs <- owner :: scope.graphs;
    Ok ({ scope; construction; owner } : Runtime_constructor_graph.t)
  | Acknowledge (graph, handle, attempt) ->
    let%bind () = initialization_graph_basis t graph in
    let%bind registration = inference_registration t graph.owner handle in
    acknowledge_inference
      ~owned_graph:(graph_mutation graph (Acknowledge (registration, attempt)))
      t
      graph.owner
      handle
      attempt
  | Observe (graph, handle, incoming) ->
    let%bind () = initialization_graph_basis t graph in
    let%bind () =
      match
        Inference_ledger.find
          t.state.inference_ledger
          ~ordinal:(Inference_ledger.Handle.ordinal handle)
      with
      | Some row
        when Inference_ledger.Handle.equal (Inference_ledger.Row.handle row) handle
             && Option.exists (Graph_owner.qualified_source graph.owner) ~f:(fun source ->
               Transcript.Source_id.equal
                 source
                 (Transcript.Scope.key (Inference_ledger.Handle.scope handle)).source) ->
        Ok ()
      | Some _ | None ->
        Error (error Conflict "observation is not in this constructor graph")
    in
    observe_inference ~owned_graph:(graph_mutation graph Preserve) t handle incoming
  | Observe_owned (graph, incoming) ->
    let%bind () = initialization_graph_basis t graph in
    observe_owned_inference
      ~owned_graph:(graph_mutation graph Preserve)
      t
      graph.owner
      incoming
  | Complete (graph, handle, completion) ->
    let%bind () = initialization_graph_basis t graph in
    complete_inference
      ~owned_graph:(graph_mutation graph Preserve)
      t
      graph.owner
      handle
      completion
  | Release (graph, handle) ->
    let%bind () = initialization_graph_basis t graph in
    release_inference ~owned_graph:(graph_mutation graph Preserve) t graph.owner handle
  | Seal graph ->
    let%bind () = initialization_graph_basis t graph in
    seal_inference_owner t graph.owner
  | Finish graph ->
    let%bind () = initialization_graph_basis t graph in
    finish_inference_owner ~owned_graph:(graph_mutation graph Finish) t graph.owner
  | Shell_approvals (construction, approval_grants) ->
    let%bind scope = runtime_initialization_scope t construction in
    initialization_transition
      t
      scope
      ~delta:(Shell_changed { t.state.shell with approval_grants })
      ~payloads:[]
  | Shell_snapshots (construction, extension_snapshots) ->
    let%bind scope = runtime_initialization_scope t construction in
    initialization_transition
      t
      scope
      ~delta:(Shell_changed { t.state.shell with extension_snapshots })
      ~payloads:[]
  | Shell_manifest (construction, grant) ->
    let%bind scope = runtime_initialization_scope t construction in
    let projected =
      Security_grant.project_manifest
        ~now:(t.services.now ())
        ~session_id:t.state.identity.session_id
        ~creating_principal:t.state.identity.creating_principal
        grant
    in
    initialization_transition
      t
      scope
      ~delta:
        (Shell_changed
           { t.state.shell with manifest_grants = grant :: t.state.shell.manifest_grants })
      ~payloads:[ Grant_created projected ]
  | Add_job (construction, job) ->
    let%bind scope = runtime_initialization_scope t construction in
    add_constructor_job t (Initialization_job scope) job
  | Add_schedule (construction, schedule) ->
    let%bind scope = runtime_initialization_scope t construction in
    add_schedule ~initialization_scope:scope t schedule
  | Cancel_schedule (construction, schedule_id) ->
    let%bind scope = runtime_initialization_scope t construction in
    cancel_schedule_internal ~initialization_scope:scope t schedule_id
  | Capture_source (construction, job_id, generation, target, limits) ->
    let%bind scope = runtime_initialization_scope t construction in
    let%bind job, binding = find_model_job_target t job_id generation in
    let%bind () =
      if List.mem scope.jobs job.id ~equal:Agent_protocol.Id.Job.equal
      then Ok ()
      else Error (error Conflict "constructor does not own this Model source")
    in
    let%bind captured = Model_job_target.capture_source binding ~target ~limits in
    initialization_transition
      t
      scope
      ~delta:(Model_job_target_captured captured)
      ~payloads:[]
  | Capture_recipe (construction, job_id, generation, attempt, target, limits) ->
    let%bind scope = runtime_initialization_scope t construction in
    capture_initialization_recipe_target t scope job_id generation attempt target limits
  | Complete_model (construction, job_id, generation, attempt, outcome) ->
    let%bind scope = runtime_initialization_scope_basis t construction in
    complete_initialization_model_job t scope job_id generation attempt outcome
  | Interrupt_model (construction, job_id, generation, attempt, reason) ->
    let%bind scope = runtime_initialization_scope_basis t construction in
    let%bind owned =
      initialization_model_job_is_owned t scope job_id generation attempt
    in
    let%bind () =
      if owned
      then Ok ()
      else Error (error Conflict "constructor does not own this interrupted Model")
    in
    interrupt_job ~initialization_scope:scope t job_id generation attempt reason
  | Checkpoint ((Delegated_load load as construction), moderator, manager)
    when Delegated_load.Initialization.equal
           load.preparation.initialization
           Installed_resume ->
    let%bind () = check_runtime_construction_admission_internal t construction in
    checkpoint_owned_moderator
      t
      (Runtime_construction.preparation_owner construction)
      ~check:(fun () -> check_runtime_construction_admission_internal t construction)
      moderator
      manager
  | Checkpoint (construction, moderator, manager) ->
    let%bind scope = runtime_initialization_scope t construction in
    checkpoint_runtime_construction t scope moderator manager
;;

let held_runtime_installation_basis t continuation =
  let activation = Admitted_activation.Continuation.target continuation in
  let open Result.Let_syntax in
  let%bind () =
    if Int.equal activation.domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Invalid_request "held runtime belongs to another Eio domain")
  in
  let%bind () =
    if
      Option.exists t.held_activation ~f:(phys_equal activation)
      && Option.exists (initial_run_preparation t) ~f:(phys_equal activation.preparation)
      && Option.is_none t.operation_worker
      && Option.is_none t.state.active_operation
      && (not t.idle_moderator_borrowed)
      && not (moderator_is_borrowed t)
    then Ok ()
    else
      Error
        (error
           Conflict
           "held runtime install requires its exact idle owner and empty worker slot")
  in
  activation.owned_basis ()
;;

let enable_held_turn_budget_internal t continuation policy =
  let activation = Admitted_activation.Continuation.target continuation in
  let open Result.Let_syntax in
  let check_before_commit () =
    let%bind () = check_held_effect continuation in
    let%bind () = held_runtime_installation_basis t continuation in
    Admitted_activation.Continuation.check_basis continuation
  in
  let%bind () = held_runtime_installation_basis t continuation in
  (* Even an equal-policy no-write result belongs to this exact live startup.
     A changed policy repeats the joint fence at the actual writer boundary. *)
  let%bind () = check_before_commit () in
  enable_automatic_turn_budget
    ~check_before_commit
    ~run_preparation:activation.preparation
    t
    policy
;;

let install_held_runtime_internal t continuation worker inference moderator_manager =
  let open Result.Let_syntax in
  let%bind () = held_runtime_installation_basis t continuation in
  (* The existing Manager snapshot validation may acquire its gate. Do it before
     the final held policy/currentness fence, never after that joint check. *)
  let%bind () =
    validate_runtime_worker t (Some worker) (Some inference) moderator_manager
  in
  let%bind () = check_held_effect continuation in
  let%bind () = held_runtime_installation_basis t continuation in
  let%bind () = Admitted_activation.Continuation.check_basis continuation in
  install_runtime_worker t (Some worker) (Some inference) moderator_manager
;;

let goal_runtime_installation_basis t continuation =
  let open Result.Let_syntax in
  let construction = Runtime_construction.Existing_goal continuation in
  let%bind () = check_runtime_construction_effect construction in
  let preparation = continuation.Goal_continuation.binding.preparation in
  if
    Option.is_none t.state.active_operation
    && Option.is_none t.initialization_scope
    && (not t.idle_moderator_borrowed)
    && (not (moderator_is_borrowed t))
    &&
    match preparation.runtime_phase with
    | Unclaimed -> Option.is_some t.operation_worker
    | Constructing -> Option.is_none t.operation_worker
    | _ -> false
  then Ok ()
  else
    Error
      (error
         Conflict
         "Goal runtime installation requires its exact idle loaded or cold owner")
;;

let delegated_runtime_installation_basis t (load : Delegated_load.t) =
  let open Result.Let_syntax in
  let%bind () = check_runtime_construction_effect (Delegated_load load) in
  if
    load.preparation.consumed
    && Option.is_none load.preparation.installation
    && Option.is_none t.operation_worker
    && Option.is_none t.initialization_scope
    && (not t.idle_moderator_borrowed)
    && not (moderator_is_borrowed t)
  then Ok ()
  else Error (error Conflict "delegated runtime installation lost its exact cold owner")
;;

let enable_owned_runtime_turn_budget t construction ~check policy =
  let open Result.Let_syntax in
  let%bind () = check () in
  match t.state.automatic_turn_budget with
  | Some budget when Chat_response.Runtime_semantics.equal_policy budget.policy policy ->
    Ok ()
  | Some _ | None ->
    let%bind candidate =
      prepare_transition t ~delta:(Automatic_turn_budget_enabled policy) ~payloads:[]
    in
    let%bind () = persist_transition ~check_before_commit:check t candidate in
    install_committed_transition_owned
      ~preparation_owner:(Some (Runtime_construction.preparation_owner construction))
      t
      candidate;
    publish_committed_transition t candidate;
    Ok ()
;;

let enable_runtime_turn_budget_internal t construction policy =
  match construction with
  | Runtime_construction.Initial continuation ->
    enable_held_turn_budget_internal t continuation policy
  | Existing_goal continuation ->
    enable_owned_runtime_turn_budget
      t
      construction
      ~check:(fun () -> goal_runtime_installation_basis t continuation)
      policy
  | Delegated_load load ->
    enable_owned_runtime_turn_budget
      t
      construction
      ~check:(fun () -> delegated_runtime_installation_basis t load)
      policy
;;

let install_runtime_construction_internal t construction worker inference manager =
  match construction with
  | Runtime_construction.Initial continuation ->
    install_held_runtime_internal t continuation worker inference manager
  | Existing_goal continuation ->
    let open Result.Let_syntax in
    let%bind () = goal_runtime_installation_basis t continuation in
    let preparation = continuation.Goal_continuation.binding.preparation in
    let%bind cold =
      match preparation.runtime_phase with
      | Constructing -> Ok true
      | Unclaimed -> Ok false
      | _ -> Error (error Conflict "Goal installation attempt was consumed")
    in
    let%bind () =
      match t.operation_worker with
      | Some current
        when (not cold)
             && phys_equal current worker
             && Option.equal phys_equal manager t.moderator_manager
             && Option.exists t.inference_execution ~f:(phys_equal inference) -> Ok ()
      | None when cold -> validate_runtime_worker t (Some worker) (Some inference) manager
      | _ ->
        Error
          (error Conflict "Goal installation cannot replace a different physical runtime")
    in
    let%bind () = goal_runtime_installation_basis t continuation in
    let%bind () =
      if cold
      then install_runtime_worker t (Some worker) (Some inference) manager
      else Ok ()
    in
    let scope : Goal_continuation.runtime_scope =
      { issuing_actor = t.inference_owner_identity
      ; continuation
      ; worker
      ; manager
      ; cold
      ; resume = None
      ; callback = (if cold then Pending else Joined)
      ; jobs = []
      ; graphs = []
      }
    in
    preparation.runtime_phase <- Installed scope;
    Ok ()
  | Delegated_load load ->
    let open Result.Let_syntax in
    let%bind () = delegated_runtime_installation_basis t load in
    let%bind () = validate_runtime_worker t (Some worker) (Some inference) manager in
    let%bind () = delegated_runtime_installation_basis t load in
    let%bind () = install_runtime_worker t (Some worker) (Some inference) manager in
    load.preparation.installation <- Some { worker; inference; manager };
    Ok ()
;;

let acknowledge_goal_job_runtime_internal t (execution : Goal_execution_runtime.t) =
  let open Result.Let_syntax in
  let preparation = execution.binding.preparation in
  let%bind owner =
    match preparation.cause with
    | Claimed_job { owner; _ } -> Ok owner
    | Resume_command _ | Pending_wake _ ->
      Error
        (error Invalid_request "resource acknowledgement requires the actual claimed Job")
  in
  let%bind scope = select_goal_runtime t execution in
  let%bind () = preparation.registered_basis () in
  let%bind () = preparation.registered_authority () in
  let%bind () = goal_construction_basis t preparation in
  let%bind job = job_scope_current t owner.scope in
  if
    owner.scope.active
    && (not owner.scope.cancel_requested)
    && Atomic.get owner.scope.authority_live
    && Option.is_none t.initialization_scope
    &&
    match scope.callback with
    | Joined -> true
    | Pending | Executing _ | Completed _ -> false
  then (
    preparation.runtime_phase
    <- Handed_off (scope, Existing_execution (Claimed_job_resource job));
    Ok ())
  else Error (error Conflict "claimed Goal Job did not join its actual runtime lifecycle")
;;

let begin_goal_resume_callback_internal t continuation resume =
  let open Result.Let_syntax in
  let%bind scope = select_goal_runtime t continuation in
  let%bind () = check_runtime_construction_effect (Existing_goal continuation) in
  let%bind () =
    if
      scope.cold
      && Option.is_none scope.resume
      && phys_equal scope.worker (Runtime_builder.Runtime_resume.worker resume)
      && Option.equal
           phys_equal
           scope.manager
           (Runtime_builder.Runtime_resume.manager resume)
      &&
      match scope.callback with
      | Pending -> true
      | _ -> false
    then Runtime_builder.Runtime_resume.check_pending resume
    else
      Error
        (error
           Conflict
           "Goal resume callback is not this cold runtime's unconsumed lifecycle")
  in
  let%bind () = check_runtime_construction_effect (Existing_goal continuation) in
  scope.resume <- Some resume;
  Ok scope
;;

let claim_goal_resume_event t scope id snapshot event =
  let open Result.Let_syntax in
  let%bind run = goal_runtime_run t scope in
  let%bind () = check_runtime_construction_effect (Existing_goal scope.continuation) in
  let%bind () =
    match scope.Goal_continuation.callback, scope.resume, event with
    | Pending, Some resume, Chat_response.Moderation.Event.Session_resume
      when idle_moderator_eligible t ->
      Runtime_builder.Runtime_resume.check_pending resume
    | _ ->
      Error (error Conflict "Goal lifecycle is not ready for its actual Session_resume")
  in
  let%bind receipt, event =
    Queued_moderator_event.claim_ordinary
      ~state:t.state
      ~id
      ~snapshot
      ~operation_id:None
      ~event
      ~now:(t.services.now ())
  in
  let%bind original =
    Result.of_option
      (Run_admission.Scope.original_actor
         (Run_authorities.scope scope.continuation.binding.preparation.binding))
      ~error:(error Permission_denied "Goal lifecycle has no original Run authorization")
  in
  let admission = create_agent_admission (Some (create_agent_custody original)) in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then retire_agent_admission admission)
    ~f:(fun () ->
      let%bind run_scope = Run_scope.create ~run ~execution_id:id in
      let borrow : queued_event_borrow =
        { kind = Ordinary
        ; lifecycle_owner = Some (Existing_goal_resume scope)
        ; job_scope = None
        ; agent_admission = Resumed_run (Some admission)
        ; receipt
        ; before = snapshot
        ; event
        ; retirement_reason = None
        ; callback_active = true
        ; native_goals = Goal_native_actions.create ()
        ; authority_live = Atomic.make true
        ; run_actions = Some (Run_action_service.create ~scope:run_scope)
        ; committed = false
        ; stop_retirement = None
        ; cancel = None
        ; cancel_requested = false
        }
      in
      let%bind candidate =
        prepare_transition t ~delta:(Moderator_execution_changed receipt) ~payloads:[]
      in
      let%bind ack = Goal_runtime_acknowledgement.prepare t scope ~candidate in
      let check_before_commit () =
        let%bind () =
          check_runtime_construction_effect (Existing_goal scope.continuation)
        in
        let%bind () = check_agent_admission admission in
        let%bind () = Goal_runtime_acknowledgement.check ack ~actor:t ~candidate in
        if
          Option.is_none t.queued_event_borrow
          &&
          match scope.callback with
          | Pending -> true
          | _ -> false
        then Ok ()
        else Error (error Conflict "Goal lifecycle claim changed before ACK")
      in
      Eio.Cancel.protect (fun () ->
        let%bind () = persist_transition ~check_before_commit t candidate in
        install_committed_transition ~goal_runtime_acknowledgement:ack t candidate;
        scope.callback <- Executing id;
        t.queued_event_borrow <- Some borrow;
        t.idle_moderator_borrowed <- true;
        acknowledged := true;
        publish_committed_transition t candidate;
        Ok (Some borrow)))
;;

let finish_goal_resume_callback_internal t scope =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  let%bind () =
    if Option.is_some t.queued_event_borrow || moderator_is_borrowed t
    then Error (error Conflict "Goal resume callback has not joined")
    else (
      match scope.Goal_continuation.callback with
      | Pending ->
        (* The actual runtime's legacy/absent callback returned without invoking
           the supplied extension claim. It cannot replay that constructor ACK. *)
        Option.value_map
          scope.resume
          ~default:(Error (error Conflict "Goal resume lifecycle is absent"))
          ~f:Runtime_builder.Runtime_resume.check_pending
      | Completed id ->
        if
          List.exists t.state.moderator_executions ~f:(fun receipt ->
            Agent_protocol.Id.Moderator_execution.equal receipt.context.id id
            && Agent_protocol.Moderator_execution.equal_phase
                 receipt.context.phase
                 Session_resume
            && Agent_protocol.Invocation.equal_observer
                 receipt.context.source
                 scope.continuation.binding.preparation.run.source.observer
            &&
            match receipt.status with
            | Completed _ -> true
            | _ -> false)
        then Ok ()
        else
          Error (error Conflict "Goal resume has no successful actual lifecycle receipt")
      | Executing _ | Joined ->
        Error (error Conflict "Goal resume callback is not a fresh joined result"))
  in
  scope.callback <- Joined;
  let preparation = scope.continuation.binding.preparation in
  (match preparation.runtime_phase with
   | Installed current when phys_equal current scope ->
     preparation.runtime_phase <- Callback_completed scope
   | Retired current when phys_equal current scope -> ()
   | _ -> ());
  match preparation.control with
  | None -> Ok None
  | Some control ->
    let construction = Runtime_construction.Existing_goal scope.continuation in
    let%bind settled = complete_controlled_callback t construction control in
    (match settled, preparation.cause with
     | None, _ | Some _, Claimed_job _ -> Ok (Some control)
     | Some (index, run), (Resume_command _ | Pending_wake _) ->
       let%bind settlement = goal_resume_settlement index preparation run in
       let%map handoff =
         match preparation.cause with
         | Resume_command _ ->
           let result = Goal_resume_result.Continuation.Settled settlement in
           preparation.resume_outcome <- Some result;
           Ok (Goal_runtime_handoff.Resume result)
         | Pending_wake _ -> Ok (Existing_execution (Lifecycle_settlement settlement))
         | Claimed_job _ ->
           Error (error Invalid_request "claimed Job is not a lifecycle settlement")
       in
       preparation.runtime_phase <- Handed_off (scope, handoff);
       None)
;;

let joined_goal_runtime_basis t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  let%bind () =
    match scope.callback with
    | Joined
      when Option.is_none t.queued_event_borrow
           && (not (moderator_is_borrowed t))
           && Option.is_none t.initialization_scope -> Ok ()
    | Pending | Executing _ | Completed _ | Joined ->
      Error (error Conflict "Goal lifecycle ownership has not joined")
  in
  Run_admission.Scope.check_current
    (Run_authorities.scope scope.continuation.binding.preparation.binding)
;;

(* Shared actual aggregate writer for a joined existing-Goal lifecycle. A Finish
   intent alone is not terminal evidence; only the real completion candidate and
   terminal receipt can install a settlement/handoff. *)
let finalize_goal_runtime_settlement t scope index run =
  let open Result.Let_syntax in
  let preparation = scope.Goal_continuation.continuation.binding.preparation in
  let%bind () = joined_goal_runtime_basis t scope in
  let now, sample = completion_clock_pair t in
  let%bind settled =
    Run_work_settlement.prepare
      index
      ~state:t.state
      ~previous:run
      ~owned_work:run.Agent_protocol.Run.owned_work
      ~terminal_work:run.terminal_work
      ~operation_id:None
      ~now
  in
  let%bind settled_run =
    Result.of_option
      (Run_state.find settled run.id)
      ~error:(error Conflict "Goal aggregate lost its Run")
  in
  match settled_run.lifecycle with
  | Waiting _ ->
    Error (error Internal_error "Goal aggregate introduced a wake without a callback")
  | Admitted | Active -> Ok None
  | Terminal _ ->
    let%bind candidate =
      prepare_transition t ~delta:(Run_state_changed settled) ~payloads:[]
    in
    let%bind acknowledgement = Goal_runtime_acknowledgement.prepare t scope ~candidate in
    let%bind completions = prepare_completion_plan t candidate (Some sample) in
    let%bind settlement = goal_resume_settlement settled preparation settled_run in
    let%bind handoff =
      match preparation.cause with
      | Resume_command _ ->
        Ok
          (Goal_runtime_handoff.Resume
             (Goal_resume_result.Continuation.Settled settlement))
      | Pending_wake _ ->
        Ok (Goal_runtime_handoff.Existing_execution (Lifecycle_settlement settlement))
      | Claimed_job _ ->
        Error (error Invalid_request "claimed Job cannot settle a lifecycle callback")
    in
    let%bind () =
      persist_transition
        ~check_before_commit:(fun () ->
          let%bind () = joined_goal_runtime_basis t scope in
          Goal_runtime_acknowledgement.check acknowledgement ~actor:t ~candidate)
        t
        candidate
    in
    install_committed_transition ~goal_runtime_acknowledgement:acknowledgement t candidate;
    Option.iter
      completions
      ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
    preparation.runtime_phase <- Handed_off (scope, handoff);
    (match handoff with
     | Goal_runtime_handoff.Resume handoff -> preparation.resume_outcome <- Some handoff
     | Existing_execution _ -> ());
    publish_committed_transition t candidate;
    Ok (Some settlement)
;;

let continue_goal_episode_internal t continuation =
  let open Result.Let_syntax in
  let preparation = continuation.Goal_continuation.binding.preparation in
  let failed error =
    Ok
      (Goal_resume_result.Resume_failed
         { receipt = Goal_continuation.receipt continuation; error })
  in
  let proceed_execution () =
    let%bind scope = select_goal_runtime t continuation in
    let%bind () =
      if
        Option.is_none t.queued_event_borrow
        && (not (moderator_is_borrowed t))
        && Option.is_none t.initialization_scope
        && Option.is_none t.state.active_operation
        &&
        match scope.callback with
        | Joined -> true
        | _ -> false
      then Ok ()
      else Error (error Conflict "Goal continuation lifecycle has not joined")
    in
    let%bind index =
      Result.of_option
        t.state.run_state
        ~error:(error Conflict "Goal continuation Run index is absent")
    in
    let%bind run =
      Result.of_option
        (Run_state.find index preparation.run.id)
        ~error:(error Conflict "Goal continuation Run is absent")
    in
    match preparation.runtime_phase with
    | Handed_off (actual, Resume result) when phys_equal actual scope ->
      Ok
        (Goal_resume_result.Resumed
           { receipt = Goal_continuation.receipt continuation; continuation = result })
    | _ ->
      let%bind () =
        if
          Agent_protocol.Goal_episode.matches_run
            (Run_goal_link.episode preparation.link)
            run
        then Ok ()
        else
          Error (error Conflict "Goal continuation episode changed before final handoff")
      in
      (match run.lifecycle with
       | Terminal _ ->
         let%map settlement = goal_resume_settlement index preparation run in
         let result = Goal_resume_result.Continuation.Settled settlement in
         preparation.runtime_phase <- Handed_off (scope, Resume result);
         preparation.resume_outcome <- Some result;
         Goal_resume_result.Resumed
           { receipt = Goal_continuation.receipt continuation; continuation = result }
       | Waiting wake ->
         let%map () = check_runtime_construction_effect (Existing_goal continuation) in
         let result = Goal_resume_result.Continuation.Waiting wake in
         preparation.runtime_phase <- Handed_off (scope, Resume result);
         preparation.resume_outcome <- Some result;
         Goal_resume_result.Resumed
           { receipt = Goal_continuation.receipt continuation; continuation = result }
       | Admitted | Active ->
         let%bind settlement = finalize_goal_runtime_settlement t scope index run in
         (match settlement with
          | Some settlement ->
            Ok
              (Goal_resume_result.Resumed
                 { receipt = Goal_continuation.receipt continuation
                 ; continuation = Goal_resume_result.Continuation.Settled settlement
                 })
          | None ->
            let pending_finish =
              List.exists (Run_state.intents index) ~f:(fun intent ->
                Agent_protocol.Id.Run.equal intent.Run_intent.receipt.run_id run.id
                && Run_intent.Disposition.equal intent.disposition Pending
                &&
                match intent.action with
                | Finish _ -> true
                | Continue | Wait _ -> false)
            in
            if pending_finish
            then
              Error
                (error Conflict "Goal continuation still awaits its actual Finish work")
            else (
              let%bind () =
                check_runtime_construction_effect (Existing_goal continuation)
              in
              let%bind recovery =
                History_continuation.prepare t.state ~retiring_history:false
              in
              let operation = create_turn_operation t Administrative in
              let%bind turn =
                Turn_admission.create
                  t.state
                  ~operation
                  ~notification_wakes:[]
                  ~adopt_deferred:false
              in
              let%bind work =
                Agent_protocol.Run_work.create
                  ~key:(Operation operation.id)
                  ~generation:operation.generation
              in
              let%bind next =
                Run_work_settlement.prepare
                  index
                  ~state:t.state
                  ~previous:run
                  ~owned_work:(run.owned_work @ [ work ])
                  ~terminal_work:run.terminal_work
                  ~operation_id:None
                  ~now:operation.started_at
              in
              let before = t.state in
              let%bind candidate =
                prepare_transition
                  t
                  ~delta:
                    (Batch
                       (History_continuation.deltas recovery
                        @ Turn_admission.deltas turn
                        @ [ Run_state_changed next ]))
                  ~payloads:
                    (History_continuation.payloads recovery @ Turn_admission.payloads turn)
              in
              let%bind ack = prepare_goal_operation_ack t scope ~operation ~candidate in
              let controller =
                ack.Goal_runtime_operation_acknowledgement.held.proof.controller
              in
              let owner = ack.owner in
              let%bind fact = Goal_runtime_acknowledgement.prepare t scope ~candidate in
              let attempted = ref false in
              let%bind staged =
                Turn_admission_staging.capture
                  ~owner:t.run_preparation_owner
                  ~before
                  ~candidate
                  ~operation
                  ~remaining_audit:t.command_audit
                  ~commit_attempted:attempted
                  ~plan:operation
              in
              let installed = ref false in
              Exn.protect
                ~finally:(fun () ->
                  if not !installed
                  then (
                    retire_agent_admission owner.admission;
                    controller.close ());
                  if !attempted && not !installed then Goal_continuation.close preparation)
                ~f:(fun () ->
                  let%bind () =
                    persist_transition
                      ~commit_attempted:attempted
                      ~check_before_commit:(fun () ->
                        let%bind () =
                          check_runtime_construction_effect (Existing_goal continuation)
                        in
                        let%bind () =
                          Goal_runtime_operation_acknowledgement.check
                            ack
                            ~actor:t
                            ~candidate
                        in
                        let%bind () =
                          Goal_runtime_acknowledgement.check fact ~actor:t ~candidate
                        in
                        Turn_admission_staging.check_before_writer
                          staged
                          ~owner:t.run_preparation_owner
                          ~state:t.state)
                      t
                      candidate
                  in
                  install_committed_transition
                    ~goal_runtime_acknowledgement:fact
                    ~goal_operation_acknowledgement:ack
                    t
                    candidate;
                  installed := true;
                  let%bind acknowledgement =
                    Turn_admission_staging.acknowledge
                      staged
                      ~owner:t.run_preparation_owner
                      ~state:t.state
                  in
                  let%bind operation =
                    Turn_admission_staging.finish
                      acknowledgement
                      ~owner:t.run_preparation_owner
                      ~state:t.state
                  in
                  publish_committed_transition t candidate;
                  launch_worker t operation;
                  Ok
                    (Goal_resume_result.Resumed
                       { receipt = Goal_continuation.receipt continuation
                       ; continuation = Started operation
                       })))))
  in
  let proceed () =
    let handed_off =
      match preparation.runtime_phase with
      | Handed_off _ -> true
      | _ -> false
    in
    match preparation.control with
    | None -> proceed_execution ()
    | Some _ when handed_off -> proceed_execution ()
    | Some control ->
      let construction = Runtime_construction.Existing_goal continuation in
      let%bind settled = complete_controlled_callback t construction control in
      let%map outcome =
        match settled with
        | None -> Ok (Goal_resume_result.Continuation.Controlled control)
        | Some (index, run) ->
          let%map settlement = goal_resume_settlement index preparation run in
          Goal_resume_result.Continuation.Settled settlement
      in
      preparation.resume_outcome <- Some outcome;
      Goal_resume_result.Resumed
        { receipt = Goal_continuation.receipt continuation; continuation = outcome }
  in
  match proceed () with
  | Ok result -> Ok result
  | Error error -> failed error
;;

let with_goal_wake_scope t execution f =
  let open Result.Let_syntax in
  let%bind scope = select_goal_runtime t execution in
  let%bind wake = Goal_execution_runtime.wake execution in
  let%bind () = check_runtime_construction_effect (Existing_goal execution) in
  let%bind () =
    match
      scope.callback, execution.Goal_continuation.binding.preparation.runtime_phase
    with
    | Joined, (Installed _ | Callback_completed _) -> Ok ()
    | ( (Pending | Executing _ | Completed _ | Joined)
      , ( Unclaimed
        | Starting_writer _
        | Starting_acknowledged
        | Running_writer _
        | Constructing
        | Installed _
        | Callback_completed _
        | Handed_off _
        | Retired _
        | Closed ) ) ->
      Error (error Conflict "Goal wake has no unconsumed joined runtime")
  in
  f scope wake
;;

let enqueue_goal_wake_job_internal t execution delivery before after =
  with_goal_wake_scope t execution (fun scope wake ->
    if
      Option.exists
        (Run_job_delivery.Key.of_wake wake)
        ~f:(Run_job_delivery.Key.equal (Run_job_delivery.key delivery))
    then enqueue_run_job_delivery ~goal_runtime_scope:scope t delivery before after
    else Error (error Conflict "Goal wake differs from retained Job delivery"))
;;

let claim_goal_wake_schedule_internal t execution expected =
  with_goal_wake_scope t execution (fun scope wake ->
    let open Result.Let_syntax in
    let%bind current = find_schedule t expected.Agent_protocol.Schedule.id in
    let%bind () =
      if
        Jsonaf.exactly_equal
          (Agent_protocol.Schedule.to_json current)
          (Agent_protocol.Schedule.to_json expected)
      then Ok ()
      else Error (error Conflict "Goal wake schedule changed before claim")
    in
    match wake.occurrence with
    | Delivered_timer { schedule_id; _ }
      when Agent_protocol.Id.Schedule.equal schedule_id current.id ->
      claim_schedule ~goal_runtime_scope:scope t current.id current.generation
    | Delivered_timer _ | Job_completion _ | Subscription_delivery _ ->
      Error (error Conflict "Goal wake differs from claimed schedule"))
;;

let complete_goal_wake_schedule_internal t execution expected before manager after =
  with_goal_wake_scope t execution (fun scope wake ->
    match wake.occurrence with
    | Delivered_timer { schedule_id; _ }
      when Agent_protocol.Id.Schedule.equal
             schedule_id
             expected.Agent_protocol.Schedule.id ->
      complete_schedule
        ~goal_runtime_scope:scope
        t
        expected.id
        expected.generation
        (Some before)
        (Some expected)
        (Some after)
        (Some manager)
    | Delivered_timer _ | Job_completion _ | Subscription_delivery _ ->
      Error (error Conflict "Goal wake differs from completed schedule"))
;;

let deliver_goal_wake_job_internal t execution expected before after =
  with_goal_wake_scope t execution (fun scope wake ->
    match wake.occurrence with
    | Job_completion { job_id; attempt }
      when Agent_protocol.Id.Job.equal job_id expected.Agent_protocol.Job.id
           && Int.equal attempt expected.attempt ->
      deliver_job_without_legacy
        ~goal_runtime_scope:scope
        t
        expected.id
        expected.generation
        (Some before)
        (Some expected)
        (Some after)
      |> Result.map ~f:ignore
    | Job_completion _ | Delivered_timer _ | Subscription_delivery _ ->
      Error (error Conflict "Goal wake differs from completed Job"))
;;

let finish_goal_wake_execution_internal t execution =
  let open Result.Let_syntax in
  let preparation = execution.Goal_continuation.binding.preparation in
  let%bind scope = select_goal_runtime t execution in
  let%bind () =
    if
      Option.is_none t.queued_event_borrow
      && (not (moderator_is_borrowed t))
      && Option.is_none t.initialization_scope
    then Ok ()
    else Error (error Conflict "Goal wake callback has not joined")
  in
  let result handoff =
    match handoff with
    | Goal_execution_handoff.Queued_event event ->
      Ok (Goal_execution_runtime.Wake_result.Queued event)
    | Subscription_turn operation ->
      Ok (Goal_execution_runtime.Wake_result.Started operation)
    | Lifecycle_wait wake -> Ok (Goal_execution_runtime.Wake_result.Waiting wake)
    | Lifecycle_settlement settlement ->
      Ok (Goal_execution_runtime.Wake_result.Settled settlement)
    | Claimed_job_resource _ -> Error (error Invalid_request "claimed Job is not a wake")
  in
  match preparation.runtime_phase with
  | Handed_off (current, Existing_execution handoff) when phys_equal current scope ->
    result handoff
  | Unclaimed
  | Starting_writer _
  | Starting_acknowledged
  | Running_writer _
  | Constructing
  | Installed _
  | Callback_completed _
  | Handed_off _
  | Retired _
  | Closed ->
    let%bind () = joined_goal_runtime_basis t scope in
    let%bind previous = Goal_execution_runtime.wake execution in
    let%bind index =
      Result.of_option
        t.state.run_state
        ~error:(error Conflict "Goal wake Run index is absent")
    in
    let%bind run =
      Result.of_option
        (Run_state.find index preparation.run.id)
        ~error:(error Conflict "Goal wake Run is absent")
    in
    let%bind handoff =
      match run.lifecycle with
      | Terminal _ ->
        let%map settlement = goal_resume_settlement index preparation run in
        Goal_execution_handoff.Lifecycle_settlement settlement
      | Waiting wake when not (Agent_protocol.Run_wake.equal previous wake) ->
        (* A genuinely joined callback wrote this distinct Wait. Returning its
           factual ACK neither Enables nor starts another Operation. *)
        Ok (Goal_execution_handoff.Lifecycle_wait wake)
      | Admitted | Active ->
        let%bind settlement = finalize_goal_runtime_settlement t scope index run in
        (match settlement with
         | Some settlement -> Ok (Goal_execution_handoff.Lifecycle_settlement settlement)
         | None -> Error (error Conflict "Goal wake has no joined lifecycle outcome"))
      | Waiting _ ->
        Error
          (error
             Conflict
             "Goal wake has no acknowledged handoff or new lifecycle outcome")
    in
    preparation.runtime_phase <- Handed_off (scope, Existing_execution handoff);
    result handoff
;;

let finish_goal_wake_runtime_internal t execution =
  let open Result.Let_syntax in
  let preparation = execution.Goal_continuation.binding.preparation in
  let handed_off =
    match preparation.runtime_phase with
    | Handed_off _ -> true
    | _ -> false
  in
  match preparation.control, preparation.settled_callback with
  | Some control, Some settlement ->
    let%map _ =
      observe_callback_settlement
        t
        (Runtime_construction.Existing_goal execution)
        control
        settlement
    in
    Goal_execution_runtime.Wake_result.Settled settlement
  | None, _ -> finish_goal_wake_execution_internal t execution
  | Some _, None when handed_off -> finish_goal_wake_execution_internal t execution
  | Some control, None ->
    let construction = Runtime_construction.Existing_goal execution in
    let%bind settled = complete_controlled_callback t construction control in
    (match settled with
     | None -> Ok (Goal_execution_runtime.Wake_result.Controlled control)
     | Some (index, run) ->
       let%map settlement = goal_resume_settlement index preparation run in
       Goal_execution_runtime.Wake_result.Settled settlement)
;;

let initialization_construction_resource t construction scope owner =
  let open Result.Let_syntax in
  let scope_basis () =
    let%bind () = validate_initialization_scope_basis t scope in
    if
      Option.exists (Initialization_scope.construction scope) ~f:(fun actual ->
        Preparation_owner.same
          (Runtime_construction.preparation_owner actual)
          (Runtime_construction.preparation_owner construction))
    then Ok ()
    else Error (error Conflict "constructor resource preparation changed")
  in
  let event_basis borrow =
    let%bind () = scope_basis () in
    if
      Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
      && Option.exists (constructor_scope_of_borrow t borrow) ~f:(phys_equal scope)
      && initialization_callback_is_owned t scope
      && borrow.callback_active
      && Atomic.get borrow.authority_live
      && not (borrow.committed || borrow.cancel_requested)
    then Ok ()
    else Error (error Conflict "constructor resource Event execution ended")
  in
  let job_basis job =
    let%bind () = scope_basis () in
    let%bind current = job_scope_current t job in
    if
      List.mem
        scope.Initialization_scope.jobs
        current.id
        ~equal:Agent_protocol.Id.Job.equal
      && job.active
      && (not job.cancel_requested)
      && Atomic.get job.authority_live
    then Ok ()
    else Error (error Conflict "constructor resource Job execution ended")
  in
  let%bind selected, execution =
    match owner with
    | Agent_protocol.Job.Moderator_event id ->
      let%bind borrow =
        Result.of_option
          t.queued_event_borrow
          ~error:(error Conflict "constructor resource has no actual Event")
      in
      let%map () =
        if Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        then event_basis borrow
        else Error (error Conflict "constructor resource Event changed")
      in
      `Event borrow, None
    | Invocation id ->
      let%bind execution =
        List.find t.invocation_executions ~f:(fun execution ->
          Agent_protocol.Id.Invocation.equal id execution.dispatched.context.id)
        |> Result.of_option
             ~error:(error Conflict "constructor resource has no actual Invocation")
      in
      let%map selected =
        match execution.owner with
        | Event_moderator borrow ->
          let%map () = event_basis borrow in
          `Event borrow
        | Background_job job ->
          let%bind () = job_scope_can_execute t job in
          let%map () = job_basis job in
          `Job job
        | Foreground _ | Invocation_moderator _ ->
          Error (error Conflict "constructor resource Invocation has another owner")
      in
      selected, Some execution
  in
  let basis () =
    let%bind () =
      match selected with
      | `Event borrow -> event_basis borrow
      | `Job job -> job_basis job
    in
    match execution with
    | None -> Ok ()
    | Some execution ->
      if
        List.mem t.invocation_executions execution ~equal:phys_equal
        && execution.accepts_children
        && Atomic.get execution.authority_live
        && List.exists
             t.state.invocations
             ~f:(Agent_protocol.Invocation.equal execution.dispatched)
      then Ok ()
      else Error (error Conflict "constructor resource Invocation execution ended")
  in
  let%bind () = check_runtime_construction_effect construction in
  let%bind () = check_initialization_agent_actor scope in
  let%map () = basis () in
  { Held_authored_resource.domain = (Stdlib.Domain.self () :> int); basis }
;;

let runtime_construction_resource_internal t construction owner =
  let constructor =
    Option.filter t.initialization_scope ~f:(fun scope ->
      Option.exists (Initialization_scope.construction scope) ~f:(fun actual ->
        Preparation_owner.same
          (Runtime_construction.preparation_owner actual)
          (Runtime_construction.preparation_owner construction)))
  in
  match constructor with
  | Some scope -> initialization_construction_resource t construction scope owner
  | None ->
    (match construction with
     | Runtime_construction.Initial continuation ->
       held_authored_resource_internal t continuation owner
     | Delegated_load _ ->
       Error (error Conflict "ordinary load has no actual Init resource owner")
     | Existing_goal continuation ->
       let open Result.Let_syntax in
       let%bind scope = select_goal_runtime t continuation in
       let%bind borrow, execution =
         match owner with
         | Agent_protocol.Job.Moderator_event id ->
           let%bind borrow =
             Result.of_option
               t.queued_event_borrow
               ~error:(error Conflict "Goal resource has no actual Event owner")
           in
           let%bind () =
             if Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id
             then goal_runtime_event_basis t borrow scope
             else Error (error Conflict "Goal resource Event changed")
           in
           Ok (`Event borrow, None)
         | Invocation id ->
           let%bind execution =
             List.find t.invocation_executions ~f:(fun execution ->
               Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
             |> Result.of_option
                  ~error:(error Conflict "Goal resource has no actual Invocation owner")
           in
           let%map borrow =
             match execution.owner with
             | Event_moderator borrow ->
               let%map () = goal_runtime_event_basis t borrow scope in
               `Event borrow
             | Background_job job ->
               let%bind () = job_scope_can_execute t job in
               if Option.exists (goal_runtime_job t job.job) ~f:(phys_equal scope)
               then Ok (`Job job)
               else Error (error Conflict "Goal resource Job belongs to another startup")
             | Foreground _ | Invocation_moderator _ ->
               Error
                 (error
                    Conflict
                    "Goal resource Invocation belongs to another physical owner")
           in
           borrow, Some execution
       in
       let basis () =
         let%bind () = goal_runtime_scope_basis t scope in
         let%bind () =
           match borrow with
           | `Event borrow -> goal_runtime_event_basis t borrow scope
           | `Job job ->
             let%bind current = job_scope_current t job in
             if
               Option.exists (goal_runtime_job t current) ~f:(phys_equal scope)
               && job.active
               && (not job.cancel_requested)
               && Atomic.get job.authority_live
             then Ok ()
             else Error (error Conflict "Goal resource Job execution ended")
         in
         match execution with
         | None -> Ok ()
         | Some execution ->
           if
             List.mem t.invocation_executions execution ~equal:phys_equal
             && execution.accepts_children
             && Atomic.get execution.authority_live
             && List.exists
                  t.state.invocations
                  ~f:(Agent_protocol.Invocation.equal execution.dispatched)
           then Ok ()
           else Error (error Conflict "Goal resource Invocation execution ended")
       in
       let%bind () = check_runtime_construction_effect construction in
       let%map () = basis () in
       { Held_authored_resource.domain = (Stdlib.Domain.self () :> int); basis })
;;

(* An acknowledged Job borrows installed resources without acquiring fresh
   Goal execution permission. Authorization runs outside the mailbox below; this
   retained token's basis is pure and suitable for Owner lease publication. *)
let job_runtime_resource_internal t (owner : Job_runtime_owner.t) worker inference manager
  =
  let open Result.Let_syntax in
  let%bind () = check_job_runtime_owner_internal t owner in
  let%bind () =
    match owner.attribution with
    | Goal -> Ok ()
    | Ordinary ->
      Error (error Invalid_request "ordinary Job has no Goal resource borrower")
  in
  let%bind job = job_scope_current t owner.scope in
  let%bind parent = Goal_work_attribution.Retained_parent.of_job t.state job in
  let%bind parent =
    Result.of_option parent ~error:(error Conflict "Goal Job has no retained Run work")
  in
  let run = parent.run in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "Goal Job Run index is absent")
  in
  let%bind link =
    Result.of_option
      (Run_state.goal_link index run.id)
      ~error:(error Conflict "Goal Job immutable association is absent")
  in
  let%bind goal =
    Option.bind t.state.goal_catalog ~f:(fun catalog ->
      Goal_catalog.find catalog (Run_goal_link.goal_id link))
    |> Result.of_option ~error:(error Conflict "Goal Job Goal is absent")
  in
  let%bind policy = Goal_activation_policy.create ~goal ~link in
  let%bind binding =
    Result.of_option
      (Run_authorities.find t.run_authorities run.id)
      ~error:(error Permission_denied "Goal Job lost its live Run authority")
  in
  let scope = Run_authorities.scope binding in
  let%bind _ =
    Result.of_option
      (Run_admission.Scope.original_actor scope)
      ~error:(error Permission_denied "Goal Job original authentication is unavailable")
  in
  let basis () =
    let%bind current = job_scope_current t owner.scope in
    let%bind () =
      if
        Int.equal owner.domain (Stdlib.Domain.self () :> int)
        && phys_equal owner.issuing_actor t.inference_owner_identity
        && runtime_admission_open t
        && (not t.stopped)
        && Option.is_none (Eio.Promise.peek t.finished)
        && owner.scope.active
        && (not owner.scope.cancel_requested)
        && Atomic.get owner.scope.authority_live
        && (match current.status with
            | Running | Waiting_permission _ -> true
            | Queued
            | Waiting_completion _
            | Succeeded
            | Failed _
            | Cancelled
            | Interrupted _ -> false)
        && Option.exists t.operation_worker ~f:(phys_equal worker)
        && Option.exists t.inference_execution ~f:(phys_equal inference)
        && Option.equal phys_equal t.moderator_manager manager
        && Run_authorities.is_current t.run_authorities binding ~run_id:run.id
      then Ok ()
      else Error (error Conflict "Goal Job resource borrower was retired or displaced")
    in
    let%bind current_index =
      Result.of_option
        t.state.run_state
        ~error:(error Conflict "Goal Job Run index is absent")
    in
    let%bind current_run =
      Result.of_option
        (Run_state.find current_index run.id)
        ~error:(error Conflict "Goal Job original Run is absent")
    in
    let%bind installed =
      Run_source_installation.captured
        (Run_state.installation current_index)
        ~generation:t.state.identity.generation
    in
    let%bind () =
      if
        Option.exists
          (Run_state.goal_link current_index run.id)
          ~f:(Run_goal_link.equal link)
        && Agent_protocol.Run_source.equal installed run.source
        && Agent_protocol.Run_source.equal current_run.source run.source
        && List.mem
             current_run.owned_work
             parent.work
             ~equal:Agent_protocol.Run_work.equal
        && (not
              (List.mem
                 current_run.relinquished_work
                 parent.work
                 ~equal:Agent_protocol.Run_work.equal))
        && (not
              (List.exists current_run.terminal_work ~f:(fun terminal ->
                 Agent_protocol.Run_work.equal terminal.work parent.work)))
        &&
        match current_run.lifecycle with
        | Admitted | Active | Waiting _ -> true
        | Terminal _ -> false
      then Ok ()
      else Error (error Conflict "Goal Job original retained work or source changed")
    in
    let%bind () =
      Goal_activation_policy.check_association
        policy
        ~state:t.state
        ~run:current_run
        ~admission:(Agent_protocol.Goal_episode.admission (Run_goal_link.episode link))
    in
    Goal_activation_policy.check_admitted_policy policy ~state:t.state
  in
  let%map () = basis () in
  { Held_authored_resource.domain = (Stdlib.Domain.self () :> int); basis }, scope
;;

let end_runtime_construction_internal t construction =
  match construction with
  | Runtime_construction.Initial continuation ->
    end_held_activation_internal t continuation.target
  | Delegated_load load ->
    let open Result.Let_syntax in
    let%bind () =
      if
        Preparation_owner.belongs_to
          (Runtime_construction.preparation_owner construction)
          ~owner:t.run_preparation_owner
      then Ok ()
      else Error (error Conflict "delegated load cleanup belongs to another Actor")
    in
    let constructor =
      Option.filter t.initialization_scope ~f:(fun scope ->
        match Initialization_scope.construction scope with
        | Some (Delegated_load actual) -> phys_equal actual load
        | Some (Initial _ | Existing_goal _) | None -> false)
    in
    let jobs =
      Option.value_map constructor ~default:[] ~f:(fun scope ->
        scope.Initialization_scope.jobs)
    in
    Runtime_construction.close construction;
    let%bind () =
      Option.value_map constructor ~default:(Ok ()) ~f:(end_initialization t)
    in
    List.fold_result jobs ~init:() ~f:(fun () id ->
      let%map _ = cancel_job_internal t id in
      ())
  | Existing_goal continuation ->
    let open Result.Let_syntax in
    let preparation = continuation.Goal_continuation.binding.preparation in
    let%bind () =
      if
        Run_preparation.Custody.belongs_to
          (Goal_continuation.custody preparation)
          ~owner:t.run_preparation_owner
      then Ok ()
      else Error (error Conflict "Goal construction cleanup belongs to another Actor")
    in
    (match preparation.runtime_phase with
     | Handed_off _ -> Ok ()
     | _ when Option.is_some preparation.control ->
       let constructor =
         Option.filter t.initialization_scope ~f:(fun scope ->
           match Initialization_scope.construction scope with
           | Some (Existing_goal actual) -> phys_equal actual continuation
           | Some (Initial _ | Delegated_load _) | None -> false)
       in
       Runtime_construction.close construction;
       Option.value_map constructor ~default:(Ok ()) ~f:(end_initialization t)
     | _ ->
       let scope =
         match preparation.runtime_phase with
         | Installed scope | Callback_completed scope | Retired scope -> Some scope
         | _ -> None
       in
       let constructor =
         Option.filter t.initialization_scope ~f:(fun scope ->
           match Initialization_scope.construction scope with
           | Some (Existing_goal current) -> phys_equal current continuation
           | Some (Initial _ | Delegated_load _) | None -> false)
       in
       let jobs =
         Option.value_map constructor ~default:[] ~f:(fun scope ->
           scope.Initialization_scope.jobs)
         @ Option.value_map scope ~default:[] ~f:(fun scope ->
           List.map scope.Goal_continuation.jobs ~f:(fun job -> job.Agent_protocol.Job.id))
       in
       Runtime_construction.close construction;
       let%bind () =
         Option.value_map constructor ~default:(Ok ()) ~f:(end_initialization t)
       in
       (* Retire only acknowledged new constructor descendants, never the old Run,
         its passive wake, prior work or account. Their ordinary factual result
         path owns any actual Run work/permission settlement. *)
       List.fold_result
         (List.dedup_and_sort jobs ~compare:Agent_protocol.Id.Job.compare)
         ~init:()
         ~f:(fun () id ->
           let%bind _ = cancel_job_internal t id in
           Ok ()))
;;

let acquire_recurrence_activation_internal t ~actor ~authorize ~observation =
  let open Result.Let_syntax in
  let%bind custody =
    Activation_custody.create
      ~owner:t.recurrence_activation_owner
      ~state:t.state
      ~actor
      ~authorize
      ~origin:observation.Recurrence_run_observation.origin
  in
  let%bind _checked = check_recurrence_activation_internal t custody observation in
  (* One live cell per actual retained current execution; no independent quota. *)
  List.iter t.recurrence_activations ~f:(fun old ->
    if Activation_custody.same_occurrence old custody then Activation_custody.close old);
  t.recurrence_activations
  <- custody :: List.filter t.recurrence_activations ~f:Activation_custody.is_live;
  Ok custody
;;

let observe_recurrence_child t reservation =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind controller = require_recurrence_controller t in
  let%bind reference =
    Result.of_option
      t.state.spec.delegation
      ~error:(error Invalid_state "captured child has no delegation reference")
  in
  let%bind record = Recurrence_controller.resolve_delegation controller reference in
  let%bind () =
    match record.stage, record.revocation with
    | (Child_installed | Linked), None -> Ok ()
    | (Reserved | Artifact_installed), None | _, Some _ ->
      Error (error Conflict "captured child has no current installed delegation")
  in
  let%bind origin = Recurrence_child_origin.of_record record in
  let%bind () =
    if
      Recurrence_child_reservation.equal
        reservation
        (Recurrence_child_origin.reservation origin)
    then Ok ()
    else Error (error Conflict "captured child belongs to another occurrence")
  in
  let%bind () = Recurrence_child_origin.validate_initial_state origin t.state in
  let%bind current = Recurrence_controller.observe controller t.state in
  let basis_revision = t.state.counters.revision in
  let check_current () =
    let%bind () = require_runtime_admission t in
    let%bind () =
      if
        Option.is_none (Eio.Promise.peek t.finished)
        && (not t.stopped)
        && Recurrence_controller.is_current current
        && Recurrence_controller.automatic current
        && Int64.equal basis_revision t.state.counters.revision
      then Ok ()
      else Error (error Conflict "captured child observation is no longer current")
    in
    Recurrence_child_origin.validate_initial_state origin t.state
  in
  let%bind () = check_current () in
  let%map child_association =
    Recurrence_child_association.create ~reservation ~reference
  in
  let proof : Recurrence_child_link.t =
    { association = child_association; controller; check_current }
  in
  proof
;;

(* Nonyielding owner-epoch retirement, shared by orderly Shutdown and exceptional
   owner exit. This does not persist, invoke callbacks, cancel/join work or claim
   rollback of already committed effects. *)
let retire_execution_custody t =
  close_recurrence_activations t;
  Legacy_queue_custody.retire t.legacy_queue_custody;
  t.legacy_queue_custody <- Legacy_queue_custody.empty;
  Legacy_schedule_custody.retire t.legacy_schedule_custody;
  t.legacy_schedule_custody <- Legacy_schedule_custody.empty;
  Option.iter t.legacy_callback_scope ~f:(fun scope ->
    match scope.Callback_scope.custody with
    | Unavailable -> ()
    | Admitted admission -> retire_agent_admission admission);
  t.legacy_callback_scope <- None;
  t.moderator_manager <- None;
  retire_instruction_continuations t;
  Option.iter t.operation_agent_custody ~f:Operation_owner.retire;
  List.iter t.pending_agent_custody ~f:(fun (_, custody) -> retire_agent_custody custody);
  Job_custody.retire t.job_agent_custody;
  Option.iter t.initialization_scope ~f:(fun scope ->
    retire_agent_admission scope.agent_admission);
  List.iter t.invocation_executions ~f:(fun execution ->
    Atomic.set execution.authority_live false);
  List.iter t.job_scopes ~f:(fun scope -> Atomic.set scope.authority_live false);
  Option.iter t.moderator_borrow ~f:(fun borrow ->
    Atomic.set borrow.authority_live false;
    Option.iter borrow.observation ~f:Observation_continuation.retire);
  Option.iter t.queued_event_borrow ~f:(fun borrow ->
    Option.iter
      (Queued_agent_admission.admission borrow.agent_admission)
      ~f:retire_agent_admission;
    borrow.callback_active <- false;
    Atomic.set borrow.authority_live false);
  close_run_preparation t;
  t.initialization_scope <- None
;;

(* Negative provenance only. These existing public ingress ports can return
   fresh execution/resource/input capabilities without carrying a preparation.
   Factual completion, denial, release and source bookkeeping are deliberately
   absent. Every port retains its existing positive authorization unchanged. *)
let exclude_ordinary_deferred_ingress : type a. t -> a request -> unit =
  fun t request ->
  match request with
  | Admit_inference _
  | Allocate_inference _
  | Admit_model_job _
  | Begin_initialization _
  | Begin_run_initialization _
  | Reserve_run_history_block _
  | Checkpoint_run_moderator _
  | Start_run_constructor_model_job _
  | Add_run_constructor_job _
  | Add_run_constructor_schedule _
  | Add_initialization_model_job _
  | Start_initialization_model_job _
  | Claim_initialization_model_job _
  | Capture_initialization_recipe_target _ -> exclude_effect_deferred t Ordinary_execution
  | Held_startup (Begin_held_activation _ | Begin_input _ | Begin_authored _) ->
    exclude_effect_deferred t Activation_consumed
  | Goal_request request ->
    (match request with
     | Initialization_completion _ | Read _ | Apply _ -> ())
  | _ -> ()
;;

let check_native_goal_owner t = function
  | Native_goal_owner.Event borrow -> validate_queued_event_borrow t borrow
  | Moderator borrow -> validate_moderator_borrow t borrow
;;

let native_goal_request
  : type a. t -> a Native_goal_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let open Result.Let_syntax in
  let check owner = check_native_goal_owner t owner in
  match request with
  | Resume_receipt selection -> native_goal_resume_receipt_internal t selection
  | Resume_status (admission, authorize, invocation) ->
    native_goal_resume_status_internal t admission authorize invocation
  | Select_resume -> select_native_goal_resume_internal t
  | Begin_resume selection -> begin_native_goal_resume_preparation_internal t selection
  | Observe_dispatch (selection, outcome) ->
    observe_native_goal_dispatch_internal t selection outcome
  | Stage_create (admission, authorize, request) ->
    stage_native_goal_create t admission authorize request
  | Stage_control (admission, authorize, request) ->
    stage_native_goal_control t admission authorize request
  | Stage_edit (admission, authorize, edit) ->
    stage_native_goal_edit t admission authorize edit
  | Stage_resume (admission, authorize, request) ->
    stage_native_goal_resume t admission authorize request
  | Read (admission, authorize) ->
    let%bind _, actions, current = native_goal_execution t admission Get in
    let%bind state = native_goal_projection t actions in
    let actor = Goal_native_admission.actor admission in
    let%bind _ = Goal_command_admission.read state ~actor ~authorize:(authorize actor) in
    let%bind () = current.check_current () in
    let%map () = Goal_native_admission.check_now admission t.state ~effect_kind:Get in
    state
  | Close_scope owner ->
    Goal_native_actions.close (Native_goal_owner.actions owner);
    Ok ()
  | Install_scope (owner, scope) ->
    let%bind () = check owner in
    Goal_native_actions.install_scope (Native_goal_owner.actions owner) scope
  | Deliverable (owner, receipt) ->
    let%bind () = check owner in
    Goal_native_actions.deliverable (Native_goal_owner.actions owner) receipt
  | Accept (owner, receipt) ->
    let%bind () = check owner in
    Goal_native_actions.accept (Native_goal_owner.actions owner) receipt
  | Prepare (owner, receipts) ->
    let%bind () = check owner in
    Goal_native_actions.prepare (Native_goal_owner.actions owner) receipts
  | Rollback (owner, receipt) ->
    (* Factual rollback may retire an issued loan after callback revocation. It
       never selects a replacement owner or grants fresh permission. *)
    Goal_native_actions.rollback (Native_goal_owner.actions owner) receipt;
    Ok ()
;;

let deliver_native_goal_receipt = function
  | None -> Ok ()
  | Some receipt ->
    Chat_response.Goal_native_scope.emit receipt |> Result.map_error ~f:(error Conflict)
;;

let stage_native_goal_create t ~admission ~authorize ~request =
  Result.bind
    (call t (Native_goal (Stage_create (admission, authorize, request))))
    ~f:deliver_native_goal_receipt
;;

let stage_native_goal_control t ~admission ~authorize ~request =
  Result.bind
    (call t (Native_goal (Stage_control (admission, authorize, request))))
    ~f:deliver_native_goal_receipt
;;

let stage_native_goal_edit t ~admission ~authorize ~edit =
  Result.bind
    (call t (Native_goal (Stage_edit (admission, authorize, edit))))
    ~f:deliver_native_goal_receipt
;;

let stage_native_goal_resume t ~admission ~authorize ~request =
  Result.bind
    (call t (Native_goal (Stage_resume (admission, authorize, request))))
    ~f:deliver_native_goal_receipt
;;

let native_goal_state t ~admission ~authorize =
  call t (Native_goal (Read (admission, authorize)))
;;

let select_native_goal_resume t = call t (Native_goal Select_resume)

let begin_native_goal_resume_preparation t ~selection =
  call t (Native_goal (Begin_resume selection))
;;

let observe_native_goal_dispatch t ~selection ~failure =
  call t (Native_goal (Observe_dispatch (selection, failure)))
;;

let native_goal_resume_receipt t ~selection =
  call t (Native_goal (Resume_receipt selection))
;;

let native_goal_resume_status t ~admission ~authorize ~invocation_id =
  call t (Native_goal (Resume_status (admission, authorize, invocation_id)))
;;

let handle_child_accounting_request
  : type a. t -> a Child_accounting_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  match request with
  | Observe_installation (source_owner, reference) ->
    observe_child_installation_internal t ~source_owner ~reference
  | Register_installation
      (native_callback, source_owner, child, check_parent, max_children, max_encoded_bytes)
    ->
    register_child_installation_internal
      ?native_callback
      t
      ~source_owner
      ~child
      ~check_parent
      ~max_children
      ~max_encoded_bytes
  | Observe_usage (source_owner, actor, authorize, reference) ->
    observe_child_usage_internal t ~source_owner ~actor ~authorize ~reference
  | Import_usage
      (source_owner, actor, authorize, observation, max_children, max_encoded_bytes) ->
    import_child_usage_internal
      t
      ~source_owner
      ~actor
      ~authorize
      ~observation
      ~max_children
      ~max_encoded_bytes
;;

let handle : type a. t -> a request -> (a, Agent_protocol.Error.t) result =
  fun t request ->
  if Option.is_some t.lifecycle_fence && not (lifecycle_request_allowed request)
  then Error (error Conflict "session lifecycle is reserved")
  else (
    exclude_ordinary_deferred_ingress t request;
    match request with
    | Native_goal request -> native_goal_request t request
    | Begin_lifecycle (attachment_id, generation, revision) ->
      begin_lifecycle t attachment_id generation revision
    | Lifecycle_state fence ->
      Result.map (check_lifecycle_fence t fence) ~f:(fun () -> t.state)
    | Retire_lifecycle fence ->
      Result.map (check_lifecycle_fence t fence) ~f:(fun () -> fence.phase <- Retiring)
    | Abort_lifecycle fence ->
      let open Result.Let_syntax in
      let%bind () = check_lifecycle_fence t fence in
      (match fence.phase with
       | Retiring -> Error (error Conflict "retired lifecycle owner cannot reopen")
       | Reserved ->
         t.lifecycle_fence <- None;
         Ok ())
    | Manage_moderator_follow_up (operation_id, observer) ->
      manage_moderator_follow_up t operation_id observer
    | Admit_moderator_turn operation_id -> admit_moderator_turn t operation_id
    | Admit_notification_turn operation_id -> admit_notification_turn t operation_id
    | Claim_delegated_event (id, delegation, snapshot, event) ->
      claim_delegated_event t id delegation snapshot event
    | Claim_job_event (scope, id, snapshot, event) ->
      claim_job_event t scope id snapshot event
    | Claim_job_moderator (scope, invocation) -> claim_job_moderator t scope invocation
    | Claim_ordinary_event (id, operation_id, snapshot, event) ->
      claim_ordinary_event t id operation_id snapshot event
    | Claim_queued_event (id, operation_id, snapshot) ->
      claim_queued_event t id operation_id snapshot
    | Claim_legacy_callback (callback, operation_id) ->
      claim_legacy_callback t callback operation_id
    | Claim_initialization_callback (scope, manager, callback) ->
      claim_initialization_callback t scope manager callback
    | Retire_initialization_resource (scope, manager) ->
      retire_initialization_resource t scope manager
    | Claim_queued_retirement (id, snapshot, reason) ->
      claim_queued_retirement t id snapshot reason
    | Commit_queued_event (borrow, snapshot, requests, decision, notifications) ->
      let open Result.Let_syntax in
      let%bind () = validate_queued_event_borrow t borrow in
      with_staged_transaction t (Moderator_event borrow.receipt.context.id) (fun () ->
        commit_queued_event t borrow snapshot requests decision notifications)
    | Reconcile_run_recovery ->
      let open Result.Let_syntax in
      let%bind delta =
        Goal_catalog_source.recovery_delta t.state ~now:(t.services.now ())
      in
      (match delta with
       | None -> Ok ()
       | Some delta -> transition t ~delta ~payloads:[] |> Result.map ~f:ignore)
    | Run_actions executing -> run_actions_internal t executing
    | Finish_queued_event (borrow, interrupted) ->
      finish_queued_event t borrow interrupted
    | Set_queued_event_cancel (borrow, cancel) ->
      Result.map (queued_event_can_commit t borrow) ~f:(fun () ->
        borrow.cancel <- Some cancel)
    | Commit_invocation_call (operation_id, invocation, entry) ->
      commit_invocation_call t operation_id invocation entry
    | Claim_invocation (operation_id, invocation) ->
      claim_invocation t operation_id invocation
    | Claim_idle_invocation (borrow, invocation) ->
      claim_idle_invocation t borrow invocation
    | Claim_event_invocation (borrow, invocation) ->
      claim_event_invocation t borrow invocation
    | Claim_job_scope (id, generation, attempt, deadline) ->
      claim_job_scope t id generation attempt deadline
    | Claim_job_invocation (scope, invocation) ->
      (match t.moderator_borrow with
       | Some borrow
         when Option.exists borrow.job_scope ~f:(phys_equal scope)
              && Option.exists invocation.context.parent_invocation ~f:(fun parent ->
                Agent_protocol.Id.Invocation.equal parent borrow.invocation.context.id
                || List.exists t.invocation_executions ~f:(fun execution ->
                  invocation_execution_owned_by borrow execution
                  && Agent_protocol.Id.Invocation.equal
                       parent
                       execution.dispatched.context.id)) ->
         claim_idle_invocation t borrow invocation
       | _ -> claim_job_invocation t scope invocation)
    | Finish_job_scope scope -> finish_job_scope t scope
    | Seal_job_scope scope ->
      (match List.mem t.job_scopes scope ~equal:phys_equal with
       | false -> Error (error Conflict "background execution scope has ended")
       | true ->
         scope.active <- false;
         Atomic.set scope.authority_live false;
         scope.unfinished_on_return
         <- job_has_moderator t scope
            || List.exists t.invocation_executions ~f:(job_execution_owned_by scope);
         signal_job_scope scope;
         cancel_job_moderators t scope;
         Ok ())
    | Set_job_scope_cancel (scope, cancel) ->
      let open Result.Let_syntax in
      let%map () = job_scope_can_execute t scope in
      scope.cancel <- Some cancel
    | Finish_invocation (execution, outcome, requests, commit_starts, authoring_reference)
      ->
      let open Result.Let_syntax in
      let%bind () =
        match List.mem t.invocation_executions execution ~equal:phys_equal with
        | true -> Ok ()
        | false -> Error (error Conflict "invocation callback no longer owns its result")
      in
      with_staged_transaction t (Invocation execution.dispatched.context.id) (fun () ->
        match
          finish_invocation t execution outcome requests commit_starts authoring_reference
        with
        | Ok _ as result -> result
        | Error _ as failure ->
          Option.iter execution.native_goal ~f:(fun (entry, _) ->
            Goal_native_actions.Entry.discard_speculative entry);
          failure
        | exception exn ->
          let backtrace = Stdlib.Printexc.get_raw_backtrace () in
          Option.iter execution.native_goal ~f:(fun (entry, _) ->
            Goal_native_actions.Entry.discard_speculative entry);
          Stdlib.Printexc.raise_with_backtrace exn backtrace)
    | Claim_moderator_invocation (operation_id, invocation) ->
      claim_moderator_invocation t operation_id invocation
    | Claim_moderator_observation (operation_id, invocation_id) ->
      claim_moderator_observation t (Some operation_id) invocation_id
    | Claim_next_moderator_observation (operation_id, observer) ->
      claim_next_moderator_observation t (Some operation_id) observer
    | Claim_idle_moderator_observation (observer, tools) ->
      if idle_moderator_eligible t
      then
        Result.map (claim_next_moderator_observation t None observer) ~f:(fun borrow ->
          Option.iter borrow ~f:(fun borrow -> borrow.accepts_children <- tools);
          borrow)
      else Ok None
    | Commit_moderator_invocation (borrow, resolved, snapshot) ->
      let open Result.Let_syntax in
      let%bind () = validate_moderator_borrow t borrow in
      with_staged_transaction t (Invocation borrow.invocation.context.id) (fun () ->
        commit_moderator_invocation t borrow resolved snapshot)
    | Finish_moderator_invocation (borrow, failure) ->
      finish_moderator_invocation t borrow failure
    | Set_idle_moderator_cancel (borrow, cancel) ->
      let open Result.Let_syntax in
      let%bind () = validate_moderator_borrow t borrow in
      (match
         ( borrow.job_scope
         , borrow.operation_id
         , t.state.lifecycle.desired
         , t.state.lifecycle.observed )
       with
       | Some scope, None, _, _ ->
         let%map () = job_scope_can_execute t scope in
         borrow.cancel <- Some cancel
       | None, None, Running, Idle ->
         borrow.cancel <- Some cancel;
         Ok ()
       | _ ->
         Error (error Conflict "idle observation was stopped before callback execution"))
    | Commit_extensions (generation, revision, changes) ->
      commit_extensions_internal t generation revision changes
    | State -> Ok t.state
    | Prepare_ingress_submission
        (source, producer, registration_id, namespace, key, payload) ->
      prepare_ingress_submission_internal
        t
        source
        producer
        registration_id
        namespace
        key
        payload
    | Commit_ingress_submission (proposal, before, snapshot) ->
      commit_ingress_submission_internal t proposal before snapshot
    | Due_schedules -> due_schedules t
    | Read_job id -> Result.map (find_job t id) ~f:(job_with_progress t)
    | Publish_job_progress (id, progress) ->
      publish_job_progress_internal t id progress;
      Ok ()
    | Prepare_background_job (owner, request) -> prepare_background_job t owner request
    | Stage_background_job (job, capacity) -> stage_background_job_internal t job capacity
    | Stage_subscription_mutation (owner, source, previous, next) ->
      stage_subscription_mutation_internal t owner source previous next
    | Create_script_subscription
        (owner, source, kind, lifetime_ms, wake, completion_schema) ->
      create_script_subscription_internal
        t
        owner
        source
        kind
        lifetime_ms
        wake
        completion_schema
    | Select_subscription_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_subscriptions.select
        t.staged_subscriptions
        ~owner
        ~receipts
        ~lookup:(lookup_subscription t)
    | Abort_subscription_mutation (owner, receipt) ->
      let open Result.Let_syntax in
      let%map () = Staged_subscriptions.abort t.staged_subscriptions ~owner ~receipt in
      sync_extension_clock t
    | Finish_script_subscription (owner, source, id, expected_epoch, completion) ->
      finish_script_subscription_internal t owner source id expected_epoch completion
    | Read_script_subscription (owner, source, id) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      let%bind subscription =
        Result.of_option
          (provisional_subscription t owner id)
          ~error:(error Invalid_state "subscription is not retained")
      in
      let%map () = subscription_owned t source subscription in
      subscription
    | Expire_subscriptions -> expire_subscriptions_internal t
    | Create_script_ingress (owner, source, id, epoch, namespace, schema) ->
      create_script_ingress_internal t owner source id epoch namespace schema
    | Revoke_script_ingress (owner, source, id, reason) ->
      revoke_script_ingress_internal t owner source id reason
    | Read_script_ingress (owner, source, id) ->
      read_script_ingress_internal t owner source id
    | Abort_ingress_mutation (owner, receipt) ->
      Staged_ingress.abort t.staged_ingress ~owner ~receipt
    | Select_ingress_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_ingress.select
        t.staged_ingress
        ~owner
        ~receipts
        ~lookup:(lookup_ingress t)
        ~subscription:
          (ingress_subscription_lookup
             t
             (Staged_subscriptions.values t.staged_subscriptions))
    | Create_script_notification
        (owner, source, correlation, completion, wake, disclosure_pins) ->
      create_script_notification_internal
        t
        owner
        source
        correlation
        completion
        wake
        disclosure_pins
    | Read_script_notification (owner, source, id) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      let%bind value =
        Result.of_option
          (provisional_notification t owner id)
          ~error:(error Invalid_state "notification is not retained")
      in
      let%map () = notification_owned t source value in
      value
    | Select_notification_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_notifications.select
        t.staged_notifications
        ~owner
        ~receipts
        ~lookup:(lookup_notification t)
    | Abort_notification_mutation (owner, receipt) ->
      Staged_notifications.abort t.staged_notifications ~owner ~receipt
    | Stage_schedule_mutation (owner, source, previous, next) ->
      stage_schedule_mutation_internal t owner source previous next
    | Create_script_schedule (owner, source, delay_ms, payload, misfire) ->
      create_script_schedule_internal t owner source delay_ms payload misfire
    | Select_schedule_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_schedules.select t.staged_schedules ~owner ~receipts ~lookup:(fun id ->
        List.find t.state.schedules ~f:(fun value ->
          Agent_protocol.Id.Schedule.equal value.id id))
    | Abort_schedule_mutation (owner, receipt) ->
      let open Result.Let_syntax in
      let%map () = Staged_schedules.abort t.staged_schedules ~owner ~receipt in
      sync_extension_clock t
    | Read_script_schedule (owner, source, id) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      let%bind value =
        Result.of_option
          (provisional_schedule t owner id)
          ~error:(error Invalid_state "schedule is not retained")
      in
      let%map () = schedule_owned t source value in
      value
    | Select_background_jobs (owner, ids) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      Staged_jobs.select t.staged_jobs ~owner ~ids
    | Abort_background_job (owner, id) -> Staged_jobs.abort t.staged_jobs ~owner ~id
    | Has_staged_background_job (owner, id) ->
      let open Result.Let_syntax in
      let%map () = background_owner_active t owner in
      Staged_jobs.contains t.staged_jobs ~owner ~id
    | Read_script_job (owner, id) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      let%bind staged = Staged_jobs.find t.staged_jobs ~owner ~id in
      (match staged with
       | Some job -> Ok job
       | None ->
         let%bind job = find_job t id in
         let%map () = validate_job_generation t job t.state.identity.generation in
         job_with_progress t job)
    | Read_script_job_result (owner, expected) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      let%bind job = find_job t expected.id in
      let%bind () = validate_job_generation t job t.state.identity.generation in
      let%bind () =
        match
          Jsonaf.exactly_equal
            (Agent_protocol.Job.to_json job)
            (Agent_protocol.Job.to_json expected)
        with
        | true -> Ok ()
        | false -> Error (error Conflict "job changed before artifact materialization")
      in
      let load_artifact =
        Option.map t.services.job_results ~f:(fun publisher ->
          Agent_store.Job_result_store.Publisher.load publisher)
      in
      let%bind completion = Agent_protocol.Job.terminal_completion ?load_artifact job in
      Result.of_option
        completion
        ~error:(error Invalid_state "job has no terminal completion")
    | Cancel_script_job (owner, id) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      let%bind staged =
        Staged_jobs.cancel t.staged_jobs ~owner ~id ~now:(t.services.now ())
      in
      (match staged with
       | Some _ -> Ok ()
       | None ->
         let%bind job = find_job t id in
         let%bind () = validate_job_generation t job t.state.identity.generation in
         Result.map (cancel_job_internal t id) ~f:ignore)
    | Configuration -> configuration_view t
    | Set_organization_admission admission ->
      t.organization_admission <- Some admission;
      Ok ()
    | Set_configuration_policy policy ->
      t.configuration_policy <- Some policy;
      Ok ()
    | Prepare_configuration_update request -> prepare_configuration_update t request
    | Commit_configuration_update validated -> commit_configuration_update t validated
    | Begin_configuration_capture operation_id ->
      begin_configuration_capture t operation_id
    | Mark_configuration_capture (capture, configuration) ->
      mark_configuration_capture t capture configuration
    | Finish_configuration_capture (capture, success) ->
      finish_configuration_capture t capture success
    | Snapshot -> Ok (current_snapshot t)
    | Observe -> Ok (t.state, current_snapshot t)
    | Set_operation_worker worker ->
      let%bind.Result () =
        Option.value_map worker ~default:(Ok ()) ~f:(fun _ ->
          require_selected_execution t)
      in
      set_operation_worker t worker
    | Set_runtime_worker (original_actor, worker, inference, moderator_manager) ->
      let open Result.Let_syntax in
      let%bind () =
        Option.value_map worker ~default:(Ok ()) ~f:(fun _ ->
          require_selected_execution t)
      in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ ->
          Error (error Permission_denied "runtime installation authentication expired")
      in
      set_runtime_worker t worker inference moderator_manager
    | Check_runtime_admission continuation ->
      let open Result.Let_syntax in
      let%bind () = require_runtime_admission t in
      (match continuation with
       | None -> require_selected_execution t
       | Some continuation -> held_runtime_installation_basis t continuation)
    | Retire_runtime_worker closing -> retire_runtime_worker t ~closing
    | Set_compaction_inference port ->
      t.compaction_inference <- port;
      Ok ()
    | Enable_automatic_turn_budget (original_actor, policy) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ -> Error (error Permission_denied "turn budget authentication expired")
      in
      enable_automatic_turn_budget t policy
    | Enable_run_constructor_turn_budget (preparation, policy) ->
      enable_automatic_turn_budget ~run_preparation:preparation t policy
    | Set_automatic_turn_pauses conditions ->
      (match
         t.state.active_operation, moderator_is_borrowed t, t.idle_moderator_borrowed
       with
       | None, false, false ->
         let open Result.Let_syntax in
         let%bind budget =
           t.state.automatic_turn_budget
           |> Result.of_option
                ~error:(error Invalid_state "automatic-turn policy is not enabled")
         in
         let next = Automatic_turn_budget.with_pauses budget conditions in
         (match Automatic_turn_budget.equal budget next with
          | true -> Ok ()
          | false ->
            transition
              t
              ~delta:
                (Session_delta.Automatic_turn_pauses_changed
                   next.policy.budget.pause_conditions)
              ~payloads:[]
            |> Result.map ~f:ignore)
       | _ ->
         Error
           (error Conflict "pause changes wait for active moderator or foreground work"))
    | Change_moderator (original_actor, moderator) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ ->
          Error (error Permission_denied "moderator checkpoint authentication expired")
      in
      change_moderator t moderator
    | Change_workspace workspace -> change_workspace t workspace
    | Shell_approval_grants -> Ok t.state.shell.approval_grants
    | Replace_shell_approval_grants (run_preparation, approval_grants) ->
      replace_shell_approval_grants ?run_preparation t approval_grants
    | Replace_shell_extension_snapshots (run_preparation, extension_snapshots) ->
      replace_shell_extension_snapshots ?run_preparation t extension_snapshots
    | Shell_manifest_grants -> Ok t.state.shell.manifest_grants
    | Add_shell_manifest_grant (run_preparation, grant) ->
      add_shell_manifest_grant ?run_preparation t grant
    | Reset (attachment_id, expected_revision, options) ->
      reset_internal t attachment_id expected_revision options
    | Upgrade_prompt (attachment_id, expected_revision, target_revision) ->
      upgrade_prompt_internal t attachment_id expected_revision target_revision
    | Commit_administration (attachment_id, expected_revision, kind, state) ->
      commit_administration t attachment_id expected_revision kind state
    | Validate_administration_basis (attachment_id, expected) ->
      validate_administration_basis t attachment_id expected
    | Commit_reconciled_administration (attachment_id, expected, kind, candidate) ->
      commit_reconciled_administration t attachment_id expected kind candidate
    | Begin_initialization (purpose, original_actor, expected) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor ->
          if Operator_authorization.is_current actor
          then Ok ()
          else Error (error Permission_denied "initialization authentication expired")
      in
      begin_initialization ?original_actor ~purpose t expected
    | Borrow_initialization_agent_actor scope ->
      let open Result.Let_syntax in
      let%bind () = validate_initialization_scope t scope in
      let%bind custody = custody_of_admission (Some scope.agent_admission) in
      (match custody with
       | None -> Ok None
       | Some custody -> Result.map (Execution_custody.actor custody) ~f:Option.some)
    | Borrow_operation_agent_actor id ->
      let open Result.Let_syntax in
      let%bind _ = running_operation t id in
      operation_agent_actor t id
    | Borrow_compaction_agent_actor operation ->
      let open Result.Let_syntax in
      let%bind _ = running_compaction t operation in
      operation_agent_actor t operation.id
    | Borrow_invocation_agent_actor (execution, invocation) ->
      invocation_agent_actor t execution invocation
    | Borrow_moderator_agent_actor (borrow, invocation) ->
      let open Result.Let_syntax in
      let%bind () = validate_moderator_borrow t borrow in
      let%bind () =
        if
          Agent_protocol.Invocation.equal borrow.invocation invocation
          && Atomic.get borrow.authority_live
        then Ok ()
        else
          Error
            (error
               Permission_denied
               "agent authority belongs to another or expired moderator")
      in
      let%bind custody = moderator_agent_custody t borrow in
      (match custody with
       | None -> Ok None
       | Some custody ->
         Result.map (Execution_custody.actor custody) ~f:(fun actor ->
           Some
             (Operator_authorization.guarded
                ~principal:(Operator_authorization.principal actor)
                ~is_current:(fun () ->
                  Atomic.get borrow.authority_live
                  && Operator_authorization.is_current actor))))
    | Begin_run_initialization (purpose, preparation, expected) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      begin_initialization
        ~run_preparation:preparation
        ?original_actor:(Run_preparation.original_actor preparation)
        ~purpose
        t
        expected
    | End_initialization scope -> end_initialization t scope
    | Goal_request (Initialization_completion scope) ->
      initialization_goal_completion_internal t scope
    | Complete_initialization (scope, candidate, moderator_manager) ->
      complete_initialization t scope candidate moderator_manager
    | Checkpoint_runtime_construction (scope, moderator, moderator_manager) ->
      checkpoint_runtime_construction t scope moderator moderator_manager
    | Fail_initialization (scope, failure) -> fail_initialization t scope failure
    | Start (original_actor, attachment_id, expected_parent_stop_epoch) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ -> Error (error Permission_denied "start authentication expired")
      in
      with_writer t attachment_id (fun () ->
        let%bind source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
        let%map summary = start_internal ?expected_parent_stop_epoch t in
        (match t.lifecycle_agent_custody with
         | Admitted _ -> ()
         | Unadmitted ->
           t.lifecycle_agent_custody
           <- Admitted
                { generation = t.state.identity.generation
                ; source
                ; pending =
                    Pending
                      (create_agent_admission
                         (Option.map original_actor ~f:create_agent_custody))
                });
        summary)
    | Start_initial_delegated (reference, expected_parent_stop_epoch) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id ->
         (match t.state.pending_initial_start with
          | true -> start_internal ?expected_parent_stop_epoch t
          | false -> Ok (Session_state.summary t.state))
       | _ ->
         Error
           (error Permission_denied "delegation.start: child relationship does not match"))
    | Fail_initial_delegated (reference, failure) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id ->
         (match t.state.pending_initial_start with
          | false -> Ok (Session_state.summary t.state)
          | true ->
            let open Result.Let_syntax in
            let%map _ =
              transition
                t
                ~delta:
                  (Batch
                     [ Initial_start_consumed
                     ; Lifecycle_changed { desired = Stopped; observed = Failed failure }
                     ; Failure_changed (Some failure)
                     ])
                ~payloads:
                  [ Session_state_changed
                      { desired_state = Stopped; observed_state = Failed failure }
                  ]
            in
            Session_state.summary t.state)
       | _ ->
         Error
           (error Permission_denied "delegation.start: child relationship does not match"))
    | Queue_start attachment_id ->
      with_writer t attachment_id (fun () -> queue_start_internal t)
    | Activate_queued_start -> activate_queued_start t
    | Update_organization (principal, request) ->
      with_writer t request.attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind admission =
          Result.of_option
            t.organization_admission
            ~error:(error Invalid_state "organization admission is not configured")
        in
        let%bind plan =
          Session_organization_transition.create
            t.state
            ~expected_metadata_revision:request.expected_metadata_revision
            ~patch:request.patch
        in
        let delta = Session_organization_transition.delta plan in
        let%bind candidate = Session_delta.apply t.state delta in
        let payloads =
          if Session_organization_transition.changed plan
          then
            [ Agent_protocol.Event.Durable.Payload.Session_updated
                (Session_state.summary candidate)
            ]
          else []
        in
        let%bind transition = prepare_transition t ~delta ~payloads in
        let%bind () =
          Eio.Cancel.protect (fun () ->
            let%map () =
              Session_organization_admission.persist
                admission
                ~principal
                ~host_id:request.host_id
                ~additions:(Session_organization_transition.additions plan)
                ~commit:(fun () -> persist_transition t transition)
            in
            install_committed_transition t transition;
            publish_committed_transition t transition)
        in
        Ok (Session_state.summary t.state))
    | Set_recurrence_controller controller ->
      if
        not
          (Agent_protocol.Id.Session.equal
             (Agent_protocol.Session_ref.session_id
                (Recurrence_controller.session controller))
             t.state.identity.session_id)
      then Error (error Invalid_request "recurrence controller belongs to another actor")
      else (
        match t.recurrence_controller with
        | Some _ -> Error (error Conflict "recurrence controller is already installed")
        | None ->
          t.recurrence_controller <- Some controller;
          Ok ())
    | Reserve_recurrence_child (actor, authorize, occurrence, expected_control_revision)
      ->
      let open Result.Let_syntax in
      let%bind () = require_runtime_admission t in
      let%bind controller = require_recurrence_controller t in
      let prepare () =
        Recurrence_creation_admission.prepare
          t.state
          ~controller
          ~actor
          ~authorize
          ~occurrence
          ~expected_control_revision
      in
      let%bind prepared = prepare () in
      let%bind () = check_recurrence_creation_admission t prepared in
      let catalog =
        Option.value t.state.recurrence_catalog ~default:Recurrence_catalog.empty
      in
      let child_session_id, transaction_id =
        match Recurrence_creation_admission.reservation prepared with
        | Some row ->
          ( Recurrence_child_reservation.child_session_id row
          , Recurrence_child_reservation.transaction_id row )
        | None ->
          Agent_protocol.Id.Session.create (), Agent_protocol.Id.Transaction.create ()
      in
      let%bind next, reservation =
        Recurrence_catalog.reserve_child
          catalog
          ~recurrence_id:
            (Recurrence_entry.id (Recurrence_creation_admission.entry prepared))
          ~principal_id:(Operator_authorization.principal actor).id
          ~child_session_id
          ~transaction_id
          ~occurrence
      in
      let%bind () =
        if
          Int64.equal
            (Recurrence_catalog.revision next)
            (Recurrence_catalog.revision catalog)
        then Ok ()
        else (
          let%bind candidate =
            prepare_transition
              t
              ~delta:(Session_delta.Recurrence_catalog_changed next)
              ~payloads:[]
          in
          let%bind () = check_recurrence_creation_admission t prepared in
          let%bind () = persist_transition t candidate in
          install_committed_transition t candidate;
          publish_committed_transition t candidate;
          Ok ())
      in
      let%bind refreshed = prepare () in
      let%bind () = check_recurrence_creation_admission t refreshed in
      let%bind () =
        match Recurrence_creation_admission.reservation refreshed with
        | Some row when Recurrence_child_reservation.equal row reservation -> Ok ()
        | None | Some _ ->
          Error (error Conflict "committed creation reservation changed before permit")
      in
      let permit : Recurrence_creation.t =
        { owner = t.recurrence_creation_owner; actor; authorize; reservation }
      in
      Ok permit
    | Check_recurrence_creation permit -> refresh_recurrence_creation t permit
    | Record_recurrence_execution (actor, authorize, intent, attempt) ->
      record_recurrence_execution_internal t ~actor ~authorize ~intent ~attempt
    | Record_prepared_recurrence_execution (binding, actor, authorize, intent, attempt) ->
      record_recurrence_execution_internal ~binding t ~actor ~authorize ~intent ~attempt
    | Observe_recurrence_run (actor, authorize, intent, attempt) ->
      observe_recurrence_run_internal t ~actor ~authorize ~intent ~attempt
    | Import_recurrence_execution (actor, authorize, automatic_policy, observation) ->
      import_recurrence_execution_internal
        t
        ~actor
        ~authorize
        ~automatic_policy
        ~observation
    | Import_held_recurrence_execution
        (held, actor, authorize, automatic_policy, observation) ->
      import_recurrence_execution_internal
        ~held
        t
        ~actor
        ~authorize
        ~automatic_policy
        ~observation
    | Acquire_recurrence_activation (actor, authorize, observation) ->
      acquire_recurrence_activation_internal t ~actor ~authorize ~observation
    | Check_recurrence_activation (custody, observation) ->
      check_recurrence_activation_internal t custody observation
    | Release_recurrence_activation custody ->
      if Activation_custody.belongs_to custody ~owner:t.recurrence_activation_owner
      then (
        Activation_custody.release_original custody;
        t.recurrence_activations
        <- List.filter t.recurrence_activations ~f:Activation_custody.is_live;
        Ok ())
      else Error (error Conflict "activation custody belongs to another actor")
    | Verify_recurrence_child reservation -> observe_recurrence_child t reservation
    | Link_recurrence_child (permit, child, max_children, max_encoded_bytes) ->
      let open Result.Let_syntax in
      let%bind checked = refresh_recurrence_creation t permit in
      let%bind controller = require_recurrence_controller t in
      let%bind () =
        if
          Recurrence_controller.same_store
            controller
            child.Recurrence_child_link.controller
        then Ok ()
        else Error (error Conflict "recurrence child belongs to another Store")
      in
      let association = child.Recurrence_child_link.association in
      let%bind () =
        Recurrence_child_association.validate
          association
          ~reservation:permit.Recurrence_creation.reservation
      in
      let%bind catalog =
        Result.of_option
          t.state.recurrence_catalog
          ~error:(error Conflict "recurrence parent lost its catalog")
      in
      let%bind next = Recurrence_catalog.link_child catalog association in
      let%bind children =
        Child_accounting.register
          t.state
          ~reference:(Recurrence_child_association.reference association)
          ~max_children
          ~max_encoded_bytes
      in
      let%bind children_changed = child_contributions_changed t.state children in
      let catalog_changed =
        not
          (Int64.equal
             (Recurrence_catalog.revision next)
             (Recurrence_catalog.revision catalog))
      in
      let check () =
        let%bind () = Recurrence_creation.Checked.check_current checked in
        let%bind () = child.check_current () in
        Recurrence_creation.Checked.check_current checked
      in
      let%bind () = check () in
      let%bind () =
        if (not catalog_changed) && not children_changed
        then Ok ()
        else (
          let delta =
            Session_delta.Batch
              ((if catalog_changed
                then [ Session_delta.Recurrence_catalog_changed next ]
                else [])
               @
               if children_changed
               then [ Session_delta.Child_contributions_changed children ]
               else [])
          in
          let%bind transition = prepare_transition t ~delta ~payloads:[] in
          let%bind () = check () in
          let%bind () = persist_transition t transition in
          install_committed_transition t transition;
          publish_committed_transition t transition;
          Ok ())
      in
      Ok association
    | Recurrence_read (Definitions (actor, authorize)) ->
      let open Result.Let_syntax in
      let%bind controller = require_recurrence_controller t in
      Recurrence_command_admission.read t.state ~controller ~actor ~authorize
    | Recurrence_read (Query (actor, authorize, request)) ->
      let open Result.Let_syntax in
      let%bind () = Recurrence_command_admission.check_read actor ~authorize t.state in
      let%bind controller = require_recurrence_controller t in
      let%bind planning =
        Recurrence_runtime.status t.recurrence_runtime ~state:t.state ~controller
      in
      Recurrence_query.read t.state ~controller ~actor ~authorize ~planning ~request
    | Recurrence_read (Planning (actor, authorize)) ->
      let open Result.Let_syntax in
      let%bind () = Recurrence_command_admission.check_read actor ~authorize t.state in
      let%bind controller = require_recurrence_controller t in
      let%bind planning =
        Recurrence_runtime.status t.recurrence_runtime ~state:t.state ~controller
      in
      (* Status observation may yield. The existing metadata reader repeats the
         original read policy and genuine Current checks before disclosure. *)
      let%map entries =
        Recurrence_command_admission.read t.state ~controller ~actor ~authorize
      in
      Recurrence_planning_read.{ entries; planning }
    | Set_recurrence_planning_host host ->
      let open Result.Let_syntax in
      let%bind (_ : Recurrence_controller.t) = require_recurrence_controller t in
      Recurrence_runtime.set_host t.recurrence_runtime host
    | Recurrence_due_ids ->
      if runtime_admission_open t then Ok (Recurrence_runtime.ids t.state) else Ok []
    | Begin_recurrence_due recurrence_id ->
      let open Result.Let_syntax in
      if not (runtime_admission_open t)
      then Error (error Conflict "recurrence runtime admission is closed")
      else (
        let%bind controller = require_recurrence_controller t in
        let%bind () = reconcile_recurrences_internal t in
        let%bind snapshot =
          Recurrence_runtime.snapshot
            t.recurrence_runtime
            ~wall:(t.services.now ())
            ~monotonic:(t.services.monotonic_now ())
        in
        Recurrence_runtime.begin_due
          t.recurrence_runtime
          ~state:t.state
          ~controller
          ~recurrence_id
          ~snapshot)
    | Finish_recurrence_due prepared ->
      let open Result.Let_syntax in
      if not (runtime_admission_open t)
      then Error (error Conflict "recurrence runtime admission is closed")
      else (
        let%bind controller = require_recurrence_controller t in
        let%bind validation =
          Recurrence_runtime.validate
            t.recurrence_runtime
            prepared
            ~state:t.state
            ~controller
        in
        let%bind candidate =
          match Recurrence_runtime.delta validation with
          | None -> Ok None
          | Some delta ->
            prepare_transition t ~delta ~payloads:[] |> Result.map ~f:Option.some
        in
        let%bind () =
          Recurrence_runtime.check_current t.recurrence_runtime validation ~state:t.state
        in
        let%bind () =
          if runtime_admission_open t
          then Ok ()
          else Error (error Conflict "recurrence runtime admission closed before commit")
        in
        match candidate with
        | None ->
          Recurrence_runtime.install_phase t.recurrence_runtime validation ~state:t.state;
          Ok ()
        | Some candidate ->
          let%bind () = persist_transition t candidate in
          install_committed_transition t candidate;
          Recurrence_runtime.install_phase t.recurrence_runtime validation ~state:t.state;
          publish_committed_transition t candidate;
          Ok ())
    | Release_recurrence_due preparation ->
      Recurrence_runtime.release t.recurrence_runtime preparation;
      Ok ()
    | Apply_recurrence_command (actor, authorize, request) ->
      let open Result.Let_syntax in
      let%bind () = Recurrence_command_admission.check_write actor ~authorize t.state in
      let%bind controller = require_recurrence_controller t in
      (* Reconciliation is an independently durable safety change. If it changes
         CAS, the original command must be retried with fresh expectations. *)
      let%bind () =
        if Recurrence_command.Mutation.needs_source request.mutation
        then reconcile_recurrences_internal t
        else Ok ()
      in
      let%bind prepared =
        Recurrence_command_admission.prepare
          t.state
          ~controller
          ~actor
          ~authorize
          ~request
          ~now:(t.services.now ())
      in
      let%bind () = Recurrence_command_admission.check_write actor ~authorize t.state in
      let%bind () = Recurrence_command_admission.check_current prepared in
      let%map () =
        match prepared.delta with
        | None -> Ok ()
        | Some delta ->
          let%bind candidate = prepare_transition t ~delta ~payloads:[] in
          let previous = t.state in
          let%bind adoption =
            if Recurrence_runtime.needs_adoption ~previous ~current:candidate.state
            then
              Recurrence_runtime.snapshot
                t.recurrence_runtime
                ~wall:(t.services.now ())
                ~monotonic:(t.services.monotonic_now ())
              |> Result.map ~f:Option.some
            else Ok None
          in
          let%bind () =
            Recurrence_command_admission.check_write actor ~authorize t.state
          in
          let%bind () = Recurrence_command_admission.check_current prepared in
          let%bind () = persist_transition t candidate in
          install_committed_transition t candidate;
          Option.iter adoption ~f:(fun snapshot ->
            Recurrence_runtime.adopt_control
              t.recurrence_runtime
              ~previous
              ~current:t.state
              ~snapshot);
          publish_committed_transition t candidate;
          Ok ()
      in
      prepared.receipt
    | Goal_request (Read (actor, authorize)) ->
      Goal_command_admission.read t.state ~actor ~authorize
    | Apply_instruction_command (admission, source, request) ->
      let open Result.Let_syntax in
      let%bind decision =
        Instruction_command_admission.prepare
          t.state
          ~admission
          ~source
          ~request
          ~now:(t.services.now ())
      in
      (match decision with
       | Retained receipt -> Ok receipt
       | Prepared { selection; receipt } ->
         let%bind candidate =
           prepare_transition
             t
             ~delta:(Instruction_selection_changed selection)
             ~payloads:[]
         in
         let%bind () =
           Instruction_command_admission.check_now t.state ~admission ~source ~request
         in
         let%map () = install t candidate in
         receipt)
    | Goal_request (Apply (actor, authorize, session, request)) ->
      let open Result.Let_syntax in
      let%bind prepared =
        Goal_command_admission.prepare
          t.state
          ~actor
          ~authorize
          ~session
          ~request
          ~now:(t.services.now ())
      in
      let%map () =
        match prepared.delta with
        | None -> Ok ()
        | Some delta ->
          let%bind delta =
            match request.Goal_command.mutation with
            | Hold (goal_id, _) ->
              Goal_control_transition.prepare_hold t.state ~goal_id ~delta
            | Abandon (goal_id, _) ->
              Goal_control_transition.prepare_abandon t.state ~goal_id ~delta
            | Create _
            | Revise_objective _
            | Record_progress _
            | Change_budget _
            | Adopt_source _ -> Ok delta
          in
          let%bind transition = prepare_transition t ~delta ~payloads:[] in
          let%bind () = Goal_command_admission.check_write actor ~authorize t.state in
          let check_before_commit =
            match request.Goal_command.mutation with
            | Hold (_, _) ->
              Some (fun () -> Goal_command_admission.check_write actor ~authorize t.state)
            | Create _
            | Revise_objective _
            | Record_progress _
            | Change_budget _
            | Adopt_source _
            | Abandon _ -> None
          in
          let explicit_goal_holds =
            match request.Goal_command.mutation with
            | Hold (id, _) -> [ id ]
            | Create _
            | Revise_objective _
            | Record_progress _
            | Change_budget _
            | Adopt_source _
            | Abandon _ -> []
          in
          install ?check_before_commit ~explicit_goal_holds t transition
      in
      prepared.receipt
    | Update_metadata (attachment_id, expected_metadata_revision, patch) ->
      with_writer t attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind delta =
          Session_metadata_transition.apply t.state ~expected_metadata_revision ~patch
        in
        match delta with
        | None -> transition t ~delta:(Session_delta.Batch []) ~payloads:[]
        | Some delta ->
          let%bind candidate = Session_delta.apply t.state delta in
          transition
            t
            ~delta
            ~payloads:
              [ Agent_protocol.Event.Durable.Payload.Session_updated
                  (Session_state.summary candidate)
              ])
    | Stop (attachment_id, mode) ->
      with_writer t attachment_id (fun () -> stop_internal t mode)
    | Stop_delegated (reference, mode) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id -> stop_internal t mode
       | _ ->
         Error
           (error Permission_denied "delegation.stop: child relationship does not match"))
    | Stop_managed (reference, key, mode, generation, max_receipts) ->
      stop_managed_internal t reference key mode generation max_receipts
    | Append_history (attachment_id, entries) ->
      with_writer t attachment_id (fun () -> append_history t entries)
    | Stop_delegated_at_epoch (reference, epoch, force) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id ->
         (match t.state.parent_stop_epoch with
          | Some previous when (not force) && Int64.(epoch <= previous) ->
            Ok (Session_state.summary t.state)
          | _ -> stop_internal ~parent_stop_epoch:epoch t Cancel)
       | _ ->
         Error
           (error Permission_denied "delegation.stop: child relationship does not match"))
    | Defer_history (attachment_id, entries) ->
      with_writer t attachment_id (fun () -> defer_history t entries)
    | Submit_message (original_actor, attachment_id, submitting_principal, timing, entry)
      ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor ->
          let principal = Operator_authorization.principal actor in
          if
            Operator_authorization.is_current actor
            && Agent_protocol.Principal.has_scope principal Send_messages
            && Agent_protocol.Id.Principal.equal principal.id submitting_principal
          then Ok ()
          else
            Error
              (error
                 Permission_denied
                 "message authentication expired or differs from submitter")
      in
      submit_message ?original_actor t attachment_id submitting_principal timing entry
    | Control_pending (principal, project, request, replacement) ->
      control_pending_internal t principal project request replacement
    | Capture_run_constructor_model_source
        (preparation, job_id, generation, target, limits) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      capture_model_job_source
        ~run_preparation:preparation
        t
        job_id
        generation
        target
        limits
    | Capture_run_constructor_recipe_target
        (preparation, job_id, generation, attempt, target, limits) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      capture_recipe_target
        ~run_preparation:preparation
        t
        job_id
        generation
        attempt
        target
        limits
    | Start_run_constructor_model_job (preparation, job) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      let%bind job = add_constructor_job t (Run_constructor_job preparation) job in
      let%bind claimed = claim_job ~run_preparation:preparation t job.id job.generation in
      Result.of_option
        claimed
        ~error:(error Conflict "constructor model call could not claim its durable job")
    | Complete_run_constructor_model_job
        (preparation, job_id, generation, attempt, outcome) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      complete_job ~run_preparation:preparation t job_id generation attempt outcome
    | Interrupt_run_constructor_job (preparation, job_id, generation, attempt, reason) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      interrupt_job ~run_preparation:preparation t job_id generation attempt reason
    | Add_run_constructor_job (preparation, job) ->
      add_constructor_job t (Run_constructor_job preparation) job
    | Add_run_constructor_schedule (preparation, schedule) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      add_schedule ~run_preparation:preparation t schedule
    | Cancel_run_constructor_schedule (preparation, id) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      cancel_schedule_internal ~run_preparation:preparation t id
    | Reserve_run_history_block (preparation, count) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      reserve_history_block ~run_preparation:preparation t count
    | Checkpoint_run_moderator (preparation, moderator, moderator_manager) ->
      checkpoint_run_moderator t preparation moderator moderator_manager
    | Admit_prepared_run (preparation, scope, session, entry) ->
      if not (Run_preparation.belongs_to preparation ~owner:t.run_preparation_owner)
      then
        Ok
          (Run_admission_outcome.Rejected
             (error Conflict "run preparation belongs to another actor"))
      else
        Exn.protect
          ~finally:(fun () ->
            Run_preparation.close preparation;
            match t.run_preparation with
            | Some (Initial active) when phys_equal active preparation ->
              t.run_preparation <- None
            | Some _ | None -> ())
          ~f:(fun () ->
            let attempted = ref false in
            let result =
              let open Result.Let_syntax in
              let%bind () = check_run_preparation t preparation in
              admit_run
                ~preparation
                ~commit_attempted:attempted
                t
                scope
                (Run_preparation.request preparation)
                session
                (Run_preparation.request_sha256 preparation)
                entry
            in
            match result with
            | Ok receipt -> Ok (Run_admission_outcome.Admitted receipt)
            | Error failure ->
              let retained =
                ordinary_run_receipt
                  t
                  ~principal_id:(Run_preparation.principal_id preparation)
                  ~key:(Run_preparation.request preparation).key
                  ~request_sha256:(Run_preparation.request_sha256 preparation)
              in
              (match retained with
               | Ok (Some ({ kind = Admission; _ } as receipt)) ->
                 Ok (Run_admission_outcome.Admitted receipt)
               | Ok (Some { kind = Action | Terminal; _ }) | Ok None | Error _ ->
                 Ok
                   (if !attempted
                    then Run_admission_outcome.Uncertain failure
                    else Run_admission_outcome.Rejected failure)))
    | Begin_run_preparation
        (original_actor, authorize, principal_id, request, request_sha256) ->
      begin_run_preparation_internal
        ?original_actor
        t
        ~authorize
        ~principal_id
        ~request:(Run_admission_request.of_writer request)
        ~request_sha256
    | Begin_headless_run_preparation (actor, authorize, request) ->
      let open Result.Let_syntax in
      let authorize = Run_command_authorization.check actor ~authorize in
      let principal_id = (Operator_authorization.principal actor).id in
      let request = Run_admission_request.of_headless request in
      let%bind request_sha256 = Run_admission_request.request_sha256 request in
      begin_run_preparation_internal
        ~original_actor:actor
        t
        ~authorize
        ~principal_id
        ~request
        ~request_sha256
    | Bind_run_source (preparation, source) ->
      bind_run_source_internal t ~preparation ~source
    | Held_startup request ->
      (match request with
       | Goal_continuation request ->
         (match request with
          | Receipt (actor, authorize, session, request) ->
            goal_resume_receipt_internal t ~actor ~authorize ~session ~request
          | Begin (actor, authorize, session, request) ->
            begin_goal_resume_preparation_internal t ~actor ~authorize ~session ~request
          | Bind (preparation, source) ->
            bind_goal_continuation_source_internal t ~preparation ~source
          | Admit binding -> admit_goal_resume_internal t binding
          | Close preparation -> end_goal_continuation_preparation_internal t preparation
          | Select_execution_wake request -> select_goal_runtime_wake_internal t request
          | Reconcile_wake_authority request ->
            reconcile_goal_wake_authority_internal t request
          | Begin_wake wake -> begin_goal_wake_preparation_internal t wake
          | Begin_job owner -> begin_goal_job_runtime_preparation_internal t owner
          | Bind_execution (preparation, source) ->
            bind_goal_continuation_source_internal t ~preparation ~source
          | Prepare_execution binding -> prepare_goal_execution_runtime_internal t binding
          | Close_execution preparation ->
            end_goal_continuation_preparation_internal t preparation
          | Check_job_owner owner -> check_job_runtime_owner_internal t owner
          | Acknowledge_job_resource execution ->
            acknowledge_goal_job_runtime_internal t execution
          | Job_resource (owner, worker, inference, manager) ->
            job_runtime_resource_internal t owner worker inference manager
          | Claim_wake_event (execution, id, snapshot) ->
            claim_queued_event ~goal_execution:execution t id None snapshot
          | Enqueue_wake_job (execution, delivery, before, after) ->
            enqueue_goal_wake_job_internal t execution delivery before after
          | Claim_wake_schedule (execution, schedule) ->
            claim_goal_wake_schedule_internal t execution schedule
          | Complete_wake_schedule (execution, schedule, before, manager, after) ->
            complete_goal_wake_schedule_internal t execution schedule before manager after
          | Deliver_wake_job (execution, job, before, after) ->
            deliver_goal_wake_job_internal t execution job before after
          | Deliver_wake_notifications (execution, proposal) ->
            deliver_idle_notifications_internal ~goal_execution:execution t proposal
          | Finish_wake execution -> finish_goal_wake_runtime_internal t execution)
       | Effect_deferred request -> effect_deferred_request t request
       | Input_graph request -> input_graph_request t request
       | Begin_authored (continuation, startup, snapshot) ->
         begin_held_authored_internal t continuation startup snapshot
       | Ready_authored scope -> ready_held_authored_internal t scope
       | Claim_authored (scope, id, snapshot, event) ->
         claim_held_authored_event t scope id snapshot event
       | Finish_authored scope -> finish_held_authored_internal t scope
       | Authored_resource (continuation, owner) ->
         held_authored_resource_internal t continuation owner
       | Begin_input continuation -> begin_held_input_internal t continuation
       | Ready_input (scope, input) -> ready_held_input_internal t scope input
       | Submit_input (scope, input) -> submit_held_run_input_internal t scope input
       | Close_input scope -> close_held_input_internal t scope
       | End_held_activation activation -> end_held_activation_internal t activation
       | Enable_turn_budget (continuation, policy) ->
         enable_held_turn_budget_internal t continuation policy
       | Install_runtime (continuation, worker, inference, manager) ->
         install_held_runtime_internal t continuation worker inference manager
       | Goal request ->
         (match request with
          | Receipt (actor, authorize, request, session) ->
            goal_run_receipt_internal t ~actor ~authorize ~request ~session
          | Admit (binding, intent, session) ->
            admit_held_goal_run_internal t ~binding ~intent ~session)
       | Begin_held_activation (binding, held, checked) ->
         begin_held_activation_internal t binding held checked
       | Construction request ->
         (match request with
          | Load request -> delegated_load_request t request
          | Mutate mutation -> runtime_constructor_mutation_request t mutation
          | Check_admission construction ->
            check_runtime_construction_admission_internal t construction
          | Begin_goal (construction, step) ->
            begin_goal_runtime_construction_internal t construction step
          | Begin_initialization (construction, purpose, expected) ->
            (match construction with
             | Initial continuation ->
               begin_held_initialization_internal t continuation purpose expected
             | Existing_goal _ | Delegated_load _ ->
               begin_runtime_initialization_internal t construction purpose expected)
          | Reserve_history (construction, count) ->
            reserve_runtime_history_block_internal t construction count
          | Add_model (scope, job) -> add_initialization_model_job t scope job
          | Model_running (scope, job_id, generation, attempt) ->
            initialization_model_job_is_running t scope job_id generation attempt
          | Enable_budget (construction, policy) ->
            enable_runtime_turn_budget_internal t construction policy
          | Install (construction, worker, inference, manager) ->
            install_runtime_construction_internal t construction worker inference manager
          | Begin_resume (continuation, resume) ->
            begin_goal_resume_callback_internal t continuation resume
          | Claim_resume (scope, id, snapshot, event) ->
            claim_goal_resume_event t scope id snapshot event
          | Finish_resume scope -> finish_goal_resume_callback_internal t scope
          | Continue_goal continuation -> continue_goal_episode_internal t continuation
          | Resource (construction, owner) ->
            runtime_construction_resource_internal t construction owner
          | End construction -> end_runtime_construction_internal t construction))
    | Admit_held_recurrence_run (binding, intent, attempt, session) ->
      admit_held_recurrence_run_internal t ~binding ~intent ~attempt ~session
    | Close_run_preparation preparation ->
      if not (Run_preparation.belongs_to preparation ~owner:t.run_preparation_owner)
      then Error (error Conflict "run preparation belongs to another actor")
      else (
        Run_preparation.close preparation;
        (match t.run_preparation with
         | Some (Initial active) when phys_equal active preparation ->
           close_run_preparation t
         | Some _ | None -> ());
        Ok ())
    | Run_start_receipt (authorize, principal_id, request, request_sha256) ->
      let open Result.Let_syntax in
      let%bind () = authorize t.state in
      let%bind _ = write_attachment t request.attachment_id in
      let%bind () =
        if Agent_protocol.Id.Session.equal request.session_id t.state.identity.session_id
        then Ok ()
        else Error (error Invalid_request "run receipt targets another session")
      in
      let%bind retained =
        ordinary_run_receipt t ~principal_id ~key:request.key ~request_sha256
      in
      (match retained with
       | None -> Ok None
       | Some ({ kind = Admission; _ } as receipt) -> Ok (Some receipt)
       | Some { kind = Action | Terminal; _ } ->
         Error (error Conflict "run start key belongs to another action"))
    | Admit_run (scope, request, session, request_sha256, entry) ->
      admit_run
        t
        scope
        (Run_admission_request.of_writer request)
        session
        request_sha256
        entry
    | Submit_managed_message (reference, key, fingerprint, generation, maximum, entry) ->
      submit_managed_message t reference key fingerprint generation maximum entry
    | Compact (original_actor, attachment_id, expected_revision) ->
      let%bind.Result () = require_selected_execution t in
      compact_internal t original_actor attachment_id expected_revision
    | Delete_history (attachment_id, revision, history_id) ->
      delete_history_internal t attachment_id revision history_id
    | Edit_history request -> edit_history_internal t request
    | Continue_history request -> continue_history_internal t request
    | Adopt_deferred -> adopt_deferred t
    | Reserve_history_block count -> reserve_history_block t count
    | Commit_worker_entry (operation_id, entry) ->
      commit_worker_entry t operation_id entry
    | Prepare_authoring_input (operation_id, materialization, history, effective) ->
      prepare_authoring_input t operation_id materialization history effective
    | Publish_invocation_output (operation_id, invocation_id, entry) ->
      publish_invocation_output t operation_id invocation_id entry
    | Consume_deferred operation_id -> consume_deferred t operation_id
    | Consume_notifications (operation_id, plan) ->
      consume_notifications_internal t operation_id plan
    | Deliver_idle_notifications plan -> deliver_idle_notifications_internal t plan
    | Admit_standalone_delivery plan -> admit_standalone_delivery_internal t plan
    | Retire_obsolete_moderator_delivery (revision, job) ->
      retire_obsolete_moderator_delivery_internal t revision job
    | Deliver_standalone_completion (revision, job, capabilities, policy) ->
      deliver_standalone_completion_internal t revision job capabilities policy
    | Consume_initial_notifications (operation_id, proposal) ->
      consume_notifications_internal
        ~wakes:proposal.wakes
        ~discarded_wakes:proposal.discarded_wakes
        t
        operation_id
        proposal.pending
    | Commit_worker_moderator (operation_id, snapshot) ->
      commit_worker_moderator t operation_id snapshot
    | Has_writer_attachment -> Ok (has_writer_attachment t)
    | Authorize_writer attachment_id -> with_writer t attachment_id (fun () -> Ok ())
    | Invocation_granted (tool_name, identity_digest) ->
      Ok (invocation_granted t ~tool_name ~identity_digest)
    | Worker_ready (operation_id, cancel) -> worker_ready t operation_id cancel
    | Worker_terminal (operation_id, outcome, compaction_custody) ->
      with_runtime_terminal t operation_id (fun () ->
        worker_terminal t operation_id outcome compaction_custody)
    | Compaction_terminal (operation_id, outcome) ->
      with_runtime_terminal t operation_id (fun () ->
        compaction_terminal t operation_id outcome)
    | Cancel_operation (attachment_id, operation_id) ->
      cancel_operation_internal t attachment_id operation_id
    | Open_permission (permission, timeout_seconds, fallback) ->
      open_permission t permission timeout_seconds fallback
    | Respond_permission
        (attachment_id, principal_id, permission_id, generation, choice, reason) ->
      respond_permission_internal
        t
        attachment_id
        principal_id
        permission_id
        generation
        choice
        reason
    | Resolve_permission_system (permission_id, generation, choice, reason) ->
      resolve_permission_system t permission_id generation choice reason
    | Expire_permission (permission_id, generation, fallback) ->
      expire_permission_internal t permission_id generation fallback
    | Revoke_grant (attachment_id, grant_id, reason) ->
      revoke_grant t attachment_id grant_id reason
    | Change_job (attachment_id, job) -> change_job t attachment_id job
    | Capture_inference_target (target, limits) ->
      capture_inference_target t target limits
    | Capture_model_job_source (job_id, generation, target, limits) ->
      capture_model_job_source t job_id generation target limits
    | Capture_recipe_target (job_id, generation, attempt, target, limits) ->
      capture_recipe_target t job_id generation attempt target limits
    | Add_initialization_model_job (scope, job) ->
      add_initialization_model_job t scope job
    | Start_initialization_model_job (scope, job) ->
      start_initialization_model_job t scope job
    | Claim_initialization_model_job (scope, job_id, generation) ->
      claim_initialization_model_job t scope job_id generation
    | Initialization_model_job_is_current (scope, job_id, generation, attempt) ->
      initialization_model_job_is_current t scope job_id generation attempt
    | Capture_initialization_recipe_target
        (scope, job_id, generation, attempt, target, limits) ->
      capture_initialization_recipe_target t scope job_id generation attempt target limits
    | Complete_initialization_model_job (scope, job_id, generation, attempt, outcome) ->
      complete_initialization_model_job t scope job_id generation attempt outcome
    | Add_job job -> add_job t job
    | Claim_job (purpose, job_id, generation) -> claim_job ~purpose t job_id generation
    | Complete_job (job_id, generation, attempt, outcome) ->
      complete_job t job_id generation attempt outcome
    | Complete_background_job (job_id, generation, attempt, outcome) ->
      complete_background_job t job_id generation attempt outcome
    | Defer_background_job (job_id, generation, attempt, dependency) ->
      defer_background_job t job_id generation attempt dependency
    | Refresh_background_job (job_id, generation, attempt) ->
      refresh_background_job t job_id generation attempt
    | Recover_background_results (max_count, max_total_bytes) ->
      recover_background_results t max_count max_total_bytes
    | Enqueue_run_job_delivery (delivery, before, after) ->
      enqueue_run_job_delivery t delivery before after
    | Deliver_job (job_id, generation, expected, expected_job, moderator_snapshot, manager)
      -> deliver_job t job_id generation expected expected_job moderator_snapshot manager
    | Cancel_job_internal job_id -> cancel_job_internal t job_id
    | Cancel_job (attachment_id, job_id, expected_generation, expected_attempt) ->
      with_writer t attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind job = find_job t job_id in
        let%bind () =
          match expected_generation, expected_attempt with
          | None, None -> Ok ()
          | Some generation, Some attempt ->
            if
              Int.equal generation t.state.identity.generation
              && Int.equal generation job.generation
              && Int.equal attempt job.attempt
            then Ok ()
            else Error (error Conflict "job occurrence has changed")
          | Some _, None | None, Some _ ->
            Error (error Invalid_request "job occurrence requires generation and attempt")
        in
        cancel_job_internal t job_id)
    | Interrupt_job (job_id, generation, attempt, reason) ->
      interrupt_job t job_id generation attempt reason
    | Change_schedule (attachment_id, event, schedule) ->
      change_schedule t attachment_id event schedule
    | Add_schedule schedule -> add_schedule t schedule
    | Callback_schedule_after_ms (scope, delay_ms, payload) ->
      callback_schedule_after_ms t scope delay_ms payload
    | Callback_schedule_cancel (scope, schedule_id) ->
      callback_schedule_cancel t scope schedule_id
    | Cancel_schedule (attachment_id, schedule_id, expected_generation) ->
      with_writer t attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind schedule = find_schedule t schedule_id in
        let%bind () =
          match expected_generation with
          | None -> Ok ()
          | Some generation ->
            if
              Int.equal generation t.state.identity.generation
              && Int.equal generation schedule.generation
            then Ok ()
            else Error (error Conflict "schedule occurrence has changed")
        in
        cancel_schedule_internal t schedule_id)
    | Cancel_schedule_internal schedule_id -> cancel_schedule_internal t schedule_id
    | Claim_schedule (schedule_id, generation) -> claim_schedule t schedule_id generation
    | Retry_schedule (schedule_id, generation) -> retry_schedule t schedule_id generation
    | Complete_schedule
        ( schedule_id
        , generation
        , expected
        , expected_schedule
        , moderator_snapshot
        , moderator_manager ) ->
      complete_schedule
        t
        schedule_id
        generation
        expected
        expected_schedule
        moderator_snapshot
        moderator_manager
    | Fail_schedule (schedule_id, generation, failure) ->
      fail_schedule t schedule_id generation failure
    | Skip_schedule (schedule_id, generation) -> skip_schedule t schedule_id generation
    | Claim_idle_moderator -> claim_idle_moderator t
    | Apply_observation_follow_up -> apply_observation_follow_up t
    | Complete_idle_moderator drain -> complete_idle_moderator t drain
    | Fail_idle_moderator failure -> fail_idle_moderator t failure
    | Attach (mode, subscribe, principal_id, reclaim_token) ->
      attach t mode subscribe principal_id reclaim_token
    | Detach attachment_id -> detach t attachment_id
    | Renew_owner (attachment_id, generation) -> renew_owner t attachment_id generation
    | Owner_expired generation -> owner_expired t generation
    | Child_accounting request -> handle_child_accounting_request t request
    | Checkpoint persist -> persist t.state
    | Quiescent_checkpoint inspect ->
      (match
         ( t.state.active_operation
         , t.active_cancel
         , t.invocation_executions
         , t.job_scopes
         , t.moderator_borrow
         , t.queued_event_borrow
         , t.foreground_moderator
         , t.idle_moderator_borrowed
         , Staged_jobs.is_empty t.staged_jobs
           && Staged_subscriptions.is_empty t.staged_subscriptions
           && Staged_ingress.is_empty t.staged_ingress
           && Staged_schedules.is_empty t.staged_schedules
           && Staged_notifications.is_empty t.staged_notifications
         , Active_calls.snapshot t.active_calls )
       with
       | None, None, [], [], None, None, None, false, true, ([], []) ->
         Result.map (inspect t.state) ~f:Option.some
       | _ -> Ok None)
    | Open_inference_owner (preparation, source) ->
      let%bind.Result () =
        match preparation with
        | None -> require_selected_execution t
        | Some preparation ->
          let%bind.Result () = check_run_preparation t preparation in
          require_selected_or_held_execution t (Some preparation)
      in
      open_inference_owner t source
    | Admit_inference
        (run_preparation, owner, relation, operation_id, invocation_id, configuration) ->
      let%bind.Result () = require_selected_or_held_execution t run_preparation in
      admit_inference
        ?run_preparation
        t
        owner
        relation
        operation_id
        invocation_id
        configuration
    | Allocate_inference (execution, owner, relation, configuration) ->
      allocate_inference t execution owner relation configuration
    | Admit_model_job (execution, job) -> admit_model_job t execution job
    | Refresh_inference selected -> refresh_inference t selected
    | Acknowledge_inference (run_preparation, owner, handle, attempt) ->
      acknowledge_inference ?run_preparation t owner handle attempt
    | Observe_inference (run_preparation, handle, incoming) ->
      observe_inference ?run_preparation t handle incoming
    | Observe_owned_inference (run_preparation, owner, incoming) ->
      observe_owned_inference ?run_preparation t owner incoming
    | Complete_inference (run_preparation, owner, handle, completion) ->
      complete_inference ?run_preparation t owner handle completion
    | Release_inference (run_preparation, owner, handle) ->
      release_inference ?run_preparation t owner handle
    | Seal_inference_owner owner -> seal_inference_owner t owner
    | Finish_inference_owner (run_preparation, owner) ->
      finish_inference_owner ?run_preparation t owner
    | Reconcile_inference_recovery -> reconcile_inference_recovery t
    | Shutdown ->
      retire_execution_custody t;
      abort_all_staged_work t;
      Option.iter t.owner_timer_cancel ~f:(fun resolver ->
        Eio.Promise.resolve resolver ());
      t.owner_timer_cancel <- None;
      Option.iter t.active_cancel ~f:(fun cancel -> cancel ());
      List.iter t.job_scopes ~f:cancel_job_scope;
      Option.iter t.queued_event_borrow ~f:(fun borrow ->
        borrow.callback_active <- false;
        Atomic.set borrow.authority_live false;
        borrow.cancel_requested <- true;
        Option.iter borrow.cancel ~f:(fun cancel -> cancel ()));
      Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
        Map.iter !(t.subscribers) ~f:Subscriber.close;
        t.subscribers := Map.Poly.empty);
      Map.iter !(t.permission_waiters) ~f:(fun waiter ->
        Eio.Promise.resolve
          waiter.resolver
          Agent_protocol.Permission.
            { choice = Deny
            ; principal_id = None
            ; resolved_at = t.services.now ()
            ; reason = Some "session actor shut down"
            });
      t.permission_waiters := Map.Poly.empty;
      t.stopped <- true;
      Ok ())
;;

let rec reject_pending mailbox =
  match Mailbox.pop mailbox with
  | None -> ()
  | Some (Pack (_, _, resolver)) ->
    Actor_reply.resolve
      resolver
      (Error
         (Agent_protocol.Error.create
            Server_shutting_down
            ~message:"session actor is shut down"
            ~retryable:true
            ()));
    reject_pending mailbox
;;

let close_owner t =
  t.stopped <- true;
  t.command_audit <- None;
  retire_execution_custody t;
  Mailbox.close t.mailbox
;;

let rec run t =
  match Mailbox.pop t.mailbox with
  | None -> ()
  | Some (Pack (command_audit, request, resolver)) ->
    t.command_audit <- command_audit;
    (match handle t request with
     | result ->
       t.command_audit <- None;
       if t.stopped then Mailbox.close t.mailbox;
       Actor_reply.resolve resolver result;
       if not t.stopped then run t
     | exception exn ->
       let backtrace = Stdlib.Printexc.get_raw_backtrace () in
       Eio.Cancel.protect (fun () ->
         close_owner t;
         Actor_reply.resolve_exception resolver exn backtrace);
       Exn.raise_with_original_backtrace exn backtrace)
;;

let create_internal
      ~runtime_source_owner
      ~ordinary_execution_admission
      ~schedule_permission_timeouts
      ~sw
      ~clock
      ~mailbox_capacity
      ~owner_lease_duration_ms
      ~max_attachments
      ~subscriber_capacity
      ~compaction_env
      ~(initial_state : Session_state.t)
      ~persistence
      ~operation_worker
      ~services
  =
  if max_attachments <= 0 then invalid_arg "max_attachments must be positive";
  if subscriber_capacity <= 0 then invalid_arg "subscriber_capacity must be positive";
  (match Staged_subscriptions.validate_limits services.subscription_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  (match Staged_ingress.validate_limits services.ingress_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  (match Staged_schedules.validate_limits services.schedule_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  (match Staged_notifications.validate_limits services.notification_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  let finished, finish = Eio.Promise.create () in
  let t =
    { sw
    ; sleep = (fun seconds -> Eio.Time.sleep clock seconds)
    ; mailbox = Mailbox.create ~capacity:mailbox_capacity
    ; finished
    ; persistence
    ; services
    ; subscriber_mutex = Eio.Mutex.create ()
    ; active_calls = Active_calls.create ()
    ; subscribers = ref Map.Poly.empty
    ; permission_waiters = ref Map.Poly.empty
    ; organization_admission = None
    ; configuration_policy = None
    ; recurrence_controller = None
    ; recurrence_runtime = Recurrence_runtime.create ~origin:(services.monotonic_now ())
    ; recurrence_creation_owner = ref ()
    ; recurrence_activation_owner = Activation_custody.Owner.create ()
    ; recurrence_activations = []
    ; configuration_update_owner = Configuration_update.Owner.create ()
    ; configuration_capture = Configuration_capture.create ()
    ; operation_worker
    ; compaction_inference = None
    ; inference_execution = None
    ; moderator_manager = None
    ; compaction_env
    ; owner_lease_duration_ms
    ; max_attachments
    ; subscriber_capacity
    ; schedule_permission_timeouts
    ; owner_timer_cancel = None
    ; active_cancel = None
    ; lifecycle_owner = ref ()
    ; lifecycle_fence = None
    ; runtime_retirement = None
    ; idle_moderator_borrowed = false
    ; moderator_borrow = None
    ; queued_event_borrow = None
    ; legacy_callback_scope = None
    ; legacy_queue_custody = Legacy_queue_custody.empty
    ; legacy_schedule_custody = Legacy_schedule_custody.empty
    ; operation_agent_custody = None
    ; lifecycle_agent_custody = Unadmitted
    ; intent_agent_custody = []
    ; pending_agent_custody = []
    ; job_agent_custody = Job_custody.empty
    ; run_authorities = Run_authorities.empty
    ; runtime_source_owner
    ; ordinary_execution_admission
    ; runtime_source_domain = (Stdlib.Domain.self () :> int)
    ; run_preparation_owner = Run_preparation.Owner.create ()
    ; run_preparation = None
    ; effect_deferred = None
    ; run_source_binding = None
    ; held_activation = None
    ; held_input_scope = None
    ; held_authored_start = None
    ; foreground_moderator = None
    ; invocation_executions = []
    ; inference_owner_identity = ref ()
    ; inference_owners = []
    ; initialization_owner = ref ()
    ; initialization_scope = None
    ; job_scopes = []
    ; staged_jobs = Staged_jobs.create ()
    ; staged_subscriptions = Staged_subscriptions.create ()
    ; staged_ingress = Staged_ingress.create ()
    ; staged_schedules = Staged_schedules.create ()
    ; staged_notifications = Staged_notifications.create ()
    ; notification_inputs = None
    ; extension_clock = Extension_clock.create ()
    ; invocation_gate = Chat_response.Execution_gate.create ()
    ; event_sequence = Atomic.make initial_state.counters.event_sequence
    ; state = initial_state
    ; stopped = false
    ; command_audit = None
    }
  in
  sync_extension_clock t;
  (* A persisted actor outlives the tool/script that created it. Its future
     operations acquire their own budgets and delegated authority; inheriting
     this caller's lexical ChatML frame would poison them after creation ends. *)
  Chatml_execution.without_ambient_context (fun () ->
    Eio.Fiber.fork ~sw (fun () ->
      Exn.protect
        ~f:(fun () -> run t)
        ~finally:(fun () ->
          Eio.Cancel.protect (fun () ->
            Exn.protect
              ~f:(fun () ->
                close_owner t;
                reject_pending t.mailbox)
              ~finally:(fun () -> Eio.Promise.resolve finish ())))));
  Option.iter (owner_attachment t) ~f:(fun attachment ->
    Option.iter attachment.owner_lease ~f:(schedule_owner_lease t));
  t
;;

let create_with_owner_lease_duration
      ~schedule_permission_timeouts
      ~sw
      ~clock
      ~mailbox_capacity
      ~owner_lease_duration_ms
      ~max_attachments
      ~subscriber_capacity
      ~compaction_env
      ~initial_state
      ~persistence
      ~operation_worker
      ~services
  =
  create_internal
    ~runtime_source_owner:None
    ~ordinary_execution_admission:(fun () -> Ok ())
    ~schedule_permission_timeouts
    ~sw
    ~clock
    ~mailbox_capacity
    ~owner_lease_duration_ms
    ~max_attachments
    ~subscriber_capacity
    ~compaction_env
    ~initial_state
    ~persistence
    ~operation_worker
    ~services
;;

let create_with_runtime_source_owner
      ~runtime_source_owner
      ~ordinary_execution_admission
      ~schedule_permission_timeouts
      ~sw
      ~clock
      ~mailbox_capacity
      ~owner_lease_duration_ms
      ~max_attachments
      ~subscriber_capacity
      ~compaction_env
      ~initial_state
      ~persistence
      ~operation_worker
      ~services
  =
  create_internal
    ~runtime_source_owner:(Some runtime_source_owner)
    ~ordinary_execution_admission
    ~schedule_permission_timeouts
    ~sw
    ~clock
    ~mailbox_capacity
    ~owner_lease_duration_ms
    ~max_attachments
    ~subscriber_capacity
    ~compaction_env
    ~initial_state
    ~persistence
    ~operation_worker
    ~services
;;

let runtime_source_owner_identity t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then invalid_arg "runtime source identity belongs to another Eio domain";
  t.runtime_source_owner
;;

let create
      ~sw
      ~clock
      ~mailbox_capacity
      ~compaction_env
      ~initial_state
      ~persistence
      ~operation_worker
      ~services
  =
  create_with_owner_lease_duration
    ~schedule_permission_timeouts:true
    ~sw
    ~clock
    ~mailbox_capacity
    ~owner_lease_duration_ms:60_000
    ~max_attachments:1_024
    ~subscriber_capacity:512
    ~compaction_env
    ~initial_state
    ~persistence
    ~operation_worker
    ~services
;;

