let publish_job_progress t ~invocation_id progress =
  match Job_progress_buffer.valid progress with
  | false -> ()
  | true ->
    let _promise, resolver = Eio.Promise.create () in
    ignore
      (Mailbox.try_push
         t.mailbox
         ~priority:Transient
         (Pack (None, Publish_job_progress (invocation_id, progress), resolver))
       : bool)
;;

let claim_job t ~job_id ~generation =
  let%bind.Result () =
    Option.value_map
      (List.find_map t.state.jobs ~f:(fun job ->
         if Agent_protocol.Id.Job.equal job.id job_id
         then
           if
             Int.equal generation job.generation
             && Int.equal generation t.state.identity.generation
             && (held_authored_job_deferred t job
                 || goal_runtime_job_deferred t job
                 || goal_job_suspended t job)
           then None
           else held_authored_job t job
         else None))
      ~default:(Ok ())
      ~f:(refresh_held_authored t)
  in
  let deferred =
    List.exists t.state.jobs ~f:(fun job ->
      Agent_protocol.Id.Job.equal job.id job_id
      && Int.equal generation job.generation
      && Int.equal generation t.state.identity.generation
      && (goal_runtime_job_deferred t job || goal_job_suspended t job))
  in
  let%bind.Result () =
    if deferred then Ok () else refresh_goal_runtime_job t ~job_id ~generation
  in
  call t (Claim_job (Execute, job_id, generation))
;;

