let install_held_runtime
      ?automatic_turn_policy
      ?moderator_manager
      t
      ~continuation
      ~worker
      ~inference
  =
  let open Result.Let_syntax in
  let%bind () = held_runtime_installation_basis t continuation in
  let%bind () = Admitted_activation.Continuation.refresh continuation in
  Eio.Cancel.protect (fun () ->
    let%bind () =
      match automatic_turn_policy with
      | None -> Ok ()
      | Some policy ->
        let%bind () = call t (Held_startup (Enable_turn_budget (continuation, policy))) in
        (* The factual policy ACK can rotate target/controller Store custody.
           Refresh outside the mailbox before physical installation. *)
        Admitted_activation.Continuation.refresh continuation
    in
    call
      t
      (Held_startup (Install_runtime (continuation, worker, inference, moderator_manager))))
;;

let submit_held_run_input t ~scope ~input =
  let open Result.Let_syntax in
  let%bind () =
    if
      Int.equal scope.Held_input_scope.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
    then Ok ()
    else Error (error Conflict "held input belongs to another actor or domain")
  in
  let%bind () =
    match scope.phase with
    | Parsed_ready recorded
      when Runtime_input_preparation.Prepared_input.equal recorded input -> Ok ()
    | Parsing | Parsed_ready _ | Consumed _ | Root_attempt_unconfirmed | Closed ->
      Error
        (error Conflict "held root input has already been submitted or is unavailable")
  in
  let%bind () = Admitted_activation.Continuation.refresh scope.continuation in
  Eio.Cancel.protect (fun () -> call t (Held_startup (Submit_input (scope, input))))
;;

let held_authored_resource t ~continuation ~owner =
  let%bind.Result () = Admitted_activation.Continuation.refresh continuation in
  call t (Held_startup (Authored_resource (continuation, owner)))
;;

let start_held_authored_run t ~continuation ~startup =
  let open Result.Let_syntax in
  let%bind () = Admitted_activation.Continuation.refresh continuation in
  let%bind snapshot =
    match Runtime_builder.Authored_start.manager startup with
    | None -> Ok None
    | Some manager ->
      Chat_response.Moderator_manager.identity_snapshot manager
      |> Result.map_error ~f:(error Invalid_state)
      |> Result.map ~f:Option.some
  in
  let%bind () = Admitted_activation.Continuation.refresh continuation in
  let%bind scope =
    Eio.Cancel.protect (fun () ->
      call t (Held_startup (Begin_authored (continuation, startup, snapshot))))
  in
  let%bind () = refresh_held_authored t scope in
  let%bind () =
    Eio.Cancel.protect (fun () -> call t (Held_startup (Ready_authored scope)))
  in
  let claim ~event ~snapshot callback =
    with_event_tools
      t
      ~claim:(fun () ->
        let%bind snapshot = snapshot () in
        let%map () = refresh_held_authored t scope in
        Some
          (Held_startup
             (Claim_authored
                (scope, Agent_protocol.Id.Moderator_execution.create (), snapshot, event))))
      callback
  in
  let%bind () = Runtime_builder.Authored_start.run startup ~claim in
  let%bind () =
    match (Admitted_activation.Continuation.target scope.continuation).control with
    | Some _ -> Ok ()
    | None -> refresh_held_authored t scope
  in
  let%map receipt =
    Eio.Cancel.protect (fun () -> call t (Held_startup (Finish_authored scope)))
  in
  receipt
;;

let with_held_input t ~continuation ~prepare f =
  let open Result.Let_syntax in
  let%bind scope =
    Eio.Cancel.protect (fun () -> call t (Held_startup (Begin_input continuation)))
  in
  let final_check () =
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = check_held_effect continuation in
    let%bind () = input_scope_basis t scope in
    Admitted_activation.Continuation.check_basis continuation
  in
  let refresh () =
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = Admitted_activation.Continuation.refresh continuation in
    let%map () = final_check () in
    final_check
  in
  let checkpoint () =
    let%bind check = refresh () in
    check ()
  in
  let allocate_inference ~graph ~relation ~configuration =
    let%bind () = checkpoint () in
    (* The canonical allocation guard captures this actual Parsing scope and
       registration. Do not compose a second fresh-work gate after admission. *)
    inference_port t (Inference_held_input scope) ~graph ~relation ~configuration
  in
  let execution : Runtime_input_preparation.Execution.t =
    { request = scope.request; id = scope.id; checkpoint; refresh; allocate_inference }
  in
  scope.issued_execution <- Some execution;
  let cleanup () =
    (match scope.phase with
     | Parsing | Parsed_ready _ -> scope.phase <- Closed
     | Consumed _ | Root_attempt_unconfirmed | Closed -> ());
    Eio.Cancel.protect (fun () -> call t (Held_startup (Close_input scope)))
  in
  let run () =
    let%bind () = checkpoint () in
    let%bind input = prepare ~scope execution in
    let%bind () = checkpoint () in
    let%bind () = call t (Held_startup (Ready_input (scope, input))) in
    f ~scope ~input
  in
  match run () with
  | Ok value ->
    let%map () = cleanup () in
    value
  | Error _ as result ->
    (try ignore (cleanup () : (unit, Agent_protocol.Error.t) result) with
     | _ -> ());
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    (try ignore (cleanup () : (unit, Agent_protocol.Error.t) result) with
     | _ -> ());
    Exn.raise_with_original_backtrace exn backtrace
;;

let install_runtime_construction
      ?automatic_turn_policy
      ?moderator_manager
      t
      ~construction
      ~worker
      ~inference
  =
  match construction with
  | Runtime_construction.Initial continuation ->
    install_held_runtime
      ?automatic_turn_policy
      ?moderator_manager
      t
      ~continuation
      ~worker
      ~inference
  | Existing_goal _ | Delegated_load _ ->
    let open Result.Let_syntax in
    let%bind () = Runtime_construction.refresh construction in
    Eio.Cancel.protect (fun () ->
      let%bind () =
        match automatic_turn_policy with
        | None -> Ok ()
        | Some policy ->
          let%bind () =
            call t (Held_startup (Construction (Enable_budget (construction, policy))))
          in
          Runtime_construction.refresh construction
      in
      call
        t
        (Held_startup
           (Construction (Install (construction, worker, inference, moderator_manager)))))
;;

let run_goal_runtime_resume t ~continuation ~resume =
  let open Result.Let_syntax in
  let construction = Runtime_construction.Existing_goal continuation in
  let%bind () = Runtime_construction.refresh construction in
  let%bind scope =
    Eio.Cancel.protect (fun () ->
      call t (Held_startup (Construction (Begin_resume (continuation, resume)))))
  in
  let claim ~event ~snapshot callback =
    with_event_tools
      t
      ~claim:(fun () ->
        let%bind snapshot = snapshot () in
        let%map () = Runtime_construction.refresh construction in
        Some
          (Held_startup
             (Construction
                (Claim_resume
                   ( scope
                   , Agent_protocol.Id.Moderator_execution.create ()
                   , snapshot
                   , event )))))
      callback
  in
  let%bind () = Runtime_builder.Runtime_resume.run resume ~claim in
  Eio.Cancel.protect (fun () ->
    call t (Held_startup (Construction (Finish_resume scope))))
;;

let run_goal_execution_runtime_resume t ~execution ~resume =
